INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "花粉は「見る」の目的語なので、「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、見られる対象を表せず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「花粉に顕微鏡で見る」では見る対象を示せず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、見る対象が合わない。"}], "correct_answer": "を", "explanations": {"を": "花粉は「見る」の目的語なので、「を」で示す。", "へ": "方向を示す「へ」では、見られる対象を表せず文が成り立たない。", "に": "「花粉に顕微鏡で見る」では見る対象を示せず、文が成り立たない。", "から": "起点を示す「から」では、見る対象が合わない。"}, "error_tags": {"を": "対格", "へ": "方向", "から": "起点", "に": "位置・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花から花へ移る、黄色い小さな粉のことです。", "primary_collocate": null, "pronunciation": "かふん", "ipa": "kaɸɯɴ", "syllable_count": 3, "sentences": [{"text": "ハチの足に黄色い花粉がたくさんついていた。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "ハチの足[あし]に黄色[きいろ]い花粉[かふん]がたくさんついていた。", "sentence_source": "generated"}, {"text": "ハチは花から花へ飛んで、花粉を運ぶ。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "ハチは花[はな]から花[はな]へ飛[と]んで、花粉[かふん]を運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "ユリの花を触ったら、指に花粉がついた。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "ユリの花[はな]を触[さわ]ったら、指[ゆび]に花粉[かふん]がついた。", "sentence_source": "generated"}, {"text": "花粉が服につくと、洗ってもなかなか落ちない。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "花粉[かふん]が服[ふく]につくと、洗[あら]ってもなかなか落[お]ちない。", "sentence_source": "generated"}, {"text": "春になると、風に乗って花粉が遠くまで飛ぶ。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "春[はる]になると、風[かぜ]に乗[の]って花粉[かふん]が遠[とお]くまで飛[と]ぶ。", "sentence_source": "generated"}, {"text": "ちょうちょが花粉をつけて、次の花に移った。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "ちょうちょが花粉[かふん]をつけて、次[つぎ]の花[はな]に移[うつ]った。", "sentence_source": "generated"}, {"text": "机の上に黄色い花粉が落ちていたので、ふきんでふいた。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に黄色[きいろ]い花粉[かふん]が落[お]ちていたので、ふきんでふいた。", "sentence_source": "generated"}, {"text": "花粉を顕微鏡で見ると、丸い形をしていた。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "花粉[かふん]を顕微鏡[けんびきょう]で見[み]ると、丸[まる]い形[かたち]をしていた。", "sentence_source": "generated"}, {"text": "花瓶のユリから花粉が落ちて、白いテーブルが汚れた。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "花瓶[かびん]のユリから花粉[かふん]が落[お]ちて、白[しろ]いテーブルが汚[よご]れた。", "sentence_source": "generated"}, {"text": "子どもは鼻に花粉がついて、くしゃみをした。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "子[こ]どもは鼻[はな]に花粉[かふん]がついて、くしゃみをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花粉", "label": "基本形"}, {"form": "かふん", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "花から花へ運ばれる黄色い小さな粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "黄色い小さな粉で、ハチの足にたくさんついた物として自然に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "容器の名詞で、粉の代わりに足につく物としては合わない。"}, {"text": "花壇", "is_correct": false, "explanation": "花を植える場所の名詞で、足にたくさんついた物として合わない。"}, {"text": "花束", "is_correct": false, "explanation": "まとまった花の束で、黄色い粉が足につく状況と合わない。"}], "explanations": {"花粉": "黄色い小さな粉で、ハチの足にたくさんついた物として自然に合う。", "花瓶": "容器の名詞で、粉の代わりに足につく物としては合わない。", "花壇": "花を植える場所の名詞で、足にたくさんついた物として合わない。", "花束": "まとまった花の束で、黄色い粉が足につく状況と合わない。"}, "sentence_index": 0, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海水を煮詰めて、花粉を取り出した。", "explanation": "ここは〈塩〉の意味。花粉は海水から取れるものではないので、煮詰めて取り出す文脈には合わない。"}, {"text": "花粉をフライパンに敷いて、油がわりにした。", "explanation": "ここは〈油〉の意味。花粉は油がわりにはならないので、フライパンに敷いて使う文脈には合わない。"}, {"text": "化粧のあとに花粉をはたくと、肌がさらさらになる。", "explanation": "ここは〈パウダー〉の意味。この語は植物の花の粉を指すので、化粧品の粉には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "黄色い粉で、机の上に落ちていた物として自然に合う。"}, {"text": "花屋", "is_correct": false, "explanation": "花を売る店の名詞で、机の上に落ちていた物としては合わない。"}, {"text": "花畑", "is_correct": false, "explanation": "花が広く植えられた場所で、机の上に落ちる物として合わない。"}, {"text": "花嫁", "is_correct": false, "explanation": "人を指す名詞で、粉として落ちていた文脈に合わない。"}], "explanations": {"花粉": "黄色い粉で、机の上に落ちていた物として自然に合う。", "花屋": "花を売る店の名詞で、机の上に落ちていた物としては合わない。", "花畑": "花が広く植えられた場所で、机の上に落ちる物として合わない。", "花嫁": "人を指す名詞で、粉として落ちていた文脈に合わない。"}, "sentence_index": 6, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理に花粉を入れてとろみをつける。", "explanation": "ここは〈片栗粉〉の意味。花粉は料理のとろみづけには使わないので合わない。"}, {"text": "コーヒーに花粉を入れて甘くする。", "explanation": "ここは〈砂糖〉の意味。花粉は甘味料ではないので、甘くする文脈には合わない。"}, {"text": "花粉で服のしみを落とす。", "explanation": "ここは〈洗剤〉の意味。花粉は洗浄には使わないので、しみを落とす文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黄色い花粉を服についた。", "corrected_sentence": "黄色い花粉が服についた。", "error_description": "「ついた」の主語は花粉なので「が」。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花粉がルーペで見ると、丸い形をしていた。", "corrected_sentence": "花粉をルーペで見ると、丸い形をしていた。", "error_description": "「見る」の目的語は「を」。「が」にすると花粉が見る主体になり、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "花粉は「運んでもらう」対象で、目的語として「を」で示す。"}, {"text": "の", "is_correct": false, "explanation": "「花粉の風に」では名詞をつなぐだけで、運んでもらう動作の主語にも目的語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「花粉に運んで」では運ぶ相手になり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「花粉と運んで」では共同の相手になり、意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "花粉は「運んでもらう」対象で、目的語として「を」で示す。", "の": "「花粉の風に」では名詞をつなぐだけで、運んでもらう動作の主語にも目的語にもならない。", "に": "「花粉に運んで」では運ぶ相手になり、文が成り立たない。", "と": "「花粉と運んで」では共同の相手になり、意味が合わない。"}, "error_tags": {"を": "対格", "に": "位置・相手", "と": "共同", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "花粉は「集める」の目的語なので、「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、集める対象の花粉を表せず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では名詞をつなぐだけで、動詞の目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、集める対象が合わなくなる。"}], "correct_answer": "を", "explanations": {"を": "花粉は「集める」の目的語なので、「を」で示す。", "へ": "方向を示す「へ」では、集める対象の花粉を表せず文が成り立たない。", "の": "連体の「の」では名詞をつなぐだけで、動詞の目的語にならない。", "から": "起点を示す「から」では、集める対象が合わなくなる。"}, "error_tags": {"を": "対格", "へ": "方向", "の": "連体", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花のおしべにある粉。植物が実や種子を作るためのもので、虫や風によって運ばれる。", "primary_collocate": null, "pronunciation": "かふん", "ipa": "kaɸɯɴ", "syllable_count": 3, "sentences": [{"text": "おしべの先にある花粉がめしべにつくと、実ができる。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "おしべの先[さき]にある花粉[かふん]がめしべにつくと、実[み]ができる。", "sentence_source": "generated"}, {"text": "この木は花粉を風に運んでもらって、種を作る。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "この木[き]は花粉[かふん]を風[かぜ]に運[はこ]んでもらって、種[たね]を作[つく]る。", "sentence_source": "generated"}, {"text": "虫が花粉を運ぶので、果物の木は実をつけられる。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "虫[むし]が花粉[かふん]を運[はこ]ぶので、果物[くだもの]の木[き]は実[み]をつけられる。", "sentence_source": "generated"}, {"text": "雨が続くと、花粉が運ばれず、実が少なくなる。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、花粉[かふん]が運[はこ]ばれず、実[み]が少[すく]なくなる。", "sentence_source": "generated"}, {"text": "農家の人は、筆で花粉をめしべにつけている。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、筆[ふで]で花粉[かふん]をめしべにつけている。", "sentence_source": "generated"}, {"text": "花粉がめしべにつかなければ、種はできない。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "花粉[かふん]がめしべにつかなければ、種[たね]はできない。", "sentence_source": "generated"}, {"text": "スギは大量の花粉を風に乗せて、遠くへ飛ばす。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "スギは大量[たいりょう]の花粉[かふん]を風[かぜ]に乗[の]せて、遠[とお]くへ飛[と]ばす。", "sentence_source": "generated"}, {"text": "ミツバチは花粉を集めて、巣に持ち帰る。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "ミツバチは花粉[かふん]を集[あつ]めて、巣[す]に持[も]ち帰[かえ]る。", "sentence_source": "generated"}, {"text": "花粉が運ばれたおかげで、秋に大きな実がなった。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "花粉[かふん]が運[はこ]ばれたおかげで、秋[あき]に大[おお]きな実[み]がなった。", "sentence_source": "generated"}, {"text": "植物にとって、花粉は種を作るために必要なものだ。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]にとって、花粉[かふん]は種[たね]を作[つく]るために必要[ひつよう]なものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花粉", "label": "基本形"}, {"form": "かふん", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "おしべにあり、実や種子を作るために虫や風で運ばれる粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "おしべにあり、めしべにつくことで実を作る粉として自然に合う。"}, {"text": "花茎", "is_correct": false, "explanation": "花を支える茎で、めしべにつくことで実ができる文脈に合わない。"}, {"text": "蜜", "is_correct": false, "explanation": "花の甘い液で、めしべについて実を作る役目を持たないので合わない。"}, {"text": "花束", "is_correct": false, "explanation": "まとまった花の束で、おしべの先にある物として合わない。"}], "explanations": {"花粉": "おしべにあり、めしべにつくことで実を作る粉として自然に合う。", "花茎": "花を支える茎で、めしべにつくことで実ができる文脈に合わない。", "蜜": "花の甘い液で、めしべについて実を作る役目を持たないので合わない。", "花束": "まとまった花の束で、おしべの先にある物として合わない。"}, "sentence_index": 0, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は花粉を植えて、芽を出させる。", "explanation": "ここは〈種〉の意味。花粉は植えて芽を出させるものではないので、この文脈には合わない。"}, {"text": "父は花粉を砂糖の代わりにコーヒーに入れた。", "explanation": "ここは〈砂糖〉の意味。花粉は甘味料ではないので、コーヒーに入れる文脈には合わない。"}, {"text": "花粉で服のしみを落とした。", "explanation": "ここは〈洗剤〉の意味。花粉は洗浄には使わないので、しみを落とす文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "大量に風に乗せて飛ばされる粉として自然に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "容器の名詞で、風に乗せて飛ばす物としては合わない。"}, {"text": "花畑", "is_correct": false, "explanation": "花が植えられた場所で、風に乗せて飛ばす物として合わない。"}, {"text": "花壇", "is_correct": false, "explanation": "花を植える場所の名詞で、風に乗せて飛ばす物として合わない。"}], "explanations": {"花粉": "大量に風に乗せて飛ばされる粉として自然に合う。", "花瓶": "容器の名詞で、風に乗せて飛ばす物としては合わない。", "花畑": "花が植えられた場所で、風に乗せて飛ばす物として合わない。", "花壇": "花を植える場所の名詞で、風に乗せて飛ばす物として合わない。"}, "sentence_index": 6, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープに花粉を入れて、塩味をつける。", "explanation": "ここは〈塩〉の意味。花粉は調味料ではないので、塩味をつける文脈には合わない。"}, {"text": "花粉をまぶして、油で揚げる。", "explanation": "ここは〈パン粉〉の意味。花粉は揚げ物の衣にはならないので、まぶして揚げる文脈には合わない。"}, {"text": "花粉をお湯で溶かして、朝のコーヒーを淹れた。", "explanation": "ここは〈インスタントコーヒーの粉〉の意味。花粉は湯に溶けないので、コーヒーを淹れる文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "おしべの先にある花粉を、めしべに届くと、実ができる。", "corrected_sentence": "おしべの先にある花粉が、めしべに届くと、実ができる。", "error_description": "「届く」の主語は花粉なので「が」。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39555, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ミツバチは花粉に集めて、巣に運ぶ。", "corrected_sentence": "ミツバチは花粉を集めて、巣に運ぶ。", "error_description": "「集める」の目的語は「を」。「に」にすると、集める対象が合わなくなり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
