INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39556, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "花の粉がめしべにつくこと。", "primary_collocate": null, "pronunciation": "じゅふん", "ipa": "d͡ʑɯɸɯɴ", "syllable_count": 3, "sentences": [{"text": "ハチが花粉を運ぶので、花は受粉できる。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "ハチが花粉[かふん]を運[はこ]ぶので、花[はな]は受粉[じゅふん]できる。", "sentence_source": "generated"}, {"text": "雨が続くと、虫が来ないため受粉しにくい。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、虫[むし]が来[こ]ないため受粉[じゅふん]しにくい。", "sentence_source": "generated"}, {"text": "受粉が終わると、花びらは落ちてしまう。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]が終[お]わると、花[はな]びらは落[お]ちてしまう。", "sentence_source": "generated"}, {"text": "風が強い日は、トウモロコシの受粉がよく進む。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、トウモロコシの受粉[じゅふん]がよく進[すす]む。", "sentence_source": "generated"}, {"text": "農家は筆を使って、花を一つずつ受粉させる。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "農家[のうか]は筆[ふで]を使[つか]って、花[はな]を一[ひと]つずつ受粉[じゅふん]させる。", "sentence_source": "generated"}, {"text": "受粉に失敗したので、今年は実が少なかった。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]に失敗[しっぱい]したので、今年[ことし]は実[み]が少[すく]なかった。", "sentence_source": "generated"}, {"text": "春にミツバチが飛ぶと、リンゴの花は受粉する。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "春[はる]にミツバチが飛[と]ぶと、リンゴの花[はな]は受粉[じゅふん]する。", "sentence_source": "generated"}, {"text": "虫のいない温室では、人の手で受粉するしかない。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "虫[むし]のいない温室[おんしつ]では、人[ひと]の手[て]で受粉[じゅふん]するしかない。", "sentence_source": "generated"}, {"text": "この花は夜に咲き、ガが来て受粉を助ける。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "この花[はな]は夜[よる]に咲[さ]き、ガが来[き]て受粉[じゅふん]を助[たす]ける。", "sentence_source": "generated"}, {"text": "受粉のあとで、めしべの根もとがふくらみ始めた。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]のあとで、めしべの根[ね]もとがふくらみ始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受粉する", "label": "辞書形"}, {"form": "受粉した", "label": "過去形"}, {"form": "受粉して", "label": "て形"}, {"form": "受粉しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "花粉がめしべにつく、植物の基本的な現象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39556, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発芽", "is_correct": false, "explanation": "発芽は種子などが芽を出すこと。ハチが花粉を運ぶ文脈で、花が発芽するとは言わないので合わない"}, {"text": "受粉", "is_correct": true, "explanation": "花粉がめしべにつくこと。ハチが花粉を運び、花が実をつける流れに合う"}, {"text": "落葉", "is_correct": false, "explanation": "葉が落ちる現象。花粉を運ぶ話とは無関係で、花には使えない"}, {"text": "施肥", "is_correct": false, "explanation": "肥料を与える作業。花粉を運ぶ働きを表さないので合わない"}], "explanations": {"発芽": "発芽は種子などが芽を出すこと。ハチが花粉を運ぶ文脈で、花が発芽するとは言わないので合わない", "受粉": "花粉がめしべにつくこと。ハチが花粉を運び、花が実をつける流れに合う", "落葉": "葉が落ちる現象。花粉を運ぶ話とは無関係で、花には使えない", "施肥": "肥料を与える作業。花粉を運ぶ働きを表さないので合わない"}, "sentence_index": 0, "correct_answer": "受粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "メダカの卵は、受粉してから十日ほどでふ化する。", "explanation": "ここは〈受精〉の意味。卵と精子が結びつくのは受精で、受粉は花粉がめしべにつく植物の話に限るので合わない。"}, {"text": "妊娠の初期に、医師が受粉を確認した。", "explanation": "ここは〈受胎〉の意味。妊娠が成立することを指す語で、花粉の移動を表す受粉とは合わない。"}, {"text": "夏の終わりに、木は多くの実を受粉させた。", "explanation": "ここは〈結実〉の意味。実がなる段階を指すので、花粉をめしべに運ぶ受粉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39556, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移植", "is_correct": false, "explanation": "植え替えること。花を移すという意味で、ミツバチが飛ぶ文脈に合わない"}, {"text": "接ぎ木", "is_correct": false, "explanation": "別の株を接いで増やす作業。花粉を運ぶ働きを表さないので合わない"}, {"text": "受粉", "is_correct": true, "explanation": "ミツバチが花粉を運び、花粉がめしべにつく意味で文に合う"}, {"text": "発根", "is_correct": false, "explanation": "根が出ること。花を主語にした文では意味が通らない"}], "explanations": {"移植": "植え替えること。花を移すという意味で、ミツバチが飛ぶ文脈に合わない", "接ぎ木": "別の株を接いで増やす作業。花粉を運ぶ働きを表さないので合わない", "受粉": "ミツバチが花粉を運び、花粉がめしべにつく意味で文に合う", "発根": "根が出ること。花を主語にした文では意味が通らない"}, "sentence_index": 6, "correct_answer": "受粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家畜に人工的に受粉させ、子牛が生まれた。", "explanation": "ここは〈授精〉の意味。人の手で家畜に行うのは授精で、受粉は植物の花粉の話なので合わない。"}, {"text": "新しい制度は、多くの人に受粉された。", "explanation": "ここは〈受容〉の意味。制度や考えを受け入れる場合に使い、花粉に関する受粉とは合わない。"}, {"text": "宅配の荷物を、玄関で受粉しました。", "explanation": "ここは〈受領〉の意味。届いた物を受け取る場面で使い、植物の受粉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39556, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風が吹くと花粉がめしべに届き、受粉を進む。", "corrected_sentence": "風が吹くと花粉がめしべに届き、受粉が進む。", "error_description": "誤りは〈受粉を〉。〈進む〉は自動詞なので、動作の主体を〈が〉で示す。正しくは〈受粉が進む〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39556, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は受粉を失敗しやすい。", "corrected_sentence": "雨の日は受粉に失敗しやすい。", "error_description": "誤りは〈受粉を〉。〈失敗する〉は〈に〉を取るので、正しくは〈受粉に失敗〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
