INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39557, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "植物の雄しべの花粉が雌しべの先について、種ができるもとになること。", "primary_collocate": null, "pronunciation": "じゅふん", "ipa": "d͡ʑɯɸɯɴ", "syllable_count": 3, "sentences": [{"text": "受粉が起きなければ、花に種はできない。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]が起[お]きなければ、花[はな]に種[たね]はできない。", "sentence_source": "generated"}, {"text": "雄しべの花粉がめしべの先に落ちて、受粉が成り立つ。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "雄[お]しべの花粉[かふん]がめしべの先[さき]に落[お]ちて、受粉[じゅふん]が成[な]り立[た]つ。", "sentence_source": "generated"}, {"text": "かぼちゃの雌花は、朝のうちに受粉させるとよく実る。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "かぼちゃの雌花[めばな]は、朝[あさ]のうちに受粉[じゅふん]させるとよく実[みの]る。", "sentence_source": "generated"}, {"text": "受粉した花だけが、やがて種をつくり始める。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]した花[はな]だけが、やがて種[たね]をつくり始[はじ]める。", "sentence_source": "generated"}, {"text": "一本の木だけでは受粉しない品種もある。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "一本[いっぽん]の木[き]だけでは受粉[じゅふん]しない品種[ひんしゅ]もある。", "sentence_source": "generated"}, {"text": "温度が低すぎると、花粉が育たず受粉が難しい。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "温度[おんど]が低[ひく]すぎると、花粉[かふん]が育[そだ]たず受粉[じゅふん]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "梨の栽培では、受粉の時期を逃さないことが大切だ。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "梨[なし]の栽培[さいばい]では、受粉[じゅふん]の時期[じき]を逃[のが]さないことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "受粉の仕組みを、図を使って先生が説明した。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]の仕組[しく]みを、図[ず]を使[つか]って先生[せんせい]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "花粉がめしべの先につくと受粉し、種のもとができる。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "花粉[かふん]がめしべの先[さき]につくと受粉[じゅふん]し、種[たね]のもとができる。", "sentence_source": "generated"}, {"text": "受粉がうまくいったかどうかは、数日後に実のふくらみでわかる。", "target_word": "受粉", "complexity_tier": "T3", "furigana": "受粉[じゅふん]がうまくいったかどうかは、数日後[すうじつご]に実[み]のふくらみでわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受粉する", "label": "辞書形"}, {"form": "受粉した", "label": "過去形"}, {"form": "受粉して", "label": "て形"}, {"form": "受粉しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "種や実ができるもとになる、植物の生殖の過程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発芽", "is_correct": false, "explanation": "発芽は種子が芽を出すこと。種ができる条件としては合わない"}, {"text": "落葉", "is_correct": false, "explanation": "葉が落ちる現象。種の形成とは関係しない"}, {"text": "受粉", "is_correct": true, "explanation": "花粉がめしべの先につく現象。種ができるもとになる条件として自然"}, {"text": "挿し木", "is_correct": false, "explanation": "枝を挿して株を増やす方法。種の形成の前提にはならない"}], "explanations": {"発芽": "発芽は種子が芽を出すこと。種ができる条件としては合わない", "落葉": "葉が落ちる現象。種の形成とは関係しない", "受粉": "花粉がめしべの先につく現象。種ができるもとになる条件として自然", "挿し木": "枝を挿して株を増やす方法。種の形成の前提にはならない"}, "sentence_index": 0, "correct_answer": "受粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カエルの卵は、受粉してからゼリーに包まれる。", "explanation": "ここは〈受精〉の意味。動物の卵と精子の結合を指すので、植物の受粉とは合わない。"}, {"text": "妊娠五週目に、受粉が確かめられた。", "explanation": "ここは〈受胎〉の意味。人や動物の妊娠の成立を指し、受粉は花粉の話なので合わない。"}, {"text": "秋になり、木は一度に多くの果実を受粉させた。", "explanation": "ここは〈結実〉の意味。果実ができる段階を指すので、花粉の移動を表す受粉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木材", "is_correct": false, "explanation": "木を加工した材料。栽培の時期を表す語としては意味を成さない"}, {"text": "樹脂", "is_correct": false, "explanation": "木から出るねばり状の物質。栽培の時期とは結びつかない"}, {"text": "受粉", "is_correct": true, "explanation": "花粉をめしべにつける作業。梨の栽培で時期を逃さないことが重要になる"}, {"text": "根粒", "is_correct": false, "explanation": "根にできる小さな粒。栽培の時期とは合わない"}], "explanations": {"木材": "木を加工した材料。栽培の時期を表す語としては意味を成さない", "樹脂": "木から出るねばり状の物質。栽培の時期とは結びつかない", "受粉": "花粉をめしべにつける作業。梨の栽培で時期を逃さないことが重要になる", "根粒": "根にできる小さな粒。栽培の時期とは合わない"}, "sentence_index": 6, "correct_answer": "受粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牛に受粉を施し、翌年に子牛が生まれた。", "explanation": "ここは〈授精〉の意味。家畜に行うのは授精で、受粉は植物に使う語なので合わない。"}, {"text": "この提案は社員の間で広く受粉された。", "explanation": "ここは〈受容〉の意味。提案や考えを受け入れる場合に使い、花粉の受粉とは合わない。"}, {"text": "午後に荷物を受粉しておきました。", "explanation": "ここは〈受領〉の意味。届いた物を受け取る場合に使い、植物の受粉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風は受粉に妨げることがある。", "corrected_sentence": "強い風は受粉を妨げることがある。", "error_description": "誤りは〈受粉に〉。〈妨げる〉は他動詞で目的語に〈を〉を取るので、正しくは〈受粉を妨げる〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "受粉を遅れると、実の数が減る。", "corrected_sentence": "受粉が遅れると、実の数が減る。", "error_description": "誤りは〈受粉を〉。〈遅れる〉は自動詞なので、受粉を主語として〈受粉が〉と示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "食べる対象の苺を示す目的語で、「苺を、みんなで食べた」として自然。"}, {"text": "が", "is_correct": false, "explanation": "「苺が」にすると苺が食べる主体になり、文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「苺に食べた」では食べる対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「苺で食べた」は手段・場所となり、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "食べる対象の苺を示す目的語で、「苺を、みんなで食べた」として自然。", "が": "「苺が」にすると苺が食べる主体になり、文の意味が崩れる。", "に": "「苺に食べた」では食べる対象を示せず、不自然。", "で": "「苺で食べた」は手段・場所となり、目的語にならない。"}, "error_tags": {"が": "主語（食べる主体）", "に": "相手・方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "洗う対象の苺を示す目的語で、「苺を洗ってから」として自然。"}, {"text": "と", "is_correct": false, "explanation": "「苺と洗ってから」では洗う対象を示せず、一緒に洗う意味にもならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、洗う対象にはならず文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を表すので、洗う対象を示す位置に入らない。"}], "correct_answer": "を", "explanations": {"を": "洗う対象の苺を示す目的語で、「苺を洗ってから」として自然。", "と": "「苺と洗ってから」では洗う対象を示せず、一緒に洗う意味にもならず不自然。", "へ": "方向を表すので、洗う対象にはならず文が成立しない。", "より": "比較や起点を表すので、洗う対象を示す位置に入らない。"}, "error_tags": {"と": "相手・連れ", "へ": "方向・到達点", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あかい、あまいくだものです。", "primary_collocate": null, "pronunciation": "いちご", "ipa": "itɕiɡo", "syllable_count": 3, "sentences": [{"text": "苺は赤くて甘いので、子どもに人気がある。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]は赤[あか]くて甘[あま]いので、子[こ]どもに人気[にんき]がある。", "sentence_source": "generated"}, {"text": "母が買ってきた苺を、みんなで食べた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "母[はは]が買[か]ってきた苺[いちご]を、みんなで食[た]べた。", "sentence_source": "generated"}, {"text": "ケーキの上に大きな苺がのっている。", "target_word": "苺", "complexity_tier": "T3", "furigana": "ケーキの上[うえ]に大[おお]きな苺[いちご]がのっている。", "sentence_source": "generated"}, {"text": "この苺は甘くて、砂糖をかけなくてもおいしい。", "target_word": "苺", "complexity_tier": "T3", "furigana": "この苺[いちご]は甘[あま]くて、砂糖[さとう]をかけなくてもおいしい。", "sentence_source": "generated"}, {"text": "朝ごはんに、ヨーグルトと苺を食べた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、ヨーグルトと苺[いちご]を食[た]べた。", "sentence_source": "generated"}, {"text": "まだ白い苺は、すっぱくて食べられなかった。", "target_word": "苺", "complexity_tier": "T3", "furigana": "まだ白[しろ]い苺[いちご]は、すっぱくて食[た]べられなかった。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れておいた苺が、全部なくなった。", "target_word": "苺", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れておいた苺[いちご]が、全部[ぜんぶ]なくなった。", "sentence_source": "generated"}, {"text": "苺を洗ってから、お皿に並べた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]を洗[あら]ってから、お皿[さら]に並[なら]べた。", "sentence_source": "generated"}, {"text": "妹は苺が大好きで、いつも一番に手を出す。", "target_word": "苺", "complexity_tier": "T3", "furigana": "妹[いもうと]は苺[いちご]が大好[だいす]きで、いつも一番[いちばん]に手[て]を出[だ]す。", "sentence_source": "generated"}, {"text": "赤くなった苺から先に、かごに入れた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "赤[あか]くなった苺[いちご]から先[さき]に、かごに入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苺", "label": "基本形"}, {"form": "いちご", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "赤くて甘い小さな果物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: すっぱく (Zipf 1.83)']::text[], '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苺", "is_correct": true, "explanation": "赤くて甘い果物で、子どもに人気があるという文の主語として合う。"}, {"text": "大根", "is_correct": false, "explanation": "白くて甘くない野菜なので、赤くて甘いという説明に合わない。"}, {"text": "豆腐", "is_correct": false, "explanation": "白くて淡白な食品で、赤くも甘くもないため文に合わない。"}, {"text": "ピーマン", "is_correct": false, "explanation": "緑色で苦味のある野菜なので、赤くて甘い性質と矛盾する。"}], "explanations": {"苺": "赤くて甘い果物で、子どもに人気があるという文の主語として合う。", "大根": "白くて甘くない野菜なので、赤くて甘いという説明に合わない。", "豆腐": "白くて淡白な食品で、赤くも甘くもないため文に合わない。", "ピーマン": "緑色で苦味のある野菜なので、赤くて甘い性質と矛盾する。"}, "sentence_index": 0, "correct_answer": "苺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この苺はさやごと茹でて、塩をふって食べる。", "explanation": "ここは〈枝豆〉の食べ方の語感。苺にはさやがなく、さやごと茹でて食べる果物ではないので合わない。"}, {"text": "この苺は皮を湯むきしてから、みじん切りにして炒めた。", "explanation": "ここは〈トマト〉の下ごしらえ。苺は湯むきせず生で食べる果物なので、この言い方に合わない。"}, {"text": "この苺は皮をむいてから、だしで煮て、おでんに入れた。", "explanation": "ここは〈大根〉のおでんの語感。苺はおでんの具にはしないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苺", "is_correct": true, "explanation": "冷蔵庫に入れておいた果物が全部なくなったという文脈に合う。"}, {"text": "新聞", "is_correct": false, "explanation": "紙の印刷物で、冷蔵庫に入れて保存するものではないので文に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "本で、冷蔵庫に入れておく物ではないので、この文脈に合わない。"}, {"text": "ティッシュ", "is_correct": false, "explanation": "紙製品で、冷蔵庫に入れて保存する物ではないので文に合わない。"}], "explanations": {"苺": "冷蔵庫に入れておいた果物が全部なくなったという文脈に合う。", "新聞": "紙の印刷物で、冷蔵庫に入れて保存するものではないので文に合わない。", "教科書": "本で、冷蔵庫に入れておく物ではないので、この文脈に合わない。", "ティッシュ": "紙製品で、冷蔵庫に入れて保存する物ではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "苺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この苺は一晩水に浸してから、ご飯と一緒に炊く。", "explanation": "ここは〈大豆〉の下ごしらえの語感。苺は水に浸して炊く食材ではないので、この使い方は合わない。"}, {"text": "この苺は藁で表面を炙って、たたきにする。", "explanation": "ここは〈かつお〉のたたきの語感。苺は藁で炙ってたたきにする食材ではないので合わない。"}, {"text": "この苺は水を替えながら研いでから、ざるに上げる。", "explanation": "ここは〈米〉の語感。米は研ぐが、苺は洗うだけなので、研ぐとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "苺でたくさん食べて、おなかが痛くなった。", "corrected_sentence": "苺をたくさん食べて、おなかが痛くなった。", "error_description": "「食べる」の目的語は「を」で示す。「で」は手段や場所を表すので、苺を食べたのに「で」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39558, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "苺が洗って、ヘタを取ってから食べた。", "corrected_sentence": "苺を洗って、ヘタを取ってから食べた。", "error_description": "「洗う」の目的語は「を」で示す。「が」は主語になり、苺が洗う側になって誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "苺が主語で、白い花を咲かせ始める主体を示すので自然。"}, {"text": "を", "is_correct": false, "explanation": "「苺を、白い花を咲かせ始めた」では苺が目的語になり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「苺に白い花を咲かせ始めた」では相手を示し、主語になれず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「苺で白い花を咲かせ始めた」は手段・場所になり、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "苺が主語で、白い花を咲かせ始める主体を示すので自然。", "を": "「苺を、白い花を咲かせ始めた」では苺が目的語になり、不自然。", "に": "「苺に白い花を咲かせ始めた」では相手を示し、主語になれず不自然。", "で": "「苺で白い花を咲かせ始めた」は手段・場所になり、主語にならない。"}, "error_tags": {"を": "目的語（対象）", "に": "相手・方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "苺の葉という所属を示し、「苺の葉の間から」として自然。"}, {"text": "と", "is_correct": false, "explanation": "「苺と葉の間から」では並列の意味になり、所属を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、名詞を修飾する位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、苺と葉を結ぶ所属の位置に合わない。"}], "correct_answer": "の", "explanations": {"の": "苺の葉という所属を示し、「苺の葉の間から」として自然。", "と": "「苺と葉の間から」では並列の意味になり、所属を示せず不自然。", "へ": "方向を表すので、名詞を修飾する位置には入らない。", "より": "比較を表すので、苺と葉を結ぶ所属の位置に合わない。"}, "error_tags": {"と": "並列", "へ": "方向・到達点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "バラ科の多年草。春に白い花が咲き、赤くて甘い実をつける。果実は食用にされる。", "primary_collocate": null, "pronunciation": "いちご", "ipa": "itɕiɡo", "syllable_count": 3, "sentences": [{"text": "苺は春に白い花が咲いて、あとで赤い実がなる。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]は春[はる]に白[しろ]い花[はな]が咲[さ]いて、あとで赤[あか]い実[み]がなる。", "sentence_source": "generated"}, {"text": "庭の苺が、白い花をつけ始めた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "庭[にわ]の苺[いちご]が、白[しろ]い花[はな]をつけ始[はじ]めた。", "sentence_source": "generated"}, {"text": "苺はバラ科の植物で、毎年同じ株から育つ。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]はバラ科[か]の植物[しょくぶつ]で、毎年[まいとし]同[おな]じ株[かぶ]から育[そだ]つ。", "sentence_source": "generated"}, {"text": "ベランダのプランターで苺を育てている。", "target_word": "苺", "complexity_tier": "T3", "furigana": "ベランダのプランターで苺[いちご]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "苺の花が終わると、小さな緑の実ができる。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]の花[はな]が終[お]わると、小[ちい]さな緑[みどり]の実[み]ができる。", "sentence_source": "generated"}, {"text": "苺は多年草なので、冬を越えてまた芽を出す。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]は多年草[たねんそう]なので、冬[ふゆ]を越[こ]えてまた芽[め]を出[だ]す。", "sentence_source": "generated"}, {"text": "苺の株が増えたので、友達に分けてあげた。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]の株[かぶ]が増[ふ]えたので、友達[ともだち]に分[わ]けてあげた。", "sentence_source": "generated"}, {"text": "苺の葉の間から、赤い実が顔を出している。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]の葉[は]の間[あいだ]から、赤[あか]い実[み]が顔[かお]を出[だ]している。", "sentence_source": "generated"}, {"text": "苺は日当たりのいい場所に植えると、よく実がなる。", "target_word": "苺", "complexity_tier": "T3", "furigana": "苺[いちご]は日当[ひあ]たりのいい場所[ばしょ]に植[う]えると、よく実[み]がなる。", "sentence_source": "generated"}, {"text": "畑の苺に水をやるのが、毎朝の仕事だ。", "target_word": "苺", "complexity_tier": "T3", "furigana": "畑[はたけ]の苺[いちご]に水[みず]をやるのが、毎朝[まいあさ]の仕事[しごと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苺", "label": "基本形"}, {"form": "いちご", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "春に白い花が咲き、赤い実をつけるバラ科の多年草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苺", "is_correct": true, "explanation": "春に白い花が咲き、あとで赤い実がなる草本の植物として文に合う。"}, {"text": "竹", "is_correct": false, "explanation": "竹は草の仲間で、赤い実をつける植物ではないので文に合わない。"}, {"text": "杉", "is_correct": false, "explanation": "杉は花粉を飛ばす針葉樹で、白い花が咲いて赤い実がなる説明と合わない。"}, {"text": "松", "is_correct": false, "explanation": "松は針葉樹で、赤い実がなるという説明に合わない。"}], "explanations": {"苺": "春に白い花が咲き、あとで赤い実がなる草本の植物として文に合う。", "竹": "竹は草の仲間で、赤い実をつける植物ではないので文に合わない。", "杉": "杉は花粉を飛ばす針葉樹で、白い花が咲いて赤い実がなる説明と合わない。", "松": "松は針葉樹で、赤い実がなるという説明に合わない。"}, "sentence_index": 0, "correct_answer": "苺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この苺を根元から伐って、薪にした。", "explanation": "ここは〈木〉の語感。木は伐って薪にするが、草本の苺にはそのような扱いはしないので合わない。"}, {"text": "この苺の筍を掘って、煮物にした。", "explanation": "ここは〈竹〉の語感。筍は竹の若芽で、苺の地下から掘り出すものではないので合わない。"}, {"text": "ベランダで苺を飼っている。", "explanation": "ここは〈動物〉の語感。苺は植物なので、飼うではなく育てると言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苺", "is_correct": true, "explanation": "株が増えて友達に分ける、という草本の株分けの文脈に合う。"}, {"text": "猫", "is_correct": false, "explanation": "動物なので、株が増えて分けるという植物の文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "家具なので、株が増えて分けるという文脈に合わない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物なので、株が増えて分けるという文脈に合わない。"}], "explanations": {"苺": "株が増えて友達に分ける、という草本の株分けの文脈に合う。", "猫": "動物なので、株が増えて分けるという植物の文脈に合わない。", "机": "家具なので、株が増えて分けるという文脈に合わない。", "電車": "乗り物なので、株が増えて分けるという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "苺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑の苺を刈って、芝のように平らにならすのが、毎朝の仕事だ。", "explanation": "ここは〈芝〉の語感。苺は刈って整える植物ではないので、この動詞とは合わない。"}, {"text": "畑の苺が一斉に田植えされるのが、毎朝の仕事だ。", "explanation": "ここは〈稲〉の語感。苺は田植えをしない作物なので、この言い方は合わない。"}, {"text": "畑の苺を脱穀するのが、毎朝の仕事だ。", "explanation": "ここは〈麦〉の語感。苺は穀物ではなく、脱穀という作業は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の苺を、白い花を咲かせ始めた。", "corrected_sentence": "庭の苺が、白い花を咲かせ始めた。", "error_description": "「咲かせる」の主体である苺は「が」で示す。「を」は目的語を示すので、苺に使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の苺を肥料をやるのが、毎週の仕事だ。", "corrected_sentence": "庭の苺に肥料をやるのが、毎週の仕事だ。", "error_description": "「やる」の相手（与える先）は「に」で示す。「を」は与える物に使うので、苺に使うのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
