INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "食べる対象の西瓜を示す目的語で、「西瓜を食べすぎて」として自然。"}, {"text": "が", "is_correct": false, "explanation": "「西瓜が食べすぎて」では西瓜が食べる主体になり、意味が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「西瓜に食べすぎて」では食べる対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「西瓜で食べすぎて」は手段・場所になり、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "食べる対象の西瓜を示す目的語で、「西瓜を食べすぎて」として自然。", "が": "「西瓜が食べすぎて」では西瓜が食べる主体になり、意味が成立しない。", "に": "「西瓜に食べすぎて」では食べる対象を示せず、不自然。", "で": "「西瓜で食べすぎて」は手段・場所になり、目的語にならない。"}, "error_tags": {"が": "主語（食べる主体）", "に": "相手・方向", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "西瓜は、夏に食べる、赤くて甘い果物です。", "primary_collocate": null, "pronunciation": "すいか", "ipa": "sɯika", "syllable_count": 3, "sentences": [{"text": "夏は冷えた西瓜が一番おいしい。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "夏[なつ]は冷[ひ]えた西瓜[すいか]が一番[いちばん]おいしい。", "sentence_source": "generated"}, {"text": "西瓜は赤くて甘いので、夏によく食べる。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は赤[あか]くて甘[あま]いので、夏[なつ]によく食[た]べる。", "sentence_source": "generated"}, {"text": "海に行った帰りに、西瓜を買った。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "海[うみ]に行[い]った帰[かえ]りに、西瓜[すいか]を買[か]った。", "sentence_source": "generated"}, {"text": "大きな西瓜を、家族みんなで切って食べた。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "大[おお]きな西瓜[すいか]を、家族[かぞく]みんなで切[き]って食[た]べた。", "sentence_source": "generated"}, {"text": "暑い日には、冷たい西瓜がほしくなる。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]には、冷[つめ]たい西瓜[すいか]がほしくなる。", "sentence_source": "generated"}, {"text": "祖母が西瓜を冷蔵庫で冷やしておいてくれた。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "祖母[そぼ]が西瓜[すいか]を冷蔵庫[れいぞうこ]で冷[ひ]やしておいてくれた。", "sentence_source": "generated"}, {"text": "西瓜は夏の果物で、冬にはあまり見かけない。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は夏[なつ]の果物[くだもの]で、冬[ふゆ]にはあまり見[み]かけない。", "sentence_source": "generated"}, {"text": "西瓜を食べすぎて、おなかが痛くなった。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]を食[た]べすぎて、おなかが痛[いた]くなった。", "sentence_source": "generated"}, {"text": "弟は西瓜が好きで、毎日のように食べている。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "弟[おとうと]は西瓜[すいか]が好[す]きで、毎日[まいにち]のように食[た]べている。", "sentence_source": "generated"}, {"text": "まるい西瓜を二つに切ると、中は真っ赤だった。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "まるい西瓜[すいか]を二[ふた]つに切[き]ると、中[なか]は真[ま]っ赤[か]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "西瓜", "label": "基本形"}, {"form": "すいか", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "夏に食べる赤くて甘い大きな果物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西瓜", "is_correct": true, "explanation": "夏に冷やして食べると一番おいしい果物なので、文の主語として合う。"}, {"text": "味噌", "is_correct": false, "explanation": "発酵した調味料で、冷えたものが一番おいしいという文脈に合わない。"}, {"text": "醤油", "is_correct": false, "explanation": "調味料で、冷やして食べる食品ではないので文に合わない。"}, {"text": "海苔", "is_correct": false, "explanation": "乾物で、夏に冷やして一番おいしいという食べ方は合わない。"}], "explanations": {"西瓜": "夏に冷やして食べると一番おいしい果物なので、文の主語として合う。", "味噌": "発酵した調味料で、冷えたものが一番おいしいという文脈に合わない。", "醤油": "調味料で、冷やして食べる食品ではないので文に合わない。", "海苔": "乾物で、夏に冷やして一番おいしいという食べ方は合わない。"}, "sentence_index": 0, "correct_answer": "西瓜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな西瓜を、家族みんなでグラタンにして食べた。", "explanation": "ここは〈じゃがいも〉のグラタンの語感。西瓜はグラタンにする果物ではないので、この使い方に合わない。"}, {"text": "大きな西瓜を、家族みんなでおろして食べた。", "explanation": "ここは〈大根〉の下ごしらえの語感。西瓜はおろして食べるものではないので合わない。"}, {"text": "大きな西瓜を、家族みんなで蒸して食べた。", "explanation": "ここは〈さつまいも〉の調理の語感。西瓜は蒸して食べる食材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": true, "explanation": "夏の果物で、冬にはあまり見かけないという説明に合う。"}, {"text": "餅", "is_correct": false, "explanation": "果物ではないので、夏の果物という説明に合わない。"}, {"text": "卵", "is_correct": false, "explanation": "果物ではないので、夏の果物という説明に合わない。"}, {"text": "豆腐", "is_correct": false, "explanation": "果物ではないので、夏の果物という説明に合わない。"}], "explanations": {"西瓜": "夏の果物で、冬にはあまり見かけないという説明に合う。", "餅": "果物ではないので、夏の果物という説明に合わない。", "卵": "果物ではないので、夏の果物という説明に合わない。", "豆腐": "果物ではないので、夏の果物という説明に合わない。"}, "sentence_index": 6, "correct_answer": "西瓜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "西瓜は藁で包んで、三日ほど発酵させてから食べる。", "explanation": "ここは〈納豆〉の発酵の語感。西瓜は発酵させて食べる果物ではないので合わない。"}, {"text": "西瓜は冬の鍋料理に入れて、体を温める。", "explanation": "ここは〈白菜〉の鍋野菜の語感。西瓜は鍋に入れる食材ではないので合わない。"}, {"text": "西瓜は臼に入れて、杵でついて餅にする。", "explanation": "ここは〈餅〉の語感。餅はつくが、西瓜を餅にするとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "西瓜で食べすぎて、胃もたれした。", "corrected_sentence": "西瓜を食べすぎて、胃もたれした。", "error_description": "「食べる」の目的語は「を」で示す。「で」は手段や場所を表すので、西瓜を食べたのに「で」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "西瓜を一切れ飲んだ。", "corrected_sentence": "西瓜を一切れ食べた。", "error_description": "西瓜は食べる果物なので「飲む」は合わない。「食べた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
