INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39561, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "西瓜は、ウリ科の植物で、夏に収穫される大きな果実です。外側は緑色の皮で覆われ、中は赤い果肉と黒い種があります。水分が多く、甘い味が特徴です。", "primary_collocate": null, "pronunciation": "すいか", "ipa": "sɯika", "syllable_count": 3, "sentences": [{"text": "西瓜の外側は緑色の皮で、中は赤い。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]の外側[そとがわ]は緑色[みどりいろ]の皮[かわ]で、中[なか]は赤[あか]い。", "sentence_source": "generated"}, {"text": "西瓜は水分が多いので、のどがかわいたときによい。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は水分[すいぶん]が多[おお]いので、のどがかわいたときによい。", "sentence_source": "generated"}, {"text": "西瓜は夏に収穫される、大きな果実だ。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は夏[なつ]に収穫[しゅうかく]される、大[おお]きな果実[かじつ]だ。", "sentence_source": "generated"}, {"text": "西瓜を切ると、赤い果肉に黒い種が並んでいた。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]を切[き]ると、赤[あか]い果肉[かにく]に黒[くろ]い種[たね]が並[なら]んでいた。", "sentence_source": "generated"}, {"text": "西瓜はウリ科の植物で、つるが長くのびる。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]はウリ科[か]の植物[しょくぶつ]で、つるが長[なが]くのびる。", "sentence_source": "generated"}, {"text": "畑の西瓜が大きくなったので、来週収穫する。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "畑[はたけ]の西瓜[すいか]が大[おお]きくなったので、来週[らいしゅう]収穫[しゅうかく]する。", "sentence_source": "generated"}, {"text": "西瓜は水分が九割ほどあって、味はあっさり甘い。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は水分[すいぶん]が九割[きゅうわり]ほどあって、味[あじ]はあっさり甘[あま]い。", "sentence_source": "generated"}, {"text": "たたくといい音がする西瓜は、よく熟れている。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "たたくといい音[おと]がする西瓜[すいか]は、よく熟[う]れている。", "sentence_source": "generated"}, {"text": "西瓜の黒い種は、炒めて食べる国もある。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]の黒[くろ]い種[たね]は、炒[いた]めて食[た]べる国[くに]もある。", "sentence_source": "generated"}, {"text": "西瓜は重いので、持ち帰るのが大変だ。", "target_word": "西瓜", "complexity_tier": "T3", "furigana": "西瓜[すいか]は重[おも]いので、持[も]ち帰[かえ]るのが大変[たいへん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "西瓜", "label": "基本形"}, {"form": "すいか", "label": "ひらがな表記"}], "register": "中立（普通体）", "sense_fingerprint": "緑の皮と赤い果肉、黒い種をもつ水分の多いウリ科の大きな果実", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9917535d-1ee3-48f0-905e-62105b0c1b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西瓜", "is_correct": true, "explanation": "緑色の皮で中が赤い果実という説明に合う。"}, {"text": "バナナ", "is_correct": false, "explanation": "皮は黄色く、中は白い果肉なので、緑の皮と赤い果肉の説明に合わない。"}, {"text": "みかん", "is_correct": false, "explanation": "皮も中も橙色なので、緑色の皮と赤い果肉の説明と矛盾する。"}, {"text": "キウイ", "is_correct": false, "explanation": "皮は茶色で中は緑色なので、緑の皮と赤い果肉の説明に合わない。"}], "explanations": {"西瓜": "緑色の皮で中が赤い果実という説明に合う。", "バナナ": "皮は黄色く、中は白い果肉なので、緑の皮と赤い果肉の説明に合わない。", "みかん": "皮も中も橙色なので、緑色の皮と赤い果肉の説明と矛盾する。", "キウイ": "皮は茶色で中は緑色なので、緑の皮と赤い果肉の説明に合わない。"}, "sentence_index": 0, "correct_answer": "西瓜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "西瓜は栗のように鬼皮をむいて、渋皮を取ってから食べる。", "explanation": "ここは〈栗〉の下ごしらえの語感。西瓜には鬼皮や渋皮を取る下ごしらえはないので、この言い方は合わない。"}, {"text": "西瓜は背わたを取ってから、塩を振って湯がく。", "explanation": "ここは〈海老〉の下ごしらえの語感。西瓜に背わたはないので、この処理の言い方は合わない。"}, {"text": "西瓜は皮を薄くむいて、一枚ずつ重ねて、海苔のように乾かす。", "explanation": "ここは〈海苔〉の製法の語感。西瓜は薄く重ねて乾かす食材ではないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": true, "explanation": "水分が九割ほどで味が甘いという説明に合う。"}, {"text": "白米", "is_correct": false, "explanation": "水分が九割もなく、味も甘くないので、文の説明と合わない。"}, {"text": "塩", "is_correct": false, "explanation": "水分がほとんどなく、甘くもないので、文の説明と合わない。"}, {"text": "味噌", "is_correct": false, "explanation": "水分は半分ほどで、甘い果物ではないので文に合わない。"}], "explanations": {"西瓜": "水分が九割ほどで味が甘いという説明に合う。", "白米": "水分が九割もなく、味も甘くないので、文の説明と合わない。", "塩": "水分がほとんどなく、甘くもないので、文の説明と合わない。", "味噌": "水分は半分ほどで、甘い果物ではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "西瓜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "西瓜は干して粉にしてから、小麦粉のように練って生地にする。", "explanation": "ここは〈小麦粉〉の使い方の語感。西瓜を練って生地にするとは言わないので合わない。"}, {"text": "西瓜は水に浮くので、川辺で流しそうめんの船に使う。", "explanation": "ここは〈笹舟〉の語感。西瓜は船として使わず、この使い方は合わない。"}, {"text": "西瓜は豆腐のように重石をのせて水を切り、ごま和えにする。", "explanation": "ここは〈豆腐〉の下ごしらえの語感。西瓜は水切りして和えにする食材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "西瓜を水分が多いので、暑い日にぴったりだ。", "corrected_sentence": "西瓜は水分が多いので、暑い日にぴったりだ。", "error_description": "「水分が多い」の主題は「は」で示す。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑で西瓜が収穫した。", "corrected_sentence": "畑で西瓜が収穫された。", "error_description": "西瓜は収穫される側なので受け身の「された」が必要。「収穫した」は西瓜が収穫する主体になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3361c338-6e56-449e-8b1e-cdcf1bbca704') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
