INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39562, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みのる。花が終わったあとに、たべものになるくだものややさいができること。", "primary_collocate": null, "pronunciation": "みのる", "ipa": "minoɾɯ", "syllable_count": 3, "sentences": [{"text": "秋になると、畑のトマトが赤く実ります。", "target_word": "実ります", "complexity_tier": "T3", "furigana": "秋[あき]になると、畑[はたけ]のトマトが赤[あか]く実[みの]ります。", "sentence_source": "generated"}, {"text": "花が終わったあと、木にりんごが実りました。", "target_word": "実りました", "complexity_tier": "T3", "furigana": "花[はな]が終[お]わったあと、木[き]にりんごが実[みの]りました。", "sentence_source": "generated"}, {"text": "今年は暑かったので、ぶどうがたくさん実っています。", "target_word": "実って", "complexity_tier": "T3", "furigana": "今年[ことし]は暑[あつ]かったので、ぶどうがたくさん実[みの]っています。", "sentence_source": "generated"}, {"text": "庭のなすが実ったので、みんなで食べました。", "target_word": "実った", "complexity_tier": "T3", "furigana": "庭[にわ]のなすが実[みの]ったので、みんなで食[た]べました。", "sentence_source": "generated"}, {"text": "このみかんの木は、毎年冬に実ります。", "target_word": "実ります", "complexity_tier": "T3", "furigana": "このみかんの木[き]は、毎年[まいとし]冬[ふゆ]に実[みの]ります。", "sentence_source": "generated"}, {"text": "雨が少なかったせいで、きゅうりがあまり実りませんでした。", "target_word": "実りませんでした", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なかったせいで、きゅうりがあまり実[みの]りませんでした。", "sentence_source": "generated"}, {"text": "畑にはトウモロコシが実って、収穫を待っています。", "target_word": "実って", "complexity_tier": "T3", "furigana": "畑[はたけ]にはトウモロコシが実[みの]って、収穫[しゅうかく]を待[ま]っています。", "sentence_source": "generated"}, {"text": "春に花が咲いた木には、夏になると緑の小さな果物が実ります。", "target_word": "実ります", "complexity_tier": "T3", "furigana": "春[はる]に花[はな]が咲[さ]いた木[き]には、夏[なつ]になると緑[みどり]の小[ちい]さな果物[くだもの]が実[みの]ります。", "sentence_source": "generated"}, {"text": "実る前の青いトマトは、まだ固くて食べられません。", "target_word": "実る", "complexity_tier": "T3", "furigana": "実[みの]る前[まえ]の青[あお]いトマトは、まだ固[かた]くて食[た]べられません。", "sentence_source": "generated"}, {"text": "去年は台風で落ちましたが、今年は柿がしっかり実りました。", "target_word": "実りました", "complexity_tier": "T3", "furigana": "去年[きょねん]は台風[たいふう]で落[お]ちましたが、今年[ことし]は柿[かき]がしっかり実[みの]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実る", "label": "辞書形"}, {"form": "実り", "label": "連用形"}, {"form": "実って", "label": "て形"}, {"form": "実った", "label": "た形"}, {"form": "実らない", "label": "ない形"}, {"form": "実れば", "label": "仮定形"}], "register": "丁寧", "sense_fingerprint": "花のあとに、果物や野菜が実際にできる植物の変化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faaa67aa-cb63-45cf-9845-a7dc7a4f1e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実ります", "is_correct": true, "explanation": "正解。果実が育って実ることを表し、トマトに合う。"}, {"text": "咲きます", "is_correct": false, "explanation": "花が開く意味で、トマトの果実には使わないので合わない。"}, {"text": "散ります", "is_correct": false, "explanation": "花びらや葉が落ちる意味で、果実には合わない。"}, {"text": "歩きます", "is_correct": false, "explanation": "移動の意味で、植物の果実には合わない。"}], "explanations": {"実ります": "正解。果実が育って実ることを表し、トマトに合う。", "咲きます": "花が開く意味で、トマトの果実には使わないので合わない。", "散ります": "花びらや葉が落ちる意味で、果実には合わない。", "歩きます": "移動の意味で、植物の果実には合わない。"}, "sentence_index": 0, "correct_answer": "実ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏になると、きゅうりのつるがどんどん実ります。", "explanation": "ここは〈伸びる〉の意味。つるは伸びるもので、実るとは言わないので合わない。"}, {"text": "春になると、庭のチューリップが実ります。", "explanation": "ここは〈咲く〉の意味。チューリップは咲くもので、果実ができる「実る」とは言わないので合わない。"}, {"text": "桜の花びらが実って、道がピンク色になりました。", "explanation": "ここは〈散る〉の意味。花びらは散るもので、実るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実って", "is_correct": true, "explanation": "正解。トウモロコシが実って収穫を待つ、という流れに合う。"}, {"text": "枯れて", "is_correct": false, "explanation": "枯れると収穫を待つ意味にならないので合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "植物が眠るとは言わないので合わない。"}, {"text": "沈んで", "is_correct": false, "explanation": "沈むでは収穫の話に合わないので合わない。"}], "explanations": {"実って": "正解。トウモロコシが実って収穫を待つ、という流れに合う。", "枯れて": "枯れると収穫を待つ意味にならないので合わない。", "眠って": "植物が眠るとは言わないので合わない。", "沈んで": "沈むでは収穫の話に合わないので合わない。"}, "sentence_index": 6, "correct_answer": "実って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空に星が実ります。", "explanation": "ここは〈光る〉の意味。星は光るもので、実るとは言わないので合わない。"}, {"text": "暑さで葉が実って、しおれてしまいました。", "explanation": "ここは〈生い茂る〉の意味。葉は茂るもので、実るものではないので合わない。"}, {"text": "オーブンで焼きすぎて、パンが実ってしまいました。", "explanation": "ここは〈焦げる〉の意味。パンは焦げるもので、実るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑をトマトが実ります。", "corrected_sentence": "畑にトマトが実ります。", "error_description": "「実る」は場所を「に」で示す。「畑を」は誤りで、正しくは「畑に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "実りました", "is_correct": true, "explanation": "正解。丁寧な過去形で、過去にりんごが実った事実を表す。"}, {"text": "実らなかった", "is_correct": false, "explanation": "否定の過去形で、りんごが実らなかったという逆の意味になる。"}, {"text": "実らせました", "is_correct": false, "explanation": "使役形で、りんごを主語にする文には合わない。"}, {"text": "実れば", "is_correct": false, "explanation": "仮定形で条件の意味になり、ここでは合わない。"}], "correct_form": "実りました", "base_form": "実る", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"実りました": "正解。丁寧な過去形で、過去にりんごが実った事実を表す。", "実らなかった": "否定の過去形で、りんごが実らなかったという逆の意味になる。", "実らせました": "使役形で、りんごを主語にする文には合わない。", "実れば": "仮定形で条件の意味になり、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ぶどうが秋に実るました。", "corrected_sentence": "ぶどうが秋に実りました。", "error_description": "「ました」の前は連用形「実り」。「実るました」は誤りで、正しくは「実りました」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "実ります", "is_correct": true, "explanation": "正解。丁寧な現在形で、夏に果実が育つ一般的な事実を表す。"}, {"text": "実って", "is_correct": false, "explanation": "て形で、文末がないので単独では文が完結しない。"}, {"text": "実らない", "is_correct": false, "explanation": "否定の普通体で、果実ができないという逆の意味になる。"}, {"text": "実りませんでした", "is_correct": false, "explanation": "丁寧な過去否定で、時制と意味が合わない。"}], "correct_form": "実ります", "base_form": "実る", "form_label": "丁寧な現在形", "sentence_index": 7, "explanations": {"実ります": "正解。丁寧な現在形で、夏に果実が育つ一般的な事実を表す。", "実って": "て形で、文末がないので単独では文が完結しない。", "実らない": "否定の普通体で、果実ができないという逆の意味になる。", "実りませんでした": "丁寧な過去否定で、時制と意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35033a2-3df4-477c-9b1a-3834224515ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「殺虫をする」の「を」で、動作の対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「殺虫へするつもり」は「へ」が動作の対象を示せず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「殺虫がする」は主語と動詞が合わず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「殺虫のするつもり」は「の」で名詞をつなぐ形になり、「する」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「殺虫をする」の「を」で、動作の対象を示す。", "へ": "「殺虫へするつもり」は「へ」が動作の対象を示せず、文が成り立たない。", "が": "「殺虫がする」は主語と動詞が合わず、文が成り立たない。", "の": "「殺虫のするつもり」は「の」で名詞をつなぐ形になり、「する」の目的語にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「殺虫の作業中」の「の」で、直後の名詞を修飾する。"}, {"text": "へ", "is_correct": false, "explanation": "「殺虫へ作業中」は方向の意味になり、修飾の関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「殺虫から作業中」は起点の意味になり、文の構造が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「殺虫を作業中」は「を」が「作業中」の目的語にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「殺虫の作業中」の「の」で、直後の名詞を修飾する。", "へ": "「殺虫へ作業中」は方向の意味になり、修飾の関係が成り立たない。", "から": "「殺虫から作業中」は起点の意味になり、文の構造が合わない。", "を": "「殺虫を作業中」は「を」が「作業中」の目的語にならず、文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語（対象）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "むしを ころす こと。", "primary_collocate": null, "pronunciation": "さっちゅう", "ipa": "sattɕɯː", "syllable_count": 4, "sentences": [{"text": "台所にゴキブリが出たので、すぐに殺虫をした。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "台所[だいどころ]にゴキブリが出[で]たので、すぐに殺虫[さっちゅう]をした。", "sentence_source": "generated"}, {"text": "庭の木に虫が多いから、週末に殺虫をするつもりだ。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]に虫[むし]が多[おお]いから、週末[しゅうまつ]に殺虫[さっちゅう]をするつもりだ。", "sentence_source": "generated"}, {"text": "殺虫の前に、ペットを部屋の外へ出しておいた。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]の前[まえ]に、ペットを部屋[へや]の外[そと]へ出[だ]しておいた。", "sentence_source": "generated"}, {"text": "この部屋は殺虫が終わったばかりで、まだ薬のにおいが強い。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "この部屋[へや]は殺虫[さっちゅう]が終[お]わったばかりで、まだ薬[くすり]のにおいが強[つよ]い。", "sentence_source": "generated"}, {"text": "農家は畑の殺虫に毎年たくさんの時間を使う。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "農家[のうか]は畑[はたけ]の殺虫[さっちゅう]に毎年[まいとし]たくさんの時間[じかん]を使[つか]う。", "sentence_source": "generated"}, {"text": "殺虫をしても、虫はまた次の年に戻ってくる。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]をしても、虫[むし]はまた次[つぎ]の年[とし]に戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "蚊が多い季節になると、近所でも殺虫を始める家が増える。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "蚊[か]が多[おお]い季節[きせつ]になると、近所[きんじょ]でも殺虫[さっちゅう]を始[はじ]める家[いえ]が増[ふ]える。", "sentence_source": "generated"}, {"text": "殺虫の作業中は、窓を開けて空気を入れかえる必要がある。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]の作業中[さぎょうちゅう]は、窓[まど]を開[あ]けて空気[くうき]を入[い]れかえる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "虫を見ても怖がらず、落ち着いて殺虫した。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "虫[むし]を見[み]ても怖[こわ]がらず、落[お]ち着[つ]いて殺虫[さっちゅう]した。", "sentence_source": "generated"}, {"text": "古い倉庫を使う前に、まず殺虫と掃除を済ませた。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "古[ふる]い倉庫[そうこ]を使[つか]う前[まえ]に、まず殺虫[さっちゅう]と掃除[そうじ]を済[す]ませた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殺虫", "label": "基本形"}, {"form": "殺虫する", "label": "サ変動詞形"}, {"form": "殺虫した", "label": "過去形"}, {"form": "殺虫して", "label": "テ形"}], "register": "中立(常体)", "sense_fingerprint": "虫を殺す行為そのもの(一般的な意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殺虫", "is_correct": true, "explanation": "正解。「すぐに殺虫をした」で、虫を殺す行為を表す。"}, {"text": "害虫", "is_correct": false, "explanation": "「害虫をした」は動詞と合わず、文が成り立たない。"}, {"text": "薬剤", "is_correct": false, "explanation": "「薬剤をした」は行為として成り立たず、文の骨組みに合わない。"}, {"text": "網戸", "is_correct": false, "explanation": "「網戸をした」は意味が通らず、「をした」の形にならない。"}], "explanations": {"殺虫": "正解。「すぐに殺虫をした」で、虫を殺す行為を表す。", "害虫": "「害虫をした」は動詞と合わず、文が成り立たない。", "薬剤": "「薬剤をした」は行為として成り立たず、文の骨組みに合わない。", "網戸": "「網戸をした」は意味が通らず、「をした」の形にならない。"}, "sentence_index": 0, "correct_answer": "殺虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まな板を熱湯で殺虫した。", "explanation": "ここは「殺菌」の意味の文。「殺虫」は虫を殺すことなので、まな板の細菌を消す場合には使わない。"}, {"text": "けがをした指を殺虫してから、絆創膏を貼った。", "explanation": "ここは「消毒」の意味の文。「殺虫」は虫が対象なので、傷口の細菌を消す場合には使わない。"}, {"text": "畑にネズミが出たので、わなで殺虫した。", "explanation": "ここは「駆除」の意味の文。「殺虫」は虫が対象なので、ネズミのような動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殺虫", "is_correct": true, "explanation": "正解。「殺虫を始める家が増える」で、虫を殺す行為を表す。"}, {"text": "蚊帳", "is_correct": false, "explanation": "「蚊帳を始める」は道具に動作を始めるとなり、成り立たない。"}, {"text": "霧吹き", "is_correct": false, "explanation": "「霧吹きを始める」は道具の名前で、行為の名詞として合わない。"}, {"text": "窓枠", "is_correct": false, "explanation": "「窓枠を始める」は意味が通らず、動作の名詞として合わない。"}], "explanations": {"殺虫": "正解。「殺虫を始める家が増える」で、虫を殺す行為を表す。", "蚊帳": "「蚊帳を始める」は道具に動作を始めるとなり、成り立たない。", "霧吹き": "「霧吹きを始める」は道具の名前で、行為の名詞として合わない。", "窓枠": "「窓枠を始める」は意味が通らず、動作の名詞として合わない。"}, "sentence_index": 6, "correct_answer": "殺虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "使ったマスクは、捨てる前に殺虫した。", "explanation": "ここは「消毒」の意味の文。「殺虫」は虫が対象なので、マスクの細菌を消す場合には使わない。"}, {"text": "手術の道具は、使う前に殺虫しておく。", "explanation": "ここは「滅菌」の意味の文。「殺虫」は虫が対象なので、道具の細菌を消す場合には使わない。"}, {"text": "町に出たクマを殺虫した。", "explanation": "ここは「退治」の意味の文。「殺虫」は虫が対象なので、クマのような大型の動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴキブリが増えてきたので、来週の土曜に殺虫がするつもりだ。", "corrected_sentence": "ゴキブリが増えてきたので、来週の土曜に殺虫をするつもりだ。", "error_description": "「殺虫がする」は誤り。「する」の動作の対象には「を」を付けるので、「殺虫をする」が正しい。（誤り：が → 正しい：を）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、台所で殺虫するました。", "corrected_sentence": "昨日、台所で殺虫しました。", "error_description": "「するました」は誤り。「する」の連用形は「し」なので、「殺虫しました」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「殺虫のために」の「の」で、直前の語を名詞として修飾する。"}, {"text": "に", "is_correct": false, "explanation": "「殺虫にために」は助詞が重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「殺虫へために」は方向の意味になり、成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「殺虫からために」は起点の意味になり、文の構造が合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「殺虫のために」の「の」で、直前の語を名詞として修飾する。", "に": "「殺虫にために」は助詞が重なり、文が成り立たない。", "へ": "「殺虫へために」は方向の意味になり、成り立たない。", "から": "「殺虫からために」は起点の意味になり、文の構造が合わない。"}, "error_tags": {"に": "方向・相手", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "害虫などの虫を殺すこと。多く「殺虫剤」の形で使う。", "primary_collocate": null, "pronunciation": "さっちゅう", "ipa": "sattɕɯː", "syllable_count": 4, "sentences": [{"text": "害虫が増えたので、野菜の殺虫を急いで行った。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]が増[ふ]えたので、野菜[やさい]の殺虫[さっちゅう]を急[いそ]いで行[おこな]った。", "sentence_source": "generated"}, {"text": "殺虫のために、畑に薬をまくことにした。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]のために、畑[はたけ]に薬[くすり]をまくことにした。", "sentence_source": "generated"}, {"text": "農家にとって、殺虫は収穫を守る大切な仕事だ。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "農家にとって、殺虫[さっちゅう]は収穫を守る大切な仕事だ。", "sentence_source": "generated"}, {"text": "殺虫の効果は強いが、人の体には安全なものを選びたい。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]の効果[こうか]は強[つよ]いが、人[ひと]の体[からだ]には安全[あんぜん]なものを選[えら]びたい。", "sentence_source": "generated"}, {"text": "この薬は殺虫に使われるが、花には使えない。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "この薬[くすり]は殺虫[さっちゅう]に使[つか]われるが、花[はな]には使[つか]えない。", "sentence_source": "generated"}, {"text": "稲に害虫がついたため、村全体で殺虫を行った。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "稲[いね]に害虫[がいちゅう]がついたため、村全体[むらぜんたい]で殺虫[さっちゅう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "殺虫を終えたあと、二日間は畑に入ってはいけない。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]を終[お]えたあと、二日間[ふつかかん]は畑[はたけ]に入[はい]ってはいけない。", "sentence_source": "generated"}, {"text": "温室では害虫が広がりやすく、定期的に殺虫が必要になる。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "温室[おんしつ]では害虫[がいちゅう]が広[ひろ]がりやすく、定期的[ていきてき]に殺虫[さっちゅう]が必要[ひつよう]になる。", "sentence_source": "generated"}, {"text": "殺虫を怠ると、果物が虫に食べられてしまう。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "殺虫[さっちゅう]を怠[おこた]ると、果物[くだもの]が虫[むし]に食[た]べられてしまう。", "sentence_source": "generated"}, {"text": "毛虫が増える前に、公園の木に殺虫を行った。", "target_word": "殺虫", "complexity_tier": "T3", "furigana": "毛虫[けむし]が増[ふ]える前[まえ]に、公園[こうえん]の木[き]に殺虫[さっちゅう]を行[おこな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "殺虫", "label": "基本形"}, {"form": "殺虫する", "label": "サ変動詞形"}, {"form": "殺虫された", "label": "受身の過去形"}, {"form": "殺虫して", "label": "テ形"}], "register": "中立(常体)", "sense_fingerprint": "害虫を駆除するために虫を殺すこと(農業・薬剤の文脈)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殺虫", "is_correct": true, "explanation": "正解。「野菜の殺虫を急いで行った」で、害虫を殺す作業を表す。"}, {"text": "畑", "is_correct": false, "explanation": "「畑を急いで行った」は行為の名詞として成り立たない。"}, {"text": "肥料", "is_correct": false, "explanation": "「肥料を行った」は動詞と合わず、文が成り立たない。"}, {"text": "種", "is_correct": false, "explanation": "「種を行った」は作業の名詞として意味が通らない。"}], "explanations": {"殺虫": "正解。「野菜の殺虫を急いで行った」で、害虫を殺す作業を表す。", "畑": "「畑を急いで行った」は行為の名詞として成り立たない。", "肥料": "「肥料を行った」は動詞と合わず、文が成り立たない。", "種": "「種を行った」は作業の名詞として意味が通らない。"}, "sentence_index": 0, "correct_answer": "殺虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の雑草を殺虫して、きれいにした。", "explanation": "ここは「除草」の意味の文。「殺虫」は虫が対象なので、雑草を取り除く場合には使わない。"}, {"text": "水道水を殺虫してから、飲料に使う。", "explanation": "ここは「消毒」の意味の文。「殺虫」は虫を殺す意味なので、水中の細菌には使わない。"}, {"text": "庭に来たカラスを殺虫するため、わなを仕掛けた。", "explanation": "ここは「駆除」の意味の文。「殺虫」は虫が対象なので、カラスのような鳥には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殺虫", "is_correct": true, "explanation": "正解。「殺虫を終えたあと」で、害虫を殺す作業を表す。"}, {"text": "花壇", "is_correct": false, "explanation": "「花壇を終えた」は場所の名詞で、作業の名詞として成り立たない。"}, {"text": "苗", "is_correct": false, "explanation": "「苗を終えた」は植物の名詞で、作業の名詞として意味が通らない。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草を終えた」は対象の名詞で、作業の名詞として成り立たない。"}], "explanations": {"殺虫": "正解。「殺虫を終えたあと」で、害虫を殺す作業を表す。", "花壇": "「花壇を終えた」は場所の名詞で、作業の名詞として成り立たない。", "苗": "「苗を終えた」は植物の名詞で、作業の名詞として意味が通らない。", "雑草": "「雑草を終えた」は対象の名詞で、作業の名詞として成り立たない。"}, "sentence_index": 6, "correct_answer": "殺虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食器は熱湯で殺虫してから使う。", "explanation": "ここは「殺菌」の意味の文。「殺虫」は虫が対象なので、食器の細菌を消す場合には使わない。"}, {"text": "実験器具は、使う前に殺虫しておく。", "explanation": "ここは「滅菌」の意味の文。「殺虫」は虫を殺す意味なので、細菌やウイルスには使わない。"}, {"text": "畑に出たイノシシを殺虫した。", "explanation": "ここは「退治」の意味の文。「殺虫」は虫が対象なので、イノシシのような大型の動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "果樹園で殺虫に行うことにした。", "corrected_sentence": "果樹園で殺虫を行うことにした。", "error_description": "「殺虫に行う」は誤り。「行う」は動作の対象に「を」を付けるので、「殺虫を行う」が正しい。（誤り：に → 正しい：を）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "殺虫しで二日たつまでは、畑に入らないでください。", "corrected_sentence": "殺虫して二日たつまでは、畑に入らないでください。", "error_description": "「しで」は誤り。「する」のて形は「して」なので、「殺虫して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「咲いた」の主語「チューリップ」に付く格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「咲く」は自動詞なので、目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "場所や時点を示す助詞で、ここは主語の位置なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、ここには移動の方向がなく、主語の位置にも入らない。"}], "correct_answer": "が", "explanations": {"が": "「咲いた」の主語「チューリップ」に付く格助詞。", "を": "「咲く」は自動詞なので、目的語の「を」は取れない。", "に": "場所や時点を示す助詞で、ここは主語の位置なので合わない。", "へ": "方向を示すが、ここには移動の方向がなく、主語の位置にも入らない。"}, "error_tags": {"を": "目的語（自動詞に付かない）", "に": "場所（主語の位置ではない）", "へ": "方向（移動の意味がない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "しぼむ", "is_correct": true, "explanation": "花がひらく状態の反対で、花が縮んで閉じることを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "休息を表す動詞で、花のひらく・しぼむの対義語ではない。"}, {"text": "煮る", "is_correct": false, "explanation": "料理の動作で、花の状態とは関係がない。"}, {"text": "光る", "is_correct": false, "explanation": "明るく輝く意味で、花がひらく・しぼむの対義語ではない。"}], "correct_answer": "しぼむ", "explanations": {"しぼむ": "花がひらく状態の反対で、花が縮んで閉じることを表す。", "眠る": "休息を表す動詞で、花のひらく・しぼむの対義語ではない。", "煮る": "料理の動作で、花の状態とは関係がない。", "光る": "明るく輝く意味で、花がひらく・しぼむの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "しぼむ", "is_correct": true, "explanation": "花がひらく状態の反対で、花が縮んで閉じることを表す。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動詞で、花の開花の対義語ではない。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を下げる他動詞で、花の状態とは関係がない。"}, {"text": "泣く", "is_correct": false, "explanation": "感情の動作で、花のひらく・しぼむの対義語ではない。"}], "correct_answer": "しぼむ", "explanations": {"しぼむ": "花がひらく状態の反対で、花が縮んで閉じることを表す。", "歩く": "移動の動詞で、花の開花の対義語ではない。", "冷やす": "温度を下げる他動詞で、花の状態とは関係がない。", "泣く": "感情の動作で、花のひらく・しぼむの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "花がひらくことです。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "春になると、公園の桜が一斉に咲く。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]の桜[さくら]が一斉[いっせい]に咲[さ]く。", "sentence_source": "generated"}, {"text": "庭のチューリップが昨日やっと咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "庭[にわ]のチューリップが昨日[きのう]やっと咲[さ]いた。", "sentence_source": "generated"}, {"text": "朝顔は朝に咲いて、昼にはしぼんでしまう。", "target_word": "咲いて", "complexity_tier": "T3", "furigana": "朝顔[あさがお]は朝[あさ]に咲[さ]いて、昼[ひる]にはしぼんでしまう。", "sentence_source": "generated"}, {"text": "道のそばに小さな黄色い花が咲いている。", "target_word": "咲いている", "complexity_tier": "T3", "furigana": "道[みち]のそばに小[ちい]さな黄色[きいろ]い花[はな]が咲[さ]いている。", "sentence_source": "generated"}, {"text": "寒すぎて、今年は梅がなかなか咲かない。", "target_word": "咲かない", "complexity_tier": "T3", "furigana": "寒[さむ]すぎて、今年[ことし]は梅[うめ]がなかなか咲[さ]かない。", "sentence_source": "generated"}, {"text": "暖かい日が続けば、桜はすぐに咲くだろう。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "暖[あたた]かい日[ひ]が続[つづ]けば、桜[さくら]はすぐに咲[さ]くだろう。", "sentence_source": "generated"}, {"text": "ひまわりは夏の強い日ざしの中で大きく咲く。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "ひまわりは夏[なつ]の強[つよ]い日[ひ]ざしの中[なか]で大[おお]きく咲[さ]く。", "sentence_source": "generated"}, {"text": "母が育てているバラが、ベランダでみごとに咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "母[はは]が育[そだ]てているバラが、ベランダでみごとに咲[さ]いた。", "sentence_source": "generated"}, {"text": "花が咲く前に、雨で枝が折れてしまった。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "花[はな]が咲[さ]く前[まえ]に、雨[あめ]で枝[えだ]が折[お]れてしまった。", "sentence_source": "generated"}, {"text": "去年は咲かなかった花が、今年は庭いっぱいに咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "去年[きょねん]は咲[さ]かなかった花[はな]が、今年[ことし]は庭[にわ]いっぱいに咲[さ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "咲く", "label": "基本形"}, {"form": "咲き", "label": "連用形"}, {"form": "咲いて", "label": "テ形"}, {"form": "咲いた", "label": "過去形"}, {"form": "咲かない", "label": "ない形"}, {"form": "咲けば", "label": "仮定形"}, {"form": "咲こう", "label": "意志形"}], "register": "中立(常体)", "sense_fingerprint": "花がひらく(自然の花の開花)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咲く", "is_correct": true, "explanation": "「春になると」は毎年の習慣を表すので、現在形の終止形「咲く」が文を言い切る。"}, {"text": "咲いて", "is_correct": false, "explanation": "テ形は文を言い切れない。「桜が一斉に咲いて。」では文が終わらない。"}, {"text": "咲き", "is_correct": false, "explanation": "連用形は文末にならず、ここでは文が途中で切れてしまう。"}, {"text": "咲こう", "is_correct": false, "explanation": "意志形は話し手の意志を表す。自然の開花を述べる習慣の文には合わない。"}], "explanations": {"咲く": "「春になると」は毎年の習慣を表すので、現在形の終止形「咲く」が文を言い切る。", "咲いて": "テ形は文を言い切れない。「桜が一斉に咲いて。」では文が終わらない。", "咲き": "連用形は文末にならず、ここでは文が途中で切れてしまう。", "咲こう": "意志形は話し手の意志を表す。自然の開花を述べる習慣の文には合わない。"}, "sentence_index": 0, "correct_answer": "咲く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋になって、山の木々が一斉に咲いた。", "explanation": "ここは〈紅葉する〉の意味。木々は花のように開くのではなく葉の色が変わるので、〈咲く〉は合わない。"}, {"text": "道のそばに、黄色い柿が咲いている。", "explanation": "柿は花がひらくのではなく実るものなので、〈咲く〉は合わない。〈実る〉が正しい。"}, {"text": "道のそばに、小さな黄色い葉が咲いている。", "explanation": "葉は花のように開くのではなく、芽が出て茂るものなので〈咲く〉とは言わない。〈茂る〉が合う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咲く", "is_correct": true, "explanation": "夏の日ざしの中で大きく咲くという事実を述べる、現在形の終止形「咲く」。"}, {"text": "咲け", "is_correct": false, "explanation": "命令形で、事実を述べる文には合わない。"}, {"text": "咲かず", "is_correct": false, "explanation": "否定の連用形で、文を終えられない。"}, {"text": "咲かせ", "is_correct": false, "explanation": "使役の連用形で、文末にならない。ここでは文が途中で切れてしまう。"}], "explanations": {"咲く": "夏の日ざしの中で大きく咲くという事実を述べる、現在形の終止形「咲く」。", "咲け": "命令形で、事実を述べる文には合わない。", "咲かず": "否定の連用形で、文を終えられない。", "咲かせ": "使役の連用形で、文末にならない。ここでは文が途中で切れてしまう。"}, "sentence_index": 6, "correct_answer": "咲く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年は庭の木の新芽が一斉に咲いた。", "explanation": "ここは〈芽吹く〉の意味。新芽は花のように開くものではないので、〈咲く〉は合わない。"}, {"text": "夕方、窓の外の空が一面に咲いた。", "explanation": "ここは〈開ける〉の意味。空は花のように開くものではなく、雲が切れて広がるので〈咲く〉は合わない。"}, {"text": "寒い朝、庭の芝生が一面に咲いた。", "explanation": "ここは〈生え揃う〉の意味。芝生は花を咲かせるものではなく、生え広がるものなので〈咲く〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の朝、庭のアサガオが咲きて、昼にはしぼんでしまう。", "corrected_sentence": "夏の朝、庭のアサガオが咲いて、昼にはしぼんでしまう。", "error_description": "五段動詞「咲く」のテ形は「咲いて」。「咲きて」は連用形に「て」を付けた誤った形で、語形として存在しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "咲いた", "is_correct": true, "explanation": "「やっと」は過去の出来事を表すので、過去形「咲いた」が正しい。"}, {"text": "咲いて", "is_correct": false, "explanation": "テ形は文を終えられない。「昨日やっと咲いて。」では文が完結しない。"}, {"text": "咲かない", "is_correct": false, "explanation": "否定形にすると「咲かなかった」の意味になり、チューリップが咲いたという事実と逆になる。"}, {"text": "咲けば", "is_correct": false, "explanation": "仮定形で、確定した事実「昨日やっと咲いた」を述べる文には合わない。"}], "correct_form": "咲いた", "base_form": "咲く", "form_label": "過去形", "sentence_index": 1, "explanations": {"咲いた": "「やっと」は過去の出来事を表すので、過去形「咲いた」が正しい。", "咲いて": "テ形は文を終えられない。「昨日やっと咲いて。」では文が完結しない。", "咲かない": "否定形にすると「咲かなかった」の意味になり、チューリップが咲いたという事実と逆になる。", "咲けば": "仮定形で、確定した事実「昨日やっと咲いた」を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39570, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭のひまわりを大きく咲いた。", "corrected_sentence": "庭のひまわりが大きく咲いた。", "error_description": "「咲く」は自動詞なので、動作の主体（主語）には「が」を付ける。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "咲いた", "is_correct": true, "explanation": "「みごとに」を伴う過去の開花の描写なので、過去形「咲いた」が合う。"}, {"text": "咲こう", "is_correct": false, "explanation": "意志形で、すでに起きた開花を描写する文には合わない。"}, {"text": "咲き", "is_correct": false, "explanation": "連用形で文末にならず、この文は言い切れない。"}, {"text": "咲かず", "is_correct": false, "explanation": "否定の連用形で、ここでは文が途中で切れてしまう。"}], "correct_form": "咲いた", "base_form": "咲く", "form_label": "過去形", "sentence_index": 7, "explanations": {"咲いた": "「みごとに」を伴う過去の開花の描写なので、過去形「咲いた」が合う。", "咲こう": "意志形で、すでに起きた開花を描写する文には合わない。", "咲き": "連用形で文末にならず、この文は言い切れない。", "咲かず": "否定の連用形で、ここでは文が途中で切れてしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「咲いていた」の主語「つぼみ」に付く格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「咲く」は自動詞なので、目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "場所や時点を示す助詞で、主語の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、ここでは「つぼみで咲いていた」となり意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「咲いていた」の主語「つぼみ」に付く格助詞。", "を": "「咲く」は自動詞なので、目的語の「を」は取れない。", "に": "場所や時点を示す助詞で、主語の位置には入らない。", "で": "場所や手段を示すが、ここでは「つぼみで咲いていた」となり意味が通らない。"}, "error_tags": {"を": "目的語（自動詞に付かない）", "に": "場所（主語の位置ではない）", "で": "場所・手段（主語の位置ではない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つぼむ", "is_correct": true, "explanation": "つぼみが開く変化の反対で、花が閉じてつぼみの状態に戻ることを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "休息を表す動詞で、花の開く・閉じるの対義語ではない。"}, {"text": "煮る", "is_correct": false, "explanation": "料理の動作で、花の変化とは無関係。"}, {"text": "光る", "is_correct": false, "explanation": "明るく輝く意味で、開花の対義語ではない。"}], "correct_answer": "つぼむ", "explanations": {"つぼむ": "つぼみが開く変化の反対で、花が閉じてつぼみの状態に戻ることを表す。", "眠る": "休息を表す動詞で、花の開く・閉じるの対義語ではない。", "煮る": "料理の動作で、花の変化とは無関係。", "光る": "明るく輝く意味で、開花の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "花のつぼみが開いて、花びらが見えるようになる。", "primary_collocate": null, "pronunciation": "さく", "ipa": "sakɯ", "syllable_count": 2, "sentences": [{"text": "つぼみがふくらんで、やがて白い花が咲く。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "つぼみがふくらんで、やがて白[しろ]い花[はな]が咲[さ]く。", "sentence_source": "generated"}, {"text": "朝、ベランダに出ると、昨夜まで固かったつぼみが咲いていた。", "target_word": "咲いていた", "complexity_tier": "T3", "furigana": "朝[あさ]、ベランダに出[で]ると、昨夜[さくや]まで固[かた]かったつぼみが咲[さ]いていた。", "sentence_source": "generated"}, {"text": "水をやり続けたら、とうとうサボテンにも花が咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "水[みず]をやり続[つづ]けたら、とうとうサボテンにも花[はな]が咲[さ]いた。", "sentence_source": "generated"}, {"text": "二月の寒い朝、庭の梅が咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "二月[にがつ]の寒[さむ]い朝[あさ]、庭[にわ]の梅[うめ]が咲[さ]いた。", "sentence_source": "generated"}, {"text": "この花は夜になってから咲くので、昼間は見られない。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "この花[はな]は夜[よる]になってから咲[さ]くので、昼間[ひるま]は見[み]られない。", "sentence_source": "generated"}, {"text": "つぼみのうちは緑色だが、咲くと鮮やかな赤になる。", "target_word": "咲く", "complexity_tier": "T3", "furigana": "つぼみのうちは緑色[みどりいろ]だが、咲[さ]くと鮮[あざ]やかな赤[あか]になる。", "sentence_source": "generated"}, {"text": "去年植えた球根から、ようやく水仙が咲いた。", "target_word": "咲いた", "complexity_tier": "T3", "furigana": "去年[きょねん]植[う]えた球根[きゅうこん]から、ようやく水仙[すいせん]が咲[さ]いた。", "sentence_source": "generated"}, {"text": "日当たりが悪いと、花はきれいに咲かないことが多い。", "target_word": "咲かない", "complexity_tier": "T3", "furigana": "日当[ひあ]たりが悪[わる]いと、花[はな]はきれいに咲[さ]かないことが多[おお]い。", "sentence_source": "generated"}, {"text": "満開に咲いている花を、近くで写真に撮った。", "target_word": "咲いている", "complexity_tier": "T3", "furigana": "満開[まんかい]に咲[さ]いている花[はな]を、近[ちか]くで写真[しゃしん]に撮[と]った。", "sentence_source": "generated"}, {"text": "雨がやんだ後、公園のあじさいが咲きはじめた。", "target_word": "咲きはじめた", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだ後[あと]、公園[こうえん]のあじさいが咲[さ]きはじめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "咲く", "label": "基本形"}, {"form": "咲き", "label": "連用形"}, {"form": "咲いて", "label": "テ形"}, {"form": "咲いた", "label": "過去形"}, {"form": "咲かない", "label": "ない形"}, {"form": "咲けば", "label": "仮定形"}, {"form": "咲こう", "label": "意志形"}], "register": "中立(常体)", "sense_fingerprint": "つぼみが開いて花びらが見えるようになる(開花の変化)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7027329f-781d-4983-bb14-05a931bba1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咲く", "is_correct": true, "explanation": "つぼみから花がひらく変化を、現在形の終止形「咲く」で言い切る。"}, {"text": "咲いて", "is_correct": false, "explanation": "テ形は文を言い切れない。「やがて白い花が咲いて。」では文が終わらない。"}, {"text": "咲き", "is_correct": false, "explanation": "連用形は文末にならず、ここでは文が途中で切れてしまう。"}, {"text": "咲こう", "is_correct": false, "explanation": "意志形は話し手の意志を表す。自然の変化を描写する文には合わない。"}], "explanations": {"咲く": "つぼみから花がひらく変化を、現在形の終止形「咲く」で言い切る。", "咲いて": "テ形は文を言い切れない。「やがて白い花が咲いて。」では文が終わらない。", "咲き": "連用形は文末にならず、ここでは文が途中で切れてしまう。", "咲こう": "意志形は話し手の意志を表す。自然の変化を描写する文には合わない。"}, "sentence_index": 0, "correct_answer": "咲く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事を終えて、みんなの顔が咲いた。", "explanation": "ここは〈ほころぶ〉の意味。顔は花のように開くものではなく、表情がゆるむので〈咲く〉は合わない。"}, {"text": "秋、庭の柿の木に実が咲いた。", "explanation": "ここは〈実る〉の意味。実は花のように開くのではなく実るものなので、〈咲く〉は合わない。"}, {"text": "雨の後、庭の石に苔が咲いた。", "explanation": "ここは〈生える〉の意味。苔は花を咲かせず、生えて広がるものなので〈咲く〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咲いた", "is_correct": true, "explanation": "「去年植えた」から「ようやく」という過去の出来事を述べる過去形。"}, {"text": "咲け", "is_correct": false, "explanation": "命令形で、経過を報告する文には合わない。"}, {"text": "咲かず", "is_correct": false, "explanation": "否定の連用形で、文を終えられない。"}, {"text": "咲かせ", "is_correct": false, "explanation": "使役の連用形で、文末にならない。"}], "explanations": {"咲いた": "「去年植えた」から「ようやく」という過去の出来事を述べる過去形。", "咲け": "命令形で、経過を報告する文には合わない。", "咲かず": "否定の連用形で、文を終えられない。", "咲かせ": "使役の連用形で、文末にならない。"}, "sentence_index": 6, "correct_answer": "咲いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨がやんだ後、公園の木の新芽が咲きはじめた。", "explanation": "ここは〈芽吹く〉の意味。新芽は花のように開くものではないので、〈咲く〉は合わない。"}, {"text": "雨がやんだ後、公園の池の水面が咲きはじめた。", "explanation": "ここは〈広がる〉の意味。水面は花のように開くものではなく、波紋が広がるので〈咲く〉は合わない。"}, {"text": "雨がやんだ後、公園の芝生が咲きはじめた。", "explanation": "ここは〈生え揃う〉の意味。芝生は花を咲かせるものではなく、生え揃うものなので〈咲く〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "固いつぼみがふくらんで、やがて白い花が咲きる。", "corrected_sentence": "固いつぼみがふくらんで、やがて白い花が咲く。", "error_description": "五段動詞「咲く」の終止形は「咲く」。「咲きる」は存在しない誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "咲いていた", "is_correct": true, "explanation": "「昨夜まで固かった」と比べた過去の状態なので、過去の「ていた」形が合う。"}, {"text": "咲いたら", "is_correct": false, "explanation": "条件形で、ここでは文が途中で切れてしまい述語として成立しない。"}, {"text": "咲いていない", "is_correct": false, "explanation": "否定なので、朝につぼみが咲いていた事実と反する。"}, {"text": "咲かなかった", "is_correct": false, "explanation": "過去の否定で、つぼみが咲いていたという事実と反する。"}], "correct_form": "咲いていた", "base_form": "咲く", "form_label": "ていた形", "sentence_index": 1, "explanations": {"咲いていた": "「昨夜まで固かった」と比べた過去の状態なので、過去の「ていた」形が合う。", "咲いたら": "条件形で、ここでは文が途中で切れてしまい述語として成立しない。", "咲いていない": "否定なので、朝につぼみが咲いていた事実と反する。", "咲かなかった": "過去の否定で、つぼみが咲いていたという事実と反する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39571, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、庭のあじさいを咲きはじめた。", "corrected_sentence": "夕方、庭のあじさいが咲きはじめた。", "error_description": "「咲きはじめる」は自動詞。主語の「あじさい」には「が」を付ける。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "咲かない", "is_correct": true, "explanation": "「〜ことが多い」に続く否定形で、咲かないことが多いという一般的な傾向を述べる。"}, {"text": "咲けば", "is_correct": false, "explanation": "仮定形で、「花はきれいに〜ないことが多い」という傾向の文には合わない。"}, {"text": "咲いた", "is_correct": false, "explanation": "「咲いたことが多い」は文法的には成立するが、日当たりが悪いと咲かないという文意と逆になるので誤り。"}, {"text": "咲こう", "is_correct": false, "explanation": "意志形で、事実の傾向を述べる文には合わない。"}], "correct_form": "咲かない", "base_form": "咲く", "form_label": "否定形", "sentence_index": 7, "explanations": {"咲かない": "「〜ことが多い」に続く否定形で、咲かないことが多いという一般的な傾向を述べる。", "咲けば": "仮定形で、「花はきれいに〜ないことが多い」という傾向の文には合わない。", "咲いた": "「咲いたことが多い」は文法的には成立するが、日当たりが悪いと咲かないという文意と逆になるので誤り。", "咲こう": "意志形で、事実の傾向を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd28592-cbc0-45fd-b14a-bebd7286389c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『取り入れる』は他動詞で、取り入れる対象の〈農法〉を示すので『を』が入る。"}, {"text": "が", "is_correct": false, "explanation": "『取り入れる』は他動詞なので、目的語には『を』が要る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、『取り入れる』の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「取り入れた」の目的語を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『取り入れる』は他動詞で、取り入れる対象の〈農法〉を示すので『を』が入る。", "が": "『取り入れる』は他動詞なので、目的語には『を』が要る。", "へ": "方向を表すが、『取り入れる』の目的語にはならない。", "の": "連体修飾の助詞で、「取り入れた」の目的語を示せず、文が成り立たない。"}, "error_tags": {"が": "『取り入れる』は他動詞なので、目的語には『を』が要る。", "へ": "方向を表すが、『取り入れる』の目的語にはならない。", "の": "連体修飾の助詞で、「取り入れた」の目的語を示せず、文が成り立たない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "畑での作物の育て方です。", "primary_collocate": null, "pronunciation": "のうほう", "ipa": "noːhoː", "syllable_count": 4, "sentences": [{"text": "この地域では、昔ながらの農法で野菜を育てている。", "target_word": "農法", "complexity_tier": "T3", "furigana": "この地域(ちいき)では、昔(むかし)ながらの農法(のうほう)で野菜(やさい)を育(そだ)てている。", "sentence_source": "generated"}, {"text": "雨が少ないので、水を節約する農法が広まった。", "target_word": "農法", "complexity_tier": "T3", "furigana": "雨(あめ)が少(すく)ないので、水(みず)を節約(せつやく)する農法(のうほう)が広(ひろ)まった。", "sentence_source": "generated"}, {"text": "祖父は化学肥料を使わない農法にこだわっている。", "target_word": "農法", "complexity_tier": "T3", "furigana": "祖父(そふ)は化学肥料(かがくひりょう)を使(つか)わない農法(のうほう)にこだわっている。", "sentence_source": "generated"}, {"text": "新しい農法を試したところ、畑の収穫が二倍になった。", "target_word": "農法", "complexity_tier": "T3", "furigana": "新(あたら)しい農法(のうほう)を試(ため)したところ、畑(はたけ)の収穫(しゅうかく)が二倍(にばい)になった。", "sentence_source": "generated"}, {"text": "農法が変わると、畑の景色も変わる。", "target_word": "農法", "complexity_tier": "T3", "furigana": "農法(のうほう)が変(か)わると、畑(はたけ)の景色(けしき)も変(か)わる。", "sentence_source": "generated"}, {"text": "山の斜面では、段々畑での農法が昔から受け継がれてきた。", "target_word": "農法", "complexity_tier": "T3", "furigana": "やまのしゃめんでは、だんだんばたけでのうほうがむかしからうけつがれてきた。", "sentence_source": "generated"}, {"text": "同じ作物ばかり作ると土が弱るので、農法を工夫する必要がある。", "target_word": "農法", "complexity_tier": "T3", "furigana": "同(おな)じ作物(さくもつ)ばかり作(つく)ると土(つち)が弱(よわ)るので、農法(のうほう)を工夫(くふう)する必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "彼は外国で学んだ農法を日本の畑に取り入れた。", "target_word": "農法", "complexity_tier": "T3", "furigana": "彼(かれ)は外国(がいこく)で学(まな)んだ農法(のうほう)を日本(にほん)の畑(はたけ)に取(と)り入(い)れた。", "sentence_source": "generated"}, {"text": "農法の違いで、同じ米でも味が少し変わるそうだ。", "target_word": "農法", "complexity_tier": "T3", "furigana": "農法(のうほう)の違(ちが)いで、同(おな)じ米(こめ)でも味(あじ)が少(すこ)し変(か)わるそうだ。", "sentence_source": "generated"}, {"text": "農家の人が集まって、それぞれの農法について話し合った。", "target_word": "農法", "complexity_tier": "T3", "furigana": "農家(のうか)の人(ひと)が集(あつ)まって、それぞれの農法(のうほう)について話(はな)し合(あ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農法", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "畑で作物を育てるやり方。地域や考え方による育て方の違い。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農夫", "is_correct": false, "explanation": "人を表す語で、「〜で野菜を育てる」の手段にはならない。"}, {"text": "害虫", "is_correct": false, "explanation": "野菜を荒らす虫で、育て方を表さないのでここには入らない。"}, {"text": "砂利", "is_correct": false, "explanation": "土をおおう石で、野菜の育て方の手段としては成り立たない。"}, {"text": "農法", "is_correct": true, "explanation": "ここは「育て方」を表す〈農法〉が入る。"}], "explanations": {"農夫": "人を表す語で、「〜で野菜を育てる」の手段にはならない。", "害虫": "野菜を荒らす虫で、育て方を表さないのでここには入らない。", "砂利": "土をおおう石で、野菜の育て方の手段としては成り立たない。", "農法": "ここは「育て方」を表す〈農法〉が入る。"}, "sentence_index": 0, "correct_answer": "農法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農法は、毎朝早く畑に出かけて汗を流している。", "explanation": "ここは〈農家〉（人）の意味。農法は方法なので、畑に出かけて働くことはできない。"}, {"text": "この畑では農法を植えている。", "explanation": "ここは〈作物〉の意味。作物は植えるものだが、農法は育て方なので植えられない。"}, {"text": "父は農法を営んで、家族を養っている。", "explanation": "ここは〈農業〉（仕事）の意味。「営む」は仕事や商売に使うので、育て方の農法には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農家", "is_correct": false, "explanation": "人や家を表し、「工夫する」の対象にはならない。"}, {"text": "雑草", "is_correct": false, "explanation": "畑に生える草で、工夫の対象としては成り立たない。"}, {"text": "夕立", "is_correct": false, "explanation": "天気の現象で、「工夫する」の対象にはならない。"}, {"text": "農法", "is_correct": true, "explanation": "ここは育て方の〈農法〉が入り、工夫する対象になる。"}], "explanations": {"農家": "人や家を表し、「工夫する」の対象にはならない。", "雑草": "畑に生える草で、工夫の対象としては成り立たない。", "夕立": "天気の現象で、「工夫する」の対象にはならない。", "農法": "ここは育て方の〈農法〉が入り、工夫する対象になる。"}, "sentence_index": 6, "correct_answer": "農法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑に農法をまいて、草が育つのを待った。", "explanation": "ここは〈肥料〉の意味。肥料は畑にまくが、農法は方法なのでまけない。"}, {"text": "祖父は隣の農法を耕して、毎年米を作っている。", "explanation": "ここは〈農地〉の意味。田畑は耕すが、育て方の農法は耕せないので合わない。"}, {"text": "彼は手先の農法がすばらしく、時計も直せる。", "explanation": "ここは〈技術〉の意味。手先の腕前を指す語なので、育て方の農法には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この農法を地域に広まった。", "corrected_sentence": "この農法が地域に広まった。", "error_description": "『農法』に続く助詞が『を』になっている。『広まる』は自動詞なので、主語を示す『が』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農家は新しい農法に試した。", "corrected_sentence": "農家は新しい農法を試した。", "error_description": "『農法』に続く助詞が『に』になっている。『試す』は他動詞なので目的語を示す『を』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この農法は」と主題を示す「は」が入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、ここは主題の位置で、「は」の代わりにはならない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、主題の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、ここでは主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "「この農法は」と主題を示す「は」が入る。", "を": "目的語を示す助詞だが、ここは主題の位置で、「は」の代わりにはならない。", "に": "場所や相手を示すが、主題の位置には入らない。", "と": "並列や相手を示すが、ここでは主題にはならない。"}, "error_tags": {"を": "目的語を示す助詞だが、ここは主題の位置で、「は」の代わりにはならない。", "に": "場所や相手を示すが、主題の位置には入らない。", "と": "並列や相手を示すが、ここでは主題にはならない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「昔と今の農法を比べる」と、比べる対象を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "『比べる』の目的語は『を』で、『が』は付かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「比べる」の対象は示せず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、述語『比べる』の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「昔と今の農法を比べる」と、比べる対象を示す「を」が入る。", "が": "『比べる』の目的語は『を』で、『が』は付かない。", "へ": "方向を表すが、「比べる」の対象は示せず文が成り立たない。", "の": "連体修飾の助詞で、述語『比べる』の目的語にはならない。"}, "error_tags": {"が": "『比べる』の目的語は『を』で、『が』は付かない。", "の": "連体修飾の助詞で、述語『比べる』の目的語にはならない。", "へ": "方向を表すが、「比べる」の対象は示せず文が成り立たない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "作物を育てるための方法や技術のことです。", "primary_collocate": null, "pronunciation": "のうほう", "ipa": "noːhoː", "syllable_count": 4, "sentences": [{"text": "寒い土地に合った農法を研究している大学がある。", "target_word": "農法", "complexity_tier": "T3", "furigana": "寒(さむ)い土地(とち)に合(あ)った農法(のうほう)を研究(けんきゅう)している大学(だいがく)がある。", "sentence_source": "generated"}, {"text": "この農法は、農薬を使わずに害虫を防ぐ技術だ。", "target_word": "農法", "complexity_tier": "T3", "furigana": "この農法(のうほう)は、農薬(のうやく)を使(つか)わずに害虫(がいちゅう)を防(ふせ)ぐ技術(ぎじゅつ)だ。", "sentence_source": "generated"}, {"text": "昔の農法は人の手に頼る作業が多かった。", "target_word": "農法", "complexity_tier": "T3", "furigana": "昔(むかし)の農法(のうほう)は人(ひと)の手(て)に頼(たよ)る作業(さぎょう)が多(おお)かった。", "sentence_source": "generated"}, {"text": "農法を学ぶために、彼女は一年間農家で働いた。", "target_word": "農法", "complexity_tier": "T3", "furigana": "農法(のうほう)を学(まな)ぶために、彼女(かのじょ)は一年間(いちねんかん)農家(のうか)で働(はたら)いた。", "sentence_source": "generated"}, {"text": "機械を使う農法のおかげで、少ない人数でも広い土地を耕せる。", "target_word": "農法", "complexity_tier": "T3", "furigana": "機械(きかい)を使(つか)う農法(のうほう)のおかげで、少(すく)ない人数(にんずう)でも広(ひろ)い土地(とち)を耕(たがや)せる。", "sentence_source": "generated"}, {"text": "伝統的な農法を守る農家が少なくなってきている。", "target_word": "農法", "complexity_tier": "T3", "furigana": "伝統的(でんとうてき)な農法(のうほう)を守(まも)る農家(のうか)が少(すく)なくなってきている。", "sentence_source": "generated"}, {"text": "国によって気候が違うので、農法も同じではない。", "target_word": "農法", "complexity_tier": "T3", "furigana": "国(くに)によって気候(きこう)が違(ちが)うので、農法(のうほう)も同(おな)じではない。", "sentence_source": "generated"}, {"text": "先生は、昔と今の農法を比べる授業をした。", "target_word": "農法", "complexity_tier": "T3", "furigana": "先生(せんせい)は、昔(むかし)と今(いま)の農法(のうほう)を比(くら)べる授業(じゅぎょう)をした。", "sentence_source": "generated"}, {"text": "環境にやさしい農法が、若い農家に人気がある。", "target_word": "農法", "complexity_tier": "T3", "furigana": "環境(かんきょう)にやさしい農法(のうほう)が、若(わか)い農家(のうか)に人気(にんき)がある。", "sentence_source": "generated"}, {"text": "農法を変えたことで、土の状態がよくなった。", "target_word": "農法", "complexity_tier": "T3", "furigana": "農法(のうほう)を変(か)えたことで、土(つち)の状態(じょうたい)がよくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農法", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "作物を育てる方法・技術の体系。研究や伝統、環境との関わりで語られる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "花をさす器で、土地に合った研究の対象にはならない。"}, {"text": "運動会", "is_correct": false, "explanation": "学校の行事で、「寒い土地に合った」研究の対象として成り立たない。"}, {"text": "農夫", "is_correct": false, "explanation": "人を表し、「合った〜を研究する」の対象としてはおかしい。"}, {"text": "農法", "is_correct": true, "explanation": "ここは作物の育て方の〈農法〉が入る。"}], "explanations": {"花瓶": "花をさす器で、土地に合った研究の対象にはならない。", "運動会": "学校の行事で、「寒い土地に合った」研究の対象として成り立たない。", "農夫": "人を表し、「合った〜を研究する」の対象としてはおかしい。", "農法": "ここは作物の育て方の〈農法〉が入る。"}, "sentence_index": 0, "correct_answer": "農法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農法は毎朝早く起きて、畑で汗を流している。", "explanation": "ここは〈農家〉（人）の意味。農法は方法なので、起きて汗を流すことはできない。"}, {"text": "彼女は農法が豊富で、どんな質問にも答える。", "explanation": "ここは〈知識〉の意味。「豊富」は知識や情報に使うので、育て方の農法には合わない。"}, {"text": "祖父は農法を営み、家族を養ってきた。", "explanation": "ここは〈農業〉（仕事）の意味。「営む」は仕事に使うので、育て方の農法には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三角形", "is_correct": false, "explanation": "図形で、気候の違いによって変わるものではないので文が成り立たない。"}, {"text": "縄跳び", "is_correct": false, "explanation": "遊びの道具で、この文脈には合わない。"}, {"text": "野球", "is_correct": false, "explanation": "スポーツで、気候によって違う方法の文脈には入らない。"}, {"text": "農法", "is_correct": true, "explanation": "気候の違いで変わる〈農法〉が入る。"}], "explanations": {"三角形": "図形で、気候の違いによって変わるものではないので文が成り立たない。", "縄跳び": "遊びの道具で、この文脈には合わない。", "野球": "スポーツで、気候によって違う方法の文脈には入らない。", "農法": "気候の違いで変わる〈農法〉が入る。"}, "sentence_index": 6, "correct_answer": "農法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土に農法を混ぜて、野菜の苗を植えた。", "explanation": "ここは〈肥料〉の意味。肥料は土に混ぜるが、農法は方法なので混ぜられない。"}, {"text": "父は毎朝、農法にえさをやってから畑へ出かけた。", "explanation": "ここは〈家畜〉の意味。えさをやるのは家畜で、育て方の農法にはえさをやれないので合わない。"}, {"text": "この畑では、春に農法を植えて芽が出るのを待つ。", "explanation": "ここは〈種子〉の意味。種は植えるが、農法は植えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は新しい農法を詳しくなろうと、毎日本を読んだ。", "corrected_sentence": "父は新しい農法に詳しくなろうと、毎日本を読んだ。", "error_description": "『農法』に続く助詞が『を』になっている。『詳しい』は『〜に詳しい』の形で『に』を取るので、『に』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39575, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑では農法を変わったことで、収穫が増えた。", "corrected_sentence": "畑では農法を変えたことで、収穫が増えた。", "error_description": "『農法を』に続く動詞が誤り。『変わる』は自動詞で目的語『を』と合わないので、他動詞『変える』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「授業は」で主題を示し、「とても分かりやすい」と述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「授業を、とても分かりやすい」では目的語が成り立たず、形容詞の文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「授業に、とても分かりやすい」は対象・位置の関係が成り立たず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「授業へ」は行き先を表すが、この文脈には方向の意味がない。"}], "correct_answer": "は", "explanations": {"は": "正解。「授業は」で主題を示し、「とても分かりやすい」と述べる文になる。", "を": "「授業を、とても分かりやすい」では目的語が成り立たず、形容詞の文に合わない。", "に": "「授業に、とても分かりやすい」は対象・位置の関係が成り立たず、不自然。", "へ": "「授業へ」は行き先を表すが、この文脈には方向の意味がない。"}, "error_tags": {"を": "目的語の取り違え", "に": "対象・位置の取り違え", "へ": "方向の取り違え"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「体育の授業は」で主題を示し、「教室で行われた」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「体育の授業と教室で行われた」は授業と教室を並べる形になり、授業が教室で行われたという関係を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「体育の授業より教室で行われた」は比較の基準を示す形になり、行われた場所とつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「体育の授業で教室で行われた」は場所を示す「で」が重なり、不自然。"}], "correct_answer": "は", "explanations": {"は": "正解。「体育の授業は」で主題を示し、「教室で行われた」と続く。", "と": "「体育の授業と教室で行われた」は授業と教室を並べる形になり、授業が教室で行われたという関係を示せない。", "より": "「体育の授業より教室で行われた」は比較の基準を示す形になり、行われた場所とつながらない。", "で": "「体育の授業で教室で行われた」は場所を示す「で」が重なり、不自然。"}, "error_tags": {"と": "並列の取り違え", "より": "比較の取り違え", "で": "場所の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学校で、先生が教えたり、子どもたちが勉強したりする時間のこと。", "primary_collocate": null, "pronunciation": "じゅぎょう", "ipa": "dʑɯɡʲoː", "syllable_count": 3, "sentences": [{"text": "今日の授業は、午後一時に始まる。", "target_word": "授業", "complexity_tier": "T2", "furigana": "今日[きょう]の授業[じゅぎょう]は、午後[ごご]一時[いちじ]に始[はじ]まる。", "sentence_source": "generated"}, {"text": "田中先生の授業は、とても分かりやすい。", "target_word": "授業", "complexity_tier": "T3", "furigana": "田中[たなか]先生[せんせい]の授業[じゅぎょう]は、とても分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "授業が終わると、みんなは急いで校庭へ走っていった。", "target_word": "授業", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わると、みんなは急[いそ]いで校庭[こうてい]へ走[はし]っていった。", "sentence_source": "generated"}, {"text": "風邪をひいたので、今日は授業を休んだ。", "target_word": "授業", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたので、今日[きょう]は授業[じゅぎょう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "先生は授業で、新しい漢字を教えてくれた。", "target_word": "授業", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で、新[あたら]しい漢字[かんじ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "私は英語の授業が好きだ。", "target_word": "授業", "complexity_tier": "T2", "furigana": "私[わたし]は英語[えいご]の授業[じゅぎょう]が好[す]きだ。", "sentence_source": "generated"}, {"text": "授業の前に、教科書とノートを机の上に出しておく。", "target_word": "授業", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の前[まえ]に、教科書[きょうかしょ]とノートを机[つくえ]の上[うえ]に出[だ]しておく。", "sentence_source": "generated"}, {"text": "雨が降ったので、体育の授業は教室で行われた。", "target_word": "授業", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、体育[たいいく]の授業[じゅぎょう]は教室[きょうしつ]で行[おこな]われた。", "sentence_source": "generated"}, {"text": "授業でわからなかったところを、放課後に先生に聞いた。", "target_word": "授業", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]でわからなかったところを、放課後[ほうかご]に先生[せんせい]に聞[き]いた。", "sentence_source": "generated"}, {"text": "明日は授業がないから、ゆっくり朝寝坊できる。", "target_word": "授業", "complexity_tier": "T3", "furigana": "明日[あした]は授業[じゅぎょう]がないから、ゆっくり朝寝坊[あさねぼう]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "授業", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "学校で先生が生徒に教える時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 朝寝坊 (Zipf 2.44)']::text[], '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "授業", "is_correct": true, "explanation": "正解。学校で先生が教える時間を指し、「今日の○○は午後一時に始まる」に入る。"}, {"text": "給食", "is_correct": false, "explanation": "給食は昼に食べる食事で、午後一時に始まる時間の主語にはならない。"}, {"text": "校庭", "is_correct": false, "explanation": "校庭は場所の名前で、時刻を表す「始まる」の主語として成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は家で行う課題で、学校の時間が午後一時に始まるという文と合わない。"}], "explanations": {"授業": "正解。学校で先生が教える時間を指し、「今日の○○は午後一時に始まる」に入る。", "給食": "給食は昼に食べる食事で、午後一時に始まる時間の主語にはならない。", "校庭": "校庭は場所の名前で、時刻を表す「始まる」の主語として成り立たない。", "宿題": "宿題は家で行う課題で、学校の時間が午後一時に始まるという文と合わない。"}, "sentence_index": 0, "correct_answer": "授業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今月の授業をまだ払っていない。", "explanation": "ここは〈授業料〉の意味。授業（学校の時間）は払うものではないので、支払いの対象には授業料を使う。"}, {"text": "会社の授業で、新しい機械の使い方を学んだ。", "explanation": "ここは〈研修〉の意味。授業は学校の教科の時間を指し、会社の研修には使わない。"}, {"text": "顧問の先生が、部活の授業を毎週担当している。", "explanation": "ここは〈指導〉の意味。部活の指導は教科外で行うもので、教科の時間を指す授業は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授業", "is_correct": true, "explanation": "正解。授業の準備として教科書とノートを出しておく、という文になる。"}, {"text": "花壇", "is_correct": false, "explanation": "花壇は植物を植える場所で、教科書を出す準備の基準として前に置く文脈に合わない。"}, {"text": "校庭", "is_correct": false, "explanation": "校庭は屋外の場所で、教科書を机に出す準備と結びつかない。"}, {"text": "体育館", "is_correct": false, "explanation": "体育館は施設の名前で、教科書を机の上に出す準備の基準としては不自然。"}], "explanations": {"授業": "正解。授業の準備として教科書とノートを出しておく、という文になる。", "花壇": "花壇は植物を植える場所で、教科書を出す準備の基準として前に置く文脈に合わない。", "校庭": "校庭は屋外の場所で、教科書を机に出す準備と結びつかない。", "体育館": "体育館は施設の名前で、教科書を机の上に出す準備の基準としては不自然。"}, "sentence_index": 6, "correct_answer": "授業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放課後、みんなで授業を掃除した。", "explanation": "ここは〈教室〉の意味。掃除するのは教室などの場所で、授業は時間なので掃除の対象にならない。"}, {"text": "締め切りまでに授業を提出するために、早起きした。", "explanation": "ここは〈宿題〉の意味。提出するのは宿題や課題で、授業は提出できないので合わない。"}, {"text": "祖父に、感謝の授業を書いて送った。", "explanation": "ここは〈手紙〉の意味。書いて送るのは手紙で、授業は書いたり送ったりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業を終わると、みんなは急いで運動場へ走っていった。", "corrected_sentence": "授業が終わると、みんなは急いで運動場へ走っていった。", "error_description": "正しくは「授業が終わる」。「終わる」は主語に「が」を取る自動詞なので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は授業を休講になったので、ゆっくり朝寝坊できる。", "corrected_sentence": "明日は授業が休講になったので、ゆっくり朝寝坊できる。", "error_description": "正しくは「授業が休講になる」。「なる」は主語に「が」を取るので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
