INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「授業の準備」で、授業に関する準備を示す連体修飾になる。"}, {"text": "が", "is_correct": false, "explanation": "「授業が準備に」は主語が立たず、準備の関係を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「授業を準備に」は目的語の取り違えになり、「準備に時間をかける」の形が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「授業へ準備に」は方向の意味になり、準備の対象を示せない。"}], "correct_answer": "の", "explanations": {"の": "正解。「授業の準備」で、授業に関する準備を示す連体修飾になる。", "が": "「授業が準備に」は主語が立たず、準備の関係を表せない。", "を": "「授業を準備に」は目的語の取り違えになり、「準備に時間をかける」の形が成り立たない。", "へ": "「授業へ準備に」は方向の意味になり、準備の対象を示せない。"}, "error_tags": {"が": "主語の取り違え", "へ": "方向の取り違え", "を": "目的語の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学校などで、教師が生徒に対して行う教育活動。教えること、学ぶことの時間。", "primary_collocate": null, "pronunciation": "じゅぎょう", "ipa": "dʑɯɡʲoː", "syllable_count": 3, "sentences": [{"text": "この学校では、週に二十五時間の授業が行われている。", "target_word": "授業", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、週[しゅう]に二十五[にじゅうご]時間[じかん]の授業[じゅぎょう]が行[おこな]われている。", "sentence_source": "generated"}, {"text": "新しい先生は、写真を使った授業を工夫している。", "target_word": "授業", "complexity_tier": "T3", "furigana": "新[あたら]しい先生[せんせい]は、写真[しゃしん]を使[つか]った授業[じゅぎょう]を工夫[くふう]している。", "sentence_source": "generated"}, {"text": "授業を受けるために、生徒たちは毎朝八時までに登校する。", "target_word": "授業", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]を受[う]けるために、生徒[せいと]たちは毎朝[まいあさ]八時[はちじ]までに登校[とうこう]する。", "sentence_source": "generated"}, {"text": "授業の内容が難しすぎて、ついていけない生徒もいる。", "target_word": "授業", "complexity_tier": "T4", "furigana": "授業[じゅぎょう]の内容[ないよう]が難[むずか]しすぎて、ついていけない生徒[せいと]もいる。", "sentence_source": "generated"}, {"text": "教師は、生徒が発言しやすい授業を目指している。", "target_word": "授業", "complexity_tier": "T4", "furigana": "教師[きょうし]は、生徒[せいと]が発言[はつげん]しやすい授業[じゅぎょう]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "台風のため、全校で授業が中止になった。", "target_word": "授業", "complexity_tier": "T3", "furigana": "台風[たいふう]のため、全校[ぜんこう]で授業[じゅぎょう]が中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "参観日には、親が子どもの授業を見学できる。", "target_word": "授業", "complexity_tier": "T3", "furigana": "参観日[さんかんび]には、親[おや]が子[こ]どもの授業[じゅぎょう]を見学[けんがく]できる。", "sentence_source": "generated"}, {"text": "彼は授業の準備に、毎晩二時間かけている。", "target_word": "授業", "complexity_tier": "T3", "furigana": "彼[かれ]は授業[じゅぎょう]の準備[じゅんび]に、毎晩[まいばん]二時間[にじかん]かけている。", "sentence_source": "generated"}, {"text": "オンラインで授業を配信する学校が増えた。", "target_word": "授業", "complexity_tier": "T4", "furigana": "オンラインで授業[じゅぎょう]を配信[はいしん]する学校[がっこう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "授業で習ったことを、家で復習すると忘れにくい。", "target_word": "授業", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で習[なら]ったことを、家[いえ]で復習[ふくしゅう]すると忘[わす]れにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "授業", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "教師が生徒に行う教育活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "授業", "is_correct": true, "explanation": "正解。学校で教師が行う教育活動を指し、時間数を持って行われる文に入る。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、「二十五時間が行われている」の対象にはならない。"}, {"text": "校庭", "is_correct": false, "explanation": "校庭は場所で、時間数を持って行われる活動の語としては合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は家庭での課題で、学校で時間数を持って行われる教育活動ではない。"}], "explanations": {"授業": "正解。学校で教師が行う教育活動を指し、時間数を持って行われる文に入る。", "教室": "教室は場所で、「二十五時間が行われている」の対象にはならない。", "校庭": "校庭は場所で、時間数を持って行われる活動の語としては合わない。", "宿題": "宿題は家庭での課題で、学校で時間数を持って行われる教育活動ではない。"}, "sentence_index": 0, "correct_answer": "授業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は、授業を生徒全員に配った。", "explanation": "ここは〈教材〉の意味。配るのはプリントなどの教材で、授業は配れないので合わない。"}, {"text": "部活では、顧問が部員の授業を毎日している。", "explanation": "ここは〈指導〉の意味。部活の指導は教科外で行うもので、教科の時間を指す授業は使わない。"}, {"text": "先生は毎日、授業を出す。", "explanation": "ここは〈宿題〉の意味。出す（課す）のは宿題などの課題で、授業は出せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授業", "is_correct": true, "explanation": "正解。「子どもの授業を見学できる」は、参観日に親が教育活動を見る文として成り立つ。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本で、見学の対象として「子どもの教科書を見学する」とは言えない。"}, {"text": "通学路", "is_correct": false, "explanation": "通学路は道で、参観日に見学する対象として文脈に合わない。"}, {"text": "寝顔", "is_correct": false, "explanation": "寝顔は見るものだが、参観日に見学する対象としては成り立たない。"}], "explanations": {"授業": "正解。「子どもの授業を見学できる」は、参観日に親が教育活動を見る文として成り立つ。", "教科書": "教科書は本で、見学の対象として「子どもの教科書を見学する」とは言えない。", "通学路": "通学路は道で、参観日に見学する対象として文脈に合わない。", "寝顔": "寝顔は見るものだが、参観日に見学する対象としては成り立たない。"}, "sentence_index": 6, "correct_answer": "授業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎月の授業を、銀行で振り込んだ。", "explanation": "ここは〈授業料〉の意味。振り込むのは授業料などの代金で、教える活動としての授業は振り込めないので合わない。"}, {"text": "祖父は毎年、感謝の授業を書いて送る。", "explanation": "ここは〈手紙〉の意味。書いて送るのは手紙で、授業は書いたり送ったりできない。"}, {"text": "夏休みの授業を、毎日少しずつ書いた。", "explanation": "ここは〈作文〉の意味。少しずつ書き進めるのは作文で、授業は書く対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この学校では、毎週十時間の授業を行われる。", "corrected_sentence": "この学校では、毎週十時間の授業が行われる。", "error_description": "正しくは「授業が行われる」。「行われる」は受身で主語に「が」を取るので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、録画した授業が生徒に配信した。", "corrected_sentence": "先生は、録画した授業を生徒に配信した。", "error_description": "正しくは「授業を配信した」。「配信する」は他動詞で目的語に「を」を取るので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「蜾蠃が青虫を運んでいる」で、運ぶ動作の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「蜾蠃を青虫を運んでいる」は目的語が二つ重なり、不自然で成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「蜾蠃に青虫を運んでいる」は対象の関係になり、運ぶ主体として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「蜾蠃へ青虫を運んでいる」は方向の意味になり、主語として働かない。"}], "correct_answer": "が", "explanations": {"が": "正解。「蜾蠃が青虫を運んでいる」で、運ぶ動作の主語を示す。", "を": "「蜾蠃を青虫を運んでいる」は目的語が二つ重なり、不自然で成り立たない。", "に": "「蜾蠃に青虫を運んでいる」は対象の関係になり、運ぶ主体として合わない。", "へ": "「蜾蠃へ青虫を運んでいる」は方向の意味になり、主語として働かない。"}, "error_tags": {"を": "目的語の取り違え", "に": "対象の取り違え", "へ": "方向の取り違え"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「蜾蠃が飛んできて」で、飛んでくる動作の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「蜾蠃を飛んできて」は主語が立たず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「蜾蠃で飛んできて」は手段の意味になり、主語として働かない。"}, {"text": "の", "is_correct": false, "explanation": "「蜾蠃の飛んできて」は連体修飾になり、動詞の主語として不完全。"}], "correct_answer": "が", "explanations": {"が": "正解。「蜾蠃が飛んできて」で、飛んでくる動作の主語を示す。", "を": "「蜾蠃を飛んできて」は主語が立たず、文が成り立たない。", "で": "「蜾蠃で飛んできて」は手段の意味になり、主語として働かない。", "の": "「蜾蠃の飛んできて」は連体修飾になり、動詞の主語として不完全。"}, "error_tags": {"を": "目的語の取り違え", "で": "手段の取り違え", "の": "修飾の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "こしの ほそい はちの なかま。", "primary_collocate": null, "pronunciation": "すがる", "ipa": "sɯɡaɾɯ", "syllable_count": 3, "sentences": [{"text": "蜾蠃は、腰がとても細いハチの仲間だ。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "蜾蠃[すがる]は、腰[こし]がとても細[ほそ]いハチの仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "庭で蜾蠃が青虫を運んでいるのを見た。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "庭[にわ]で蜾蠃[すがる]が青虫[あおむし]を運[はこ]んでいるのを見[み]た。", "sentence_source": "generated"}, {"text": "蜾蠃は土で小さな巣を作る。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "蜾蠃[すがる]は土[つち]で小[ちい]さな巣[す]を作[つく]る。", "sentence_source": "generated"}, {"text": "腰が細いので、蜾蠃はすぐに見分けられる。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "腰[こし]が細[ほそ]いので、蜾蠃[すがる]はすぐに見分[みわ]けられる。", "sentence_source": "generated"}, {"text": "古い歌集には、蜾蠃を詠んだ歌がある。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "古[ふる]い歌集[かしゅう]には、蜾蠃[すがる]を詠[よ]んだ歌[うた]がある。", "sentence_source": "generated"}, {"text": "祖父は、蜾蠃の巣を壁の隅で見つけた。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "祖父[そふ]は、蜾蠃[すがる]の巣[す]を壁[かべ]の隅[すみ]で見[み]つけた。", "sentence_source": "generated"}, {"text": "蜾蠃は人をあまり刺さないので、近づいても大丈夫だ。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "蜾蠃[すがる]は人[ひと]をあまり刺[さ]さないので、近[ちか]づいても大丈夫[だいじょうぶ]だ。", "sentence_source": "generated"}, {"text": "蜾蠃が飛んできて、窓のそばの土に穴を掘り始めた。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "蜾蠃[すがる]が飛[と]んできて、窓[まど]のそばの土[つち]に穴[あな]を掘[ほ]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "夏の日、蜾蠃は何度も巣と草むらを行き来していた。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "夏[なつ]の日[ひ]、蜾蠃[すがる]は何度[なんど]も巣[す]と草[くさ]むらを行[い]き来[き]していた。", "sentence_source": "generated"}, {"text": "図鑑で調べると、あの細い腰のハチは蜾蠃だとわかった。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "図鑑[ずかん]で調[しら]べると、あの細[ほそ]い腰[こし]のハチは蜾蠃[すがる]だとわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜾蠃", "label": "基本形"}], "register": "古風（普通体）", "sense_fingerprint": "腰の細いハチの仲間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜾蠃", "is_correct": true, "explanation": "正解。腰が細いハチの仲間を指す名詞で、「腰がとても細いハチの仲間だ」と述べる文に入る。"}, {"text": "巣", "is_correct": false, "explanation": "巣は虫が住む場所で、腰が細いハチの仲間という種類を表す主語にはならない。"}, {"text": "土", "is_correct": false, "explanation": "土は地面の材料で、腰が細いハチの仲間という説明の主語として成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花は植物の部分で、ハチの仲間を説明する主語としては合わない。"}], "explanations": {"蜾蠃": "正解。腰が細いハチの仲間を指す名詞で、「腰がとても細いハチの仲間だ」と述べる文に入る。", "巣": "巣は虫が住む場所で、腰が細いハチの仲間という種類を表す主語にはならない。", "土": "土は地面の材料で、腰が細いハチの仲間という説明の主語として成り立たない。", "花": "花は植物の部分で、ハチの仲間を説明する主語としては合わない。"}, "sentence_index": 0, "correct_answer": "蜾蠃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に、春の蜾蠃を植えた。", "explanation": "ここは〈花〉の意味。植えるのは植物の花で、蜾蠃（ハチの仲間）は植えるものではない。"}, {"text": "子どもたちは、蜾蠃で城を作った。", "explanation": "ここは〈砂〉の意味。城を作る材料は砂で、蜾蠃は材料にならない。"}, {"text": "紅茶に蜾蠃を入れて、ゆっくり飲んだ。", "explanation": "ここは〈蜂蜜〉の意味。紅茶に入れて甘くするのは蜂蜜で、蜾蠃は入れる食材ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜾蠃", "is_correct": true, "explanation": "正解。人を刺すことが少ないハチの仲間を指し、「近づいても大丈夫だ」と続く文になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は食品で、人を刺すかどうかを述べる主語として成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、人を刺すかどうかの話題にならない。"}, {"text": "石", "is_correct": false, "explanation": "石は物で、人を刺す生き物の話として文脈に合わない。"}], "explanations": {"蜾蠃": "正解。人を刺すことが少ないハチの仲間を指し、「近づいても大丈夫だ」と続く文になる。", "砂糖": "砂糖は食品で、人を刺すかどうかを述べる主語として成り立たない。", "窓": "窓は建具で、人を刺すかどうかの話題にならない。", "石": "石は物で、人を刺す生き物の話として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "蜾蠃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館で、人気の蜾蠃を借りた。", "explanation": "ここは〈本〉の意味。図書館で借りるのは本などの品物で、蜾蠃（虫）は借りるものではない。"}, {"text": "鍋で蜾蠃を沸かして、お茶を入れた。", "explanation": "ここは〈湯〉の意味。鍋で沸かすのは水や湯で、蜾蠃は沸かす対象にならない。"}, {"text": "朝、蜾蠃を開けて風を入れた。", "explanation": "ここは〈窓〉の意味。開けるのは窓や戸で、蜾蠃は開けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の朝、蜾蠃を草むらで巣を作っていた。", "corrected_sentence": "夏の朝、蜾蠃が草むらで巣を作っていた。", "error_description": "正しくは「蜾蠃が巣を作る」。「作る」の動作主は「が」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺の蜾蠃に巣は、小さな土の塊でできている。", "corrected_sentence": "窓辺の蜾蠃の巣は、小さな土の塊でできている。", "error_description": "正しくは「蜾蠃の巣」。「の」で所有を示す。「に」は対象や場所を示すので、「蜾蠃に巣」では関係が成り立たず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「蜾蠃は」で主題を示し、「青虫を針で動けなくして、巣に運ぶ」と述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「蜾蠃を青虫を運ぶ」は目的語が二つ重なり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「蜾蠃に青虫を運ぶ」は対象の関係になり、運ぶ主体として合わない。"}, {"text": "で", "is_correct": false, "explanation": "「蜾蠃で青虫を運ぶ」は手段の意味になり、主語として働かない。"}], "correct_answer": "は", "explanations": {"は": "正解。「蜾蠃は」で主題を示し、「青虫を針で動けなくして、巣に運ぶ」と述べる文になる。", "を": "「蜾蠃を青虫を運ぶ」は目的語が二つ重なり、文が成り立たない。", "に": "「蜾蠃に青虫を運ぶ」は対象の関係になり、運ぶ主体として合わない。", "で": "「蜾蠃で青虫を運ぶ」は手段の意味になり、主語として働かない。"}, "error_tags": {"を": "目的語の取り違え", "に": "対象の取り違え", "で": "手段の取り違え"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「蜾蠃を引く」で、引く対象を示す目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「辞書で蜾蠃が引くと」は蜾蠃が辞書を引く主体になり、不自然で文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「辞書で蜾蠃に引くと」は対象の関係が成り立たず、引く対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「蜾蠃で引くと」は手段の意味になり、引く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「蜾蠃を引く」で、引く対象を示す目的語になる。", "が": "「辞書で蜾蠃が引くと」は蜾蠃が辞書を引く主体になり、不自然で文脈に合わない。", "に": "「辞書で蜾蠃に引くと」は対象の関係が成り立たず、引く対象にならない。", "で": "「蜾蠃で引くと」は手段の意味になり、引く対象を示せない。"}, "error_tags": {"が": "主語の取り違え", "に": "対象の取り違え", "で": "手段の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ジガバチの古い呼び名。腰が細く、青虫などを捕らえて巣に運ぶハチ。", "primary_collocate": null, "pronunciation": "すがる", "ipa": "sɯɡaɾɯ", "syllable_count": 3, "sentences": [{"text": "蜾蠃は、ジガバチの古い呼び名である。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "蜾蠃[すがる]は、ジガバチの古[ふる]い呼[よ]び名[な]である。", "sentence_source": "generated"}, {"text": "蜾蠃は青虫を針で動けなくして、巣に運ぶ。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "蜾蠃[すがる]は青虫[あおむし]を針[はり]で動[うご]けなくして、巣[す]に運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "昔の人は、ジガバチのことを蜾蠃と呼んだ。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、ジガバチのことを蜾蠃[すがる]と呼[よ]んだ。", "sentence_source": "generated"}, {"text": "古典の注釈には、蜾蠃が他の虫の子を育てるという説が出てくる。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "古典[こてん]の注釈[ちゅうしゃく]には、蜾蠃[すがる]が他[ほか]の虫[むし]の子[こ]を育[そだ]てるという説[せつ]が出[で]てくる。", "sentence_source": "generated"}, {"text": "蜾蠃の幼虫は、親が運んだ青虫を食べて育つ。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "蜾蠃[すがる]の幼虫[ようちゅう]は、親[おや]が運[はこ]んだ青虫[あおむし]を食[た]べて育[そだ]つ。", "sentence_source": "generated"}, {"text": "現代では蜾蠃より、ジガバチという名前のほうがよく使われる。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "現代[げんだい]では蜾蠃[すがる]より、ジガバチという名前[なまえ]のほうがよく使[つか]われる。", "sentence_source": "generated"}, {"text": "蜾蠃は地面に穴を掘り、その奥に卵を産む。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "蜾蠃[すがる]は地面[じめん]に穴[あな]を掘[ほ]り、その奥[おく]に卵[たまご]を産[う]む。", "sentence_source": "generated"}, {"text": "辞書で蜾蠃を引くと、ジガバチと説明されていた。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "辞書[じしょ]で蜾蠃[すがる]を引くと、ジガバチと説明[せつめい]されていた。", "sentence_source": "generated"}, {"text": "腰の細い蜾蠃は、獲物を軽々と持ち上げて飛ぶ。", "target_word": "蜾蠃", "complexity_tier": "T4", "furigana": "腰[こし]の細[ほそ]い蜾蠃[すがる]は、獲物[えもの]を軽々[かるがる]と持[も]ち上[あ]げて飛[と]ぶ。", "sentence_source": "generated"}, {"text": "先生は、古い言葉の例として蜾蠃を黒板に書いた。", "target_word": "蜾蠃", "complexity_tier": "T3", "furigana": "先生[せんせい]は、古[ふる]い言葉[ことば]の例[れい]として蜾蠃[すがる]を黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜾蠃", "label": "基本形"}], "register": "古風（普通体）", "sense_fingerprint": "ジガバチの古称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ジガバチ (Zipf 1.15)','sentence 2 above tier T3: contains vocabulary far above tier T3: ジガバチ (Zipf 1.15)','sentence 5 above tier T3: contains vocabulary far above tier T3: ジガバチ (Zipf 1.15)','sentence 7 above tier T3: contains vocabulary far above tier T3: ジガバチ (Zipf 1.15)']::text[], '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜾蠃", "is_correct": true, "explanation": "正解。ジガバチの古い呼び名であり、「ジガバチの古い呼び名である」と言い換える文に入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は食品の名前で、生き物の古い呼び名として成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具の名前で、ジガバチの呼び名を説明する文の主語にならない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は素材の名前で、生き物の呼び名を説明する主語として合わない。"}], "explanations": {"蜾蠃": "正解。ジガバチの古い呼び名であり、「ジガバチの古い呼び名である」と言い換える文に入る。", "砂糖": "砂糖は食品の名前で、生き物の古い呼び名として成り立たない。", "窓": "窓は建具の名前で、ジガバチの呼び名を説明する文の主語にならない。", "紙": "紙は素材の名前で、生き物の呼び名を説明する主語として合わない。"}, "sentence_index": 0, "correct_answer": "蜾蠃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は、感謝の蜾蠃を書いて送った。", "explanation": "ここは〈手紙〉の意味。書いて送るのは手紙で、蜾蠃（虫）は書けないので使わない。"}, {"text": "鍋で蜾蠃を沸かしてから、お茶を入れた。", "explanation": "ここは〈湯〉の意味。鍋で沸かすのは水や湯で、蜾蠃は沸かす対象にならない。"}, {"text": "先生に言われて、その蜾蠃を暗唱した。", "explanation": "ここは〈歌〉の意味。暗唱するのは詩歌などの文章で、虫の名は暗唱の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜾蠃", "is_correct": true, "explanation": "正解。地面に穴を掘って卵を産むハチの仲間を指し、「その奥に卵を産む」と続く文になる。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根は建物の一部で、地面に穴を掘って卵を産む主語にはならない。"}, {"text": "池", "is_correct": false, "explanation": "池は水のある場所で、穴を掘って卵を産むという動作の主語として成り立たない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、地面に穴を掘る主語として文が通らない。"}], "explanations": {"蜾蠃": "正解。地面に穴を掘って卵を産むハチの仲間を指し、「その奥に卵を産む」と続く文になる。", "屋根": "屋根は建物の一部で、地面に穴を掘って卵を産む主語にはならない。", "池": "池は水のある場所で、穴を掘って卵を産むという動作の主語として成り立たない。", "鍋": "鍋は調理器具で、地面に穴を掘る主語として文が通らない。"}, "sentence_index": 6, "correct_answer": "蜾蠃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、蜾蠃をさして歩いた。", "explanation": "ここは〈傘〉の意味。さすのは傘で、蜾蠃（虫）はさす道具ではない。"}, {"text": "外に出るので、蜾蠃をはいた。", "explanation": "ここは〈靴〉の意味。はくのは靴や靴下で、蜾蠃は身につけるものではない。"}, {"text": "汗をかいたので、蜾蠃で額を拭いた。", "explanation": "ここは〈ハンカチ〉の意味。汗を拭く道具はハンカチなどで、蜾蠃は道具にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔の書物では、蜾蠃を青虫を巣に運ぶと書かれている。", "corrected_sentence": "昔の書物では、蜾蠃が青虫を巣に運ぶと書かれている。", "error_description": "正しくは「蜾蠃が運ぶ」。「運ぶ」の動作主は「が」で示すので、「を」は誤り。目的語が二つ重なり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い文献では、蜾蠃で『虫の名』と記していた。", "corrected_sentence": "古い文献では、蜾蠃を『虫の名』と記していた。", "error_description": "正しくは「蜾蠃を記していた」。「記す」は目的語に「を」を取るので、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「巣箱」と「中」を結ぶ所属を表す「の」で、ここに合う。"}, {"text": "に", "is_correct": false, "explanation": "位置を表す「に」になり、「巣箱に中で」と続かないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」になり、「巣箱を中で」と続かないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表す「と」になり、「巣箱と中で」と続かないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「巣箱」と「中」を結ぶ所属を表す「の」で、ここに合う。", "に": "位置を表す「に」になり、「巣箱に中で」と続かないので合わない。", "を": "目的語の「を」になり、「巣箱を中で」と続かないので合わない。", "と": "並列・相手を表す「と」になり、「巣箱と中で」と続かないので合わない。"}, "error_tags": {"に": "位置・方向", "を": "目的語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「置く」の対象を示す目的語の「を」で、ここに合う。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」になり、「巣箱が高い場所に置けば」では合わないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所の「に」になり、「巣箱に高い場所に置けば」と続かないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」になり、「置く」の対象にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「置く」の対象を示す目的語の「を」で、ここに合う。", "が": "主語の「が」になり、「巣箱が高い場所に置けば」では合わないので合わない。", "に": "場所の「に」になり、「巣箱に高い場所に置けば」と続かないので合わない。", "で": "手段・場所の「で」になり、「置く」の対象にはならないので合わない。"}, "error_tags": {"が": "主語", "に": "位置", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥や虫が住むための小さな家です。", "primary_collocate": null, "pronunciation": "すばこ", "ipa": "sɯbako", "syllable_count": 3, "sentences": [{"text": "庭の木に、小鳥のための巣箱をかけました。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]に、小鳥[ことり]のための巣箱[すばこ]をかけました。", "sentence_source": "generated"}, {"text": "巣箱の中で、小さなひなが鳴いています。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]の中[なか]で、小[ちい]さなひなが鳴[な]いています。", "sentence_source": "generated"}, {"text": "父は木の板で、巣箱を作ってくれました。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "父[ちち]は木[き]の板[いた]で、巣箱[すばこ]を作[つく]ってくれました。", "sentence_source": "generated"}, {"text": "春になると、巣箱にシジュウカラが入ってきます。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "春[はる]になると、巣箱[すばこ]にシジュウカラが入[はい]ってきます。", "sentence_source": "generated"}, {"text": "巣箱の穴が大きすぎると、ほかの鳥が来てしまいます。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]の穴[あな]が大[おお]きすぎると、ほかの鳥[とり]が来[き]てしまいます。", "sentence_source": "generated"}, {"text": "学校の庭の巣箱を、子どもたちは毎朝見に行きます。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "学校[がっこう]の庭[にわ]の巣箱[すばこ]を、子[こ]どもたちは毎朝[まいあさ]見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "雨が入らないように、巣箱に小さな屋根をつけた。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "雨[あめ]が入[はい]らないように、巣箱[すばこ]に小[ちい]さな屋根[やね]をつけた。", "sentence_source": "generated"}, {"text": "巣箱を高い場所に置けば、猫が近づけません。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]を高[たか]い場所[ばしょ]に置[お]けば、猫[ねこ]が近[ちか]づけません。", "sentence_source": "generated"}, {"text": "冬の間に、古い巣箱をきれいにそうじします。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]に、古[ふる]い巣箱[すばこ]をきれいにそうじします。", "sentence_source": "generated"}, {"text": "公園の巣箱に、ムクドリが巣を作り始めた。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "公園[こうえん]の巣箱[すばこ]に、ムクドリが巣[す]を作[つく]り始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巣箱", "label": "基本形"}], "register": "中立", "sense_fingerprint": "鳥が住むための小さな箱の家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巣箱", "is_correct": true, "explanation": "小鳥の住まいとなる箱で、庭の木にかけるものとして合う。"}, {"text": "手紙", "is_correct": false, "explanation": "書いたり送ったりするもので、木にかけるものではないので合わない。"}, {"text": "木の実", "is_correct": false, "explanation": "食べ物で、木にかけるものではないので合わない。"}, {"text": "種", "is_correct": false, "explanation": "まくものであって、かけるものではないので合わない。"}], "explanations": {"巣箱": "小鳥の住まいとなる箱で、庭の木にかけるものとして合う。", "手紙": "書いたり送ったりするもので、木にかけるものではないので合わない。", "木の実": "食べ物で、木にかけるものではないので合わない。", "種": "まくものであって、かけるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "巣箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥は木の枝に巣箱を作った。", "explanation": "ここは〈巣〉の意味。鳥は自分で巣を作るので、人が置く箱の巣箱とは言わないので合わない。"}, {"text": "巣箱に木の実を入れて、毎朝補充する。", "explanation": "ここは〈餌箱〉の意味。餌を入れて補充する箱は餌箱で、住むための巣箱とは言わないので合わない。"}, {"text": "巣箱に種をまき、水をやる。", "explanation": "ここは〈植木鉢〉の意味。種をまいて育てる器は植木鉢で、巣箱は植物を育てるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巣箱", "is_correct": true, "explanation": "屋根をつけて雨をよけるための小さな箱で、ここに合う。"}, {"text": "電話", "is_correct": false, "explanation": "電話はかけるものだが、屋根をつける対象にはならないので合わない。"}, {"text": "声", "is_correct": false, "explanation": "屋根をつけるものではないので、ここでは合わない。"}, {"text": "空", "is_correct": false, "explanation": "屋根をつけるものではないので、「空に屋根をつけた」とは言わない。"}], "explanations": {"巣箱": "屋根をつけて雨をよけるための小さな箱で、ここに合う。", "電話": "電話はかけるものだが、屋根をつける対象にはならないので合わない。", "声": "屋根をつけるものではないので、ここでは合わない。", "空": "屋根をつけるものではないので、「空に屋根をつけた」とは言わない。"}, "sentence_index": 6, "correct_answer": "巣箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "巣箱に本を並べた。", "explanation": "ここは〈本棚〉の意味。本を並べる場所は本棚で、巣箱には本を並べないので合わない。"}, {"text": "巣箱に花を生けた。", "explanation": "ここは〈花瓶〉の意味。花を生ける器は花瓶で、巣箱は花を入れるものではないので合わない。"}, {"text": "巣箱に現金をしまった。", "explanation": "ここは〈金庫〉の意味。現金をしまう場所は金庫で、巣箱ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近くの林に、ひなのための巣箱が置いてきた。", "corrected_sentence": "近くの林に、ひなのための巣箱を置いてきた。", "error_description": "「置いてきた」の対象は目的語なので「を」が必要。「が」は誤りで、「巣箱を置いてきた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の朝、ひなは巣箱を入って、外へ出ない。", "corrected_sentence": "夏の朝、ひなは巣箱に入って、外へ出ない。", "error_description": "「入る」は場所を表す「に」で続く。「を」は目的語の助詞で、「入る」とは続かないので誤り。「巣箱に入って」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "出発点を表す「から」で、「巣箱から出た」と続きここに合う。"}, {"text": "に", "is_correct": false, "explanation": "帰着・位置を表す「に」になり、「巣箱に出た」と続かないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」になり、「巣箱で出た」と続かないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表す「と」になり、「巣箱と出た」と続かないので合わない。"}], "correct_answer": "から", "explanations": {"から": "出発点を表す「から」で、「巣箱から出た」と続きここに合う。", "に": "帰着・位置を表す「に」になり、「巣箱に出た」と続かないので合わない。", "で": "場所・手段の「で」になり、「巣箱で出た」と続かないので合わない。", "と": "並列・相手を表す「と」になり、「巣箱と出た」と続かないので合わない。"}, "error_tags": {"に": "帰着・位置", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "札をつける対象を示す「に」で、「巣箱に札をつける」と続きここに合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」になり、「巣箱を小さな札をつけて」と続かないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」になり、「巣箱が札をつける」とは読めず合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表す「と」になり、「巣箱と札をつける」とは続かないので合わない。"}], "correct_answer": "に", "explanations": {"に": "札をつける対象を示す「に」で、「巣箱に札をつける」と続きここに合う。", "を": "目的語の「を」になり、「巣箱を小さな札をつけて」と続かないので合わない。", "が": "主語の「が」になり、「巣箱が札をつける」とは読めず合わない。", "と": "並列・相手を表す「と」になり、「巣箱と札をつける」とは続かないので合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小鳥や蜂などが巣を作ったり、住んだりするための箱。", "primary_collocate": null, "pronunciation": "すばこ", "ipa": "sɯbako", "syllable_count": 3, "sentences": [{"text": "農園では、蜂のために巣箱を畑の近くに置いている。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "農園[のうえん]では、蜂[はち]のために巣箱[すばこ]を畑[はたけ]の近[ちか]くに置[お]いている。", "sentence_source": "generated"}, {"text": "巣箱から出たミツバチが、花の間を飛び回っている。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]から出[で]たミツバチが、花[はな]の間[あいだ]を飛[と]び回[まわ]っている。", "sentence_source": "generated"}, {"text": "養蜂家は毎週、巣箱の中の蜜の量を確かめる。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "養蜂家[ようほうか]は毎週[まいしゅう]、巣箱[すばこ]の中[なか]の蜜[みつ]の量[りょう]を確[たし]かめる。", "sentence_source": "generated"}, {"text": "森の木に取りつけた巣箱で、フクロウが子を育てた。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "森[もり]の木[き]に取[と]りつけた巣箱[すばこ]で、フクロウが子[こ]を育[そだ]てた。", "sentence_source": "generated"}, {"text": "巣箱の中を調べて、ひなの数を記録した。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]の中[なか]を調[しら]べて、ひなの数[かず]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "蜂の巣箱は、日当たりのよい場所に置くとよい。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "蜂[はち]の巣箱[すばこ]は、日当[ひあ]たりのよい場所[ばしょ]に置[お]くとよい。", "sentence_source": "generated"}, {"text": "古い巣箱が壊れたので、新しいものに取り替えた。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "古[ふる]い巣箱[すばこ]が壊[こわ]れたので、新[あたら]しいものに取[と]り替[か]えた。", "sentence_source": "generated"}, {"text": "巣箱に小さな札をつけて、鳥の種類をメモした。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]に小[ちい]さな札[ふだ]をつけて、鳥[とり]の種類[しゅるい]をメモした。", "sentence_source": "generated"}, {"text": "巣箱の入り口を狭くして、スズメが入れないようにした。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "巣箱[すばこ]の入[い]り口[ぐち]を狭[せま]くして、スズメが入[はい]れないようにした。", "sentence_source": "generated"}, {"text": "雪が積もる前に、巣箱を倉庫にしまった。", "target_word": "巣箱", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もる前[まえ]に、巣箱[すばこ]を倉庫[そうこ]にしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巣箱", "label": "基本形"}], "register": "中立", "sense_fingerprint": "小鳥や蜂が巣を作るための箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巣箱", "is_correct": true, "explanation": "蜂を住まわせる箱で、畑の近くに置くものとして合う。"}, {"text": "歌", "is_correct": false, "explanation": "置けるものではないので、「歌を畑の近くに置いている」とは言えず合わない。"}, {"text": "天気", "is_correct": false, "explanation": "置けるものではないので、ここでは合わない。"}, {"text": "呼吸", "is_correct": false, "explanation": "置けるものではないので、「呼吸を置く」とは言えず合わない。"}], "explanations": {"巣箱": "蜂を住まわせる箱で、畑の近くに置くものとして合う。", "歌": "置けるものではないので、「歌を畑の近くに置いている」とは言えず合わない。", "天気": "置けるものではないので、ここでは合わない。", "呼吸": "置けるものではないので、「呼吸を置く」とは言えず合わない。"}, "sentence_index": 0, "correct_answer": "巣箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "巣箱に花を供えた。", "explanation": "ここは〈仏壇〉の意味。花を供える場所は仏壇で、巣箱には花を供えないので合わない。"}, {"text": "巣箱に水を入れて火にかける。", "explanation": "ここは〈鍋〉の意味。火にかける器は鍋で、巣箱は火にかけるものではないので合わない。"}, {"text": "巣箱に車をしまった。", "explanation": "ここは〈車庫〉の意味。車をしまう場所は車庫で、巣箱ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巣箱", "is_correct": true, "explanation": "古くなって壊れ、取り替える対象になる箱なので、ここに合う。"}, {"text": "天気", "is_correct": false, "explanation": "古くて壊れるものではないので、「古い天気が壊れた」とは言えず合わない。"}, {"text": "季節", "is_correct": false, "explanation": "壊れるものではないので、「古い季節が壊れた」とは言えず合わない。"}, {"text": "空気", "is_correct": false, "explanation": "壊れるものではないので、「古い空気が壊れた」とは言えず合わない。"}], "explanations": {"巣箱": "古くなって壊れ、取り替える対象になる箱なので、ここに合う。", "天気": "古くて壊れるものではないので、「古い天気が壊れた」とは言えず合わない。", "季節": "壊れるものではないので、「古い季節が壊れた」とは言えず合わない。", "空気": "壊れるものではないので、「古い空気が壊れた」とは言えず合わない。"}, "sentence_index": 6, "correct_answer": "巣箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "巣箱に皿をしまった。", "explanation": "ここは〈食器棚〉の意味。皿をしまう場所は食器棚で、巣箱ではないので合わない。"}, {"text": "巣箱に靴を並べた。", "explanation": "ここは〈下駄箱〉の意味。靴を並べる場所は下駄箱で、巣箱には靴を並べないので合わない。"}, {"text": "巣箱に化粧品をそろえた。", "explanation": "ここは〈化粧台〉の意味。化粧品をそろえる場所は化粧台で、巣箱には合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春の畑に、蜜蜂のための巣箱で置いておいた。", "corrected_sentence": "春の畑に、蜜蜂のための巣箱を置いておいた。", "error_description": "「置いておいた」の対象は目的語なので「を」が必要。「で」は誤りで、「巣箱を置いておいた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "巣箱が庭の隅に置いたので、ミツバチが来た。", "corrected_sentence": "巣箱を庭の隅に置いたので、ミツバチが来た。", "error_description": "「置いた」は目的語を取る動詞なので、置かれる物は「を」で示す。「巣箱が」は誤りで、「巣箱を置いたので」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
