INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『固くなる』の主語を示すので『が』が入る。"}, {"text": "を", "is_correct": false, "explanation": "『固くなる』は自動詞で、目的語『を』は付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や原因を示すが、『固くなる』の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、『固くなる』の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『固くなる』の主語を示すので『が』が入る。", "を": "『固くなる』は自動詞で、目的語『を』は付かない。", "で": "手段や原因を示すが、『固くなる』の主語にはならない。", "から": "起点を示すが、『固くなる』の主語にはならない。"}, "error_tags": {"を": "『固くなる』は自動詞で、目的語『を』は付かない。", "で": "手段や原因を示すが、『固くなる』の主語にはならない。", "から": "起点を示すが、『固くなる』の主語にはならない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ミツバチが花から集めたあまい食べ物です。", "primary_collocate": null, "pronunciation": "はちみつ", "ipa": "hatɕimitsɯ", "syllable_count": 4, "sentences": [{"text": "朝ごはんに、パンに蜂蜜をたっぷりぬって食べた。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "朝(あさ)ごはんに、パンに蜂蜜(はちみつ)をたっぷりぬって食(た)べた。", "sentence_source": "generated"}, {"text": "風邪をひいたときは、温かいお茶に蜂蜜を入れて飲む。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "風邪(かぜ)をひいたときは、温(あたた)かいお茶(ちゃ)に蜂蜜(はちみつ)を入(い)れて飲(の)む。", "sentence_source": "generated"}, {"text": "この蜂蜜は、みかんの花から集めたもので、香りがいい。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "この蜂蜜(はちみつ)は、みかんの花(はな)から集(あつ)めたもので、香(かお)りがいい。", "sentence_source": "generated"}, {"text": "蜂蜜は砂糖より甘く感じるので、少しだけ使う。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "蜂蜜(はちみつ)は砂糖(さとう)より甘(あま)く感(かん)じるので、少(すこ)しだけ使(つか)う。", "sentence_source": "generated"}, {"text": "兄は養蜂を始めて、自分で蜂蜜を取るようになった。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "兄(あに)は養蜂(ようほう)を始(はじ)めて、自分(じぶん)で蜂蜜(はちみつ)を取(と)るようになった。", "sentence_source": "generated"}, {"text": "蜂蜜を入れすぎると、ヨーグルトが甘くなりすぎる。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "蜂蜜(はちみつ)を入(い)れすぎると、ヨーグルトが甘(あま)くなりすぎる。", "sentence_source": "generated"}, {"text": "山の村のお土産に、小さな瓶に入った蜂蜜を買った。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "山(やま)の村(むら)のお土産(みやげ)に、小(ちい)さな瓶(びん)に入(はい)った蜂蜜(はちみつ)を買(か)った。", "sentence_source": "generated"}, {"text": "寒い日は蜂蜜が固くなって、スプーンですくいにくい。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "寒(さむ)い日(ひ)は蜂蜜(はちみつ)が固(かた)くなって、スプーンですくいにくい。", "sentence_source": "generated"}, {"text": "母はケーキを焼くとき、砂糖の代わりに蜂蜜を使う。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "母(はは)はケーキを焼(や)くとき、砂糖(さとう)の代(か)わりに蜂蜜(はちみつ)を使(つか)う。", "sentence_source": "generated"}, {"text": "赤ちゃんには、一歳になるまで蜂蜜を食べさせてはいけない。", "target_word": "蜂蜜", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんには、一歳(いっさい)になるまで蜂蜜(はちみつ)を食(た)べさせてはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜂蜜", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "ミツバチが花から集めた甘い食べ物。パン・お茶・料理に使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豚肉", "is_correct": false, "explanation": "パンにぬる食材ではないので、ここには入らない。"}, {"text": "牛乳", "is_correct": false, "explanation": "パンにぬるものではなく、「ぬって」と合わない。"}, {"text": "小麦粉", "is_correct": false, "explanation": "パンにぬるものではなく、「たっぷりぬって」と合わない。"}, {"text": "蜂蜜", "is_correct": true, "explanation": "パンにたっぷりぬる〈蜂蜜〉が入る。"}], "explanations": {"豚肉": "パンにぬる食材ではないので、ここには入らない。", "牛乳": "パンにぬるものではなく、「ぬって」と合わない。", "小麦粉": "パンにぬるものではなく、「たっぷりぬって」と合わない。", "蜂蜜": "パンにたっぷりぬる〈蜂蜜〉が入る。"}, "sentence_index": 0, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭で蜂蜜に刺されて、腕がはれた。", "explanation": "ここは〈蜂〉（ハチ）の意味。蜂蜜は食べ物なので、刺すことはできない。"}, {"text": "この蜂蜜は、さとうきびの搾り汁を煮詰めて作られる。", "explanation": "ここは〈砂糖〉の意味。砂糖はさとうきびから作るが、蜂蜜はミツバチの蜜から作る。"}, {"text": "蜂蜜は花の奥にあり、ミツバチが吸って飲む。", "explanation": "ここは〈花の蜜〉の意味。花の蜜は花の奥にあるが、蜂蜜は巣で作られた食べ物で花にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鶏肉", "is_correct": false, "explanation": "小さな瓶に入って売られる食材ではないので、この文に合わない。"}, {"text": "白身魚", "is_correct": false, "explanation": "瓶に入れて売られる食材ではないので、この文に合わない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "文房具で、瓶に入った食べ物を買う文には合わない。"}, {"text": "蜂蜜", "is_correct": true, "explanation": "小さな瓶に入って売られる〈蜂蜜〉が入る。"}], "explanations": {"鶏肉": "小さな瓶に入って売られる食材ではないので、この文に合わない。", "白身魚": "瓶に入れて売られる食材ではないので、この文に合わない。", "消しゴム": "文房具で、瓶に入った食べ物を買う文には合わない。", "蜂蜜": "小さな瓶に入って売られる〈蜂蜜〉が入る。"}, "sentence_index": 6, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この蜂蜜は、とうもろこしのでんぷんを煮詰めて作られる。", "explanation": "ここは〈水あめ〉の意味。水あめはでんぷんから作るが、蜂蜜はミツバチが集めた蜜から作る。"}, {"text": "蜂蜜を溶かしてろうそくを作り、部屋を明るくした。", "explanation": "ここは〈蜜蝋〉（ミツバチのろう）の意味。ろうそくには蜜ろうを使い、蜂蜜は食べ物で燃やさない。"}, {"text": "蜂蜜を熱したフライパンに入れて、からっと揚げた。", "explanation": "ここは〈油〉の意味。揚げ物は油で揚げるもので、蜂蜜では揚げられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は蜂蜜が紅茶に入れて飲んだ。", "corrected_sentence": "祖母は蜂蜜を紅茶に入れて飲んだ。", "error_description": "『蜂蜜』に続く助詞が『が』になっている。『入れる』の目的語なので『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は毎朝、蜂蜜を熱いお湯に溶けて飲んだ。", "corrected_sentence": "祖父は毎朝、蜂蜜を熱いお湯に溶かして飲んだ。", "error_description": "『蜂蜜を』に続く動詞の形が誤り。『溶ける』は自動詞で目的語『を』と合わないので、他動詞『溶かす』の『溶かして』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「生命を守る」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「守る」は対象を「を」で示すため、「生命に守る」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、守る対象の「生命」には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、守る対象としての「生命」とは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "正解。「生命を守る」の目的語を示す「を」。", "に": "「守る」は対象を「を」で示すため、「生命に守る」は成立しない。", "と": "「と」は並列や相手を示すので、守る対象の「生命」には合わない。", "へ": "「へ」は方向を示すので、守る対象としての「生命」とは結びつかない。"}, "error_tags": {"に": "場所・方向", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "正解。「どんな生命も」の「も」で、例外なく全てを含むことを表す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「生命で生きられない」は成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「生命から生きられない」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「生命より生きられない」は文として成立しない。"}], "correct_answer": "も", "explanations": {"も": "正解。「どんな生命も」の「も」で、例外なく全てを含むことを表す。", "で": "「で」は手段や場所を示すため、「生命で生きられない」は成立しない。", "から": "「から」は起点を示すので、「生命から生きられない」は意味が通らない。", "より": "「より」は比較を示すので、「生命より生きられない」は文として成立しない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生きているものに、生きていることや、生きていられる力を与えるもの。", "primary_collocate": null, "pronunciation": "せいめい", "ipa": "seːmeː", "syllable_count": 4, "sentences": [{"text": "生命は地球上でどのように生まれたのだろうか。", "target_word": "生命", "complexity_tier": "T3", "furigana": "生命[せいめい]は地球上[ちきゅうじょう]でどのように生[う]まれたのだろうか。", "sentence_source": "generated"}, {"text": "医者は患者の生命を守るために全力を尽くした。", "target_word": "生命", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の生命[せいめい]を守[まも]るために全力[ぜんりょく]を尽[つ]くした。", "sentence_source": "generated"}, {"text": "この薬のおかげで、彼の生命は救われた。", "target_word": "生命", "complexity_tier": "T3", "furigana": "この薬[くすり]のおかげで、彼[かれ]の生命[せいめい]は救[すく]われた。", "sentence_source": "generated"}, {"text": "小さな虫にも一つの生命が宿っている。", "target_word": "生命", "complexity_tier": "T3", "furigana": "小[ちい]さな虫[むし]にも一[ひと]つの生命[せいめい]が宿[やど]っている。", "sentence_source": "generated"}, {"text": "火山の近くの海で、新しい生命が見つかった。", "target_word": "生命", "complexity_tier": "T3", "furigana": "火山[かざん]の近[ちか]くの海[うみ]で、新[あたら]しい生命[せいめい]が見[み]つかった。", "sentence_source": "generated"}, {"text": "事故にあったが、幸い生命に別状はなかった。", "target_word": "生命", "complexity_tier": "T3", "furigana": "事故[じこ]にあったが、幸[さいわ]い生命[せいめい]に別状[べつじょう]はなかった。", "sentence_source": "generated"}, {"text": "彼は生命の誕生について研究している。", "target_word": "生命", "complexity_tier": "T3", "furigana": "彼[かれ]は生命[せいめい]の誕生[たんじょう]について研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "水がなければ、どんな生命も生きられない。", "target_word": "生命", "complexity_tier": "T3", "furigana": "水[みず]がなければ、どんな生命[せいめい]も生[い]きられない。", "sentence_source": "generated"}, {"text": "母は新しい生命を授かり、毎日幸せそうだ。", "target_word": "生命", "complexity_tier": "T3", "furigana": "母[はは]は新[あたら]しい生命[せいめい]を授[さず]かり、毎日[まいにち]幸[しあわ]せそうだ。", "sentence_source": "generated"}, {"text": "戦争は多くの人の生命をうばった。", "target_word": "生命", "complexity_tier": "T3", "furigana": "戦争[せんそう]は多[おお]くの人[ひと]の生命[せいめい]をうばった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生命", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "生き物が生きていることや、生きていられる力そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: うばっ (Zipf 1.45)']::text[], 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正解。「生命は地球上でどのように生まれたのか」は、生き物の始まりを問う文として自然。"}, {"text": "食料", "is_correct": false, "explanation": "食料は作られたり得られたりするもので、地球上で「生まれる」対象としては不自然。"}, {"text": "地層", "is_correct": false, "explanation": "地層は土砂の堆積によってできるもので、「生まれる」対象としては合わない。"}, {"text": "環境", "is_correct": false, "explanation": "環境は生き物を取り囲む周りの状況を指し、そのものが「生まれる」とは言わないので合わない。"}], "explanations": {"生命": "正解。「生命は地球上でどのように生まれたのか」は、生き物の始まりを問う文として自然。", "食料": "食料は作られたり得られたりするもので、地球上で「生まれる」対象としては不自然。", "地層": "地層は土砂の堆積によってできるもので、「生まれる」対象としては合わない。", "環境": "環境は生き物を取り囲む周りの状況を指し、そのものが「生まれる」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この冷蔵庫の生命は、約十年だ。", "explanation": "ここは〈寿命〉の意味。機械や製品が使える年数は寿命と言い、生命は生き物について使うので合わない。"}, {"text": "一人暮らしの生命に、ようやく慣れてきた。", "explanation": "ここは〈生活〉の意味。暮らしの様子は生活と言い、生命は生きていること自体を指すので「慣れる」の対象として合わない。"}, {"text": "祖母はこの町で八十年の生命を過ごした。", "explanation": "ここは〈生涯〉の意味。一生の長さを言うときは生涯を使い、生命は「過ごす」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命", "is_correct": true, "explanation": "正解。「生命の誕生」は生き物の始まりを指し、研究対象として自然。"}, {"text": "健康", "is_correct": false, "explanation": "健康は心身の状態で、「誕生」の対象にはならないので合わない。"}, {"text": "貯金", "is_correct": false, "explanation": "貯金は手元に蓄えるお金で、「誕生」の研究対象としては不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は一時的な感覚で、「誕生について研究」という文脈には合わない。"}], "explanations": {"生命": "正解。「生命の誕生」は生き物の始まりを指し、研究対象として自然。", "健康": "健康は心身の状態で、「誕生」の対象にはならないので合わない。", "貯金": "貯金は手元に蓄えるお金で、「誕生」の研究対象としては不自然。", "眠気": "眠気は一時的な感覚で、「誕生について研究」という文脈には合わない。"}, "sentence_index": 6, "correct_answer": "生命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "首相は記者会見で、終戦に向けた生命を読み上げた。", "explanation": "ここは〈声明〉の意味。公式の立場での発表は声明と言い、生命（生きていること）とは別の語なので合わない。"}, {"text": "受付で、まず生命を書いてください。", "explanation": "ここは〈姓名〉の意味。名字と名前を指すので、命の意味の生命では合わない。"}, {"text": "家族そろって、生命の墓参りに出かけた。", "explanation": "ここは〈清明〉の意味。清明の時期に行う墓参りを指す語で、生きていること（生命）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の遭難で、登山者の生命を危険にさらされた。", "corrected_sentence": "山の遭難で、登山者の生命が危険にさらされた。", "error_description": "「危険にさらされる」は受け身で、主語は「生命が」になる。「生命を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39584, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この手術で、子どもの生命が救わられた。", "corrected_sentence": "この手術で、子どもの生命が救われた。", "error_description": "「救う」の受け身は「救われた」。「救わられた」は誤った活用で、「ら」が余分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「周りの海を圧倒するほど」の「を」は比べる対象を示し、他動詞の目的語として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「周りの海に圧倒する」は対象を示せず、圧倒の使い方に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「周りの海と圧倒する」は並列の意味になり、比べる対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「周りの海から圧倒する」は起点を表し、比べる対象を示す文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「周りの海を圧倒するほど」の「を」は比べる対象を示し、他動詞の目的語として正しい。", "に": "「周りの海に圧倒する」は対象を示せず、圧倒の使い方に合わない。", "と": "「周りの海と圧倒する」は並列の意味になり、比べる対象を表せない。", "から": "「周りの海から圧倒する」は起点を表し、比べる対象を示す文脈に合わない。"}, "error_tags": {"に": "対象の取り違え（他動詞）", "と": "並列・共同", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「周りの川を圧倒するほど」の「を」は比べる対象を示し、他動詞の目的語として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「周りの川に圧倒する」は対象を示せず、圧倒の使い方に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「周りの川で圧倒する」は手段や場所を示すが、比べる対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「周りの川から圧倒する」は起点を表し、比べる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「周りの川を圧倒するほど」の「を」は比べる対象を示し、他動詞の目的語として正しい。", "に": "「周りの川に圧倒する」は対象を示せず、圧倒の使い方に合わない。", "で": "「周りの川で圧倒する」は手段や場所を示すが、比べる対象にはならない。", "から": "「周りの川から圧倒する」は起点を表し、比べる対象を示せない。"}, "error_tags": {"に": "対象の取り違え（他動詞）", "で": "手段・場所の取り違え", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ほかのものより、ずっと大きいこと。とても強いこと。", "primary_collocate": null, "pronunciation": "あっとう", "ipa": "at̚toː", "syllable_count": 4, "sentences": [{"text": "国会では与党の議席が野党を圧倒するほど多く、法案はすぐに通った。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "国会[こっかい]では与党[よとう]の議席[ぎせき]が野党[やとう]を圧倒[あっとう]するほど多[おお]く、法案[ほうあん]はすぐに通[とお]った。", "sentence_source": "generated"}, {"text": "世界の海の中で、太平洋は面積が周りの海を圧倒するほど大きい。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "世界[せかい]の海[うみ]の中[なか]で、太平洋[たいへいよう]は面積[めんせき]が周[まわ]りの海[うみ]を圧倒[あっとう]するほど大[おお]きい。", "sentence_source": "generated"}, {"text": "その国は軍事力が近隣諸国を圧倒するほど強く、どの国も戦うことを避けた。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "その国[くに]は軍事力[ぐんじりょく]が近隣諸国[きんりんしょこく]を圧倒[あっとう]するほど強[つよ]く、どの国[くに]も戦[たたか]うことを避[さ]けた。", "sentence_source": "generated"}, {"text": "地震の揺れは人の力を圧倒するほど強く、古い家を一瞬で壊した。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "地震[じしん]の揺[ゆ]れは人[ひと]の力[ちから]を圧倒[あっとう]するほど強[つよ]く、古[ふる]い家[いえ]を一瞬[いっしゅん]で壊[こわ]した。", "sentence_source": "generated"}, {"text": "山頂から見た星空は数が多すぎて、空が白く見えるほどで、ほかの景色を圧倒していた。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "山頂[さんちょう]から見[み]た星空[ほしぞら]は数[かず]が多[おお]すぎて、空[そら]が白[しろ]く見[み]えるほどで、ほかの景色[けしき]を圧倒[あっとう]していた。", "sentence_source": "generated"}, {"text": "今回の試合では、相手チームが私たちを圧倒するほど強く、何もできなかった。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "今回[こんかい]の試合[しあい]では、相手[あいて]チームが私[わたし]たちを圧倒[あっとう]するほど強[つよ]く、何[なに]もできなかった。", "sentence_source": "generated"}, {"text": "この町では、車の利用者が電車の利用者を圧倒していて、電車に乗る人は少ない。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "この町[まち]では、車[くるま]の利用者[りようしゃ]が電車[でんしゃ]の利用者[りようしゃ]を圧倒[あっとう]していて、電車[でんしゃ]に乗[の]る人[ひと]は少[すく]ない。", "sentence_source": "generated"}, {"text": "巨大な滝の水量は周りの川を圧倒するほどで、見ていた観光客は声も出なかった。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "巨大[きょだい]な滝[たき]の水量[すいりょう]は周[まわ]りの川[かわ]を圧倒[あっとう]するほどで、見[み]ていた観光客[かんこうきゃく]は声[こえ]も出[で]なかった。", "sentence_source": "generated"}, {"text": "参加者の数は反対派を圧倒するほど多く、新しい計画は賛成多数で決まった。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の数[かず]は反対派[はんたいは]を圧倒[あっとう]するほど多[おお]く、新しい計画[けいかく]は賛成多数[さんせいたすう]で決[き]まった。", "sentence_source": "generated"}, {"text": "彼女は二位を圧倒するほどの差をつけて、一位でゴールした。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は二位[にい]を圧倒[あっとう]するほどの差[さ]をつけて、一位[いちい]でゴールした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "圧倒", "label": "基本形"}, {"form": "圧倒する", "label": "サ変動詞"}, {"form": "圧倒的", "label": "形状詞"}], "register": "neutral", "sense_fingerprint": "量・力・差などが他と比べてずっと大きい、非常に強い(規模・強さの圧倒的な大きさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "圧倒", "is_correct": true, "explanation": "「野党を___するほど多く」で、議席の差の大きさを表す語として自然に入る。"}, {"text": "辞退", "is_correct": false, "explanation": "「辞退」は断る意味で、議席の多さを表す「〜するほど多く」の文脈に合わない。"}, {"text": "採用", "is_correct": false, "explanation": "「採用」は取り入れる意味で、「野党を採用するほど多く」は不自然で文が通らない。"}, {"text": "補償", "is_correct": false, "explanation": "「補償」は損害を埋める意味で、議席の多さを示す文脈に合わない。"}], "explanations": {"圧倒": "「野党を___するほど多く」で、議席の差の大きさを表す語として自然に入る。", "辞退": "「辞退」は断る意味で、議席の多さを表す「〜するほど多く」の文脈に合わない。", "採用": "「採用」は取り入れる意味で、「野党を採用するほど多く」は不自然で文が通らない。", "補償": "「補償」は損害を埋める意味で、議席の多さを示す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "圧倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ぶどうを圧倒して、ジュースを作った。", "explanation": "ここは〈圧搾〉（押しつぶして汁を絞る）の意味。圧倒は大きさや強さの程度を表す語で、果汁を絞る意味では使わない。"}, {"text": "痛みを圧倒するために、深呼吸をくり返した。", "explanation": "ここは〈しのぐ〉（耐え抜く）の意味。大きさや強さを表す語義ではなく、我慢して耐えることを指すため合わない。"}, {"text": "画像を圧倒して、ファイルを小さくした。", "explanation": "ここは〈圧縮〉（容積を縮める）の意味。圧倒は大きさや差の程度を表し、データを小さくする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "圧倒", "is_correct": true, "explanation": "「電車の利用者を___していて」で、利用者の数で大きく上回る状況を表し、文脈に合う。"}, {"text": "運転", "is_correct": false, "explanation": "「運転」は車両を操作することで、利用者の数の比較には入らない。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」は設備を調べる行為で、利用者の数を比べる文脈には合わない。"}, {"text": "録音", "is_correct": false, "explanation": "「録音」は音を記録する意味で、利用者の数の多さを示す文脈に合わない。"}], "explanations": {"圧倒": "「電車の利用者を___していて」で、利用者の数で大きく上回る状況を表し、文脈に合う。", "運転": "「運転」は車両を操作することで、利用者の数の比較には入らない。", "点検": "「点検」は設備を調べる行為で、利用者の数を比べる文脈には合わない。", "録音": "「録音」は音を記録する意味で、利用者の数の多さを示す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "圧倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火事を圧倒するため、消防車が出動した。", "explanation": "ここは〈消火〉（火を消すこと）の意味。圧倒は他に大きく差をつける意味で、火を消す意味では使わない。"}, {"text": "解熱剤で熱を圧倒した。", "explanation": "ここは〈抑える〉（下げる・おさえる）の意味。圧倒は大きさや力が際立つことを表し、熱を下げる意味では使わない。"}, {"text": "重いリュックが背中を圧倒して、息が苦しくなった。", "explanation": "ここは〈圧迫〉（押しつぶす）の意味。圧倒は比較の差を表し、体を押さえつける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の人口は近くの町に圧倒するほど多く、学校も増えている。", "corrected_sentence": "この町の人口は近くの町を圧倒するほど多く、学校も増えている。", "error_description": "「圧倒する」は他動詞で、比べる相手は「を」で示す。「に」は誤りで、正しくは「近くの町を圧倒するほど」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39586, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この島の山は周りの山を圧倒ほど高く、雲がかかっている。", "corrected_sentence": "この島の山は周りの山を圧倒するほど高く、雲がかかっている。", "error_description": "「圧倒するほど」の「する」が抜けている。「圧倒ほど」は語形の誤りで、正しくは「圧倒するほど」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「相手を圧倒し」の「を」は圧倒の対象を示し、他動詞の目的語として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「相手に圧倒し」は圧倒が他動詞なので不自然で、対象には「を」を使う。"}, {"text": "と", "is_correct": false, "explanation": "「相手と圧倒し」では対象を示せず、文の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「相手から圧倒し」は起点を表すが、圧倒の対象を示す文脈には合わない。"}], "correct_answer": "を", "explanations": {"を": "「相手を圧倒し」の「を」は圧倒の対象を示し、他動詞の目的語として正しい。", "に": "「相手に圧倒し」は圧倒が他動詞なので不自然で、対象には「を」を使う。", "と": "「相手と圧倒し」では対象を示せず、文の意味が通らない。", "から": "「相手から圧倒し」は起点を表すが、圧倒の対象を示す文脈には合わない。"}, "error_tags": {"に": "対象の取り違え（他動詞の目的語）", "と": "並列・共同（対象にならない）", "から": "起点（対象を示さない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ほかの生徒を圧倒して」の「を」は圧倒の対象を示し、他動詞として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ほかの生徒が圧倒して」では生徒が圧倒する主体になり、文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「ほかの生徒に圧倒して」は圧倒が他動詞なので不自然で、対象には「を」を使う。"}, {"text": "で", "is_correct": false, "explanation": "「ほかの生徒で圧倒して」は手段や場所を示すが、圧倒の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「ほかの生徒を圧倒して」の「を」は圧倒の対象を示し、他動詞として正しい。", "が": "「ほかの生徒が圧倒して」では生徒が圧倒する主体になり、文の意味が通らない。", "に": "「ほかの生徒に圧倒して」は圧倒が他動詞なので不自然で、対象には「を」を使う。", "で": "「ほかの生徒で圧倒して」は手段や場所を示すが、圧倒の対象にはならない。"}, "error_tags": {"が": "主語の取り違え", "に": "対象の取り違え（受け身との混同）", "で": "手段・場所の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他を大きく上回っていること。比べものにならないほど優れていること。", "primary_collocate": null, "pronunciation": "あっとう", "ipa": "at̚toː", "syllable_count": 4, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "圧倒的", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]ヨーロッパで発展[はってん]したゴシック様式[ようしき]の大聖堂[だいせいどう]は、その圧倒的[あっとうてき]な高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "mined"}, {"text": "彼のチームは経験でも技術でも相手を圧倒し、決勝で楽に勝った。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは経験[けいけん]でも技術[ぎじゅつ]でも相手[あいて]を圧倒[あっとう]し、決勝[けっしょう]で楽[らく]に勝[か]った。", "sentence_source": "generated"}, {"text": "新しい機種は性能が高く、他社の製品を圧倒した。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "新[あたら]しい機種[きしゅ]は性能[せいのう]が高[たか]く、他社[たしゃ]の製品[せいひん]を圧倒[あっとう]した。", "sentence_source": "generated"}, {"text": "その選手は走る速さで他の選手を圧倒して優勝した。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "その選手[せんしゅ]は走[はし]る速[はや]さで他[ほか]の選手[せんしゅ]を圧倒[あっとう]して優勝[ゆうしょう]した。", "sentence_source": "generated"}, {"text": "選挙では、与党が票数で野党を圧倒した。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "選挙[せんきょ]では、与党[よとう]が票数[ひょうすう]で野党[やとう]を圧倒[あっとう]した。", "sentence_source": "generated"}, {"text": "この作家の文章力は、ほかの新人を圧倒している。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "この作家[さっか]の文章力[ぶんしょうりょく]は、ほかの新人[しんじん]を圧倒[あっとう]している。", "sentence_source": "generated"}, {"text": "試合は最初から相手に圧倒され、一点も取れずに終わった。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "試合[しあい]は最初[さいしょ]から相手[あいて]に圧倒[あっとう]され、一点[いってん]も取[と]れずに終[お]わった。", "sentence_source": "generated"}, {"text": "英語の成績では、彼女がほかの生徒を圧倒して、クラスで一番になった。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "英語[えいご]の成績[せいせき]では、彼女[かのじょ]がほかの生徒[せいと]を圧倒[あっとう]して、クラスで一番[いちばん]になった。", "sentence_source": "generated"}, {"text": "その歌手の歌声は他を圧倒するほどすばらしく、会場は静まり返った。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "その歌手[かしゅ]の歌声[うたごえ]は他[ほか]を圧倒[あっとう]するほどすばらしく、会場[かいじょう]は静[しず]まり返[かえ]った。", "sentence_source": "generated"}, {"text": "この店のラーメンは味の点で近くの店を圧倒していて、いつも行列ができている。", "target_word": "圧倒", "complexity_tier": "T3", "furigana": "この店[みせ]のラーメンは味[あじ]の点[てん]で近[ちか]くの店[みせ]を圧倒[あっとう]していて、いつも行列[ぎょうれつ]ができている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "圧倒", "label": "基本形"}, {"form": "圧倒する", "label": "サ変動詞"}, {"form": "圧倒した", "label": "過去形"}, {"form": "圧倒される", "label": "受身形"}, {"form": "圧倒的", "label": "形状詞"}], "register": "neutral", "sense_fingerprint": "他より圧倒的に優れている、他を大きく上回る(優位・優越)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "圧倒的", "is_correct": true, "explanation": "「その___な高さと美しさ」に入る形状詞で、大聖堂の際立つ印象を表すため文脈に合う。"}, {"text": "平坦", "is_correct": false, "explanation": "「平坦」は高さと矛盾するため、高くそびえる大聖堂の描写に合わない。"}, {"text": "静的", "is_correct": false, "explanation": "「静的」は動きのない状態を指し、高さや美しさを修飾する語としては合わない。"}, {"text": "不安定", "is_correct": false, "explanation": "「不安定」は揺らぎを表し、堂々とした高さの描写に合わない。"}], "explanations": {"圧倒的": "「その___な高さと美しさ」に入る形状詞で、大聖堂の際立つ印象を表すため文脈に合う。", "平坦": "「平坦」は高さと矛盾するため、高くそびえる大聖堂の描写に合わない。", "静的": "「静的」は動きのない状態を指し、高さや美しさを修飾する語としては合わない。", "不安定": "「不安定」は揺らぎを表し、堂々とした高さの描写に合わない。"}, "sentence_index": 0, "correct_answer": "圧倒的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物が肩を圧倒して、腕がしびれた。", "explanation": "ここは〈圧迫〉（押さえつける）の意味。圧倒は他との比較で優れることを表し、体を押さえつける意味では使わない。"}, {"text": "りんごを圧倒して、果汁を絞った。", "explanation": "ここは〈圧搾〉（押しつぶして汁を絞る）の意味。圧倒は他との優劣を表す語で、果汁を絞る意味では使わない。"}, {"text": "鉄の塊を圧倒して、薄い板にした。", "explanation": "ここは〈圧延〉（ローラーで押し延ばす加工）の意味。圧倒は他との優劣を表す語で、金属を薄く延ばす加工は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "圧倒", "is_correct": true, "explanation": "「相手に___され」の受け身の形で、一方的に押された試合の流れに合う。"}, {"text": "応援", "is_correct": false, "explanation": "「応援」は味方を励む行為で、相手に押される文脈に合わない。"}, {"text": "観戦", "is_correct": false, "explanation": "「観戦」は見ることなので、一点も取れずに終わった流れと合わない。"}, {"text": "解説", "is_correct": false, "explanation": "「解説」は説明する行為で、一方的に押された試合の流れには合わず、意味が通らない。"}], "explanations": {"圧倒": "「相手に___され」の受け身の形で、一方的に押された試合の流れに合う。", "応援": "「応援」は味方を励む行為で、相手に押される文脈に合わない。", "観戦": "「観戦」は見ることなので、一点も取れずに終わった流れと合わない。", "解説": "「解説」は説明する行為で、一方的に押された試合の流れには合わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "圧倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "データを圧倒して、ファイルの容量を減らした。", "explanation": "ここは〈圧縮〉（容積を縮める）の意味。圧倒は他との優劣を表し、物の大きさを縮める意味では使わない。"}, {"text": "雪道を圧倒して、スキー場を整えた。", "explanation": "ここは〈圧雪〉（雪を踏み固めること）の意味。圧倒は他との優劣を表す語で、雪を固める意味では使わない。"}, {"text": "寒さを圧倒するために、毛布を重ねて眠った。", "explanation": "ここは〈しのぐ〉（耐え抜く）の意味。圧倒は他に勝つ意味で、我慢して耐えることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テストでは、彼女が他の生徒に圧倒して、学年で一番になった。", "corrected_sentence": "テストでは、彼女が他の生徒を圧倒して、学年で一番になった。", "error_description": "「圧倒する」は他動詞で、圧倒の対象は「を」で示す。「に」は誤りで、正しくは「他の生徒を圧倒して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39587, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手は私たちを圧倒されて、何もできなかった。", "corrected_sentence": "相手は私たちを圧倒して、何もできなかった。", "error_description": "「圧倒されて」は受け身で、圧倒される人の側に「が」が立つ形。目的語の「を」と受け身を併用しているのが誤りで、正しくは「圧倒して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「この果実は甘い」とその果実について述べる文に合う"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「果実を甘いので」では形容詞に続かず、文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "位置・相手を示す。「果実に甘いので」では形容詞とつながらず不自然"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示す。「果実で甘いので」では意味が通らない"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「この果実は甘い」とその果実について述べる文に合う", "を": "目的語を示す。「果実を甘いので」では形容詞に続かず、文が成り立たない", "に": "位置・相手を示す。「果実に甘いので」では形容詞とつながらず不自然", "で": "手段・場所を示す。「果実で甘いので」では意味が通らない"}, "error_tags": {"を": "目的語（対象）", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
