INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木や草になる、たべられるもの。", "primary_collocate": null, "pronunciation": "かじつ", "ipa": "kad͡ʑitsɯ", "syllable_count": 3, "sentences": [{"text": "秋になると、山には赤い果実がたくさん実る。", "target_word": "果実", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]には赤[あか]い果実[かじつ]がたくさん実[みの]る。", "sentence_source": "generated"}, {"text": "この果実は甘いので、子どもにも人気がある。", "target_word": "果実", "complexity_tier": "T3", "furigana": "この果実[かじつ]は甘[あま]いので、子[こ]どもにも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "鳥は木の果実を食べて、種を遠くへ運ぶ。", "target_word": "果実", "complexity_tier": "T3", "furigana": "鳥[とり]は木[き]の果実[かじつ]を食[た]べて、種[たね]を遠[とお]くへ運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "店には、季節の果実がきれいに並んでいる。", "target_word": "果実", "complexity_tier": "T3", "furigana": "店[みせ]には、季節[きせつ]の果実[かじつ]がきれいに並[なら]んでいる。", "sentence_source": "generated"}, {"text": "熟していない果実は、すっぱくて食べにくい。", "target_word": "果実", "complexity_tier": "T3", "furigana": "熟[じゅく]していない果実[かじつ]は、すっぱくて食[た]べにくい。", "sentence_source": "generated"}, {"text": "森で見つけた果実を、洗ってから口に入れた。", "target_word": "果実", "complexity_tier": "T3", "furigana": "森[もり]で見[み]つけた果実[かじつ]を、洗[あら]ってから口[くち]に入[い]れた。", "sentence_source": "generated"}, {"text": "果実のジュースは、体によいと言われている。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]のジュースは、体[からだ]によいと言[い]われている。", "sentence_source": "generated"}, {"text": "冬の間、サルは木に残った果実を探して歩く。", "target_word": "果実", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、サルは木[き]に残[のこ]った果実[かじつ]を探[さが]して歩[ある]く。", "sentence_source": "generated"}, {"text": "母は庭の果実を使って、ジャムを作った。", "target_word": "果実", "complexity_tier": "T3", "furigana": "母[はは]は庭[にわ]の果実[かじつ]を使[つか]って、ジャムを作[つく]った。", "sentence_source": "generated"}, {"text": "果実が重くなり、枝が下に曲がっている。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]が重[おも]くなり、枝[えだ]が下[した]に曲[ま]がっている。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "木や草になる、食べられる実", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: すっぱく (Zipf 1.83)']::text[], '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果汁", "is_correct": false, "explanation": "果物を搾った液体。木になって実るものではないので合わない"}, {"text": "木材", "is_correct": false, "explanation": "木を加工した材料。実らないので合わない"}, {"text": "果実", "is_correct": true, "explanation": "木になる食べられる部分。山に赤い実がたくさん実る文に合う"}, {"text": "花弁", "is_correct": false, "explanation": "花びら。実るものではないので合わない"}], "explanations": {"果汁": "果物を搾った液体。木になって実るものではないので合わない", "木材": "木を加工した材料。実らないので合わない", "果実": "木になる食べられる部分。山に赤い実がたくさん実る文に合う", "花弁": "花びら。実るものではないので合わない"}, "sentence_index": 0, "correct_answer": "果実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この果実は、三年前に町の議会で可決された。", "explanation": "ここは〈議案〉の意味。議会で可決されるのは議案で、食べられる果実の意味では使えないので合わない。"}, {"text": "この果実の液を、瓶に詰めて一年寝かせた。", "explanation": "ここは〈果汁〉の意味。搾った液を瓶で寝かせるのは果汁で、木に実る果実の意味では使えないので合わない。"}, {"text": "冬になると、果実が葉を落として休む。", "explanation": "ここは〈木〉の意味。葉を落として冬を越すのは木全体で、食べられる実の果実には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "樹脂", "is_correct": false, "explanation": "木から出る樹液の固まり。ジュースの材料にはならない"}, {"text": "樹皮", "is_correct": false, "explanation": "木の外側の皮。ジュースにはならないので合わない"}, {"text": "灌木", "is_correct": false, "explanation": "低い木の種類。ジュースの材料にはならない"}, {"text": "果実", "is_correct": true, "explanation": "食べられる実。果物のジュースの材料として文に合う"}], "explanations": {"樹脂": "木から出る樹液の固まり。ジュースの材料にはならない", "樹皮": "木の外側の皮。ジュースにはならないので合わない", "灌木": "低い木の種類。ジュースの材料にはならない", "果実": "食べられる実。果物のジュースの材料として文に合う"}, "sentence_index": 6, "correct_answer": "果実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春になると、桜の果実が一斉に咲き始める。", "explanation": "ここは〈花〉の意味。咲くのは花で、木になる食べられる実には使わないので合わない。"}, {"text": "この苗は、果実を一粒ずつ土にまいて育てた。", "explanation": "ここは〈種〉の意味。まくのは種で、果実は種を含む実全体を指すので合わない。"}, {"text": "果実は、植え替えの時期が遅れると弱る。", "explanation": "ここは〈果樹〉の意味。植え替えの対象は木そのもので、木になる実には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鳥は、熟した果実で食べる。", "corrected_sentence": "鳥は、熟した果実を食べる。", "error_description": "誤りは〈果実で〉。食べる対象は〈を〉で示す。〈で〉は手段や場所を表すので、この文では意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39588, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この木は、毎年たくさんの果実がつける。", "corrected_sentence": "この木は、毎年たくさんの果実をつける。", "error_description": "誤りは〈果実が〉。〈つける〉の目的語は〈を〉で示す。〈が〉だと主語になり、主語の木と合わなくなる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
