INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39589, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物が花のあとにつくる、種子を含む部分。多くの場合、食用になる。", "primary_collocate": null, "pronunciation": "かじつ", "ipa": "kad͡ʑitsɯ", "syllable_count": 3, "sentences": [{"text": "花が散ったあとに、小さな果実ができ始めた。", "target_word": "果実", "complexity_tier": "T3", "furigana": "花[はな]が散[ち]ったあとに、小[ちい]さな果実[かじつ]ができ始[はじ]めた。", "sentence_source": "generated"}, {"text": "果実の中には、種が入っている。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]の中[なか]には、種[たね]が入[はい]っている。", "sentence_source": "generated"}, {"text": "トマトは野菜として売られるが、植物としては果実だ。", "target_word": "果実", "complexity_tier": "T3", "furigana": "トマトは野菜[やさい]として売[う]られるが、植物[しょくぶつ]としては果実[かじつ]だ。", "sentence_source": "generated"}, {"text": "受粉した花は、やがて果実に育つ。", "target_word": "果実", "complexity_tier": "T3", "furigana": "受粉[じゅふん]した花[はな]は、やがて果実[かじつ]に育[そだ]つ。", "sentence_source": "generated"}, {"text": "果実が大きくなるまで、約三か月かかる。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]が大[おお]きくなるまで、約[やく]三[さん]か月[げつ]かかる。", "sentence_source": "generated"}, {"text": "乾燥した果実がはじけて、種が飛び散った。", "target_word": "果実", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した果実[かじつ]がはじけて、種[たね]が飛[と]び散[ち]った。", "sentence_source": "generated"}, {"text": "果実の皮がかたい植物は、中の種を守りやすい。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]の皮[かわ]がかたい植物[しょくぶつ]は、中[なか]の種[たね]を守[まも]りやすい。", "sentence_source": "generated"}, {"text": "この木は、毎年夏に黄色い果実をつける。", "target_word": "果実", "complexity_tier": "T3", "furigana": "この木[き]は、毎年[まいとし]夏[なつ]に黄色[きいろ]い果実[かじつ]をつける。", "sentence_source": "generated"}, {"text": "果実の形は、植物によってそれぞれちがう。", "target_word": "果実", "complexity_tier": "T3", "furigana": "果実[かじつ]の形[かたち]は、植物[しょくぶつ]によってそれぞれちがう。", "sentence_source": "generated"}, {"text": "実験では、果実を半分に切って種の数を数えた。", "target_word": "果実", "complexity_tier": "T3", "furigana": "実験[じっけん]では、果実[かじつ]を半分[はんぶん]に切[き]って種[たね]の数[かず]を数[かぞ]えた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "花のあとにでき、種を含む植物の器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39589, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陽光", "is_correct": false, "explanation": "太陽の光。花のあとにできるものではないので合わない"}, {"text": "石灰", "is_correct": false, "explanation": "カルシウム化合物。植物の実として生じないので合わない"}, {"text": "果実", "is_correct": true, "explanation": "花が散ったあとに種を含んでできる実。文に合う"}, {"text": "鉄くず", "is_correct": false, "explanation": "金属の破片。花のあとにできるものではないので合わない"}], "explanations": {"陽光": "太陽の光。花のあとにできるものではないので合わない", "石灰": "カルシウム化合物。植物の実として生じないので合わない", "果実": "花が散ったあとに種を含んでできる実。文に合う", "鉄くず": "金属の破片。花のあとにできるものではないので合わない"}, "sentence_index": 0, "correct_answer": "果実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花が散ったあと、果実が根を伸ばして地中に広がる。", "explanation": "ここは〈根〉の意味。根を伸ばして地中に広がるのは植物の根で、花のあとにできる果実の部分には合わない。"}, {"text": "果実の汁が花のあとに育ち、中に種を含んでいる。", "explanation": "ここは〈果汁〉の意味。果汁は搾った液体で、花のあとに育って種を含む部分の意味では使えないので合わない。"}, {"text": "花が散ると、果実が葉を広げて日光を受ける。", "explanation": "ここは〈葉〉の意味。日光を受けて広げるのは葉で、種子を含む果実の部分には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39589, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花弁", "is_correct": false, "explanation": "花びら。種を守る実の皮の持ち主にはならない"}, {"text": "落葉", "is_correct": false, "explanation": "散った葉。皮の持ち主にはならないので合わない"}, {"text": "樹脂", "is_correct": false, "explanation": "樹木の分泌物。皮のかたさとは別物で、文の主語にならない"}, {"text": "果実", "is_correct": true, "explanation": "種を含む実。その皮がかたいことで種を守る文脈に合う"}], "explanations": {"花弁": "花びら。種を守る実の皮の持ち主にはならない", "落葉": "散った葉。皮の持ち主にはならないので合わない", "樹脂": "樹木の分泌物。皮のかたさとは別物で、文の主語にならない", "果実": "種を含む実。その皮がかたいことで種を守る文脈に合う"}, "sentence_index": 6, "correct_answer": "果実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この花は朝に開き、夕方には果実がしぼむ。", "explanation": "ここは〈花〉の意味。しぼむのは花で、種を含む果実には使わないので合わない。"}, {"text": "ひまわりの果実は、朝になると東を向いて開いた。", "explanation": "ここは〈花〉の意味。朝に開くのは花で、種を含む果実には使わないので合わない。"}, {"text": "果実の枝を、春に剪定した。", "explanation": "ここは〈果樹〉の意味。剪定の対象は木の枝で、木になる実の部分には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39589, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咲き終わった花は、やがて果実を育つ。", "corrected_sentence": "咲き終わった花は、やがて果実に育つ。", "error_description": "誤りは〈果実を〉。〈育つ〉は〈に〉で結果の状態を示す自動詞なので、正しくは〈果実に育つ〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39589, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ピーマンの果実を、中に種を含む。", "corrected_sentence": "ピーマンの果実は、中に種を含む。", "error_description": "誤りは〈果実を〉。〈含む〉の主語は〈果実は〉で示す。〈を〉だと主語がなくなり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "堅果は「拾う」の対象（目的語）なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。堅果は拾われる対象で、主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。堅果は拾う対象で、道具や場所ではない。"}, {"text": "に", "is_correct": false, "explanation": "帰着や目的地を示す。「堅果に拾いに行った」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "堅果は「拾う」の対象（目的語）なので「を」。", "が": "主語を示す。堅果は拾われる対象で、主語にはならない。", "で": "手段や場所を示す。堅果は拾う対象で、道具や場所ではない。", "に": "帰着や目的地を示す。「堅果に拾いに行った」とは言わない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "に": "帰着・目的地"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かたいからを持つ、木になる実のことです。", "primary_collocate": null, "pronunciation": "けんか", "ipa": "keŋka", "syllable_count": 3, "sentences": [{"text": "くるみやどんぐりは、堅果の仲間だ。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "くるみやどんぐりは、堅果[けんか]の仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "堅果はかたい殻に包まれているので、割って食べる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]はかたい殻[から]に包[つつ]まれているので、割[わ]って食[た]べる。", "sentence_source": "generated"}, {"text": "リスは秋になると、堅果を集めて土にうめる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "リスは秋[あき]になると、堅果[けんか]を集[あつ]めて土[つち]にうめる。", "sentence_source": "generated"}, {"text": "この森には、堅果をつける木がたくさんある。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "この森[もり]には、堅果[けんか]をつける木[き]がたくさんある。", "sentence_source": "generated"}, {"text": "堅果の殻は、道具がないと割れないほどかたい。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]の殻[から]は、道具[どうぐ]がないと割[わ]れないほどかたい。", "sentence_source": "generated"}, {"text": "栗も堅果の一種で、秋に拾って焼いて食べる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "栗[くり]も堅果[けんか]の一種[いっしゅ]で、秋[あき]に拾[ひろ]って焼[や]いて食[た]べる。", "sentence_source": "generated"}, {"text": "山に入った熊は、冬に備えて堅果をたくさん食べる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "山[やま]に入[はい]った熊[くま]は、冬[ふゆ]に備[そな]えて堅果[けんか]をたくさん食[た]べる。", "sentence_source": "generated"}, {"text": "堅果を拾いに行った子どもたちは、かごいっぱいに持ち帰った。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]を拾[ひろ]いに行[い]った子[こ]どもたちは、かごいっぱいに持[も]ち帰[かえ]った。", "sentence_source": "generated"}, {"text": "堅果が実る季節になると、野生の動物たちも活発になる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]が実[みの]る季節[きせつ]になると、野生[やせい]の動物[どうぶつ]たちも活発[かっぱつ]になる。", "sentence_source": "generated"}, {"text": "かたい殻を持つ堅果は、長い間保存できる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "かたい殻[から]を持[も]つ堅果[けんか]は、長[なが]い間[あいだ]保存[ほぞん]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "堅果", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "かたい殻に包まれた木の実（どんぐり・くるみ・栗など）。日常の場面で動物や人が拾って食べるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堅果", "is_correct": true, "explanation": "くるみやどんぐりが属する、かたい殻の木の実の分類名。ここに入る語として正しい。"}, {"text": "昆虫", "is_correct": false, "explanation": "くるみやどんぐりは植物の実で、昆虫の仲間ではない。"}, {"text": "海藻", "is_correct": false, "explanation": "海に生える藻類で、陸の木になる実の仲間ではない。"}, {"text": "苔", "is_correct": false, "explanation": "地面や岩に生える植物で、くるみやどんぐりとは別の仲間。"}], "explanations": {"堅果": "くるみやどんぐりが属する、かたい殻の木の実の分類名。ここに入る語として正しい。", "昆虫": "くるみやどんぐりは植物の実で、昆虫の仲間ではない。", "海藻": "海に生える藻類で、陸の木になる実の仲間ではない。", "苔": "地面や岩に生える植物で、くるみやどんぐりとは別の仲間。"}, "sentence_index": 0, "correct_answer": "堅果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この堅果は、皮をむくと甘くてみずみずしい果肉が現れる。", "explanation": "ここは〈多汁果〉の意味。堅果は殻が硬く中身が乾いた実で、果肉に水分が多い実には使わない。"}, {"text": "米や麦は堅果で、主食として世界中で食べられている。", "explanation": "ここは〈穀物〉の意味。米や麦は穀物であり、堅果とは呼ばない。"}, {"text": "夏になると、赤く熟した堅果を鳥が食べにくる。", "explanation": "ここは〈木の実（液果）〉の意味。赤く熟して果肉がある実は、硬い殻の堅果とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堅果", "is_correct": true, "explanation": "熊が冬に食べる木の実の総称。ここに入る語として正しい。"}, {"text": "花びら", "is_correct": false, "explanation": "熊が冬に食べるものではなく、花の一部。"}, {"text": "落ち葉", "is_correct": false, "explanation": "食料にはならず、熊が冬に備えて食べるものではない。"}, {"text": "小石", "is_correct": false, "explanation": "食べ物ではなく、熊が食べるとは言えない。"}], "explanations": {"堅果": "熊が冬に食べる木の実の総称。ここに入る語として正しい。", "花びら": "熊が冬に食べるものではなく、花の一部。", "落ち葉": "食料にはならず、熊が冬に備えて食べるものではない。", "小石": "食べ物ではなく、熊が食べるとは言えない。"}, "sentence_index": 6, "correct_answer": "堅果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桃は、果肉の奥に硬い核があるので堅果と呼ばれる。", "explanation": "ここは〈核果〉の意味。桃は核（種）を包む果実で、堅果とは分類が違う。"}, {"text": "トマトは、野菜として炒めても生でも食べられる堅果だ。", "explanation": "ここは〈果菜〉の意味。トマトのように果実を野菜として食べるものは、硬い殻の堅果とは言わない。"}, {"text": "その計画は堅果で、細かな点まで確かめられている。", "explanation": "ここは〈堅実〉の意味。計画が手堅いことは「堅実」で言い、「堅果」は実の種類を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "リスは秋に堅果が集めて、冬に備えて蓄える。", "corrected_sentence": "リスは秋に堅果を集めて、冬に備えて蓄える。", "error_description": "「集める」の目的語には「を」を使う。「堅果が」と主語の形にしたのは誤りで、正しくは「堅果を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39590, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "リスが堅果を一本ずつ拾って巣に運ぶ。", "corrected_sentence": "リスが堅果を一粒ずつ拾って巣に運ぶ。", "error_description": "堅果を数える助数詞は「粒」や「個」。「一本」は細長いものに使うので誤り。正しくは「一粒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「〜と呼ぶ」の形で名前を示す。ここでは「堅果と呼ぶ」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「呼ぶ」は「〜と呼ぶ」の形をとるので、目的語の「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着を示す。「堅果に呼ぶ」とは言わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「堅果で呼ぶ」は不自然。"}], "correct_answer": "と", "explanations": {"と": "「〜と呼ぶ」の形で名前を示す。ここでは「堅果と呼ぶ」が自然。", "を": "「呼ぶ」は「〜と呼ぶ」の形をとるので、目的語の「を」は合わない。", "に": "帰着を示す。「堅果に呼ぶ」とは言わない。", "で": "手段や場所を示す。「堅果で呼ぶ」は不自然。"}, "error_tags": {"を": "目的語", "に": "帰着・目的地", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "堅果は「乾燥させる」の対象（目的語）なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。堅果は乾燥させられる対象で、主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「堅果へ乾燥させる」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「堅果より乾燥させる」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "堅果は「乾燥させる」の対象（目的語）なので「を」。", "が": "主語を示す。堅果は乾燥させられる対象で、主語にはならない。", "へ": "方向を示す。「堅果へ乾燥させる」とは言わない。", "より": "比較を示す。「堅果より乾燥させる」では意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向・帰着", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "殻が硬く、中の種子を食用とする果実の総称。例えば、くるみやどんぐりなど。", "primary_collocate": null, "pronunciation": "けんか", "ipa": "keŋka", "syllable_count": 3, "sentences": [{"text": "堅果は、脂質やミネラルを多く含む食品だ。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]は、脂質[ししつ]やミネラルを多[おお]く含[ふく]む食品[しょくひん]だ。", "sentence_source": "generated"}, {"text": "植物学では、くりやどんぐりなどを堅果と呼ぶ。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "植物学[しょくぶつがく]では、くりやどんぐりなどを堅果[けんか]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "堅果にアレルギーのある人は、食品表示を確認する必要がある。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]にアレルギーのある人[ひと]は、食品表示[しょくひんひょうじ]を確認[かくにん]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "この菓子には、数種類の堅果が刻んで入っている。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "この菓子[かし]には、数種類[すうしゅるい]の堅果[けんか]が刻[きざ]んで入[はい]っている。", "sentence_source": "generated"}, {"text": "堅果の殻を割ると、中から白い種子が現れた。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]の殻[から]を割[わ]ると、中[なか]から白[しろ]い種子[しゅし]が現[あらわ]れた。", "sentence_source": "generated"}, {"text": "ブナ科の植物は、堅果をつける木が多い。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "ブナ科[か]の植物[しょくぶつ]は、堅果[けんか]をつける木[き]が多[おお]い。", "sentence_source": "generated"}, {"text": "堅果を毎日少し食べると、健康によいと言われている。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]を毎日[まいにち]少[すこ]し食[た]べると、健康[けんこう]によいと言[い]われている。", "sentence_source": "generated"}, {"text": "農家は収穫した堅果を乾燥させてから、市場に出荷する。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "農家[のうか]は収穫[しゅうかく]した堅果[けんか]を乾燥[かんそう]させてから、市場[いちば]に出荷[しゅっか]する。", "sentence_source": "generated"}, {"text": "堅果は硬い殻に守られており、中の種子は食用になる。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "堅果[けんか]は硬[かた]い殻[から]に守[まも]られており、中[なか]の種子[しゅし]は食用[しょくよう]になる。", "sentence_source": "generated"}, {"text": "このパンは、堅果の香ばしい風味が特徴だ。", "target_word": "堅果", "complexity_tier": "T3", "furigana": "このパンは、堅果[けんか]の香[こう]ばしい風味[ふうみ]が特徴[とくちょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "堅果", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "硬い殻の中の種子を食べる果実の総称。植物学・栄養・食品の説明で使う分類名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堅果", "is_correct": true, "explanation": "脂質やミネラルを多く含む食品の分類名。ここに入る語として正しい。"}, {"text": "粘土", "is_correct": false, "explanation": "食べられない土の材料で、食品ではない。"}, {"text": "石油", "is_correct": false, "explanation": "燃料であり、食品ではない。"}, {"text": "鉱石", "is_correct": false, "explanation": "岩石から取る鉱物で、食品ではない。"}], "explanations": {"堅果": "脂質やミネラルを多く含む食品の分類名。ここに入る語として正しい。", "粘土": "食べられない土の材料で、食品ではない。", "石油": "燃料であり、食品ではない。", "鉱石": "岩石から取る鉱物で、食品ではない。"}, "sentence_index": 0, "correct_answer": "堅果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スイカは、果肉が甘くて水分が多い堅果だ。", "explanation": "ここは〈多汁果〉の意味。スイカのように水分の多い果肉を食べる実は、硬い殻の堅果とは言わない。"}, {"text": "キャベツは、堅果として炒めたり煮たりして食べる。", "explanation": "ここは〈野菜〉の意味。キャベツは野菜であり、堅果とは呼ばない。"}, {"text": "米は、堅果の一種として主食に使われる。", "explanation": "ここは〈穀物〉の意味。米は穀物で、堅果の一種ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堅果", "is_correct": true, "explanation": "健康によいと言われる食品の分類名。ここに入る語として正しい。"}, {"text": "洗剤", "is_correct": false, "explanation": "飲み込むと危険な日用品で、食べるものではない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う紙で、食べられない。"}, {"text": "針金", "is_correct": false, "explanation": "金属で、食べられない。"}], "explanations": {"堅果": "健康によいと言われる食品の分類名。ここに入る語として正しい。", "洗剤": "飲み込むと危険な日用品で、食べるものではない。", "切手": "郵便に使う紙で、食べられない。", "針金": "金属で、食べられない。"}, "sentence_index": 6, "correct_answer": "堅果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "梅は、熟すと果肉が柔らかくなる堅果として分類される。", "explanation": "ここは〈核果〉の意味。梅は果肉の内側に核がある核果で、堅果とは分類されない。"}, {"text": "ブルーベリーは、堅果として生でそのまま食べられる。", "explanation": "ここは〈液果〉の意味。ブルーベリーは果肉のある液果で、硬い殻の堅果とは言わない。"}, {"text": "その会社は堅果な経営で、長く続いている。", "explanation": "ここは〈堅実〉の意味。経営が手堅いことは「堅実」で言い、「堅果」は実の種類を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食物アレルギーのある人は、堅果が食べる前に表示を確認する。", "corrected_sentence": "食物アレルギーのある人は、堅果を食べる前に表示を確認する。", "error_description": "「食べる」の目的語は「を」。「堅果が」と主語の形にしたのは誤りで、正しくは「堅果を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39591, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農家は、堅果を炒いて香りを出してから、市場に出荷する。", "corrected_sentence": "農家は、堅果を炒って香りを出してから、市場に出荷する。", "error_description": "「炒る」のて形は「炒って」。「炒いて」は活用の誤りで、目的語「堅果を」に続く動詞の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "花や木が、実をむすぶこと。", "primary_collocate": null, "pronunciation": "けつじつ", "ipa": "ketsɯdʑitsɯ", "syllable_count": 4, "sentences": [{"text": "春に咲いた梅の花が、夏には結実して青い実になった。", "target_word": "結実", "complexity_tier": "T3", "furigana": "春(はる)に咲(さ)いた梅(うめ)の花(はな)が、夏(なつ)には結実(けつじつ)して青(あお)い実(み)になった。", "sentence_source": "generated"}, {"text": "今年は雨が多く、柿の木はあまり結実しなかった。", "target_word": "結実", "complexity_tier": "T3", "furigana": "今年(ことし)は雨(あめ)が多(おお)く、柿(かき)の木(き)はあまり結実(けつじつ)しなかった。", "sentence_source": "generated"}, {"text": "ミツバチが花粉を運ぶので、リンゴは無事に結実する。", "target_word": "結実", "complexity_tier": "T3", "furigana": "ミツバチが花粉(かふん)を運(はこ)ぶので、リンゴは無事(ぶじ)に結実(けつじつ)する。", "sentence_source": "generated"}, {"text": "花が咲いても、受粉しなければ結実しない。", "target_word": "結実", "complexity_tier": "T3", "furigana": "花(はな)が咲(さ)いても、受粉(じゅふん)しなければ結実(けつじつ)しない。", "sentence_source": "generated"}, {"text": "庭のレモンの木が初めて結実した。", "target_word": "結実", "complexity_tier": "T3", "furigana": "庭(にわ)のレモンの木(き)が初(はじ)めて結実(けつじつ)した。", "sentence_source": "generated"}, {"text": "寒さで花が落ちたため、結実の数が少なかった。", "target_word": "結実", "complexity_tier": "T3", "furigana": "寒(さむ)さで花(はな)が落(お)ちたため、結実(けつじつ)の数(かず)が少(すく)なかった。", "sentence_source": "generated"}, {"text": "植えてから結実するまでに、この木は五年かかる。", "target_word": "結実", "complexity_tier": "T3", "furigana": "植(う)えてから結実(けつじつ)するまでに、この木(き)は五年(ごねん)かかる。", "sentence_source": "generated"}, {"text": "台風の前に花が散ると、果樹の結実が悪くなる。", "target_word": "結実", "complexity_tier": "T3", "furigana": "台風(たいふう)の前(まえ)に花(はな)が散(ち)ると、果樹(かじゅ)の結実(けつじつ)が悪(わる)くなる。", "sentence_source": "generated"}, {"text": "農家は、結実を助けるために花に筆で花粉をつける。", "target_word": "結実", "complexity_tier": "T3", "furigana": "農家(のうか)は、結実(けつじつ)を助(たす)けるために花(はな)に筆(ふで)で花粉(かふん)をつける。", "sentence_source": "generated"}, {"text": "結実の時期になると、果樹園は毎日見回りが必要だ。", "target_word": "結実", "complexity_tier": "T3", "furigana": "結実(けつじつ)の時期(じき)になると、果樹園(かじゅえん)は毎日(まいにち)見回(みまわ)りが必要(ひつよう)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結実", "label": "基本形"}, {"form": "結実する", "label": "辞書形"}, {"form": "結実した", "label": "過去形"}, {"form": "結実して", "label": "て形"}, {"form": "結実しない", "label": "否定形"}], "register": "中立（普通体）", "sense_fingerprint": "花が咲いたあと、木や草が実をつけること。受粉や天候と関係する。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結実", "is_correct": true, "explanation": "花が実をむすぶ意味で、「夏には〜して青い実になった」に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "水や物が凍って固まる意味で、実がなる流れに合わない。"}, {"text": "結露", "is_correct": false, "explanation": "水蒸気が冷えて水滴になる意味で、植物の実には使わない。"}, {"text": "散布", "is_correct": false, "explanation": "薬や種をまき散らす意味で、「実になった」とつながらない。"}], "explanations": {"結実": "花が実をむすぶ意味で、「夏には〜して青い実になった」に合う。", "凍結": "水や物が凍って固まる意味で、実がなる流れに合わない。", "結露": "水蒸気が冷えて水滴になる意味で、植物の実には使わない。", "散布": "薬や種をまき散らす意味で、「実になった」とつながらない。"}, "sentence_index": 0, "correct_answer": "結実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この虫は一年で大量に結実する。", "explanation": "ここは〈繁殖〉の意味。結実は花が咲いたあとに実をつけることなので、虫が増える場面には使わない。"}, {"text": "桜は三月に結実して、道を白く染めた。", "explanation": "ここは〈開花〉の意味。結実は花のあとに実をつけることなので、花が一面に咲く場面には使わない。"}, {"text": "冷えた窓ガラスに水滴が結実した。", "explanation": "ここは〈結露〉の意味。結実は植物が実をつけることなので、冷えた窓に水分がつく場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結実", "is_correct": true, "explanation": "植物が実をつけるまでの過程を表し、ここに合う。"}, {"text": "決裂", "is_correct": false, "explanation": "話し合いが物別れになる意味で、木が実をつける文脈には合わない。"}, {"text": "融解", "is_correct": false, "explanation": "固体が溶けて液体になる意味で、植物の成長には使わない。"}, {"text": "陥没", "is_correct": false, "explanation": "地面などがくぼむ意味で、「植えてから〜までに五年」とつながらない。"}], "explanations": {"結実": "植物が実をつけるまでの過程を表し、ここに合う。", "決裂": "話し合いが物別れになる意味で、木が実をつける文脈には合わない。", "融解": "固体が溶けて液体になる意味で、植物の成長には使わない。", "陥没": "地面などがくぼむ意味で、「植えてから〜までに五年」とつながらない。"}, "sentence_index": 6, "correct_answer": "結実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このワインは三年かけて結実する。", "explanation": "ここは〈熟成〉の意味。結実は実をつけることなので、ワインを寝かせて味を深める場面には合わない。"}, {"text": "めしべに花粉をつけることを、結実という。", "explanation": "ここは〈受粉〉の意味。結実は受粉のあとに実がなることで、花粉をつける行為そのものは指さない。"}, {"text": "この道路は来月、結実する。", "explanation": "ここは〈開通〉の意味。結実は花のあとに実をつけることなので、道路が通じる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年の桃は雨が多くて結実にしなかった。", "corrected_sentence": "今年の桃は雨が多くて結実しなかった。", "error_description": "『結実する』は『結実』に『する』が付く語で、直後に格助詞『に』は付かない。『結実にしなかった』は誤りで、『結実しなかった』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39592, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の多い年は、ブドウの結実を悪くなる。", "corrected_sentence": "雨の多い年は、ブドウの結実が悪くなる。", "error_description": "『悪くなる』は主語に『が』をとるので、『結実を』は誤り。『結実が悪くなる』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
