INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39593, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "植物が花のあとに、種や実をつけること。また、努力などの結果があらわれること。", "primary_collocate": null, "pronunciation": "けつじつ", "ipa": "ketsɯdʑitsɯ", "syllable_count": 4, "sentences": [{"text": "長年の研究がついに結実し、新しい薬が完成した。", "target_word": "結実", "complexity_tier": "T3", "furigana": "長年(ながねん)の研究(けんきゅう)がついに結実(けつじつ)し、新(あたら)しい薬(くすり)が完成(かんせい)した。", "sentence_source": "generated"}, {"text": "毎日の練習が結実して、彼は大会で優勝した。", "target_word": "結実", "complexity_tier": "T3", "furigana": "毎日(まいにち)の練習(れんしゅう)が結実(けつじつ)して、彼(かれ)は大会(たいかい)で優勝(ゆうしょう)した。", "sentence_source": "generated"}, {"text": "桜の木は花のあとに結実し、小さな赤い実をつける。", "target_word": "結実", "complexity_tier": "T3", "furigana": "桜(さくら)の木(き)は花(はな)のあとに結実(けつじつ)し、小(ちい)さな赤(あか)い実(み)をつける。", "sentence_source": "generated"}, {"text": "彼女の努力は、合格という形で結実した。", "target_word": "結実", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の努力(どりょく)は、合格(ごうかく)という形(かたち)で結実(けつじつ)した。", "sentence_source": "generated"}, {"text": "この計画は十年かけて結実した。", "target_word": "結実", "complexity_tier": "T3", "furigana": "この計画(けいかく)は十年(じゅうねん)かけて結実(けつじつ)した。", "sentence_source": "generated"}, {"text": "受粉がうまくいけば、トマトは夏に結実する。", "target_word": "結実", "complexity_tier": "T3", "furigana": "受粉(じゅふん)がうまくいけば、トマトは夏(なつ)に結実(けつじつ)する。", "sentence_source": "generated"}, {"text": "二人の協力が結実して、町に新しい図書館ができた。", "target_word": "結実", "complexity_tier": "T3", "furigana": "二人(ふたり)の協力(きょうりょく)が結実(けつじつ)して、町(まち)に新(あたら)しい図書館(としょかん)ができた。", "sentence_source": "generated"}, {"text": "練習を休んでばかりでは、努力は結実しない。", "target_word": "結実", "complexity_tier": "T3", "furigana": "練習(れんしゅう)を休(やす)んでばかりでは、努力(どりょく)は結実(けつじつ)しない。", "sentence_source": "generated"}, {"text": "花は咲いたのに、霜のせいで結実しなかった。", "target_word": "結実", "complexity_tier": "T3", "furigana": "花(はな)は咲(さ)いたのに、霜(しも)のせいで結実(けつじつ)しなかった。", "sentence_source": "generated"}, {"text": "長い話し合いが結実し、両国は協定を結んだ。", "target_word": "結実", "complexity_tier": "T3", "furigana": "長(なが)い話(はな)し合(あ)いが結実(けつじつ)し、両国(りょうこく)は協定(きょうてい)を結(むす)んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結実", "label": "基本形"}, {"form": "結実する", "label": "辞書形"}, {"form": "結実した", "label": "過去形"}, {"form": "結実して", "label": "て形"}, {"form": "結実しない", "label": "否定形"}], "register": "中立（普通体）", "sense_fingerprint": "植物が実をつけること。転じて、努力や研究が成果として実ること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39593, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結実", "is_correct": true, "explanation": "研究や努力の成果があらわれる意味で、『長年の研究が〜し、薬が完成した』に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "活動や計画が止まる意味で、『薬が完成した』と矛盾する。"}, {"text": "散布", "is_correct": false, "explanation": "まき散らす意味で、研究の成果を表す文脈に合わない。"}, {"text": "結露", "is_correct": false, "explanation": "水滴ができる意味で、研究の文脈には使わない。"}], "explanations": {"結実": "研究や努力の成果があらわれる意味で、『長年の研究が〜し、薬が完成した』に合う。", "凍結": "活動や計画が止まる意味で、『薬が完成した』と矛盾する。", "散布": "まき散らす意味で、研究の成果を表す文脈に合わない。", "結露": "水滴ができる意味で、研究の文脈には使わない。"}, "sentence_index": 0, "correct_answer": "結実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では毎日、部品が結実している。", "explanation": "ここは〈製造〉の意味。結実は実をつけることや努力の成果があらわれることなので、工場で部品を作る場面には使わない。"}, {"text": "この家は三か月で結実した。", "explanation": "ここは〈完成〉の意味。結実は努力や研究が成果として実ることで、建物など物の完成には使わない。"}, {"text": "この地域のワインは五年で結実した。", "explanation": "ここは〈成熟〉の意味。結実は成果が実ることで、ワインを寝かせて熟させる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39593, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結実", "is_correct": true, "explanation": "協力などの努力が成果としてあらわれる意味で、ここに合う。"}, {"text": "融解", "is_correct": false, "explanation": "固体が溶ける意味で、人の協力には使わない。"}, {"text": "陥没", "is_correct": false, "explanation": "地面などがくぼむ意味で、協力の文脈に合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分がなくなる意味で、協力が成果を生む流れとつながらない。"}], "explanations": {"結実": "協力などの努力が成果としてあらわれる意味で、ここに合う。", "融解": "固体が溶ける意味で、人の協力には使わない。", "陥没": "地面などがくぼむ意味で、協力の文脈に合わない。", "乾燥": "水分がなくなる意味で、協力が成果を生む流れとつながらない。"}, "sentence_index": 6, "correct_answer": "結実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "限定の菓子は昼前に結実した。", "explanation": "ここは〈完売〉の意味。結実は努力や成果が実ることで、商品が売り切れる場面には使わない。"}, {"text": "春になると、この畑の芽が結実する。", "explanation": "ここは〈発芽〉の意味。結実は花のあとに実や種をつけることなので、芽が出る場面には合わない。"}, {"text": "エンジンがついに結実した。", "explanation": "ここは〈点火〉の意味。結実は成果が実ることで、エンジンに火をつける場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39593, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三年の努力がついに結実せた。", "corrected_sentence": "三年の努力がついに結実した。", "error_description": "『結実する』はサ変動詞なので、過去形は『結実した』。『結実せた』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39593, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工夫を結実し、新しい製品が生まれた。", "corrected_sentence": "この工夫が結実し、新しい製品が生まれた。", "error_description": "『結実する』は主語に『が』を取る使い方なので、『を』は誤り。『工夫が結実し』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
