INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんのものが元気に育って、さかんになること。", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "この島では、温かい海のおかげでサンゴが繁栄している。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "この島[しま]では、温[あたた]かい海[うみ]のおかげでサンゴが繁栄[はんえい]している。", "sentence_source": "generated"}, {"text": "恐竜は長いあいだ地球で繁栄したが、やがて姿を消した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]は長[なが]いあいだ地球[ちきゅう]で繁栄[はんえい]したが、やがて姿[すがた]を消[け]した。", "sentence_source": "generated"}, {"text": "栄養が豊富な湖では、小さな魚が繁栄し、鳥もたくさん集まる。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "栄養[えいよう]が豊富[ほうふ]な湖[みずうみ]では、小[ちい]さな魚[さかな]が繁栄[はんえい]し、鳥[とり]もたくさん集[あつ]まる。", "sentence_source": "generated"}, {"text": "人間が増えるにつれて、人の近くで暮らすネズミも繁栄した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "人間[にんげん]が増[ふ]えるにつれて、人[ひと]の近[ちか]くで暮[く]らすネズミも繁栄[はんえい]した。", "sentence_source": "generated"}, {"text": "森が守られたので、そこに住む生き物の繁栄が続いている。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "森[もり]が守[まも]られたので、そこに住[す]む生[い]き物[もの]の繁栄[はんえい]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "暖かい気候が続いた時代に、この植物は大いに繁栄した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "暖[あたた]かい気候[きこう]が続[つづ]いた時代[じだい]に、この植物[しょくぶつ]は大[おお]いに繁栄[はんえい]した。", "sentence_source": "generated"}, {"text": "一つの種が繁栄しすぎると、他の生き物が減ってしまうことがある。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "一[ひと]つの種[しゅ]が繁栄[はんえい]しすぎると、他[ほか]の生[い]き物[もの]が減[へ]ってしまうことがある。", "sentence_source": "generated"}, {"text": "川の水がきれいになってから、メダカが繁栄して数が何倍にもなった。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がきれいになってから、メダカが繁栄[はんえい]して数[かず]が何倍[なんばい]にもなった。", "sentence_source": "generated"}, {"text": "海の中では、昔から多くの種類の貝が繁栄してきた。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "海[うみ]の中[なか]では、昔[むかし]から多[おお]くの種類[しゅるい]の貝[かい]が繁栄[はんえい]してきた。", "sentence_source": "generated"}, {"text": "敵が少ない島だったので、その鳥は安心して繁栄できた。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "敵[てき]が少[すく]ない島[しま]だったので、その鳥[とり]は安心[あんしん]して繁栄[はんえい]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁栄する", "label": "基本形"}, {"form": "繁栄した", "label": "過去形"}, {"form": "繁栄して", "label": "て形"}, {"form": "繁栄している", "label": "進行・状態"}], "register": "neutral", "sense_fingerprint": "生き物や植物の種類・数が増えて、元気に栄えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39594, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁栄", "is_correct": true, "explanation": "生き物が元気に育ち、さかんになる意味で、サンゴの文脈に合う。"}, {"text": "挑戦", "is_correct": false, "explanation": "困難なことに取り組む意味で、サンゴの様子には使わない。"}, {"text": "捜索", "is_correct": false, "explanation": "探し回る意味で、サンゴが生きている様子とつながらない。"}, {"text": "陥没", "is_correct": false, "explanation": "地面などが落ち込む意味で、『温かい海のおかげで』と合わない。"}], "explanations": {"繁栄": "生き物が元気に育ち、さかんになる意味で、サンゴの文脈に合う。", "挑戦": "困難なことに取り組む意味で、サンゴの様子には使わない。", "捜索": "探し回る意味で、サンゴが生きている様子とつながらない。", "陥没": "地面などが落ち込む意味で、『温かい海のおかげで』と合わない。"}, "sentence_index": 0, "correct_answer": "繁栄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時期は農家の仕事が繁栄して、休む暇がない。", "explanation": "ここは〈繁忙〉の意味。繁栄は生き物や社会が元気に発展することなので、仕事が忙しい場面には使わない。"}, {"text": "わずか一羽だけ残ったこの鳥は、島でなんとか繁栄した。", "explanation": "ここは〈生存〉の意味。繁栄は数が増えて栄えることなので、一羽だけが生き延びる場面には合わない。"}, {"text": "その地域では、交通事故が繁栄した。", "explanation": "ここは〈多発〉の意味。繁栄は元気に増えて栄える意味で、事故など悪いことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39594, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁栄", "is_correct": true, "explanation": "一つの種が増えて栄える意味で、『他の生き物が減る』という文脈に合う。"}, {"text": "融解", "is_correct": false, "explanation": "固体が溶ける意味で、生き物の数の変化には使わない。"}, {"text": "決裂", "is_correct": false, "explanation": "交渉などが物別れになる意味で、生き物の数の話には合わない。"}, {"text": "座礁", "is_correct": false, "explanation": "船が浅瀬に乗り上げる意味で、生き物が増える文脈とつながらない。"}], "explanations": {"繁栄": "一つの種が増えて栄える意味で、『他の生き物が減る』という文脈に合う。", "融解": "固体が溶ける意味で、生き物の数の変化には使わない。", "決裂": "交渉などが物別れになる意味で、生き物の数の話には合わない。", "座礁": "船が浅瀬に乗り上げる意味で、生き物が増える文脈とつながらない。"}, "sentence_index": 6, "correct_answer": "繁栄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "わずか二羽が残り、その鳥は島で繁栄した。", "explanation": "ここは〈残存〉の意味。繁栄は数が増えて栄えることなので、少数が残っただけの場面には合わない。"}, {"text": "その地域では、風邪が繁栄した。", "explanation": "ここは〈流行〉の意味。繁栄は良いものが元気に増えることで、病気が広がる場面には使わない。"}, {"text": "工場の機械が繁栄した。", "explanation": "ここは〈稼働〉の意味。繁栄は生き物や社会が元気に育って発展することなので、機械が動いて働く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39594, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森が豊かになり、その中で鳥が繁栄せた。", "corrected_sentence": "森が豊かになり、その中で鳥が繁栄した。", "error_description": "『繁栄する』はサ変動詞なので、過去形は『繁栄した』。『繁栄せた』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39594, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暖かい夏は、ハチの仲間を繁栄する。", "corrected_sentence": "暖かい夏は、ハチの仲間が繁栄する。", "error_description": "『繁栄する』は主語に『が』を取る使い方なので、『を』は誤り。『仲間が繁栄する』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "勢いが弱まって衰えることで、繁栄の対義語にあたる。"}, {"text": "誕生", "is_correct": false, "explanation": "新しく生まれる意味で、繁栄の対義語ではない。"}, {"text": "発芽", "is_correct": false, "explanation": "種から芽が出る意味で、繁栄と対になる語ではない。"}, {"text": "移住", "is_correct": false, "explanation": "住む場所を移す意味で、繁栄の対義語ではない。"}], "correct_answer": "衰退", "explanations": {"衰退": "勢いが弱まって衰えることで、繁栄の対義語にあたる。", "誕生": "新しく生まれる意味で、繁栄の対義語ではない。", "発芽": "種から芽が出る意味で、繁栄と対になる語ではない。", "移住": "住む場所を移す意味で、繁栄の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『繁栄の』の『の』。『繁栄のためには』と名詞として続けるのに使う。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す『を』は、『社会を繁栄』と名詞に続けると不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』は、名詞『繁栄』の前に続くと主語にならず不自然になる。"}, {"text": "まで", "is_correct": false, "explanation": "範囲を示す『まで』は、『社会まで繁栄』と名詞に続かず、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "『繁栄の』の『の』。『繁栄のためには』と名詞として続けるのに使う。", "を": "対象を示す『を』は、『社会を繁栄』と名詞に続けると不自然になる。", "が": "主語を示す『が』は、名詞『繁栄』の前に続くと主語にならず不自然になる。", "まで": "範囲を示す『まで』は、『社会まで繁栄』と名詞に続かず、ここには入らない。"}, "error_tags": {"を": "対象の格", "が": "主語の格", "まで": "範囲の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "勢いが弱まって衰えることで、繁栄の対義語にあたる。"}, {"text": "停止", "is_correct": false, "explanation": "動きが止まる意味で、繁栄の対義語ではない。"}, {"text": "出現", "is_correct": false, "explanation": "姿を現す意味で、繁栄と対になる語ではない。"}, {"text": "上昇", "is_correct": false, "explanation": "高くなる意味で、繁栄の対義語ではない。"}], "correct_answer": "衰退", "explanations": {"衰退": "勢いが弱まって衰えることで、繁栄の対義語にあたる。", "停止": "動きが止まる意味で、繁栄の対義語ではない。", "出現": "姿を現す意味で、繁栄と対になる語ではない。", "上昇": "高くなる意味で、繁栄の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や生物などが、豊かで活気にあふれ、盛んに発展すること。", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "貿易で港町が繁栄し、各地から商人が集まった。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "貿易[ぼうえき]で港町[みなとまち]が繁栄[はんえい]し、各地[かくち]から商人[しょうにん]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "平和が続いたおかげで、江戸の町は大いに繁栄した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "平和[へいわ]が続[つづ]いたおかげで、江戸[えど]の町[まち]は大[おお]いに繁栄[はんえい]した。", "sentence_source": "generated"}, {"text": "この国の繁栄は、教育に力を入れてきたことによるものだ。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "この国[くに]の繁栄[はんえい]は、教育[きょういく]に力[ちから]を入[い]れてきたことによるものだ。", "sentence_source": "generated"}, {"text": "駅前の商店街は、昔ほど繁栄していないが、まだ人通りはある。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の商店街[しょうてんがい]は、昔[むかし]ほど繁栄[はんえい]していないが、まだ人通[ひとどお]りはある。", "sentence_source": "generated"}, {"text": "大きな工場ができて、町は急速に繁栄した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "大[おお]きな工場[こうじょう]ができて、町[まち]は急速[きゅうそく]に繁栄[はんえい]した。", "sentence_source": "generated"}, {"text": "王は国の繁栄を願って、毎年神社に参拝した。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "王[おう]は国[くに]の繁栄[はんえい]を願[ねが]って、毎年[まいとし]神社[じんじゃ]に参拝[さんぱい]した。", "sentence_source": "generated"}, {"text": "経済が繁栄している国には、仕事を求めて人が集まる。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "経済[けいざい]が繁栄[はんえい]している国[くに]には、仕事[しごと]を求[もと]めて人[ひと]が集[あつ]まる。", "sentence_source": "generated"}, {"text": "社会の繁栄のためには、働く人の健康も大切だ。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "社会[しゃかい]の繁栄[はんえい]のためには、働[はたら]く人[ひと]の健康[けんこう]も大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "戦争が終わってから、街はふたたび繁栄の時代を迎えた。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "戦争[せんそう]が終[お]わってから、街[まち]はふたたび繁栄[はんえい]の時代[じだい]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "町の繁栄を支えてきたのは、昔から続く織物の産業だ。", "target_word": "繁栄", "complexity_tier": "T3", "furigana": "町[まち]の繁栄[はんえい]を支[ささ]えてきたのは、昔[むかし]から続[つづ]く織物[おりもの]の産業[さんぎょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁栄する", "label": "基本形"}, {"form": "繁栄した", "label": "過去形"}, {"form": "繁栄して", "label": "て形"}, {"form": "繁栄の", "label": "名詞+の"}], "register": "neutral", "sense_fingerprint": "町・国・会社などの社会が豊かになり、活気をもって発展すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁栄", "is_correct": true, "explanation": "町や港が豊かになり活気づく意味で、『商人が集まった』に合う。"}, {"text": "融解", "is_correct": false, "explanation": "固体が溶ける意味で、町の発展とつながらない。"}, {"text": "陥没", "is_correct": false, "explanation": "地面が落ち込む意味で、商人が集まる流れに合わない。"}, {"text": "座礁", "is_correct": false, "explanation": "船が浅瀬に乗り上げる意味で、港町の発展の文脈には合わない。"}], "explanations": {"繁栄": "町や港が豊かになり活気づく意味で、『商人が集まった』に合う。", "融解": "固体が溶ける意味で、町の発展とつながらない。", "陥没": "地面が落ち込む意味で、商人が集まる流れに合わない。", "座礁": "船が浅瀬に乗り上げる意味で、港町の発展の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "繁栄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は部長に繁栄した。", "explanation": "ここは〈出世〉の意味。繁栄は社会や組織が栄える意味なので、一人の人が昇進する場面には使わない。"}, {"text": "今年の米は繁栄だった。", "explanation": "ここは〈豊作〉の意味。繁栄は社会や組織が栄える意味で、作物の出来を表す場面には使わない。"}, {"text": "試験の成績が繁栄した。", "explanation": "ここは〈向上〉の意味。繁栄は社会や組織が栄える意味で、個人の成績には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁栄", "is_correct": true, "explanation": "経済が豊かで活気があることを表し、『仕事を求めて人が集まる』に合う。"}, {"text": "決裂", "is_correct": false, "explanation": "交渉などが物別れになる意味で、経済の話には使わない。"}, {"text": "散布", "is_correct": false, "explanation": "まき散らす意味で、経済の状態を表す語ではない。"}, {"text": "捜索", "is_correct": false, "explanation": "探し回る意味で、経済が『国に集まる』流れとつながらない。"}], "explanations": {"繁栄": "経済が豊かで活気があることを表し、『仕事を求めて人が集まる』に合う。", "決裂": "交渉などが物別れになる意味で、経済の話には使わない。", "散布": "まき散らす意味で、経済の状態を表す語ではない。", "捜索": "探し回る意味で、経済が『国に集まる』流れとつながらない。"}, "sentence_index": 6, "correct_answer": "繁栄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の水位が繁栄した。", "explanation": "ここは〈上昇〉の意味。繁栄は社会や組織が栄える意味で、水位の変化には使わない。"}, {"text": "彼の体力は一か月で繁栄した。", "explanation": "ここは〈回復〉の意味。繁栄は多くのものが栄えることなので、個人の体力には使わない。"}, {"text": "工事が繁栄した。", "explanation": "ここは〈完了〉の意味。繁栄は栄えて発展することで、工事が終わる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "戦後、港町は急速に繁栄て、人口が増えた。", "corrected_sentence": "戦後、港町は急速に繁栄し、人口が増えた。", "error_description": "『繁栄する』の連用形は『繁栄し』。『繁栄て』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39595, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国の繁栄を、人々の協力が欠かせない。", "corrected_sentence": "国の繁栄には、人々の協力が欠かせない。", "error_description": "『繁栄には〜が欠かせない』の形で、『繁栄』に続く『には』が正しい。『を』は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地下鉄の駅に直結」で、つながる先を表す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「駅で直結」は手段の意味になり、つながる相手を示せないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「駅の直結していて」は名詞の後に動詞が続かず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「駅を直結していて」は目的語の形になり、「ビルは〜」の文の流れに合わない。"}], "correct_answer": "に", "explanations": {"に": "「地下鉄の駅に直結」で、つながる先を表す格助詞。", "で": "「駅で直結」は手段の意味になり、つながる相手を示せないので不自然。", "の": "「駅の直結していて」は名詞の後に動詞が続かず、文が成り立たない。", "を": "「駅を直結していて」は目的語の形になり、「ビルは〜」の文の流れに合わない。"}, "error_tags": {"で": "手段の格（つながる相手を示せない）", "の": "名詞と動詞がつながらない", "を": "目的語の格（文型が合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「アンプに直結する」で、つなぐ先を表す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「アンプの直結すると」は名詞修飾の形になり、「すると」の文の流れに続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では「アンプから直結」となり、つながる先を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「アンプより直結すると」となり、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「アンプに直結する」で、つなぐ先を表す格助詞。", "の": "「アンプの直結すると」は名詞修飾の形になり、「すると」の文の流れに続かない。", "から": "起点を示す「から」では「アンプから直結」となり、つながる先を表せない。", "より": "比較の「より」では「アンプより直結すると」となり、意味が通らない。"}, "error_tags": {"の": "連体修飾の格（文が続かない）", "から": "起点の格（つながる先を表せない）", "より": "比較の格（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かと何かが、とても強くつながっていること。", "primary_collocate": null, "pronunciation": "ちょっけつ", "ipa": "tɕokketsɯ", "syllable_count": 4, "sentences": [{"text": "この駅は空港と直結しているので、荷物が多くても楽だ。", "target_word": "直結", "complexity_tier": "T3", "furigana": "この駅[えき]は空港[くうこう]と直結[ちょっけつ]しているので、荷物[にもつ]が多[おお]くても楽[らく]だ。", "sentence_source": "generated"}, {"text": "新しいビルは地下鉄の駅に直結していて、雨の日でもぬれない。", "target_word": "直結", "complexity_tier": "T3", "furigana": "新[あたら]しいビルは地下鉄[ちかてつ]の駅[えき]に直結[ちょっけつ]していて、雨[あめ]の日[ひ]でもぬれない。", "sentence_source": "generated"}, {"text": "台所とリビングが直結した間取りの家に住みたい。", "target_word": "直結", "complexity_tier": "T3", "furigana": "台所[だいどころ]とリビングが直結[ちょっけつ]した間取[まど]りの家[いえ]に住[す]みたい。", "sentence_source": "generated"}, {"text": "公園の中の道は学校に直結しているため、子どもたちは安全に通える。", "target_word": "直結", "complexity_tier": "T3", "furigana": "公園[こうえん]の中[なか]の道[みち]は学校[がっこう]に直結[ちょっけつ]しているため、子[こ]どもたちは安全[あんぜん]に通[かよ]える。", "sentence_source": "generated"}, {"text": "この工場は港に直結した線路を持っていて、荷物をすぐ船に積める。", "target_word": "直結", "complexity_tier": "T3", "furigana": "この工場[こうじょう]は港[みなと]に直結[ちょっけつ]した線路[せんろ]を持[も]っていて、荷物[にもつ]をすぐ船[ふね]に積[つ]める。", "sentence_source": "generated"}, {"text": "水道管は浄水場に直結しているので、水がきれいなまま家に届く。", "target_word": "直結", "complexity_tier": "T3", "furigana": "水道管[すいどうかん]は浄水場[じょうすいじょう]に直結[ちょっけつ]しているので、水[みず]がきれいなまま家[いえ]に届[とど]く。", "sentence_source": "generated"}, {"text": "農家と店が直結した販売方法で、野菜を新鮮なまま届けている。", "target_word": "直結", "complexity_tier": "T3", "furigana": "農家[のうか]と店[みせ]が直結[ちょっけつ]した販売方法[はんばいほうほう]で、野菜[やさい]を新鮮[しんせん]なまま届[とど]けている。", "sentence_source": "generated"}, {"text": "テレビをアンプに直結すると、音がよりきれいに聞こえる。", "target_word": "直結", "complexity_tier": "T3", "furigana": "テレビをアンプに直結[ちょっけつ]すると、音[おと]がよりきれいに聞[き]こえる。", "sentence_source": "generated"}, {"text": "駅に直結した商業施設は、いつも買い物客でにぎわっている。", "target_word": "直結", "complexity_tier": "T3", "furigana": "駅[えき]に直結[ちょっけつ]した商業施設[しょうぎょうしせつ]は、いつも買[か]い物客[ものきゃく]でにぎわっている。", "sentence_source": "generated"}, {"text": "山頂へ直結するロープウェイができて、登る時間が短くなった。", "target_word": "直結", "complexity_tier": "T3", "furigana": "山頂[さんちょう]へ直結[ちょっけつ]するロープウェイができて、登[のぼ]る時間[じかん]が短[みじか]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直結する", "label": "基本形"}, {"form": "直結した", "label": "過去形・連体形"}, {"form": "直結して", "label": "て形"}, {"form": "直結している", "label": "進行・状態"}], "register": "neutral", "sense_fingerprint": "間に何も挟まず、場所や設備などが直接つながっていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直結", "is_correct": true, "explanation": "「空港と直接つながる」の意味で、「空港と〜している」にそのまま入る。"}, {"text": "混雑", "is_correct": false, "explanation": "「混雑」は人や車が集まる状態を表すので、駅と空港のつながりを表せず、文に入らない。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」は調べることなので、「空港と点検している」では駅と空港の関係が成り立たない。"}, {"text": "運転", "is_correct": false, "explanation": "「運転」は機械を動かすことなので、「空港と運転している」は文として成り立たない。"}], "explanations": {"直結": "「空港と直接つながる」の意味で、「空港と〜している」にそのまま入る。", "混雑": "「混雑」は人や車が集まる状態を表すので、駅と空港のつながりを表せず、文に入らない。", "点検": "「点検」は調べることなので、「空港と点検している」では駅と空港の関係が成り立たない。", "運転": "「運転」は機械を動かすことなので、「空港と運転している」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "直結"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は駅から直結しているが、歩いて十分ほどかかる。", "explanation": "ここは「近い」の意味。直結は間に何も挟まない強いつながりなので、歩いて十分かかる距離には使えない。「近い」と言うのが正しい。"}, {"text": "この二つの作業は直結して進められるので、どちらも同時に終わる。", "explanation": "ここは「同時に」の意味。同じ時間に重なることは「同時に」と言い、直結は間に何も挟まない強いつながりなので、時間の重なりの説明には合わない。"}, {"text": "この公園は学校に直結していて、間に一本道路が通っている。", "explanation": "ここは「隣接」の意味。直結は間に何も挟まないことなので、間に道路があるという文と矛盾し、この言葉の使い方に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直結", "is_correct": true, "explanation": "「農家と店がつながっている」ことを表し、「直結した販売方法」にそのまま入る。"}, {"text": "検品", "is_correct": false, "explanation": "「検品」は商品を検査することなので、「農家と店が検品した販売方法」では二者の関係を表せない。"}, {"text": "計量", "is_correct": false, "explanation": "「計量」は量をはかることなので、「農家と店が計量した販売方法」は文として不自然で、つながりを表せない。"}, {"text": "運搬", "is_correct": false, "explanation": "「運搬」は物を運ぶことなので、「農家と店が運搬した販売方法」では二者の関係の意味にならない。"}], "explanations": {"直結": "「農家と店がつながっている」ことを表し、「直結した販売方法」にそのまま入る。", "検品": "「検品」は商品を検査することなので、「農家と店が検品した販売方法」では二者の関係を表せない。", "計量": "「計量」は量をはかることなので、「農家と店が計量した販売方法」は文として不自然で、つながりを表せない。", "運搬": "「運搬」は物を運ぶことなので、「農家と店が運搬した販売方法」では二者の関係の意味にならない。"}, "sentence_index": 6, "correct_answer": "直結"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その雷が家の屋根に直結して、テレビが壊れた。", "explanation": "ここは「直撃」の意味。雷が勢いよく当たることは「直撃」と言い、「直結」は物と物のつながりを表すので合わない。"}, {"text": "地域の人々と市役所は、直結して仕事を進めている。", "explanation": "ここは「密接」の意味。人と組織の関係が近いことは「密接」と言い、「直結」は物理的な接続や直接的な因果を表すので合わない。"}, {"text": "この道は学校の裏で一度途切れるが、駅に直結している。", "explanation": "ここは「通じる」の意味。道が途中を経由して行き着くことは「通じる」と言い、直結は途中に何も挟まない強いつながりを表すので、途切れる道には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このビルは地下鉄の駅で直結していて、雨の日でも楽に行ける。", "corrected_sentence": "このビルは地下鉄の駅に直結していて、雨の日でも楽に行ける。", "error_description": "「直結」は「〜に直結する」と、つながる先に「に」を付ける。「で」では手段の意味になり、つながりを表せないので、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この売り場は倉庫と直結ていて、重い荷物を運びやすい。", "corrected_sentence": "この売り場は倉庫と直結していて、重い荷物を運びやすい。", "error_description": "「直結」は「直結している」と活用させる。「直結て」は「し」が抜けていて活用の誤り。正しくは「直結している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「家計に直結する」で、影響を受ける先を表す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「家計で直結する」は手段の意味になり、影響の相手を示せないので不自然。"}, {"text": "が", "is_correct": false, "explanation": "「家計が直結する」では家計が主語になり、値上がりの影響という文の意味が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「家計を直結する」は目的語の形になり、影響の関係を表せないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「家計に直結する」で、影響を受ける先を表す格助詞。", "で": "「家計で直結する」は手段の意味になり、影響の相手を示せないので不自然。", "が": "「家計が直結する」では家計が主語になり、値上がりの影響という文の意味が崩れる。", "を": "「家計を直結する」は目的語の形になり、影響の関係を表せないので合わない。"}, "error_tags": {"で": "手段の格（影響の相手を示せない）", "が": "主語の格（文の意味が崩れる）", "を": "目的語の格（文型が合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「事故に直結する」で、影響を受ける先を表す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「事故の直結する仕事」は名詞修飾の形になり、一度のミスが事故に影響するという文の意味が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「事故から直結」となり、影響の相手を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「事故より直結する」となり、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「事故に直結する」で、影響を受ける先を表す格助詞。", "の": "「事故の直結する仕事」は名詞修飾の形になり、一度のミスが事故に影響するという文の意味が崩れる。", "から": "起点の「から」では「事故から直結」となり、影響の相手を示せない。", "より": "比較の「より」では「事故より直結する」となり、意味が通らない。"}, "error_tags": {"の": "連体修飾の格（文の意味が崩れる）", "から": "起点の格（影響の相手を示せない）", "より": "比較の格（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が、別の事柄に直接的に影響を与える関係にあること。", "primary_collocate": null, "pronunciation": "ちょっけつ", "ipa": "tɕokketsɯ", "syllable_count": 4, "sentences": [{"text": "睡眠不足は、仕事の成績に直結する問題だ。", "target_word": "直結", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]は、仕事[しごと]の成績[せいせき]に直結[ちょっけつ]する問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "食べ物の値上がりは、家計に直結する。", "target_word": "直結", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の値上[ねあ]がりは、家計[かけい]に直結[ちょっけつ]する。", "sentence_source": "generated"}, {"text": "選手の練習量は、試合の結果に直結している。", "target_word": "直結", "complexity_tier": "T3", "furigana": "選手[せんしゅ]の練習量[れんしゅうりょう]は、試合[しあい]の結果[けっか]に直結[ちょっけつ]している。", "sentence_source": "generated"}, {"text": "客の満足度が売り上げに直結するので、店は接客に気を配る。", "target_word": "直結", "complexity_tier": "T3", "furigana": "客[きゃく]の満足度[まんぞくど]が売[う]り上[あ]げに直結[ちょっけつ]するので、店[みせ]は接客[せっきゃく]に気[き]を配[くば]る。", "sentence_source": "generated"}, {"text": "水不足は農家の収入に直結する大きな問題だ。", "target_word": "直結", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]は農家[のうか]の収入[しゅうにゅう]に直結[ちょっけつ]する大[おお]きな問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "手洗いの習慣が病気の予防に直結すると医者は言った。", "target_word": "直結", "complexity_tier": "T3", "furigana": "手洗[てあら]いの習慣[しゅうかん]が病気[びょうき]の予防[よぼう]に直結[ちょっけつ]すると医者[いしゃ]は言[い]った。", "sentence_source": "generated"}, {"text": "土の状態が作物の出来に直結するため、毎日畑を見回る。", "target_word": "直結", "complexity_tier": "T3", "furigana": "土[つち]の状態[じょうたい]が作物[さくもつ]の出来[でき]に直結[ちょっけつ]するため、毎日[まいにち]畑[はたけ]を見回[みまわ]る。", "sentence_source": "generated"}, {"text": "一度のミスが事故に直結する仕事なので、常に慎重さが求められる。", "target_word": "直結", "complexity_tier": "T3", "furigana": "一度[いちど]のミスが事故[じこ]に直結[ちょっけつ]する仕事[しごと]なので、常[つね]に慎重[しんちょう]さが求[もと]められる。", "sentence_source": "generated"}, {"text": "景気の悪化は、働く人の生活に直結してくる。", "target_word": "直結", "complexity_tier": "T3", "furigana": "景気[けいき]の悪化[あっか]は、働[はたら]く人[ひと]の生活[せいかつ]に直結[ちょっけつ]してくる。", "sentence_source": "generated"}, {"text": "試験の点数が進学に直結するので、生徒たちは真剣だ。", "target_word": "直結", "complexity_tier": "T3", "furigana": "試験[しけん]の点数[てんすう]が進学[しんがく]に直結[ちょっけつ]するので、生徒[せいと]たちは真剣[しんけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直結する", "label": "基本形"}, {"form": "直結した", "label": "過去形・連体形"}, {"form": "直結して", "label": "て形"}, {"form": "直結している", "label": "進行・状態"}], "register": "neutral", "sense_fingerprint": "ある出来事が、別の事柄の結果や状態にすぐ直接影響すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 見回る (Zipf 1.74)']::text[], 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直結", "is_correct": true, "explanation": "「仕事の成績に直接影響する」の意味で、「仕事の成績に直結する問題」にそのまま入る。"}, {"text": "延期", "is_correct": false, "explanation": "「延期」は日程を先に送ることなので、「仕事の成績に延期する問題」は意味が通らない。"}, {"text": "集計", "is_correct": false, "explanation": "「集計」は数を合わせることなので、「仕事の成績に集計する問題」では影響関係を表せない。"}, {"text": "検討", "is_correct": false, "explanation": "「検討」は考えて調べることなので、「仕事の成績に検討する問題」では文の意味が成り立たない。"}], "explanations": {"直結": "「仕事の成績に直接影響する」の意味で、「仕事の成績に直結する問題」にそのまま入る。", "延期": "「延期」は日程を先に送ることなので、「仕事の成績に延期する問題」は意味が通らない。", "集計": "「集計」は数を合わせることなので、「仕事の成績に集計する問題」では影響関係を表せない。", "検討": "「検討」は考えて調べることなので、「仕事の成績に検討する問題」では文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "直結"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日に傘が売れたのは、店の宣伝と直結していて、ただの偶然だった。", "explanation": "ここは「偶然」の意味。たまたま重なることは「偶然」と言い、直結は直接の影響がある関係なので、「直結していて偶然だった」は矛盾する。"}, {"text": "この二つの問題は、互いに直結があるとされている。", "explanation": "ここは「関連がある」の意味。直結は「直接の影響」を表すので、「直結がある」という言い方は不自然で、関連の意味で使うのは合わない。"}, {"text": "この二つの会社は直結しているので、互いの経営にはほとんど関係がない。", "explanation": "ここは「無関係」の意味。互いに影響がないことは「無関係」と言い、「直結」は直接の影響がある関係なので、「直結しているのに関係がない」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直結", "is_correct": true, "explanation": "「土の状態が作物の出来に直接影響する」の意味で、「作物の出来に直結するため」にそのまま入る。"}, {"text": "施肥", "is_correct": false, "explanation": "「施肥」は肥料をまくことなので、「作物の出来に施肥するため」では影響関係を表せない。"}, {"text": "灌水", "is_correct": false, "explanation": "「灌水」は水をやることなので、「作物の出来に灌水するため」では影響の意味にならない。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」は調べることなので、「作物の出来に点検するため」では土と出来の関係が成り立たない。"}], "explanations": {"直結": "「土の状態が作物の出来に直接影響する」の意味で、「作物の出来に直結するため」にそのまま入る。", "施肥": "「施肥」は肥料をまくことなので、「作物の出来に施肥するため」では影響関係を表せない。", "灌水": "「灌水」は水をやることなので、「作物の出来に灌水するため」では影響の意味にならない。", "点検": "「点検」は調べることなので、「作物の出来に点検するため」では土と出来の関係が成り立たない。"}, "sentence_index": 6, "correct_answer": "直結"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その雷が家の屋根に直結して、テレビが壊れた。", "explanation": "ここは「直撃」の意味。雷が勢いよく当たることは「直撃」と言い、「直結」は物と物のつながりを表すので合わない。"}, {"text": "地域の人々と市役所は、直結して仕事を進めている。", "explanation": "ここは「密接」の意味。人と組織の関係が近いことは「密接」と言い、「直結」は影響の直接的なつながりを表すので合わない。"}, {"text": "社長は、直結で社員の意見を聞いた。", "explanation": "ここは「直接」の意味。人が人に直接話を聞くことは「直接」と言い、「直結」は影響の関係を表すので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震の被害は、建物の安全性で直結する問題だ。", "corrected_sentence": "地震の被害は、建物の安全性に直結する問題だ。", "error_description": "「直結」は「〜に直結する」と、影響を受ける先に「に」を付ける。「で」は手段を表し、影響の相手を示せないので、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39597, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勉強時間が成績に直結てくる。", "corrected_sentence": "勉強時間が成績に直結してくる。", "error_description": "「直結」は「直結してくる」と活用させる。「直結てくる」は「し」が抜けていて活用の誤り。正しくは「直結してくる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
