INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39598, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "一つのものだけで、他のものといっしょにいないこと。", "primary_collocate": null, "pronunciation": "たんどく", "ipa": "tandokɯ", "syllable_count": 4, "sentences": [{"text": "山で単独行動をするのは危険だと、先生は注意した。", "target_word": "単独", "complexity_tier": "T3", "furigana": "山[やま]で単独[たんどく]行動[こうどう]をするのは危険[きけん]だと、先生[せんせい]は注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "彼は仲間を待たずに、単独で頂上をめざした。", "target_word": "単独", "complexity_tier": "T3", "furigana": "彼[かれ]は仲間[なかま]を待[ま]たずに、単独[たんどく]で頂上[ちょうじょう]をめざした。", "sentence_source": "generated"}, {"text": "彼女は誰にも頼らず、単独で店を開いた。", "target_word": "単独", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]にも頼[たよ]らず、単独[たんどく]で店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "彼女は単独でヨーロッパを旅行した。", "target_word": "単独", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は単独[たんどく]でヨーロッパを旅行[りょこう]した。", "sentence_source": "generated"}, {"text": "森で単独のクマに出会ったら、静かに離れたほうがいい。", "target_word": "単独", "complexity_tier": "T3", "furigana": "森[もり]で単独[たんどく]のクマに出会[であ]ったら、静[しず]かに離[はな]れたほうがいい。", "sentence_source": "generated"}, {"text": "彼は団体ではなく、単独で大会に出場した。", "target_word": "単独", "complexity_tier": "T3", "furigana": "彼[かれ]は団体[だんたい]ではなく、単独[たんどく]で大会[たいかい]に出場[しゅつじょう]した。", "sentence_source": "generated"}, {"text": "この計画は一つの会社が単独で進めるには大きすぎる。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この計画[けいかく]は一[ひと]つの会社[かいしゃ]が単独[たんどく]で進[すす]めるには大[おお]きすぎる。", "sentence_source": "generated"}, {"text": "ライオンとちがって、トラは単独で狩りをする動物だ。", "target_word": "単独", "complexity_tier": "T3", "furigana": "ライオンとちがって、トラは単独[たんどく]で狩[か]りをする動物[どうぶつ]だ。", "sentence_source": "generated"}, {"text": "単独で行動するのが好きな彼は、グループ旅行を断った。", "target_word": "単独", "complexity_tier": "T3", "furigana": "単独[たんどく]で行動[こうどう]するのが好[す]きな彼[かれ]は、グループ旅行[りょこう]を断[ことわ]った。", "sentence_source": "generated"}, {"text": "社長が単独で決めたことに、社員たちは驚いた。", "target_word": "単独", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が単独[たんどく]で決[き]めたことに、社員[しゃいん]たちは驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単独だ", "label": "基本形"}, {"form": "単独で", "label": "で形（連用）"}, {"form": "単独の", "label": "連体形"}, {"form": "単独に", "label": "に形（連用）"}], "register": "neutral", "sense_fingerprint": "人や動物、組織が仲間をつくらず、一人（一つ）だけで行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39598, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単独", "is_correct": true, "explanation": "「仲間をつくらず一人で行動する」の意味で、「単独行動」にそのまま入る。"}, {"text": "豊か", "is_correct": false, "explanation": "「豊か」は量や内容が多いことを表すので、「豊か行動」は意味が通らない。"}, {"text": "色鮮やか", "is_correct": false, "explanation": "「色鮮やか」は色の見え方を表すので、「色鮮やか行動」は成り立たない。"}, {"text": "不明瞭", "is_correct": false, "explanation": "「不明瞭」は はっきりしないことなので、「不明瞭行動」は文として不自然で、注意の内容にならない。"}], "explanations": {"単独": "「仲間をつくらず一人で行動する」の意味で、「単独行動」にそのまま入る。", "豊か": "「豊か」は量や内容が多いことを表すので、「豊か行動」は意味が通らない。", "色鮮やか": "「色鮮やか」は色の見え方を表すので、「色鮮やか行動」は成り立たない。", "不明瞭": "「不明瞭」は はっきりしないことなので、「不明瞭行動」は文として不自然で、注意の内容にならない。"}, "sentence_index": 0, "correct_answer": "単独"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この先生の授業は単独な話し方で、聞いていると眠くなる。", "explanation": "ここは「単調」の意味。変化がなく同じ調子であることは「単調」と言い、「単独」は一人でいることを指すので、話し方の調子には使わない。"}, {"text": "この問題は単独な作りで、答えはすぐ分かる。", "explanation": "ここは「単純」の意味。複雑でなく分かりやすいことは「単純」と言い、「単独」は他のものといっしょにいないことを指すので、作りの説明には合わない。"}, {"text": "彼らは仲間と一緒に、単独で頂上をめざした。", "explanation": "ここは「共同で」の意味。仲間と協力して進むことは「共同で」と言い、「単独で」は一人で行うことなので、仲間と一緒という文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39598, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "単独", "is_correct": true, "explanation": "「一つの会社が単独で進める」の意味で、「単独で進めるには」にそのまま入る。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔」は衛生的な状態を表すので、「一つの会社が清潔で進める」は意味が通らない。"}, {"text": "上品", "is_correct": false, "explanation": "「上品」は品のよさを表すので、「一つの会社が上品で進める」では計画の進め方を表せない。"}, {"text": "古風", "is_correct": false, "explanation": "「古風」は古めかしいことなので、「一つの会社が古風で進める」は文として成り立たない。"}], "explanations": {"単独": "「一つの会社が単独で進める」の意味で、「単独で進めるには」にそのまま入る。", "清潔": "「清潔」は衛生的な状態を表すので、「一つの会社が清潔で進める」は意味が通らない。", "上品": "「上品」は品のよさを表すので、「一つの会社が上品で進める」では計画の進め方を表せない。", "古風": "「古風」は古めかしいことなので、「一つの会社が古風で進める」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "単独"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は単独のやり方で、誰も真似できない店をつくった。", "explanation": "ここは「独自」の意味。やり方が独特であることは「独自」と言い、「単独」は一人で行動することを指すので合わない。"}, {"text": "この料理は単独のだしで作るので、味が深い。", "explanation": "ここは「単一」の意味。種類が一つであることは「単一」と言い、「単独」は他のものといっしょにいないことを指すので、だしの種類には使わない。"}, {"text": "彼は一人暮らしで、いつも単独の寂しさに耐えていた。", "explanation": "ここは「孤独」の意味。寂しいという気持ちは「孤独」と言い、「単独」は一人で行動することを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39598, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その若者は仲間を離れ、単独を山に登った。", "corrected_sentence": "その若者は仲間を離れ、単独で山に登った。", "error_description": "「単独」は「で」で、一人で行う様子を示す。「を」を付けると目的語になり、「山に登った」と続かない。正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単独で", "is_correct": true, "explanation": "「一人で頂上をめざした」の「で」形。仲間を待たずに一人で動いたことを表す。"}, {"text": "単独だ", "is_correct": false, "explanation": "基本形の「だ」は文末で述語になるので、「頂上をめざした」を一人で行ったと修飾する形にはならない。"}, {"text": "単独だった", "is_correct": false, "explanation": "過去の述語の形で、「頂上をめざした」の動作の仕方を表す修飾にはならない。"}, {"text": "単独ない", "is_correct": false, "explanation": "形容動詞の「単独」に「ない」は続かず、「頂上をめざした」を修飾する形にならない。"}], "correct_form": "単独で", "base_form": "単独だ", "form_label": "で形（連用）", "sentence_index": 1, "explanations": {"単独で": "「一人で頂上をめざした」の「で」形。仲間を待たずに一人で動いたことを表す。", "単独だ": "基本形の「だ」は文末で述語になるので、「頂上をめざした」を一人で行ったと修飾する形にはならない。", "単独だった": "過去の述語の形で、「頂上をめざした」の動作の仕方を表す修飾にはならない。", "単独ない": "形容動詞の「単独」に「ない」は続かず、「頂上をめざした」を修飾する形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39598, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は誰の助けも借りず、単独ない小さな店を開いた。", "corrected_sentence": "父は誰の助けも借りず、単独で小さな店を開いた。", "error_description": "「単独」は形容動詞なので「ない」ではつながらない。「で」を付けて「単独で店を開いた」とするのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単独で", "is_correct": true, "explanation": "「狩りをする」を修飾し、一頭だけで行う様子を表す「で」形。"}, {"text": "単独だった", "is_correct": false, "explanation": "過去の述語の形で、「狩りをする」を修飾する形にはならない。"}, {"text": "単独では", "is_correct": false, "explanation": "「では」は主題を示して否定と組むことが多く、「狩りをする」の修飾として文が成り立たない。"}, {"text": "単独ではない", "is_correct": false, "explanation": "否定の述語で、「狩りをする」を修飾する形にはならない。"}], "correct_form": "単独で", "base_form": "単独だ", "form_label": "で形（連用）", "sentence_index": 7, "explanations": {"単独で": "「狩りをする」を修飾し、一頭だけで行う様子を表す「で」形。", "単独だった": "過去の述語の形で、「狩りをする」を修飾する形にはならない。", "単独では": "「では」は主題を示して否定と組むことが多く、「狩りをする」の修飾として文が成り立たない。", "単独ではない": "否定の述語で、「狩りをする」を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他のものといっしょになっていないこと。一つのものだけで存在していること。", "primary_collocate": null, "pronunciation": "たんどく", "ipa": "tandokɯ", "syllable_count": 4, "sentences": [{"text": "この薬は他の薬と混ぜず、単独で飲んでください。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この薬[くすり]は他[ほか]の薬[くすり]と混[ま]ぜず、単独[たんどく]で飲[の]んでください。", "sentence_source": "generated"}, {"text": "この調味料は単独では味が弱いが、他のものと合わせるとおいしい。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この調味料[ちょうみりょう]は単独[たんどく]では味[あじ]が弱[よわ]いが、他[ほか]のものと合[あ]わせるとおいしい。", "sentence_source": "generated"}, {"text": "単独の事件ではなく、似た事件が各地で起きている。", "target_word": "単独", "complexity_tier": "T3", "furigana": "単独[たんどく]の事件[じけん]ではなく、似[に]た事件[じけん]が各地[かくち]で起[お]きている。", "sentence_source": "generated"}, {"text": "この法案は単独では通らず、他の案といっしょに話し合われた。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この法案[ほうあん]は単独[たんどく]では通[とお]らず、他[ほか]の案[あん]といっしょに話[はな]し合[あ]われた。", "sentence_source": "generated"}, {"text": "その部屋の電気は、単独のスイッチで動かすことができる。", "target_word": "単独", "complexity_tier": "T3", "furigana": "その部屋[へや]の電気[でんき]は、単独[たんどく]のスイッチで動[うご]かすことができる。", "sentence_source": "generated"}, {"text": "単独の商品として売るより、セットにしたほうが人気が出る。", "target_word": "単独", "complexity_tier": "T3", "furigana": "単独[たんどく]の商品[しょうひん]として売[う]るより、セットにしたほうが人気[にんき]が出[で]る。", "sentence_source": "generated"}, {"text": "この色は単独で見ると地味だが、他の色と並べると目立つ。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この色[いろ]は単独[たんどく]で見[み]ると地味[じみ]だが、他[ほか]の色[いろ]と並[なら]べると目立[めだ]つ。", "sentence_source": "generated"}, {"text": "単独のチームで大会に出る学校は少なく、多くは合同チームだ。", "target_word": "単独", "complexity_tier": "T3", "furigana": "単独[たんどく]のチームで大会[たいかい]に出[で]る学校[がっこう]は少[すく]なく、多[おお]くは合同[ごうどう]チームだ。", "sentence_source": "generated"}, {"text": "この機械は単独でも動くが、別の機械とつなぐと便利だ。", "target_word": "単独", "complexity_tier": "T3", "furigana": "この機械[きかい]は単独[たんどく]でも動[うご]くが、別[べつ]の機械[きかい]とつなぐと便利[べんり]だ。", "sentence_source": "generated"}, {"text": "単独の部品で売られているので、壊れたところだけ買いかえられる。", "target_word": "単独", "complexity_tier": "T3", "furigana": "単独[たんどく]の部品[ぶひん]で売[う]られているので、壊[こわ]れたところだけ買[か]いかえられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単独だ", "label": "基本形"}, {"form": "単独で", "label": "で形（連用）"}, {"form": "単独の", "label": "連体形"}, {"form": "単独では", "label": "では形（連用＋否定との共起）"}], "register": "neutral", "sense_fingerprint": "物事や物が他と組み合わさらず、それ一つだけで成り立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea5ca57-f083-4e23-be0e-1c532fca28e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単独", "is_correct": true, "explanation": "「他と混ぜずに一つだけで飲む」の意味で、「単独で飲んでください」にそのまま入る。"}, {"text": "確実", "is_correct": false, "explanation": "「確実」は確かなことを表すので、「確実で飲む」は飲み方を表せず不自然。"}, {"text": "頻繁", "is_correct": false, "explanation": "「頻繁」は回数の多さを表すので、「頻繁で飲む」では飲み方の指示にならない。"}, {"text": "正確", "is_correct": false, "explanation": "「正確」は正しく合っていることなので、「正確で飲む」は飲み方を表せず不自然。"}], "explanations": {"単独": "「他と混ぜずに一つだけで飲む」の意味で、「単独で飲んでください」にそのまま入る。", "確実": "「確実」は確かなことを表すので、「確実で飲む」は飲み方を表せず不自然。", "頻繁": "「頻繁」は回数の多さを表すので、「頻繁で飲む」では飲み方の指示にならない。", "正確": "「正確」は正しく合っていることなので、「正確で飲む」は飲み方を表せず不自然。"}, "sentence_index": 0, "correct_answer": "単独"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は単独の色で描かれていて、とても明るい。", "explanation": "ここは「単色」の意味。一色だけで描かれていることは「単色」と言い、「単独」は他のものといっしょにないことを指すので、色づかいの説明には合わない。"}, {"text": "二つの部品は、単独の大きさにそろえると組み立てにくい。", "explanation": "ここは「同じ」の意味。大きさをそろえることは「同じ」と言い、「単独」は他のものといっしょにないことを指すので、大きさの話には合わない。"}, {"text": "この部品は単独のセットで売られているので、一度に全部買う必要がある。", "explanation": "ここは「単品」の意味。一つずつ売られる品は「単品」と言い、「単独」は他のものといっしょにないことを指すので、セットと組み合わさる文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "単独", "is_correct": true, "explanation": "「一つだけで見る」の意味で、「この色は単独で見ると」にそのまま入る。"}, {"text": "華やか", "is_correct": false, "explanation": "「華やか」は見た目の派手さを表すので、「この色は華やかで見ると」は文として成り立たない。"}, {"text": "鮮明", "is_correct": false, "explanation": "「鮮明」は明確なことを表すので、「この色は鮮明で見ると」は意味が通らない。"}, {"text": "軽快", "is_correct": false, "explanation": "「軽快」は軽やかな動きを表すので、「この色は軽快で見ると」は文として不自然。"}], "explanations": {"単独": "「一つだけで見る」の意味で、「この色は単独で見ると」にそのまま入る。", "華やか": "「華やか」は見た目の派手さを表すので、「この色は華やかで見ると」は文として成り立たない。", "鮮明": "「鮮明」は明確なことを表すので、「この色は鮮明で見ると」は意味が通らない。", "軽快": "「軽快」は軽やかな動きを表すので、「この色は軽快で見ると」は文として不自然。"}, "sentence_index": 6, "correct_answer": "単独"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この番組は単独の放送で、次の回はなかった。", "explanation": "ここは「単発」の意味。一回だけで続かないことは「単発」と言い、「単独」は他のものといっしょにないことを指すので、放送の回数には使わない。"}, {"text": "この会社は単独の技術で、ほかにない製品を開発した。", "explanation": "ここは「独自」の意味。ほかにない独特の技術は「独自」と言い、「単独」では言い換えられない。"}, {"text": "この店は食器の形を単独でそろえている。", "explanation": "ここは「統一」の意味。形をそろえることは「統一」と言い、「単独」は他のものといっしょにないことを指すので、形をそろえる話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部品は単独を売られていて、壊れたところだけ買える。", "corrected_sentence": "この部品は単独で売られていて、壊れたところだけ買える。", "error_description": "「単独」に「を」を付けると目的語になり、「売られている」と続かない。「で」を使って「単独で売られている」とするのが正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単独では", "is_correct": true, "explanation": "「単独では味が弱い」と、一つだけの場合を取り上げる「では」形。"}, {"text": "単独だ", "is_correct": false, "explanation": "基本形の「だ」は文末の述語になるので、「味が弱い」の主題にはならない。"}, {"text": "単独ない", "is_correct": false, "explanation": "形容動詞の「単独」に「ない」は続かず、「味が弱い」の前に置けない。"}, {"text": "単独だった", "is_correct": false, "explanation": "過去の述語の形で、「味が弱い」を修飾する形にはならない。"}], "correct_form": "単独では", "base_form": "単独だ", "form_label": "では形（連用＋否定との共起）", "sentence_index": 1, "explanations": {"単独では": "「単独では味が弱い」と、一つだけの場合を取り上げる「では」形。", "単独だ": "基本形の「だ」は文末の述語になるので、「味が弱い」の主題にはならない。", "単独ない": "形容動詞の「単独」に「ない」は続かず、「味が弱い」の前に置けない。", "単独だった": "過去の述語の形で、「味が弱い」を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39599, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工具は単独ても使えるが、セットだと便利だ。", "corrected_sentence": "この工具は単独でも使えるが、セットだと便利だ。", "error_description": "「単独」に「ても」をつなぐには「で」が必要。「単独ても」は活用の誤りで、正しくは「単独でも」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単独の", "is_correct": true, "explanation": "「単独のチーム」の連体形で、名詞「チーム」を修飾している。"}, {"text": "単独に", "is_correct": false, "explanation": "連用形の「に」は動詞や形容詞を修飾する形で、名詞「チーム」の前には置けない。"}, {"text": "単独で", "is_correct": false, "explanation": "「単独で」は副詞的な用法なので、名詞「チーム」を直接修飾できない。"}, {"text": "単独なら", "is_correct": false, "explanation": "「単独なら」は仮定の形で、名詞「チーム」の前に置けず、修飾にならない。"}], "correct_form": "単独の", "base_form": "単独だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"単独の": "「単独のチーム」の連体形で、名詞「チーム」を修飾している。", "単独に": "連用形の「に」は動詞や形容詞を修飾する形で、名詞「チーム」の前には置けない。", "単独で": "「単独で」は副詞的な用法なので、名詞「チーム」を直接修飾できない。", "単独なら": "「単独なら」は仮定の形で、名詞「チーム」の前に置けず、修飾にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79141c28-99b3-47f4-a584-b69d65148415') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "作る動作の対象になる巣を示すので「を」が入ります。"}, {"text": "が", "is_correct": false, "explanation": "「巣が作ります」では巣が主語になり、作る対象を示せないので合いません。"}, {"text": "と", "is_correct": false, "explanation": "「巣と作ります」は並列の形になり、作る対象を直接示せないので合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「巣へ作ります」は方向の意味になり、作る対象を示す役割とは合いません。"}], "correct_answer": "を", "explanations": {"を": "作る動作の対象になる巣を示すので「を」が入ります。", "が": "「巣が作ります」では巣が主語になり、作る対象を示せないので合いません。", "と": "「巣と作ります」は並列の形になり、作る対象を直接示せないので合いません。", "へ": "「巣へ作ります」は方向の意味になり、作る対象を示す役割とは合いません。"}, "error_tags": {"が": "主格", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥や虫が住むための家です。", "primary_collocate": null, "pronunciation": "す", "ipa": "sɯ", "syllable_count": 1, "sentences": [{"text": "木の上に鳥の巣があります。", "target_word": "巣", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]に鳥[とり]の巣[す]があります。", "sentence_source": "generated"}, {"text": "春になると、つばめが家の前に巣を作ります。", "target_word": "巣", "complexity_tier": "T3", "furigana": "春[はる]になると、つばめが家[いえ]の前[まえ]に巣[す]を作[つく]ります。", "sentence_source": "generated"}, {"text": "蜂の巣に近づくと、危ないですよ。", "target_word": "巣", "complexity_tier": "T3", "furigana": "蜂[はち]の巣[す]に近[ちか]づくと、危[あぶ]ないですよ。", "sentence_source": "generated"}, {"text": "巣の中で、小さな鳥が鳴いていました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "巣[す]の中[なか]で、小[ちい]さな鳥[とり]が鳴[な]いていました。", "sentence_source": "generated"}, {"text": "親鳥は毎日、巣に虫を運びます。", "target_word": "巣", "complexity_tier": "T3", "furigana": "親鳥[おやどり]は毎日[まいにち]、巣[す]に虫[むし]を運[はこ]びます。", "sentence_source": "generated"}, {"text": "庭の木にカラスの巣を見つけました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]にカラスの巣[す]を見[み]つけました。", "sentence_source": "generated"}, {"text": "クモは細い糸で巣を作り、虫を捕まえます。", "target_word": "巣", "complexity_tier": "T3", "furigana": "クモは細[ほそ]い糸[いと]で巣[す]を作[つく]り、虫[むし]を捕[つか]まえます。", "sentence_source": "generated"}, {"text": "雨がふったので、アリは巣の中に入りました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "雨[あめ]がふったので、アリは巣[す]の中[なか]に入[はい]りました。", "sentence_source": "generated"}, {"text": "高い所にあるので、巣の中は見えません。", "target_word": "巣", "complexity_tier": "T3", "furigana": "高[たか]い所[ところ]にあるので、巣[す]の中[なか]は見[み]えません。", "sentence_source": "generated"}, {"text": "風で巣が落ちて、卵が割れてしまいました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "風[かぜ]で巣[す]が落[お]ちて、卵[たまご]が割[わ]れてしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巣", "label": "基本形"}], "register": "中立", "sense_fingerprint": "鳥や虫が住む家としての巣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巣", "is_correct": true, "explanation": "木の上で鳥が住む場所を指すので、ここに入ります。"}, {"text": "鍋", "is_correct": false, "explanation": "料理に使う道具で、鳥の住まいではないので合いません。"}, {"text": "靴", "is_correct": false, "explanation": "足にはく物で、鳥が住む場所ではないので合いません。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる物で、鳥が住む場所ではないので合いません。"}], "explanations": {"巣": "木の上で鳥が住む場所を指すので、ここに入ります。", "鍋": "料理に使う道具で、鳥の住まいではないので合いません。", "靴": "足にはく物で、鳥が住む場所ではないので合いません。", "財布": "お金を入れる物で、鳥が住む場所ではないので合いません。"}, "sentence_index": 0, "correct_answer": "巣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅人は夜、山の巣に泊まった。", "explanation": "ここは〈宿（人が泊まる場所）〉の意味です。人が一時的に泊まる場所には〈宿〉を使い、鳥や虫が住む家の〈巣〉とは違うので合いません。"}, {"text": "彼は毎日、デスクの巣で仕事をしている。", "explanation": "ここは〈机〉の意味です。仕事をする台を指す語で、鳥や虫が住むための家を表す〈巣〉には当たらないので合いません。"}, {"text": "農家の人は、朝から巣で野菜を育てている。", "explanation": "ここは〈畑〉の意味です。野菜を育てる場所には〈畑〉を使い、鳥や虫が住む家を指す〈巣〉とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巣", "is_correct": true, "explanation": "細い糸で作る、クモが住む場所を指すので、ここに入ります。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を知るための道具で、クモが糸で作るものではないので合いません。"}, {"text": "電話", "is_correct": false, "explanation": "連絡に使う機械で、クモが作るものではないので合いません。"}, {"text": "切符", "is_correct": false, "explanation": "乗り物に乗るときに使う紙で、糸で作るものではないので合いません。"}], "explanations": {"巣": "細い糸で作る、クモが住む場所を指すので、ここに入ります。", "時計": "時刻を知るための道具で、クモが糸で作るものではないので合いません。", "電話": "連絡に使う機械で、クモが作るものではないので合いません。", "切符": "乗り物に乗るときに使う紙で、糸で作るものではないので合いません。"}, "sentence_index": 6, "correct_answer": "巣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "りんごの巣をむいて、食べました。", "explanation": "ここは〈皮〉の意味です。巣は鳥や虫が住むための場所で、果物の外側の皮には使わないので合いません。"}, {"text": "小鳥を巣に入れて飼っています。", "explanation": "ここは〈鳥かご〉の意味です。人が小鳥を入れて飼う道具で、鳥が自分で作って住む巣とは違うので合いません。"}, {"text": "おもちゃを巣にしまいました。", "explanation": "ここは〈箱〉の意味です。物をしまう容器で、鳥や虫が住む場所の巣には合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "親鳥は卵を温めるため、巣が作りました。", "corrected_sentence": "親鳥は卵を温めるため、巣を作りました。", "error_description": "「巣が作りました」は誤りです。「作る」は目的語を「を」で取るので、正しくは「巣を作りました」です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39600, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カラスが庭の木に巣を飛ばしました。", "corrected_sentence": "カラスが庭の木に巣を作りました。", "error_description": "「飛ばしました」は誤りです。巣は「作る」ものなので、正しくは「巣を作りました」です。「飛ばす」は巣とは結びつきません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "作る動作の対象となる巣を示すので「を」が入ります。"}, {"text": "が", "is_correct": false, "explanation": "「巣が作った」では巣が主語になり、ハチの行為と合わないので合いません。"}, {"text": "に", "is_correct": false, "explanation": "「巣に作った」は場所を示すため、作る対象の説明にはなりません。"}, {"text": "で", "is_correct": false, "explanation": "「巣で作った」は手段の意味になり、作る対象を示せないので合いません。"}], "correct_answer": "を", "explanations": {"を": "作る動作の対象となる巣を示すので「を」が入ります。", "が": "「巣が作った」では巣が主語になり、ハチの行為と合わないので合いません。", "に": "「巣に作った」は場所を示すため、作る対象の説明にはなりません。", "で": "「巣で作った」は手段の意味になり、作る対象を示せないので合いません。"}, "error_tags": {"が": "主格", "に": "位置", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「巣の中」の形で、巣の内側を示すので「の」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「巣を中には」は巣を対象にする形になり、文の流れに合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「巣へ中には」は方向を表すので、中にひながいることを述べる文には合いません。"}, {"text": "と", "is_correct": false, "explanation": "「巣と中には」は並列の形になり、ひなが巣の中にいるという意味にはなりません。"}], "correct_answer": "の", "explanations": {"の": "「巣の中」の形で、巣の内側を示すので「の」が入ります。", "を": "「巣を中には」は巣を対象にする形になり、文の流れに合いません。", "へ": "「巣へ中には」は方向を表すので、中にひながいることを述べる文には合いません。", "と": "「巣と中には」は並列の形になり、ひなが巣の中にいるという意味にはなりません。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥や昆虫などが、卵を産んだり住んだりするために作る場所。", "primary_collocate": null, "pronunciation": "す", "ipa": "sɯ", "syllable_count": 1, "sentences": [{"text": "鳥は卵を産むために、枝で巣を作ります。", "target_word": "巣", "complexity_tier": "T3", "furigana": "鳥[とり]は卵[たまご]を産[う]むために、枝[えだ]で巣[す]を作[つく]ります。", "sentence_source": "generated"}, {"text": "軒下にハチが巣を作ったので、業者を呼びました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "軒下[のきした]にハチが巣[す]を作[つく]ったので、業者[ぎょうしゃ]を呼[よ]びました。", "sentence_source": "generated"}, {"text": "ツバメは毎年、同じ巣に帰ってきます。", "target_word": "巣", "complexity_tier": "T3", "furigana": "ツバメは毎年[まいとし]、同[おな]じ巣[す]に帰[かえ]ってきます。", "sentence_source": "generated"}, {"text": "親鳥は卵が冷えないように、巣の中であたためています。", "target_word": "巣", "complexity_tier": "T3", "furigana": "親鳥[おやどり]は卵[たまご]が冷[ひ]えないように、巣[す]の中[なか]であたためています。", "sentence_source": "generated"}, {"text": "ヘビが木に登って、鳥の巣を狙っています。", "target_word": "巣", "complexity_tier": "T3", "furigana": "ヘビが木[き]に登[のぼ]って、鳥[とり]の巣[す]を狙[ねら]っています。", "sentence_source": "generated"}, {"text": "公園の木に、小さな巣があるのを見つけました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "公園[こうえん]の木[き]に、小[ちい]さな巣[す]があるのを見[み]つけました。", "sentence_source": "generated"}, {"text": "巣を壊されても、鳥はまた新しい巣を作ります。", "target_word": "巣", "complexity_tier": "T3", "furigana": "巣[す]を壊[こわ]されても、鳥[とり]はまた新[あたら]しい巣[す]を作[つく]ります。", "sentence_source": "generated"}, {"text": "巣の中には、まだ目の開かないひなが三羽いました。", "target_word": "巣", "complexity_tier": "T3", "furigana": "巣[す]の中[なか]には、まだ目[め]の開[ひら]かないひなが三羽[さんば]いました。", "sentence_source": "generated"}, {"text": "アリの巣は、地面の下に長くつながっています。", "target_word": "巣", "complexity_tier": "T3", "furigana": "アリの巣[す]は、地面[じめん]の下[した]に長[なが]くつながっています。", "sentence_source": "generated"}, {"text": "カササギは高い木の上に巣をかけます。", "target_word": "巣", "complexity_tier": "T3", "furigana": "カササギは高[たか]い木[き]の上[うえ]に巣[す]をかけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巣", "label": "基本形"}], "register": "中立", "sense_fingerprint": "卵を産み住むために動物が作る場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巣", "is_correct": true, "explanation": "鳥が卵を産むために作る住まいを指すので、ここに入ります。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送る物で、枝で作るものではないので合いません。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる物で、枝で作る住まいではないので合いません。"}, {"text": "眼鏡", "is_correct": false, "explanation": "目を守ったり見えるようにしたりする物で、枝で作るものではないので合いません。"}], "explanations": {"巣": "鳥が卵を産むために作る住まいを指すので、ここに入ります。", "手紙": "書いて送る物で、枝で作るものではないので合いません。", "財布": "お金を入れる物で、枝で作る住まいではないので合いません。", "眼鏡": "目を守ったり見えるようにしたりする物で、枝で作るものではないので合いません。"}, "sentence_index": 0, "correct_answer": "巣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修学旅行の生徒は、夜に山の巣に泊まった。", "explanation": "ここは〈宿（人が泊まる場所）〉の意味です。人が泊まる場所には〈宿〉を使い、鳥や昆虫が住む場所を指す〈巣〉とは違うので合いません。"}, {"text": "職人は毎日、工房の巣で木を削っている。", "explanation": "ここは〈作業場〉の意味です。木を削って物を作る場所を指す語で、鳥や昆虫が住むための場所を表す〈巣〉とは違うので合いません。"}, {"text": "ゴミを巣に入れて捨てました。", "explanation": "ここは〈袋〉の意味です。ゴミを入れる容器を指し、鳥や昆虫が住む場所の巣とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巣", "is_correct": true, "explanation": "新しく作る鳥の住まいを指すので、ここに入ります。"}, {"text": "靴", "is_correct": false, "explanation": "足にはく物で、鳥が作る住まいではないので合いません。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を知るための道具で、鳥が作る住まいではないので合いません。"}, {"text": "電話", "is_correct": false, "explanation": "連絡に使う機械で、鳥が作る住まいとは違うので合いません。"}], "explanations": {"巣": "新しく作る鳥の住まいを指すので、ここに入ります。", "靴": "足にはく物で、鳥が作る住まいではないので合いません。", "時計": "時刻を知るための道具で、鳥が作る住まいではないので合いません。", "電話": "連絡に使う機械で、鳥が作る住まいとは違うので合いません。"}, "sentence_index": 6, "correct_answer": "巣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "割れた卵の巣を、ゴミ箱に捨てました。", "explanation": "ここは〈殻〉の意味です。卵を包む殻を指し、鳥や昆虫が住む場所の巣とは違うので合いません。"}, {"text": "巣にお金を入れて、出かけました。", "explanation": "ここは〈財布〉の意味です。お金を入れる物で、鳥が住む場所の巣には合いません。"}, {"text": "お気に入りの手紙を巣にしまいました。", "explanation": "ここは〈箱〉の意味です。物をしまう容器で、鳥や昆虫が住む場所の巣とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハトは木の枝で巣が作ります。", "corrected_sentence": "ハトは木の枝で巣を作ります。", "error_description": "「巣が作ります」は誤りです。「作る」は目的語を「を」で取るので、正しくは「巣を作ります」です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39601, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親鳥は毎朝、巣を料理しています。", "corrected_sentence": "親鳥は毎朝、巣を掃除しています。", "error_description": "「料理しています」は誤りです。巣は手入れをするものなので、正しくは「掃除しています」です。「料理」は食べ物に使う語で、巣とは結びつきません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
