INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "頭のよさのことです。考える力のことです。", "primary_collocate": null, "pronunciation": "ちのう", "ipa": "tɕinoː", "syllable_count": 3, "sentences": [{"text": "知能が高い。", "target_word": "知能", "complexity_tier": "T1", "furigana": "知能[ちのう]が高[たか]い。", "sentence_source": "generated"}, {"text": "この犬は知能が高い。", "target_word": "知能", "complexity_tier": "T2", "furigana": "この犬[いぬ]は知能[ちのう]が高[たか]い。", "sentence_source": "generated"}, {"text": "知能とは頭のよさだ。", "target_word": "知能", "complexity_tier": "T2", "furigana": "知能[ちのう]とは頭[あたま]のよさだ。", "sentence_source": "generated"}, {"text": "猿の知能を調べる。", "target_word": "知能", "complexity_tier": "T2", "furigana": "猿[さる]の知能[ちのう]を調[しら]べる。", "sentence_source": "generated"}, {"text": "子どもの知能を伸ばしたい。", "target_word": "知能", "complexity_tier": "T3", "furigana": "子[こ]どもの知能[ちのう]を伸[の]ばしたい。", "sentence_source": "generated"}, {"text": "知能のテストを受けた。", "target_word": "知能", "complexity_tier": "T2", "furigana": "知能[ちのう]のテストを受[う]けた。", "sentence_source": "generated"}, {"text": "イルカは知能が高いと言われている。", "target_word": "知能", "complexity_tier": "T3", "furigana": "イルカは知能[ちのう]が高[たか]いと言[い]われている。", "sentence_source": "generated"}, {"text": "知能は生まれつきだけではない。", "target_word": "知能", "complexity_tier": "T3", "furigana": "知能[ちのう]は生[う]まれつきだけではない。", "sentence_source": "generated"}, {"text": "毎日考えれば、知能が育つかもしれない。", "target_word": "知能", "complexity_tier": "T4", "furigana": "毎日[まいにち]考[かんが]えれば、知能[ちのう]が育[そだ]つかもしれない。", "sentence_source": "generated"}, {"text": "人間の知能は、ほかの動物とは違う。", "target_word": "知能", "complexity_tier": "T3", "furigana": "人間[にんげん]の知能[ちのう]は、ほかの動物[どうぶつ]とは違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知能的", "label": "派生"}, {"form": "知能指数", "label": "派生"}, {"form": "人工知能", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 頭のよさ、考える力のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知能", "is_correct": true, "explanation": "頭のよさが高い、という意味に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束が高いとは言えず意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩が高いとは言えず意味が合わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "形は合うが、笑顔が高いとは言えず意味が合わない。"}], "explanations": {"知能": "頭のよさが高い、という意味に合う。", "約束": "形は合うが、約束が高いとは言えず意味が合わない。", "散歩": "形は合うが、散歩が高いとは言えず意味が合わない。", "笑顔": "形は合うが、笑顔が高いとは言えず意味が合わない。"}, "sentence_index": 0, "correct_answer": "知能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食は知能がおいしくて、たくさん食べた。", "explanation": "知能は食べ物ではない。料理の意味で使っている誤り。"}, {"text": "彼は走りすぎて、知能が折れてしまった。", "explanation": "知能は体の骨ではない。体の部位の意味で使っている誤り。"}, {"text": "知能で手紙を書いて、友達に送った。", "explanation": "知能は筆記用具ではない。道具の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知能", "is_correct": true, "explanation": "イルカの頭のよさが高いと言われている、という意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は高さで表せず、イルカの頭のよさを述べられない。"}, {"text": "雑談", "is_correct": false, "explanation": "雑談は会話の一種で、「高い」と程度を言えない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は場所を指し、「高い」と頭のよさを表せない。"}], "explanations": {"知能": "イルカの頭のよさが高いと言われている、という意味に合う。", "天気": "天気は高さで表せず、イルカの頭のよさを述べられない。", "雑談": "雑談は会話の一種で、「高い」と程度を言えない。", "台所": "台所は場所を指し、「高い」と頭のよさを表せない。"}, "sentence_index": 6, "correct_answer": "知能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "知能を開けて、中の荷物を取り出した。", "explanation": "知能は開けられる入れ物ではない。箱の意味で使っている誤り。"}, {"text": "この部屋の知能は広くて明るい。", "explanation": "知能は部屋の様子を表さない。空間の意味で使っている誤り。"}, {"text": "知能に乗って、海を渡った。", "explanation": "知能は乗り物ではない。船の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
