INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39603, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を正しく理解し、判断したり、問題を解決したりする能力。また、その働き。", "primary_collocate": null, "pronunciation": "ちのう", "ipa": "tɕinoː", "syllable_count": 3, "sentences": [{"text": "知能を伸ばすには、毎日考えることが大切だ。", "target_word": "知能", "complexity_tier": "T3", "furigana": "知能[ちのう]を伸[の]ばすには、毎日[まいにち]考[かんが]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "知能は考える力です。", "target_word": "知能", "complexity_tier": "T2", "furigana": "知能[ちのう]は考[かんが]える力[ちから]です。", "sentence_source": "generated"}, {"text": "犬は知能が高い動物だ。", "target_word": "知能", "complexity_tier": "T3", "furigana": "犬[いぬ]は知能[ちのう]が高[たか]い動物[どうぶつ]だ。", "sentence_source": "generated"}, {"text": "知能を測るテストがある。", "target_word": "知能", "complexity_tier": "T3", "furigana": "知能[ちのう]を測[はか]るテストがある。", "sentence_source": "generated"}, {"text": "子どもの知能は成長します。", "target_word": "知能", "complexity_tier": "T2", "furigana": "子[こ]どもの知能[ちのう]は成長[せいちょう]します。", "sentence_source": "generated"}, {"text": "知能の発達には環境が大切だ。", "target_word": "知能", "complexity_tier": "T3", "furigana": "知能[ちのう]の発達[はったつ]には環境[かんきょう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "知能が高ければ、成功するとは限らない。", "target_word": "知能", "complexity_tier": "T4", "furigana": "知能[ちのう]が高[たか]ければ、成功[せいこう]するとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "カラスは高い知能を持っている。", "target_word": "知能", "complexity_tier": "T3", "furigana": "カラスは高[たか]い知能[ちのう]を持[も]っている。", "sentence_source": "generated"}, {"text": "知能を持つ機械が研究されている。", "target_word": "知能", "complexity_tier": "T4", "furigana": "知能[ちのう]を持[も]つ機械[きかい]が研究[けんきゅう]されている。", "sentence_source": "generated"}, {"text": "動物の知能について、多くの研究者が調べてきた。", "target_word": "知能", "complexity_tier": "T5", "furigana": "動物[どうぶつ]の知能[ちのう]について、多[おお]くの研究者[けんきゅうしゃ]が調[しら]べてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知能的", "label": "派生"}, {"form": "知能指数", "label": "派生"}, {"form": "人工知能", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 理解し判断し解決する能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d0173e-2e1b-4778-a025-fca7f14c2071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39603, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知能", "is_correct": true, "explanation": "見出し語そのもの(ちのう)。"}, {"text": "機能", "is_correct": false, "explanation": "きのう。「ち」が「き」に変わる1モーラ違い。"}, {"text": "地方", "is_correct": false, "explanation": "ちほう。「の」が「ほ」に変わる1モーラ違い。"}, {"text": "馳走", "is_correct": false, "explanation": "ちそう。「の」が「そ」に変わる1モーラ違い。"}], "explanations": {"知能": "見出し語そのもの(ちのう)。", "機能": "きのう。「ち」が「き」に変わる1モーラ違い。", "地方": "ちほう。「の」が「ほ」に変わる1モーラ違い。", "馳走": "ちそう。「の」が「そ」に変わる1モーラ違い。"}, "sentence_index": null, "correct_answer": "知能"}, "level_3": {"options": [{"text": "知能", "is_correct": true, "explanation": "能力を伸ばす、という意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は伸ばして育てるものではなく、意味が合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は場所で、伸ばして育てるものではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは景色で、伸ばして育てるものではない。"}], "explanations": {"知能": "能力を伸ばす、という意味に合う。", "天気": "天気は伸ばして育てるものではなく、意味が合わない。", "台所": "台所は場所で、伸ばして育てるものではない。", "夕焼け": "夕焼けは景色で、伸ばして育てるものではない。"}, "sentence_index": 0, "correct_answer": "知能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "知能が痛くて、病院に行った。", "explanation": "知能は体の部位ではない。痛む部位の意味で使っている誤り。"}, {"text": "彼は毎朝、知能を食べてから出かける。", "explanation": "知能は食べ物ではない。食べ物の意味で使っている誤り。"}, {"text": "この橋は知能が長くて、渡るのに時間がかかる。", "explanation": "知能は物の長さを表さない。「長さ」の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39603, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知能", "is_correct": true, "explanation": "見出し語そのもの(ちのう)。"}, {"text": "知謀", "is_correct": false, "explanation": "ちぼう。「の」が「ぼ」に変わる1モーラ違い。"}, {"text": "誓う", "is_correct": false, "explanation": "ちかう。「の」が「か」に変わる1モーラ違い。"}, {"text": "離農", "is_correct": false, "explanation": "りのう。「ち」が「り」に変わる1モーラ違い。"}], "explanations": {"知能": "見出し語そのもの(ちのう)。", "知謀": "ちぼう。「の」が「ぼ」に変わる1モーラ違い。", "誓う": "ちかう。「の」が「か」に変わる1モーラ違い。", "離農": "りのう。「ち」が「り」に変わる1モーラ違い。"}, "sentence_index": null, "correct_answer": "知能"}, "level_3": {"options": [{"text": "知能", "is_correct": true, "explanation": "知能が高くても成功するとは限らない、と自然につながる。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、気温と成功の関係が意味として合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、湿度と成功の関係が意味として合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、屋根と成功の関係が意味として合わない。"}], "explanations": {"知能": "知能が高くても成功するとは限らない、と自然につながる。", "気温": "形は合うが、気温と成功の関係が意味として合わない。", "湿度": "形は合うが、湿度と成功の関係が意味として合わない。", "屋根": "形は合うが、屋根と成功の関係が意味として合わない。"}, "sentence_index": 6, "correct_answer": "知能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所の知能が汚れているので、掃除した。", "explanation": "知能は汚れた物（ごみ）ではない。「ごみ」の意味で使っている誤り。"}, {"text": "知能を着て、雨の中を出かけた。", "explanation": "知能は着る物ではない。衣服の意味で使っている誤り。"}, {"text": "彼は大きな知能を投げて、窓を割った。", "explanation": "知能は投げられる物ではない。「石」の意味で使っている誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b84a40-2849-4d74-8112-fe871588c757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
