INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39604, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "わからないことを見つけるために、さがしたり調べたりすることです。", "primary_collocate": null, "pronunciation": "たんさく", "ipa": "taɴsakɯ", "syllable_count": 4, "sentences": [{"text": "子どもたちは、森の中を探索して、珍しい虫を見つけた。", "target_word": "探索", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、森[もり]の中[なか]を探索[たんさく]して、珍[めずら]しい虫[むし]を見[み]つけた。", "sentence_source": "generated"}, {"text": "洞窟の探索には、明かりと地図が欠かせない。", "target_word": "探索", "complexity_tier": "T4", "furigana": "洞窟[どうくつ]の探索[たんさく]には、明[あ]かりと地図[ちず]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "宇宙の探索は、まだ始まったばかりだ。", "target_word": "探索", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の探索[たんさく]は、まだ始[はじ]まったばかりだ。", "sentence_source": "generated"}, {"text": "新しい町を探索するのが、旅行の楽しみだ。", "target_word": "探索", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]を探索[たんさく]するのが、旅行[りょこう]の楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "探索の結果、古い井戸が見つかった。", "target_word": "探索", "complexity_tier": "T3", "furigana": "探索[たんさく]の結果[けっか]、古[ふる]い井戸[いど]が見[み]つかった。", "sentence_source": "generated"}, {"text": "ロボットが海の底を探索している。", "target_word": "探索", "complexity_tier": "T3", "furigana": "ロボットが海[うみ]の底[そこ]を探索[たんさく]している。", "sentence_source": "generated"}, {"text": "道に迷ったので、周りを少し探索してみた。", "target_word": "探索", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]ったので、周[まわ]りを少[すこ]し探索[たんさく]してみた。", "sentence_source": "generated"}, {"text": "博物館の地下を探索する冒険ゲームを遊んだ。", "target_word": "探索", "complexity_tier": "T4", "furigana": "博物館[はくぶつかん]の地下[ちか]を探索[たんさく]する冒険[ぼうけん]ゲームを遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "探索のために、チームは三日かけて山の奥まで進んだ。", "target_word": "探索", "complexity_tier": "T4", "furigana": "探索[たんさく]のために、チームは三日[みっか]かけて山[やま]の奥[おく]まで進[すす]んだ。", "sentence_source": "generated"}, {"text": "島の探索は、朝早くから始まった。", "target_word": "探索", "complexity_tier": "T3", "furigana": "島[しま]の探索[たんさく]は、朝[あさ]早[はや]くから始[はじ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "探索", "label": "基本形"}, {"form": "探索する", "label": "サ変動詞の基本形"}, {"form": "探索した", "label": "サ変動詞の過去形"}], "register": "標準（普通体）", "sense_fingerprint": "未知の物事を見つけるために探し調べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "未知の物事を探し調べる意味で、森の中で珍しい虫を見つける文脈に合う。"}, {"text": "運搬", "is_correct": false, "explanation": "物を別の場所へ運ぶ意味。森の中で虫を見つける流れには合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "場所をきれいにする意味。虫を見つける文脈とつながらない。"}, {"text": "集計", "is_correct": false, "explanation": "数を合計する意味。森の中を進んで虫を見つける場面には合わない。"}], "explanations": {"探索": "未知の物事を探し調べる意味で、森の中で珍しい虫を見つける文脈に合う。", "運搬": "物を別の場所へ運ぶ意味。森の中で虫を見つける流れには合わない。", "清掃": "場所をきれいにする意味。虫を見つける文脈とつながらない。", "集計": "数を合計する意味。森の中を進んで虫を見つける場面には合わない。"}, "sentence_index": 0, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "健康診断で血液を探索した。", "explanation": "ここは〈検査〉の意味。探索は未知の物事を探し求めることなので、健康診断のように既知の項目を調べる場面には合わない。"}, {"text": "新しく届いた資料を、担当者が年代順に探索して整理した。", "explanation": "ここは〈分類〉の意味。種類や年代ごとに分ける場面では分類を使い、探索は合わない。"}, {"text": "美術商は古い絵を探索して、本物かどうか判断した。", "explanation": "ここは〈鑑定〉の意味。真偽や価値を見極める場面では鑑定を使い、探索は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "迷って周りを少し調べてみる意味で、道に迷った場面に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に置き換える意味。周りを調べる行動とは合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける意味。道を歩く場面には合わない。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届ける意味。道に迷った場面とは合わない。"}], "explanations": {"探索": "迷って周りを少し調べてみる意味で、道に迷った場面に合う。", "翻訳": "言葉を別の言語に置き換える意味。周りを調べる行動とは合わない。", "採点": "答案などに点数をつける意味。道を歩く場面には合わない。", "配送": "荷物を届ける意味。道に迷った場面とは合わない。"}, "sentence_index": 6, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府が地域の人口を探索した。", "explanation": "ここは〈調査〉の意味。数や実態を調べて把握する場面では調査を使う。探索は未知のものを見つけることなので合わない。"}, {"text": "警察は逃走中の車を探索しながら、どこまでも追いかけた。", "explanation": "ここは〈追跡〉の意味。動いているものを追いかける場面では追跡を使い、探索は合わない。"}, {"text": "ビルの管理人は排水管を探索して、ごみを取り除いた。", "explanation": "ここは〈清掃〉の意味。汚れを取り除く場面では清掃を使い、探索は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは、川辺に探索して、きれいな石を集めた。", "corrected_sentence": "子どもたちは、川辺を探索して、きれいな石を集めた。", "error_description": "「探索する」は対象を「を」で示すので、「に」は誤り。「川辺を探索して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漁師たちは、夕方まで入り江を探索ていた。", "corrected_sentence": "漁師たちは、夕方まで入り江を探索していた。", "error_description": "「探索している」の「し」が抜けている。サ変動詞「探索する」の連用形「探索し」に「ていた」を続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「火星の探索には」の「に」が正しい（「には」と続く）。"}, {"text": "を", "is_correct": false, "explanation": "「探索をは」となり、目的語として続かないので文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「探索がは」となり、主語として続かないので文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「探索のは」となり、名詞修飾の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「火星の探索には」の「に」が正しい（「には」と続く）。", "を": "「探索をは」となり、目的語として続かないので文が成り立たない。", "が": "「探索がは」となり、主語として続かないので文が成り立たない。", "の": "「探索のは」となり、名詞修飾の形にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「探索を始める」の目的語を示す「を」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「探索が始める」となり、「始める」の主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「探索と始める」は並列の形になり、動詞につながらない。"}, {"text": "に", "is_correct": false, "explanation": "「探索に始める」は方向の形になり、動詞の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「探索を始める」の目的語を示す「を」で正しい。", "が": "「探索が始める」となり、「始める」の主語として成り立たない。", "と": "「探索と始める」は並列の形になり、動詞につながらない。", "に": "「探索に始める」は方向の形になり、動詞の対象にならない。"}, "error_tags": {"が": "主語", "と": "並列", "に": "方向・位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "未知のものや目的のものを探し求めること。", "primary_collocate": null, "pronunciation": "たんさく", "ipa": "taɴsakɯ", "syllable_count": 4, "sentences": [{"text": "研究者たちは、新しい資源の探索を進めている。", "target_word": "探索", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]たちは、新[あたら]しい資源[しげん]の探索[たんさく]を進[すす]めている。", "sentence_source": "generated"}, {"text": "火星の探索には、多くの国が協力している。", "target_word": "探索", "complexity_tier": "T4", "furigana": "火星[かせい]の探索[たんさく]には、多[おお]くの国[くに]が協力[きょうりょく]している。", "sentence_source": "generated"}, {"text": "探索の範囲を広げたところ、ようやく手がかりが得られた。", "target_word": "探索", "complexity_tier": "T4", "furigana": "探索[たんさく]の範囲[はんい]を広[ひろ]げたところ、ようやく手[て]がかりが得[え]られた。", "sentence_source": "generated"}, {"text": "深海の探索は、技術の進歩によって可能になった。", "target_word": "探索", "complexity_tier": "T4", "furigana": "深海[しんかい]の探索[たんさく]は、技術[ぎじゅつ]の進歩[しんぽ]によって可能[かのう]になった。", "sentence_source": "generated"}, {"text": "彼は長年、失われた古代都市の探索に人生をかけた。", "target_word": "探索", "complexity_tier": "T4", "furigana": "彼[かれ]は長年[ながねん]、失[うしな]われた古代[こだい]都市[とし]の探索[たんさく]に人生[じんせい]をかけた。", "sentence_source": "generated"}, {"text": "無人機が、危険な場所の探索を代わりに行う。", "target_word": "探索", "complexity_tier": "T4", "furigana": "無人機[むじんき]が、危険[きけん]な場所[ばしょ]の探索[たんさく]を代[か]わりに行[おこな]う。", "sentence_source": "generated"}, {"text": "新しい解決策の探索が、会議の目的だった。", "target_word": "探索", "complexity_tier": "T4", "furigana": "新[あたら]しい解決策[かいけつさく]の探索[たんさく]が、会議[かいぎ]の目的[もくてき]だった。", "sentence_source": "generated"}, {"text": "探索を始める前に、安全を確かめておく必要がある。", "target_word": "探索", "complexity_tier": "T4", "furigana": "探索[たんさく]を始[はじ]める前[まえ]に、安全[あんぜん]を確[たし]かめておく必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "遺跡の探索で、貴重な土器が発見された。", "target_word": "探索", "complexity_tier": "T4", "furigana": "遺跡[いせき]の探索[たんさく]で、貴重[きちょう]な土器[どき]が発見[はっけん]された。", "sentence_source": "generated"}, {"text": "探索に失敗しても、そこから学ぶことは多い。", "target_word": "探索", "complexity_tier": "T4", "furigana": "探索[たんさく]に失敗[しっぱい]しても、そこから学[まな]ぶことは多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "探索", "label": "基本形"}, {"form": "探索する", "label": "サ変動詞の基本形"}, {"form": "探索した", "label": "サ変動詞の過去形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "未知・目的のものを探し求めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "資源を求めて探し求める活動を指し、研究の進行を述べる文脈に合う。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す意味。資源を探す文脈には合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を置き換える意味。資源の話には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味。資源の話には合わない。"}], "explanations": {"探索": "資源を求めて探し求める活動を指し、研究の進行を述べる文脈に合う。", "修理": "壊れたものを直す意味。資源を探す文脈には合わない。", "翻訳": "言語を置き換える意味。資源の話には合わない。", "採点": "点数をつける意味。資源の話には合わない。"}, "sentence_index": 0, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "健康診断で血圧を探索した。", "explanation": "ここは〈検査〉の意味。数値を測って確かめる場面では検査を使う。探索は未知のものを探し求めることなので合わない。"}, {"text": "船は逃走中の密漁船を探索しながら、沖まで追いかけた。", "explanation": "ここは〈追跡〉の意味。動いている対象を追いかける場面では追跡を使い、探索は合わない。"}, {"text": "職人が古い壁を探索して、白く塗り直した。", "explanation": "ここは〈塗装〉の意味。表面に色を重ねる場面では塗装を使い、探索は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "新しい方法を探し求める活動を指し、会議の目的として述べる文脈に合う。"}, {"text": "掲示", "is_correct": false, "explanation": "紙などを人目につく所に出す意味。解決策の話には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける意味。会議の目的とは合わない。"}, {"text": "清算", "is_correct": false, "explanation": "お金の支払いを終える意味。解決策の話には合わない。"}], "explanations": {"探索": "新しい方法を探し求める活動を指し、会議の目的として述べる文脈に合う。", "掲示": "紙などを人目につく所に出す意味。解決策の話には合わない。", "配達": "物を届ける意味。会議の目的とは合わない。", "清算": "お金の支払いを終える意味。解決策の話には合わない。"}, "sentence_index": 6, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、ドライバーは燃料を探索してから出発する。", "explanation": "ここは〈給油〉の意味。燃料を車に入れる場面では給油を使い、探索は合わない。"}, {"text": "市は古い橋の耐久性を探索した。", "explanation": "ここは〈調査〉の意味。性能や状態を調べる場面では調査を使い、探索は合わない。"}, {"text": "市は毎月の交通事故の件数を探索して、表にまとめた。", "explanation": "ここは〈集計〉の意味。数を合計してまとめる場面では集計を使い、探索は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39605, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者たちは、深海に探索を進めている。", "corrected_sentence": "研究者たちは、深海の探索を進めている。", "error_description": "「深海の探索」と「の」で名詞をつなぐのが正しい。「に」では「深海に探索を進める」となり不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
