INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ダンスが好き」の「が」で、好きの対象を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「好き」は「が」で対象を示すので、「ダンスを好き」とは続かない。"}, {"text": "に", "is_correct": false, "explanation": "「ダンスに好き」は不自然で、「好き」の対象を示すのは「が」。"}, {"text": "と", "is_correct": false, "explanation": "「ダンスと好き」は意味が通らず、「好き」の対象は「が」で示す。"}], "correct_answer": "が", "explanations": {"が": "「ダンスが好き」の「が」で、好きの対象を示す格助詞。", "を": "「好き」は「が」で対象を示すので、「ダンスを好き」とは続かない。", "に": "「ダンスに好き」は不自然で、「好き」の対象を示すのは「が」。", "と": "「ダンスと好き」は意味が通らず、「好き」の対象は「が」で示す。"}, "error_tags": {"を": "目的語の格", "に": "位置・相手の格", "と": "相手・並列の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「発表会のダンス」の「の」で、名詞を続ける連体修飾の助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」で、「ダンスで」と続けても名詞の修飾にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「ダンスへ」と続けても文の意味に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、「ダンスから」と続けると文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「発表会のダンス」の「の」で、名詞を続ける連体修飾の助詞。", "で": "手段や場所を示す「で」で、「ダンスで」と続けても名詞の修飾にならない。", "へ": "方向を示す「へ」は、「ダンスへ」と続けても文の意味に合わない。", "から": "起点を示す「から」は、「ダンスから」と続けると文が成り立たない。"}, "error_tags": {"で": "手段・場所の格", "へ": "方向の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "からだをうごかして、音楽にあわせてたのしくうごくことです。", "primary_collocate": null, "pronunciation": "だんす", "ipa": "dansɯ", "syllable_count": 3, "sentences": [{"text": "友だちと音楽に合わせて、楽しくダンスをしました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "友[とも]だちと音楽[おんがく]に合[あ]わせて、楽[たの]しくダンスをしました。", "sentence_source": "generated"}, {"text": "ダンスが好きで、毎週土曜日に教室へ行きます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスが好[す]きで、毎週[まいしゅう]土曜日[どようび]に教室[きょうしつ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "運動会で、みんなでダンスを踊りました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]で、みんなでダンスを踊[おど]りました。", "sentence_source": "generated"}, {"text": "妹はダンスがじょうずで、いつも拍手をもらいます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "妹[いもうと]はダンスがじょうずで、いつも拍手[はくしゅ]をもらいます。", "sentence_source": "generated"}, {"text": "パーティーで、ダンスをする人が多かったです。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "パーティーで、ダンスをする人[ひと]が多[おお]かったです。", "sentence_source": "generated"}, {"text": "ダンスの先生は、いつも笑顔で教えてくれます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスの先生[せんせい]は、いつも笑顔[えがお]で教[おし]えてくれます。", "sentence_source": "generated"}, {"text": "子どもたちは歌を聞いて、自由にダンスを始めました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "子[こ]どもたちは歌[うた]を聞[き]いて、自由[じゆう]にダンスを始[はじ]めました。", "sentence_source": "generated"}, {"text": "発表会のダンスのために、毎日れんしゅうしています。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]のダンスのために、毎日[まいにち]れんしゅうしています。", "sentence_source": "generated"}, {"text": "ダンスをしたら、体があたたかくなりました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスをしたら、体[からだ]があたたかくなりました。", "sentence_source": "generated"}, {"text": "あの人のダンスを見ると、元気が出ます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "あの人[ひと]のダンスを見[み]ると、元気[げんき]が出[で]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "音楽に合わせて体を動かして楽しむこと(ダンスを踊る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダンス", "is_correct": true, "explanation": "音楽に合わせて楽しく体を動かす意味で、「楽しくしました」に合う。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器の名前で、「する」と続けると不自然。文の意味にも合わない。"}, {"text": "ドラム", "is_correct": false, "explanation": "楽器の名前で、「楽しく〜をしました」の動作として合わない。"}, {"text": "バイオリン", "is_correct": false, "explanation": "楽器の名前で、「をしました」の目的語として不自然。"}], "explanations": {"ダンス": "音楽に合わせて楽しく体を動かす意味で、「楽しくしました」に合う。", "ピアノ": "楽器の名前で、「する」と続けると不自然。文の意味にも合わない。", "ドラム": "楽器の名前で、「楽しく〜をしました」の動作として合わない。", "バイオリン": "楽器の名前で、「をしました」の目的語として不自然。"}, "sentence_index": 0, "correct_answer": "ダンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この階段のダンスは高くて、つまずきやすいです。", "explanation": "ここは〈段〉の意味で、近い語は〈ステップ〉。ダンスは踊りを指すので、階段の段差には合わない。"}, {"text": "手品師が、ダンスで帽子からハトを出しました。", "explanation": "ここは〈手品の道具〉の意味（別の語）。ダンスは踊りを指す語なので、手品の道具には使わない。"}, {"text": "新しく発売されたそうじ機の名前は、ダンスです。", "explanation": "ここは〈製品の名前〉の意味（別の語義）。ダンスは踊りを指すので、製品名の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダンス", "is_correct": true, "explanation": "「自由に〜を始めました」の目的語として、踊りを始めた意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「始める」の目的語になりにくく、文の意味にも合わない。"}, {"text": "ステージ", "is_correct": false, "explanation": "舞台を指す名詞で、「始める」の対象として文の意味に合わない。"}, {"text": "カーテン", "is_correct": false, "explanation": "布の名前で、「自由に始める」の対象にならない。"}], "explanations": {"ダンス": "「自由に〜を始めました」の目的語として、踊りを始めた意味に合う。", "天気": "「始める」の目的語になりにくく、文の意味にも合わない。", "ステージ": "舞台を指す名詞で、「始める」の対象として文の意味に合わない。", "カーテン": "布の名前で、「自由に始める」の対象にならない。"}, "sentence_index": 6, "correct_answer": "ダンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの人のダンスは、毎朝の天気を知らせる合図です。", "explanation": "ここは〈合図〉の意味で、〈ダンス〉は音楽に合わせて楽しく体を動かすことを指すので合わない。"}, {"text": "あの人のダンスは、重い荷物を運ぶ道具です。", "explanation": "ここは〈道具〉の意味で、〈ダンス〉は体を動かす踊りのことなので合わない。"}, {"text": "あの人のダンスは、雨の量を表す単位です。", "explanation": "ここは〈単位〉の意味。ダンスは体を動かして踊ることを指すので、数量の単位には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日の体育館で、みんなで音楽に合わせてダンスがしました。", "corrected_sentence": "雨の日の体育館で、みんなで音楽に合わせてダンスをしました。", "error_description": "「ダンスをする」の目的語は「を」が正しく、「が」を使うと文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園で、子どもたちが音楽に合わせてダンスを楽しんでしました。", "corrected_sentence": "公園で、子どもたちが音楽に合わせてダンスを楽しみました。", "error_description": "「楽しみました」が正しく、「楽しんでしました」は活用の形が不自然で文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ダンスは」の「は」で、話題を示す係助詞。ダンスについて述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「ダンスを難しい」とは続かず、目的語の格は文の述語と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ダンスにむずかしい」は不自然で、位置や相手を示す格は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、ダンスについて述べる文の主題に合わない。"}], "correct_answer": "は", "explanations": {"は": "「ダンスは」の「は」で、話題を示す係助詞。ダンスについて述べる文になる。", "を": "「ダンスを難しい」とは続かず、目的語の格は文の述語と合わない。", "に": "「ダンスにむずかしい」は不自然で、位置や相手を示す格は合わない。", "へ": "方向を示す「へ」は、ダンスについて述べる文の主題に合わない。"}, "error_tags": {"を": "目的語の格", "に": "位置・相手の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ダンスのステップ」の「の」で、名詞を続ける連体修飾の助詞。"}, {"text": "に", "is_correct": false, "explanation": "「ダンスに」は速くなる対象として文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、「ダンスから」と続けると文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は、「ダンスより」と続けると文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ダンスのステップ」の「の」で、名詞を続ける連体修飾の助詞。", "に": "「ダンスに」は速くなる対象として文が成り立たない。", "から": "起点を示す「から」は、「ダンスから」と続けると文が成り立たない。", "より": "比較を示す「より」は、「ダンスより」と続けると文の意味が通らない。"}, "error_tags": {"から": "起点の格", "より": "比較の格", "に": "位置・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "音楽に合わせて、体でリズムを取りながら、一定のステップや動きを続けること。", "primary_collocate": null, "pronunciation": "だんす", "ipa": "dansɯ", "syllable_count": 3, "sentences": [{"text": "ダンスは、同じステップを何回もくり返して覚えます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスは、同[おな]じステップを何回[なんかい]もくり返[かえ]して覚[おぼ]えます。", "sentence_source": "generated"}, {"text": "この曲のダンスは、ステップがむずかしいです。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "この曲[きょく]のダンスは、ステップがむずかしいです。", "sentence_source": "generated"}, {"text": "テレビを見ながら、ダンスの動きをまねしました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "テレビを見[み]ながら、ダンスの動[うご]きをまねしました。", "sentence_source": "generated"}, {"text": "ダンスの練習では、リズムを数えながら足を動かします。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスの練習[れんしゅう]では、リズムを数[かぞ]えながら足[あし]を動[うご]かします。", "sentence_source": "generated"}, {"text": "彼女は一時間ずっとダンスを続けても、疲れません。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一時間[いちじかん]ずっとダンスを続[つづ]けても、疲[つか]れません。", "sentence_source": "generated"}, {"text": "ダンスを習うと、リズム感が身につきます。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスを習[なら]うと、リズム感[かん]が身[み]につきます。", "sentence_source": "generated"}, {"text": "みんなのダンスがそろうと、とてもきれいです。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "みんなのダンスがそろうと、とてもきれいです。", "sentence_source": "generated"}, {"text": "音楽が速くなって、ダンスのステップも速くなりました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "音楽[おんがく]が速[はや]くなって、ダンスのステップも速[はや]くなりました。", "sentence_source": "generated"}, {"text": "ダンスの動画を見て、ステップを覚えました。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "ダンスの動画[どうが]を見[み]て、ステップを覚[おぼ]えました。", "sentence_source": "generated"}, {"text": "兄は大会に出るために、毎晩ダンスを練習しています。", "target_word": "ダンス", "complexity_tier": "T3", "furigana": "兄[あに]は大会[たいかい]に出[で]るために、毎晩[まいばん]ダンスを練習[れんしゅう]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "リズムとステップなど決まった動きを続ける踊り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダンス", "is_correct": true, "explanation": "決まったステップを繰り返して覚える踊りの意味で、文に合う。"}, {"text": "パズル", "is_correct": false, "explanation": "ピースをはめる遊びで、ステップを覚える文脈と合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵を描く芸術で、ステップを繰り返して覚える文脈と合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を届ける仕事で、ステップを覚える文脈と合わない。"}], "explanations": {"ダンス": "決まったステップを繰り返して覚える踊りの意味で、文に合う。", "パズル": "ピースをはめる遊びで、ステップを覚える文脈と合わない。", "絵画": "絵を描く芸術で、ステップを繰り返して覚える文脈と合わない。", "郵便": "手紙や荷物を届ける仕事で、ステップを覚える文脈と合わない。"}, "sentence_index": 0, "correct_answer": "ダンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダンスは、ステージで一番大きな声で歌う人のことです。", "explanation": "ここは〈人〉の意味で、近い語は〈ダンサー〉。ダンスは踊りそのものを指すので、人を表す使い方は合わない。"}, {"text": "ダンスは、料理のレシピを読むときの手順を指します。", "explanation": "ここは〈料理の手順〉の意味で、近い語は〈手順〉。ダンスは音楽に合わせて動く踊りのステップを指し、レシピの手順には使わない。"}, {"text": "ダンスは、窓ガラスをみがく道具のことです。", "explanation": "ここは〈道具〉の意味（別の語）。ダンスは踊りや動きを指すので、窓ガラスをみがく道具には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダンス", "is_correct": true, "explanation": "踊りが揃うという文脈で、そろうときれいという意味に合う。"}, {"text": "雨", "is_correct": false, "explanation": "降る雨で、動きがそろうという文脈と合わない。"}, {"text": "寝ぐせ", "is_correct": false, "explanation": "髪の乱れで、動きがそろうという文脈と合わない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる袋で、動きがそろうという文脈と合わない。"}], "explanations": {"ダンス": "踊りが揃うという文脈で、そろうときれいという意味に合う。", "雨": "降る雨で、動きがそろうという文脈と合わない。", "寝ぐせ": "髪の乱れで、動きがそろうという文脈と合わない。", "財布": "お金を入れる袋で、動きがそろうという文脈と合わない。"}, "sentence_index": 6, "correct_answer": "ダンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は大会に出るために、毎晩ダンスを買っています。", "explanation": "ここは〈買う〉の意味で、〈ダンス〉は買うものではなく練習して覚える踊りなので合わない。"}, {"text": "兄は大会に出るために、毎晩ダンスの重さを量っています。", "explanation": "ここは〈重さを量る〉の意味。ダンスは重さを量るものではなく、練習して覚える踊りを指すので合わない。"}, {"text": "兄は大会に出るために、毎晩ダンスの窓を開けています。", "explanation": "ここは〈窓を開ける〉の意味（別の語）。ダンスは窓ではなく、練習する踊りを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、ダンスに練習しています。", "corrected_sentence": "毎朝、ダンスを練習しています。", "error_description": "「練習する」の目的語は「を」で示すので、「に」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このダンスは、ステップを一つずつ覚えてから練習するします。", "corrected_sentence": "このダンスは、ステップを一つずつ覚えてから練習します。", "error_description": "「練習します」が正しく、「練習するします」は動詞の活用が重複して成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
