INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが小さく速く動いて、ゆれていること。", "primary_collocate": null, "pronunciation": "しんどう", "ipa": "ɕindoː", "syllable_count": 4, "sentences": [{"text": "電車が通ると、窓ガラスが細かく振動する。", "target_word": "振動", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が通[とお]ると、窓[まど]ガラスが細[こま]かく振動[しんどう]する。", "sentence_source": "generated"}, {"text": "スマホが机の上で振動して、メールが届いたと分かった。", "target_word": "振動", "complexity_tier": "T3", "furigana": "スマホが机[つくえ]の上[うえ]で振動[しんどう]して、メールが届[とど]いたと分[わ]かった。", "sentence_source": "generated"}, {"text": "洗濯機の振動が大きいので、床にゴムのマットを敷いた。", "target_word": "振動", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]の振動[しんどう]が大[おお]きいので、床[ゆか]にゴムのマットを敷[し]いた。", "sentence_source": "generated"}, {"text": "地面の振動を感じて、近くで工事をしているのだと気づいた。", "target_word": "振動", "complexity_tier": "T3", "furigana": "地面[じめん]の振動[しんどう]を感[かん]じて、近[ちか]くで工事[こうじ]をしているのだと気[き]づいた。", "sentence_source": "generated"}, {"text": "ギターの弦を弾くと、弦が速く振動して音が出る。", "target_word": "振動", "complexity_tier": "T3", "furigana": "ギターの弦[げん]を弾[はじ]くと、弦[げん]が速[はや]く振動[しんどう]して音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "エンジンの振動が体に伝わってきて、眠れなかった。", "target_word": "振動", "complexity_tier": "T3", "furigana": "エンジンの振動[しんどう]が体[からだ]に伝[つた]わってきて、眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "振動が強すぎたので、機械のスイッチを切った。", "target_word": "振動", "complexity_tier": "T3", "furigana": "振動[しんどう]が強[つよ]すぎたので、機械[きかい]のスイッチを切[き]った。", "sentence_source": "generated"}, {"text": "大型トラックが走るたびに、家が小さく振動する。", "target_word": "振動", "complexity_tier": "T3", "furigana": "大型[おおがた]トラックが走[はし]るたびに、家[いえ]が小[ちい]さく振動[しんどう]する。", "sentence_source": "generated"}, {"text": "この時計は、振動で時間を知らせてくれる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "この時計[とけい]は、振動[しんどう]で時間[じかん]を知[し]らせてくれる。", "sentence_source": "generated"}, {"text": "橋が風で振動しないように、丈夫な材料を使っている。", "target_word": "振動", "complexity_tier": "T3", "furigana": "橋[はし]が風[かぜ]で振動[しんどう]しないように、丈夫[じょうぶ]な材料[ざいりょう]を使[つか]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "振動", "label": "辞書形"}, {"form": "振動する", "label": "する動詞形"}, {"form": "振動した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "ものが小さく速くゆれ動く物理的な動き(機械・スマホ・地面など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39610, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "振動", "is_correct": true, "explanation": "細かく速く揺れ動くという意味で、電車が通ったときの窓ガラスの様子に合う。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が冷えて固まる変化を指すので、窓ガラスが細かく揺れる様子とは合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "液体の中の固体が底にたまる現象で、窓ガラスの揺れとは関係がない。"}, {"text": "融解", "is_correct": false, "explanation": "固体が熱でとける変化で、細かく揺れる様子を表さない。"}], "explanations": {"振動": "細かく速く揺れ動くという意味で、電車が通ったときの窓ガラスの様子に合う。", "凝固": "液体が冷えて固まる変化を指すので、窓ガラスが細かく揺れる様子とは合わない。", "沈殿": "液体の中の固体が底にたまる現象で、窓ガラスの揺れとは関係がない。", "融解": "固体が熱でとける変化で、細かく揺れる様子を表さない。"}, "sentence_index": 0, "correct_answer": "振動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の株価は大きく振動して、午後には大幅に下がった。", "explanation": "ここは〈変動〉の意味。株価の上がり下がりは「変動」で表し、「振動」は物が細かく揺れることなので合わない。"}, {"text": "事故の振動で運転手はしばらく動けなかった。", "explanation": "ここは〈衝撃〉の意味。一度の強い打撃は「衝撃」で、細かく続く揺れの「振動」とは合わない。"}, {"text": "信号機の赤いランプが振動して、みんな立ち止まった。", "explanation": "ここは〈点滅〉の意味。光がついたり消えたりする様子は「点滅」で、物体が揺れる「振動」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39610, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "振動", "is_correct": true, "explanation": "揺れる意味の語で、強すぎたという状態を表し、機械のスイッチを切る理由になる。"}, {"text": "結晶化", "is_correct": false, "explanation": "溶けた物質が規則正しく固まる変化で、機械の状態を表す文脈には合わない。"}, {"text": "凝縮", "is_correct": false, "explanation": "気体が液体に変わる変化を指し、強すぎたという状況に合わない。"}, {"text": "昇華", "is_correct": false, "explanation": "固体が直接気体になる変化で、スイッチを切る理由にならない。"}], "explanations": {"振動": "揺れる意味の語で、強すぎたという状態を表し、機械のスイッチを切る理由になる。", "結晶化": "溶けた物質が規則正しく固まる変化で、機械の状態を表す文脈には合わない。", "凝縮": "気体が液体に変わる変化を指し、強すぎたという状況に合わない。", "昇華": "固体が直接気体になる変化で、スイッチを切る理由にならない。"}, "sentence_index": 6, "correct_answer": "振動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方になると、町の振動が弱まり、通りに人影がなくなった。", "explanation": "ここは〈活気〉の意味。町のにぎやかな様子は「活気」で、物の細かい揺れを表す「振動」とは合わない。"}, {"text": "床と靴の振動で、滑りにくくなる。", "explanation": "ここは〈摩擦〉の意味。接触面がこすれ合う力は「摩擦」で、細かい揺れの「振動」とは合わない。"}, {"text": "ライターを振動させて、ろうそくに火をつけた。", "explanation": "ここは〈点火〉の意味。火をつけることは「点火」で、揺れの「振動」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39610, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大型機械が動くと、床に振動を伝わる。", "corrected_sentence": "大型機械が動くと、床に振動が伝わる。", "error_description": "「伝わる」は自動詞なので、主語の「振動」には「が」を使う。「振動を伝わる」は誤りで、正しくは「振動が伝わる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39610, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スイッチを入れると、機械が強く振動させる。", "corrected_sentence": "スイッチを入れると、機械が強く振動する。", "error_description": "「振動する」は主語だけで成り立つ自動詞。「振動させる」は他動詞で目的語が必要なので、主語の「機械が」に続けるのは誤り。正しくは「振動する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
