INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体が細かく速く揺れ動くこと。また、その動き。", "primary_collocate": null, "pronunciation": "しんどう", "ipa": "ɕindoː", "syllable_count": 4, "sentences": [{"text": "太鼓をたたくと、皮が振動して大きな音が出る。", "target_word": "振動", "complexity_tier": "T3", "furigana": "太鼓[たいこ]をたたくと、皮[かわ]が振動[しんどう]して大[おお]きな音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "地震計は、地面の小さな振動も記録できる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "地震計[じしんけい]は、地面[じめん]の小[ちい]さな振動[しんどう]も記録[きろく]できる。", "sentence_source": "generated"}, {"text": "車の振動がひどくて、本を読むと気分が悪くなる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "車[くるま]の振動[しんどう]がひどくて、本[ほん]を読[よ]むと気分[きぶん]が悪[わる]くなる。", "sentence_source": "generated"}, {"text": "音は空気が振動して耳に届くものだ。", "target_word": "振動", "complexity_tier": "T3", "furigana": "音[おと]は空気[くうき]が振動[しんどう]して耳[みみ]に届[とど]くものだ。", "sentence_source": "generated"}, {"text": "振動を止めるために、機械の下にクッションを置いた。", "target_word": "振動", "complexity_tier": "T3", "furigana": "振動[しんどう]を止[と]めるために、機械[きかい]の下[した]にクッションを置[お]いた。", "sentence_source": "generated"}, {"text": "携帯電話をマナーモードにすると、着信は振動で知らせる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]をマナーモードにすると、着信[ちゃくしん]は振動[しんどう]で知[し]らせる。", "sentence_source": "generated"}, {"text": "葉が落ちたせいで、水面が小さく振動した。", "target_word": "振動", "complexity_tier": "T3", "furigana": "葉[は]が落[お]ちたせいで、水面[すいめん]が小[ちい]さく振動[しんどう]した。", "sentence_source": "generated"}, {"text": "飛行機が離陸するとき、座席が激しく振動した。", "target_word": "振動", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が離陸[りりく]するとき、座席[ざせき]が激[はげ]しく振動[しんどう]した。", "sentence_source": "generated"}, {"text": "振動する音叉を水につけると、水が跳ね上がる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "振動[しんどう]する音叉[おんさ]を水[みず]につけると、水[みず]が跳[は]ね上[あ]がる。", "sentence_source": "generated"}, {"text": "工場の機械の振動が壁に響いて、隣の部屋まで伝わる。", "target_word": "振動", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]の振動[しんどう]が壁[かべ]に響[ひび]いて、隣[となり]の部屋[へや]まで伝[つた]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "振動", "label": "辞書形"}, {"form": "振動する", "label": "する動詞形"}, {"form": "振動した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "物体が細かく速く揺れ動くこと、またその動き(音・地震計・乗り物など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "振動", "is_correct": true, "explanation": "細かく揺れ動く意味で、太鼓の皮が揺れて音が出る場面に合う。"}, {"text": "腐敗", "is_correct": false, "explanation": "有機物が菌によって変質する現象で、太鼓の皮の揺れには合わない。"}, {"text": "凝結", "is_correct": false, "explanation": "水蒸気が水滴に変わる変化で、皮が音を出す場面とは合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "溶けた物質や粒子が底にたまる現象で、音が出る場面には合わない。"}], "explanations": {"振動": "細かく揺れ動く意味で、太鼓の皮が揺れて音が出る場面に合う。", "腐敗": "有機物が菌によって変質する現象で、太鼓の皮の揺れには合わない。", "凝結": "水蒸気が水滴に変わる変化で、皮が音を出す場面とは合わない。", "沈殿": "溶けた物質や粒子が底にたまる現象で、音が出る場面には合わない。"}, "sentence_index": 0, "correct_answer": "振動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "扇風機の羽が振動して、部屋中に風を送る。", "explanation": "ここは〈回転〉の意味。羽が軸を中心に回ることは「回転」で、細かく揺れる「振動」とは合わない。"}, {"text": "車が電柱に振動して、ボンネットがへこんだ。", "explanation": "ここは〈衝突〉の意味。ぶつかることは「衝突」で、続けて細かく揺れる「振動」とは合わない。"}, {"text": "引っ越しの荷物を振動させて、トラックまで運んだ。", "explanation": "ここは〈移動〉の意味。物を別の場所へ動かすことは「移動」で、揺れる「振動」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "振動", "is_correct": true, "explanation": "小さく揺れ動く意味で、葉が落ちて水面が揺れる場面に合う。"}, {"text": "凝縮", "is_correct": false, "explanation": "気体が液体に変わる変化を指し、水面が揺れる様子とは合わない。"}, {"text": "結晶化", "is_correct": false, "explanation": "溶けた物質が結晶になる変化で、葉が落ちる場面とは合わない。"}, {"text": "腐食", "is_correct": false, "explanation": "金属などが侵されて傷む変化で、水面の揺れを表さない。"}], "explanations": {"振動": "小さく揺れ動く意味で、葉が落ちて水面が揺れる場面に合う。", "凝縮": "気体が液体に変わる変化を指し、水面が揺れる様子とは合わない。", "結晶化": "溶けた物質が結晶になる変化で、葉が落ちる場面とは合わない。", "腐食": "金属などが侵されて傷む変化で、水面の揺れを表さない。"}, "sentence_index": 6, "correct_answer": "振動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒さで池の水が振動して、表面が固まった。", "explanation": "ここは〈凍結〉の意味。水が冷えて氷になることは「凍結」で、細かく揺れる「振動」とは合わない。"}, {"text": "パンを毎日振動させて、一か月もおいしいまま持たせた。", "explanation": "ここは〈保存〉の意味。食べ物を長く持たせることは「保存」で、物が細かく揺れる「振動」とは合わない。"}, {"text": "雨にさらされた鉄の柵が振動して、ぼろぼろになった。", "explanation": "ここは〈腐食〉の意味。金属がさびて傷むことは「腐食」で、揺れの「振動」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ラジオの音量を上げると、スピーカーの振動を強くなる。", "corrected_sentence": "ラジオの音量を上げると、スピーカーの振動が強くなる。", "error_description": "「強くなる」は状態が変わることを表し、主語の「振動」には「が」を使う。「振動を強くなる」は誤りで、正しくは「振動が強くなる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風が吹くと、水面が小さく振動させる。", "corrected_sentence": "風が吹くと、水面が小さく振動する。", "error_description": "「振動する」は主語だけで成り立つ自動詞。「振動させる」は他動詞で目的語が必要なので、主語の「水面が」に続けるのは誤り。正しくは「振動する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「様子が気になる」の「が」。「気になる」は「が」を取るので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「気になる」は「を」を取らない。「様子を気になって」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「様子に気になって」は不自然。「気になる」の前に「に」の受け手がない。"}, {"text": "で", "is_correct": false, "explanation": "「様子で気になって」は成り立たない。「で」は場所や手段を表すので、ここでは合わない。"}], "correct_answer": "が", "explanations": {"が": "「様子が気になる」の「が」。「気になる」は「が」を取るので正しい。", "を": "「気になる」は「を」を取らない。「様子を気になって」は文法的に成り立たない。", "に": "「様子に気になって」は不自然。「気になる」の前に「に」の受け手がない。", "で": "「様子で気になって」は成り立たない。「で」は場所や手段を表すので、ここでは合わない。"}, "error_tags": {"を": "object: 気になる takes が", "に": "dative: no receiver here", "で": "means/location: no fit"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「火事の様子が」の「が」。「様子」が主語になり、「生中継されていた」につながる。"}, {"text": "の", "is_correct": false, "explanation": "「火事の様子の、テレビで」は続かない。「の」は後ろに名詞を必要とする。"}, {"text": "へ", "is_correct": false, "explanation": "「様子へ」は方向を表すが、「生中継されていた」に方向の意味は不要で合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる対象を要求するが、この文には比較がなく合わない。"}], "correct_answer": "が", "explanations": {"が": "「火事の様子が」の「が」。「様子」が主語になり、「生中継されていた」につながる。", "の": "「火事の様子の、テレビで」は続かない。「の」は後ろに名詞を必要とする。", "へ": "「様子へ」は方向を表すが、「生中継されていた」に方向の意味は不要で合わない。", "より": "「より」は比べる対象を要求するが、この文には比較がなく合わない。"}, "error_tags": {"の": "possessive: no noun after", "へ": "direction: no movement", "より": "comparison: none in sentence"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがどうなっているか、そのようす。", "primary_collocate": null, "pronunciation": "ようす", "ipa": "joːsɯ", "syllable_count": 3, "sentences": [{"text": "窓から外の様子を見ると、雪がふっていた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "窓[まど]から外[そと]の様子[ようす]を見[み]ると、雪[ゆき]がふっていた。", "sentence_source": "generated"}, {"text": "病気の祖母の様子が気になって、電話をかけた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "病気[びょうき]の祖母[そぼ]の様子[ようす]が気[き]になって、電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "先生は、生徒たちの様子を見ながら話した。", "target_word": "様子", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]たちの様子[ようす]を見[み]ながら話[はな]した。", "sentence_source": "generated"}, {"text": "事故のあと、町の様子はすっかり変わった。", "target_word": "様子", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、町[まち]の様子[ようす]はすっかり変[か]わった。", "sentence_source": "generated"}, {"text": "赤ちゃんが眠っている様子は、とてもかわいい。", "target_word": "様子", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが眠[ねむ]っている様子[ようす]は、とてもかわいい。", "sentence_source": "generated"}, {"text": "友だちの様子がおかしいので、声をかけた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "友[とも]だちの様子[ようす]がおかしいので、声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "店の中の様子がわからず、入口で少し待った。", "target_word": "様子", "complexity_tier": "T3", "furigana": "店[みせ]の中[なか]の様子[ようす]がわからず、入口[いりぐち]で少[すこ]し待[ま]った。", "sentence_source": "generated"}, {"text": "火事の様子が、テレビで生中継されていた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "火事[かじ]の様子[ようす]が、テレビで生中継[なまちゅうけい]されていた。", "sentence_source": "generated"}, {"text": "知らせを受けて、現場の様子を確かめに行った。", "target_word": "様子", "complexity_tier": "T3", "furigana": "知[し]らせを受[う]けて、現場[げんば]の様子[ようす]を確[たし]かめに行[い]った。", "sentence_source": "generated"}, {"text": "工事の様子を、毎日写真に残している。", "target_word": "様子", "complexity_tier": "T3", "furigana": "工事[こうじ]の様子[ようす]を、毎日[まいにち]写真[しゃしん]に残[のこ]している。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "人や場所がいまどうなっているかという状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "様子", "is_correct": true, "explanation": "「窓から外の様子を見る」は、外の状況を見るという意味で自然に通る。"}, {"text": "鍵", "is_correct": false, "explanation": "「外の鍵を見る」は意味が通らない。鍵は見る対象として文脈に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "「外の手紙を見ると」は文脈に合わない。窓から外を見る対象として手紙は不自然。"}, {"text": "教科書", "is_correct": false, "explanation": "「外の教科書を見る」は成り立たない。窓から外を見る文脈に教科書は入らない。"}], "explanations": {"様子": "「窓から外の様子を見る」は、外の状況を見るという意味で自然に通る。", "鍵": "「外の鍵を見る」は意味が通らない。鍵は見る対象として文脈に合わない。", "手紙": "「外の手紙を見ると」は文脈に合わない。窓から外を見る対象として手紙は不自然。", "教科書": "「外の教科書を見る」は成り立たない。窓から外を見る文脈に教科書は入らない。"}, "sentence_index": 0, "correct_answer": "様子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツの様子は、Mサイズだ。", "explanation": "ここは〈サイズ〉の意味。様子は状態を表すので、服の寸法の表示には使わない。"}, {"text": "このスープの様子は、二十分で作れる。", "explanation": "ここは〈調理時間〉の意味。様子は状態を表し、所要時間は表さないので合わない。"}, {"text": "このかばんの様子は、三万円だ。", "explanation": "ここは〈値段〉の意味。様子は状態を表すので、金額を表すのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "様子", "is_correct": true, "explanation": "「店の中の様子がわからず」は、店内の状態が見えないという意味で自然に通る。"}, {"text": "切手", "is_correct": false, "explanation": "「店の中の切手がわからず」は意味が通らない。切手は状態の対象にならない。"}, {"text": "財布", "is_correct": false, "explanation": "「店の中の財布がわからず」は不自然。店内の様子を表す文脈に財布は合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "「店の中の歌詞がわからず」は成り立たない。店の中の状況を表す語ではない。"}], "explanations": {"様子": "「店の中の様子がわからず」は、店内の状態が見えないという意味で自然に通る。", "切手": "「店の中の切手がわからず」は意味が通らない。切手は状態の対象にならない。", "財布": "「店の中の財布がわからず」は不自然。店内の様子を表す文脈に財布は合わない。", "歌詞": "「店の中の歌詞がわからず」は成り立たない。店の中の状況を表す語ではない。"}, "sentence_index": 6, "correct_answer": "様子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父の様子は、もう六十歳になった。", "explanation": "ここは〈年齢〉の意味。様子は状態を表し、年数は表さないので合わない。"}, {"text": "この子の様子は、先月から三キロ増えた。", "explanation": "ここは〈体重〉の意味。様子は状態を表し、重さの増減には使わない。"}, {"text": "テレビの様子を、少し大きくした。", "explanation": "ここは〈音量〉の意味。様子は状態で、音の大きさを調節する対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の様子を心配で、電話をかけた。", "corrected_sentence": "彼の様子が心配で、電話をかけた。", "error_description": "「心配だ」は「が」を取る。様子に続く助詞が「を」になっているのは誤りで、正しくは「様子が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の街の様子を見に、家に電話した。", "corrected_sentence": "夜の街の様子を見て、家に電話した。", "error_description": "「見る」は後ろに続く「家に電話した」とつなぐために「て形」が必要。「見に」は「〜に行く」の用法で、ここでは文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「うれしそうな様子で」の「で」。〜の様子で、と状態を表して「読んだ」に続く。"}, {"text": "を", "is_correct": false, "explanation": "「うれしそうな様子を、手紙を読んだ」は不自然。「様子を」は目的語として文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「様子に、手紙を読んだ」は成り立たない。「に」は受け手や到着点で、ここでは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「様子の、手紙を読んだ」は続かない。「の」の後には名詞が必要。"}], "correct_answer": "で", "explanations": {"で": "「うれしそうな様子で」の「で」。〜の様子で、と状態を表して「読んだ」に続く。", "を": "「うれしそうな様子を、手紙を読んだ」は不自然。「様子を」は目的語として文が成り立たない。", "に": "「様子に、手紙を読んだ」は成り立たない。「に」は受け手や到着点で、ここでは合わない。", "の": "「様子の、手紙を読んだ」は続かない。「の」の後には名詞が必要。"}, "error_tags": {"を": "object: no verb fits", "に": "dative: no receiver", "の": "possessive: no noun after"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「彼の様子では」の「で」。様子から判断するという意味で、後ろの予想につながる。"}, {"text": "へ", "is_correct": false, "explanation": "「彼の様子へ、明日も来そうだ」は成り立たない。方向を表す語は合わない。"}, {"text": "より", "is_correct": false, "explanation": "「彼の様子より」は比べる対象を要求するが、この文に比較はなく不自然。"}, {"text": "を", "is_correct": false, "explanation": "「彼の様子を、明日も来そうだ」は目的語として文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「彼の様子では」の「で」。様子から判断するという意味で、後ろの予想につながる。", "へ": "「彼の様子へ、明日も来そうだ」は成り立たない。方向を表す語は合わない。", "より": "「彼の様子より」は比べる対象を要求するが、この文に比較はなく不自然。", "を": "「彼の様子を、明日も来そうだ」は目的語として文が成り立たない。"}, "error_tags": {"へ": "direction: no movement", "より": "comparison: none in sentence", "を": "object: no verb fits"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の態度や、ふるまいのありさま。", "primary_collocate": null, "pronunciation": "ようす", "ipa": "joːsɯ", "syllable_count": 3, "sentences": [{"text": "彼は困った様子で、かばんの中を探していた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "彼[かれ]は困[こま]った様子[ようす]で、かばんの中[なか]を探[さが]していた。", "sentence_source": "generated"}, {"text": "少年はうれしそうな様子で、手紙を読んだ。", "target_word": "様子", "complexity_tier": "T3", "furigana": "少年[しょうねん]はうれしそうな様子[ようす]で、手紙[てがみ]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "彼女は何も知らない様子で、笑っていた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なに]も知[し]らない様子[ようす]で、笑[わら]っていた。", "sentence_source": "generated"}, {"text": "犬は警戒した様子で、ゆっくり近づいた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "犬[いぬ]は警戒[けいかい]した様子[ようす]で、ゆっくり近[ちか]づいた。", "sentence_source": "generated"}, {"text": "彼は負けても悔しがる様子はなく、さっぱりしていた。", "target_word": "様子", "complexity_tier": "T3", "furigana": "彼[かれ]は負[ま]けても悔[くや]しがる様子[ようす]はなく、さっぱりしていた。", "sentence_source": "generated"}, {"text": "客は急いでいる様子で、店を出ていった。", "target_word": "様子", "complexity_tier": "T3", "furigana": "客[きゃく]は急[いそ]いでいる様子[ようす]で、店[みせ]を出[で]ていった。", "sentence_source": "generated"}, {"text": "彼は私の話を聞いても、驚いた様子を見せなかった。", "target_word": "様子", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の話[はなし]を聞[き]いても、驚[おどろ]いた様子[ようす]を見[み]せなかった。", "sentence_source": "generated"}, {"text": "彼の様子では、明日も来そうだ。", "target_word": "様子", "complexity_tier": "T3", "furigana": "彼[かれ]の様子[ようす]では、明日[あした]も来[く]そうだ。", "sentence_source": "generated"}, {"text": "妹は叱られても泣く様子を見せず、平気な顔をした。", "target_word": "様子", "complexity_tier": "T3", "furigana": "妹[いもうと]は叱[しか]られても泣[な]く様子[ようす]を見[み]せず、平気[へいき]な顔[かお]をした。", "sentence_source": "generated"}, {"text": "母は心配する様子もなく、静かにお茶を飲んだ。", "target_word": "様子", "complexity_tier": "T3", "furigana": "母[はは]は心配[しんぱい]する様子[ようす]もなく、静[しず]かにお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "人の態度や振る舞いとして外から見えるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ed5f6e-9d04-40a4-a25c-2e0d32e54d62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "様子", "is_correct": true, "explanation": "「困った様子で」は、困っている態度や外から見えるありさまとして自然に通る。"}, {"text": "切手", "is_correct": false, "explanation": "「困った切手で」は意味が通らない。切手は態度を表す語ではない。"}, {"text": "財布", "is_correct": false, "explanation": "「困った財布で」は成り立たない。財布は人の態度を表す語ではない。"}, {"text": "歌詞", "is_correct": false, "explanation": "「困った歌詞で」は不自然。歌詞は態度や様子を表さない。"}], "explanations": {"様子": "「困った様子で」は、困っている態度や外から見えるありさまとして自然に通る。", "切手": "「困った切手で」は意味が通らない。切手は態度を表す語ではない。", "財布": "「困った財布で」は成り立たない。財布は人の態度を表す語ではない。", "歌詞": "「困った歌詞で」は不自然。歌詞は態度や様子を表さない。"}, "sentence_index": 0, "correct_answer": "様子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の様子は、去年より十センチ高くなった。", "explanation": "ここは〈身長〉の意味。様子は態度や状態を指し、背丈の変化は表さないので合わない。"}, {"text": "この映画の様子は、二時間かかる。", "explanation": "ここは〈時間〉の意味。様子は状態を表し、長さとしての時間は表さないので合わない。"}, {"text": "この箱の様子は、五キロもある。", "explanation": "ここは〈重さ〉の意味。様子は状態を表し、重さの数値は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "様子", "is_correct": true, "explanation": "「驚いた様子を見せなかった」は、驚きの態度を表さなかったという意味で自然に通る。"}, {"text": "地図", "is_correct": false, "explanation": "「驚いた地図を見せなかった」は成り立たない。地図は態度を表す語ではない。"}, {"text": "切符", "is_correct": false, "explanation": "「驚いた切符を見せなかった」は不自然。切符は驚きの態度を表さない。"}, {"text": "辞書", "is_correct": false, "explanation": "「驚いた辞書を見せなかった」は意味が通らない。辞書は態度の対象ではない。"}], "explanations": {"様子": "「驚いた様子を見せなかった」は、驚きの態度を表さなかったという意味で自然に通る。", "地図": "「驚いた地図を見せなかった」は成り立たない。地図は態度を表す語ではない。", "切符": "「驚いた切符を見せなかった」は不自然。切符は驚きの態度を表さない。", "辞書": "「驚いた辞書を見せなかった」は意味が通らない。辞書は態度の対象ではない。"}, "sentence_index": 6, "correct_answer": "様子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお茶の様子は、ペットボトルで十本入りだ。", "explanation": "ここは〈入り数〉の意味。様子は状態を表し、本数や容量は表さないので合わない。"}, {"text": "駅までの様子は、三キロある。", "explanation": "ここは〈距離〉の意味。様子は状態を表すので、長さの数値には使わない。"}, {"text": "このパンの様子は、一斤百円だ。", "explanation": "ここは〈値段〉の意味。様子は状態を表し、売り値は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は焦った様子を、電話を切った。", "corrected_sentence": "彼女は焦った様子で、電話を切った。", "error_description": "「焦った様子で」の「で」は状態を表す。「様子を」にすると目的語になるが、後ろの「電話を切った」と続かず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人の様子を見る、声をかけた。", "corrected_sentence": "友人の様子を見て、声をかけた。", "error_description": "「見る」は後ろの「声をかけた」と続けるために「て形」が必要。「見る、」で切ると文がつながらず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bad1c4d-f01b-4f87-8fe3-07018ad5ba8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「本能が体を動かした」となり、本能が主語として動きを起こす正しい形。"}, {"text": "を", "is_correct": false, "explanation": "本能は体を動かす主体なので、「を」で目的語にするのは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、動作の主体を示すこの文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾を表すので、主語の位置に置くと文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「本能が体を動かした」となり、本能が主語として動きを起こす正しい形。", "を": "本能は体を動かす主体なので、「を」で目的語にするのは合わない。", "へ": "方向を表すので、動作の主体を示すこの文には合わない。", "の": "所有や修飾を表すので、主語の位置に置くと文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「本能で」は手段を表し、考えずに体がびくっと動く理由になる。"}, {"text": "を", "is_correct": false, "explanation": "「本能を体がびくっと動く」となり、動詞の主語と目的語が噛み合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「本能へ体がびくっと動く」となり、抽象的な本能を方向として体の動きと結べず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「本能より」では体が動く理由が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「本能で」は手段を表し、考えずに体がびくっと動く理由になる。", "を": "「本能を体がびくっと動く」となり、動詞の主語と目的語が噛み合わず不自然。", "へ": "「本能へ体がびくっと動く」となり、抽象的な本能を方向として体の動きと結べず不自然。", "より": "比較を表すので、「本能より」では体が動く理由が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体が自然にする動きや、考えなくても出てくる気持ちのこと。", "primary_collocate": null, "pronunciation": "ほんのう", "ipa": "honnoː", "syllable_count": 4, "sentences": [{"text": "熱いものに触ると、本能で手を引っこめる。", "target_word": "本能", "complexity_tier": "T3", "furigana": "熱[あつ]いものに触[さわ]ると、本能[ほんのう]で手[て]を引[ひ]っこめる。", "sentence_source": "generated"}, {"text": "危ないと思った瞬間、本能が体を動かした。", "target_word": "本能", "complexity_tier": "T3", "furigana": "危[あぶ]ないと思[おも]った瞬間[しゅんかん]、本能[ほんのう]が体[からだ]を動[うご]かした。", "sentence_source": "generated"}, {"text": "急に物が飛んできたので、本能で顔をかばった。", "target_word": "本能", "complexity_tier": "T3", "furigana": "急[きゅう]に物[もの]が飛[と]んできたので、本能[ほんのう]で顔[かお]をかばった。", "sentence_source": "generated"}, {"text": "暗い道では、本能が「早く帰れ」と私に言った。", "target_word": "本能", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]では、本能[ほんのう]が「早[はや]く帰[かえ]れ」と私[わたし]に言[い]った。", "sentence_source": "generated"}, {"text": "考える前に、本能が体を守ろうとした。", "target_word": "本能", "complexity_tier": "T3", "furigana": "考[かんが]える前[まえ]に、本能[ほんのう]が体[からだ]を守[まも]ろうとした。", "sentence_source": "generated"}, {"text": "本能に従って逃げたおかげで、けがをしなかった。", "target_word": "本能", "complexity_tier": "T3", "furigana": "本能[ほんのう]に従[したが]って逃[に]げたおかげで、けがをしなかった。", "sentence_source": "generated"}, {"text": "水に落ちた子どもは、本能で手足をばたばたさせた。", "target_word": "本能", "complexity_tier": "T3", "furigana": "水[みず]に落[お]ちた子[こ]どもは、本能[ほんのう]で手足[てあし]をばたばたさせた。", "sentence_source": "generated"}, {"text": "大きな音がすると、本能で体がびくっと動く。", "target_word": "本能", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]がすると、本能[ほんのう]で体[からだ]がびくっと動[うご]く。", "sentence_source": "generated"}, {"text": "転びそうになったとき、本能で近くの手すりをつかんだ。", "target_word": "本能", "complexity_tier": "T3", "furigana": "転[ころ]びそうになったとき、本能[ほんのう]で近[ちか]くの手[て]すりをつかんだ。", "sentence_source": "generated"}, {"text": "考えるひまはなく、本能のまま走って道を渡った。", "target_word": "本能", "complexity_tier": "T3", "furigana": "考[かんが]えるひまはなく、本能[ほんのう]のまま走[はし]って道[みち]を渡[わた]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本能", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "考える前に体や気持ちが自然に反応すること(とっさの反射的な動き)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本能", "is_correct": true, "explanation": "考える前に体が反応するという意味で、熱いものから手が反射的に離れる場面に合う。"}, {"text": "絵画", "is_correct": false, "explanation": "絵を描いた作品のことで、熱いものから手を引く動きとは合わない。"}, {"text": "計画", "is_correct": false, "explanation": "前もって立てる段取りのことで、熱いものに触れた瞬間の動きには合わない。"}, {"text": "努力", "is_correct": false, "explanation": "力を注ぐことで、反射的に手を引っこめる場面には合わない。"}], "explanations": {"本能": "考える前に体が反応するという意味で、熱いものから手が反射的に離れる場面に合う。", "絵画": "絵を描いた作品のことで、熱いものから手を引く動きとは合わない。", "計画": "前もって立てる段取りのことで、熱いものに触れた瞬間の動きには合わない。", "努力": "力を注ぐことで、反射的に手を引っこめる場面には合わない。"}, "sentence_index": 0, "correct_answer": "本能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は本能で、夕飯の材料を一グラムずつ計量した。", "explanation": "ここは〈計量〉の意味。目盛りで量ることは「計量」で、考えなくても出る「本能」とは合わない。"}, {"text": "彼女は本能で、昨日の会議の内容を詳しく書き残した。", "explanation": "ここは〈記録〉の意味。出来事を文字にして残すことは「記録」で、考えずに起こる「本能」とは合わない。"}, {"text": "昨日の出来事を本能で思い出せない。", "explanation": "ここは〈記憶〉の意味。過去を覚えておく働きは「記憶」で、考えずに起こる「本能」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本能", "is_correct": true, "explanation": "考えなくても体が動くという意味で、水に落ちた子どもが手足をばたつかせる場面に合う。"}, {"text": "知識", "is_correct": false, "explanation": "知って得た情報のことで、水に落ちて手足を動かす反射的な動きには合わない。"}, {"text": "勉強", "is_correct": false, "explanation": "学んで身につける行為のことで、溺れて手足をばたつかせる場面とは合わない。"}, {"text": "注意", "is_correct": false, "explanation": "気をつけることを指し、とっさに手足を動かす場面には合わない。"}], "explanations": {"本能": "考えなくても体が動くという意味で、水に落ちた子どもが手足をばたつかせる場面に合う。", "知識": "知って得た情報のことで、水に落ちて手足を動かす反射的な動きには合わない。", "勉強": "学んで身につける行為のことで、溺れて手足をばたつかせる場面とは合わない。", "注意": "気をつけることを指し、とっさに手足を動かす場面には合わない。"}, "sentence_index": 6, "correct_answer": "本能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の旅行を本能で段取りして、宿を予約した。", "explanation": "ここは〈計画〉の意味。前もって先の予定を組み立てることは「計画」で、考えずに起こる「本能」とは合わない。"}, {"text": "テストに向けて、本能で毎日机に向かった。", "explanation": "ここは〈努力〉の意味。意識して力を注ぐことは「努力」で、考えなくても出る「本能」とは合わない。"}, {"text": "英単語を本能で何度も書いた。", "explanation": "ここは〈暗記〉の意味。覚え込むことは「暗記」で、生まれつき備わる「本能」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱い鍋に触ると、本能に手を引っこめる。", "corrected_sentence": "熱い鍋に触ると、本能で手を引っこめる。", "error_description": "「本能で～する」は「本能によって」の意味で、手段を表す「で」を使う。「本能に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "危険を感じた瞬間、本能な反応で体が後ろに下がった。", "corrected_sentence": "危険を感じた瞬間、本能的な反応で体が後ろに下がった。", "error_description": "「本能」を名詞を修飾する形で使うには「本能的な」とする。「本能な」は誤りで、正しくは「本能的な」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
