INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39615, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間や動物が、教えられたり考えたりしなくても、生まれつき持っている行動や感じ方のこと。", "primary_collocate": null, "pronunciation": "ほんのう", "ipa": "honnoː", "syllable_count": 4, "sentences": [{"text": "渡り鳥は、本能によって毎年同じ場所へ飛んでいく。", "target_word": "本能", "complexity_tier": "T3", "furigana": "渡[わた]り鳥[どり]は、本能[ほんのう]によって毎年[まいとし]同[おな]じ場所[ばしょ]へ飛[と]んでいく。", "sentence_source": "generated"}, {"text": "子を守りたいという本能は、動物にも人間にもある。", "target_word": "本能", "complexity_tier": "T3", "furigana": "子[こ]を守[まも]りたいという本能[ほんのう]は、動物[どうぶつ]にも人間[にんげん]にもある。", "sentence_source": "generated"}, {"text": "猫は教えられなくても、本能でネズミを追いかける。", "target_word": "本能", "complexity_tier": "T3", "furigana": "猫[ねこ]は教[おし]えられなくても、本能[ほんのう]でネズミを追[お]いかける。", "sentence_source": "generated"}, {"text": "生き物には、生きのびようとする本能がある。", "target_word": "本能", "complexity_tier": "T3", "furigana": "生[い]き物[もの]には、生[い]きのびようとする本能[ほんのう]がある。", "sentence_source": "generated"}, {"text": "ウミガメの子は、本能で海のほうへ向かって進む。", "target_word": "本能", "complexity_tier": "T3", "furigana": "ウミガメの子[こ]は、本能[ほんのう]で海[うみ]のほうへ向[む]かって進[すす]む。", "sentence_source": "generated"}, {"text": "母親の本能で、彼女は赤ちゃんの泣き声にすぐ気づいた。", "target_word": "本能", "complexity_tier": "T3", "furigana": "母親[ははおや]の本能[ほんのう]で、彼女[かのじょ]は赤[あか]ちゃんの泣[な]き声[ごえ]にすぐ気[き]づいた。", "sentence_source": "generated"}, {"text": "人は本能だけでなく、理性でも行動を決める。", "target_word": "本能", "complexity_tier": "T3", "furigana": "人[ひと]は本能[ほんのう]だけでなく、理性[りせい]でも行動[こうどう]を決[き]める。", "sentence_source": "generated"}, {"text": "クモは本能で、だれにも習わずに巣を作る。", "target_word": "本能", "complexity_tier": "T3", "furigana": "クモは本能[ほんのう]で、だれにも習[なら]わずに巣[す]を作[つく]る。", "sentence_source": "generated"}, {"text": "動物の本能を研究して、行動の理由を調べている。", "target_word": "本能", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の本能[ほんのう]を研究[けんきゅう]して、行動[こうどう]の理由[りゆう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "食べ物を探す本能が、ネズミを台所へ向かわせた。", "target_word": "本能", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]を探[さが]す本能[ほんのう]が、ネズミを台所[だいどころ]へ向[む]かわせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本能", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "生まれつき持つ行動や感じ方(動物の習性・生存や子育ての欲求)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本能", "is_correct": true, "explanation": "生まれつき備わる行動の力という意味で、渡り鳥が毎年同じ場所へ飛ぶ理由になる。"}, {"text": "気分", "is_correct": false, "explanation": "その時々の心の状態のことで、毎年同じ場所へ渡る習性の理由にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、渡り鳥の行き先を決める理由にはならない。"}, {"text": "音楽", "is_correct": false, "explanation": "耳で楽しむ芸術のことで、渡り鳥の行き先を決める習性とは関係がない。"}], "explanations": {"本能": "生まれつき備わる行動の力という意味で、渡り鳥が毎年同じ場所へ飛ぶ理由になる。", "気分": "その時々の心の状態のことで、毎年同じ場所へ渡る習性の理由にはならない。", "体重": "体の重さのことで、渡り鳥の行き先を決める理由にはならない。", "音楽": "耳で楽しむ芸術のことで、渡り鳥の行き先を決める習性とは関係がない。"}, "sentence_index": 0, "correct_answer": "本能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は本能が明るく、誰とでもすぐ仲良くなる。", "explanation": "ここは〈性格〉の意味。人柄や気質のことは「性格」で、考えずに起こる行動の「本能」とは合わない。"}, {"text": "彼は本能が豊富で、この仕事にはうってつけだ。", "explanation": "ここは〈経験〉の意味。仕事で積み重ねたものは「経験」で、生まれつき備わる「本能」とは合わない。"}, {"text": "この機械は本能が高く、人の指示をよく理解する。", "explanation": "ここは〈知能〉の意味。考える力の高さは「知能」で、生まれつき備わる行動の「本能」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本能", "is_correct": true, "explanation": "生まれつき備わる行動の力という意味で、理性とともに行動を決める要因として文に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉の意味を調べる本のことで、人の行動を決める要因としてはこの文に合わない。"}, {"text": "漢字", "is_correct": false, "explanation": "字の形や読みのことで、人の行動を決める要素としてはこの文に合わない。"}, {"text": "身長", "is_correct": false, "explanation": "体の高さのことで、行動を決める要因として文脈に合わない。"}], "explanations": {"本能": "生まれつき備わる行動の力という意味で、理性とともに行動を決める要因として文に合う。", "辞書": "言葉の意味を調べる本のことで、人の行動を決める要因としてはこの文に合わない。", "漢字": "字の形や読みのことで、人の行動を決める要素としてはこの文に合わない。", "身長": "体の高さのことで、行動を決める要因として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "本能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この石は本能が硬く、曲がりにくい。", "explanation": "ここは〈性質〉の意味。物が持つ特徴は「性質」で、生き物が生まれつき持つ行動の「本能」とは合わない。"}, {"text": "ネズミは本能で、迷路の出口を論理的に割り出した。", "explanation": "ここは〈推理〉の意味。筋道を立てて答えを導くことは「推理」で、生まれつきの反応を指す「本能」とは合わない。"}, {"text": "この祭りは、本能として何百年も受け継がれてきた。", "explanation": "ここは〈伝統〉の意味。昔から受け継がれてきた習わしは「伝統」で、生まれつきの行動を指す「本能」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ツバメには、毎年同じ巣へ戻る本能をある。", "corrected_sentence": "ツバメには、毎年同じ巣へ戻る本能がある。", "error_description": "「ある」は存在を表す動詞で、主語の「本能」には「が」を使う。「本能をある」は誤りで、正しくは「本能がある」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜中に物音がすると、子を守りたい本能が強く働かせる。", "corrected_sentence": "夜中に物音がすると、子を守りたい本能が強く働く。", "error_description": "「働く」は主語だけで成り立つ自動詞。「働かせる」は他動詞で目的語が必要なので、主語の「本能が」に続けるのは誤り。正しくは「働く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不活発", "is_correct": true, "explanation": "動きが少なく元気がないようすで、活発の対義語。"}, {"text": "愉快", "is_correct": false, "explanation": "楽しく面白いさまで、活発の対義語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "行き届いて念入りなさまで、活発とは反対の関係にない。"}, {"text": "有能", "is_correct": false, "explanation": "能力が高いさまで、活発の対義語ではない。"}], "correct_answer": "不活発", "explanations": {"不活発": "動きが少なく元気がないようすで、活発の対義語。", "愉快": "楽しく面白いさまで、活発の対義語ではない。", "丁寧": "行き届いて念入りなさまで、活発とは反対の関係にない。", "有能": "能力が高いさまで、活発の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不活発", "is_correct": true, "explanation": "動きが少なく元気がないようすで、活発の対義語。"}, {"text": "豪華", "is_correct": false, "explanation": "華やかで立派なさまで、活発の対義語ではない。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に負担をかけるさまで、活発の対義語ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "厳しく規律を守るさまで、活発とは反対の関係にない。"}], "correct_answer": "不活発", "explanations": {"不活発": "動きが少なく元気がないようすで、活発の対義語。", "豪華": "華やかで立派なさまで、活発の対義語ではない。", "迷惑": "人に負担をかけるさまで、活発の対義語ではない。", "厳格": "厳しく規律を守るさまで、活発とは反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "元気に動いたり、何かをしたりするようす。", "primary_collocate": null, "pronunciation": "かっぱつ", "ipa": "kappatsɯ", "syllable_count": 4, "sentences": [{"text": "弟は活発な子で、いつも外であそんでいます。", "target_word": "活発", "complexity_tier": "T3", "furigana": "弟[おとうと]は活発[かっぱつ]な子[こ]で、いつも外[そと]であそんでいます。", "sentence_source": "generated"}, {"text": "妹は活発に走り回っています。", "target_word": "活発", "complexity_tier": "T3", "furigana": "妹[いもうと]は活発[かっぱつ]に走[はし]り回[まわ]っています。", "sentence_source": "generated"}, {"text": "活発な犬なので、毎日さんぽが必要です。", "target_word": "活発", "complexity_tier": "T3", "furigana": "活発[かっぱつ]な犬[いぬ]なので、毎日[まいにち]さんぽが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "彼女はクラスで一番活発です。", "target_word": "活発", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はクラスで一番[いちばん]活発[かっぱつ]です。", "sentence_source": "generated"}, {"text": "春になって、虫たちが活発に動き始めました。", "target_word": "活発", "complexity_tier": "T3", "furigana": "春[はる]になって、虫[むし]たちが活発[かっぱつ]に動[うご]き始[はじ]めました。", "sentence_source": "generated"}, {"text": "活発な少年たちが、公園でサッカーをしています。", "target_word": "活発", "complexity_tier": "T3", "furigana": "活発[かっぱつ]な少年[しょうねん]たちが、公園[こうえん]でサッカーをしています。", "sentence_source": "generated"}, {"text": "活発なのはいいですが、けがをしないように気をつけてください。", "target_word": "活発", "complexity_tier": "T3", "furigana": "活発[かっぱつ]なのはいいですが、けがをしないように気[き]をつけてください。", "sentence_source": "generated"}, {"text": "活発な性格なので、友だちがたくさんいます。", "target_word": "活発", "complexity_tier": "T3", "furigana": "活発[かっぱつ]な性格[せいかく]なので、友[とも]だちがたくさんいます。", "sentence_source": "generated"}, {"text": "子どもたちは活発に手をあげて、先生に答えました。", "target_word": "活発", "complexity_tier": "T3", "furigana": "子[こ]どもたちは活発[かっぱつ]に手[て]をあげて、先生[せんせい]に答[こた]えました。", "sentence_source": "generated"}, {"text": "朝から活発に動いたので、夜はぐっすり眠れました。", "target_word": "活発", "complexity_tier": "T3", "furigana": "朝[あさ]から活発[かっぱつ]に動[うご]いたので、夜[よる]はぐっすり眠[ねむ]れました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活発", "label": "語幹"}, {"form": "活発な", "label": "連体形"}, {"form": "活発に", "label": "連用形"}, {"form": "活発だ", "label": "終止形"}, {"form": "活発で", "label": "中止形"}], "register": "中立（丁寧体）", "sense_fingerprint": "元気でよく動くようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活発", "is_correct": true, "explanation": "よく動き回る子どもの様子に合い、文の内容と一致する。"}, {"text": "正確", "is_correct": false, "explanation": "正しく確かなさまを表し、子どもの様子には合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しく清らかなさまを表し、子どもの性格や様子とは言わない。"}, {"text": "抽象的", "is_correct": false, "explanation": "具体性がないさまを表し、人の動きには使わない。"}], "explanations": {"活発": "よく動き回る子どもの様子に合い、文の内容と一致する。", "正確": "正しく確かなさまを表し、子どもの様子には合わない。", "新鮮": "新しく清らかなさまを表し、子どもの性格や様子とは言わない。", "抽象的": "具体性がないさまを表し、人の動きには使わない。"}, "sentence_index": 0, "correct_answer": "活発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この石は活発だ。", "explanation": "ここは〈鮮やか〉と取り違えた用法。鮮やかは色や光の強さを表すので、動きのようすを表す活発は石には使えない。"}, {"text": "彼は一日中、活発に動かず横たわっていた。", "explanation": "ここは〈安静〉と取り違えた用法。安静は動かずに休むことで、動きが盛んな活発とは逆の意味になる。"}, {"text": "窓辺で猫が活発に眠っている。", "explanation": "ここは〈熟睡〉と取り違えた用法。熟睡は深く眠ることで、動きが盛んな活発とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活発", "is_correct": true, "explanation": "元気よく動くことを良いとする文に合い、注意を続ける流れにも自然につながる。"}, {"text": "陰気", "is_correct": false, "explanation": "暗く沈んださまを表し、この注意の文には合わない。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に負担をかけるさまを表し、文の内容とは合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "華やかで立派なさまを表し、けがの注意とは結びつかない。"}], "explanations": {"活発": "元気よく動くことを良いとする文に合い、注意を続ける流れにも自然につながる。", "陰気": "暗く沈んださまを表し、この注意の文には合わない。", "迷惑": "人に負担をかけるさまを表し、文の内容とは合わない。", "豪華": "華やかで立派なさまを表し、けがの注意とは結びつかない。"}, "sentence_index": 6, "correct_answer": "活発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この毛布は活発だ。", "explanation": "ここは〈暖かい〉と取り違えた用法。暖かいは温度や感じを表すので、動きのようすを表す活発は毛布には使えない。"}, {"text": "町の古い時計は、今日も活発に止まったままだ。", "explanation": "ここは〈故障〉と取り違えた用法。故障して止まる状態は動きが盛んな活発とは反対になるので、ここでは使えない。"}, {"text": "祖父は縁側で活発に日なたぼっこをしている。", "explanation": "ここは〈のんびり〉と取り違えた用法。のんびりは急がず落ち着いたようすなので、動きの盛んな活発とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この犬は活発の性格で、毎日たくさん走る。", "corrected_sentence": "この犬は活発な性格で、毎日たくさん走る。", "error_description": "『活発』は形状詞なので、名詞を修飾するときは『な』が必要。『の』は形が合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "活発に", "is_correct": true, "explanation": "連用形で、後ろの『走り回る』を修飾するので、文に合う。"}, {"text": "活発な", "is_correct": false, "explanation": "連体形で名詞を修飾するので、動詞『走り回る』を修飾する文では使えない。"}, {"text": "活発だ", "is_correct": false, "explanation": "終止形で文を言い切るので、『走り回っています』と続けられない。"}, {"text": "活発だった", "is_correct": false, "explanation": "過去形で、今の様子を述べる文と合わない。"}], "correct_form": "活発に", "base_form": "活発", "form_label": "連用形", "sentence_index": 1, "explanations": {"活発に": "連用形で、後ろの『走り回る』を修飾するので、文に合う。", "活発な": "連体形で名詞を修飾するので、動詞『走り回る』を修飾する文では使えない。", "活発だ": "終止形で文を言い切るので、『走り回っています』と続けられない。", "活発だった": "過去形で、今の様子を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は高齢でも活発の、毎朝散歩を続けている。", "corrected_sentence": "祖父は高齢でも活発で、毎朝散歩を続けている。", "error_description": "『活発』は形状詞なので、後ろに続けるときは『で』が必要。『の』では形が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活発な", "is_correct": true, "explanation": "連体形で、後ろの『性格』を修飾するので、文に合う。"}, {"text": "活発に", "is_correct": false, "explanation": "連用形は名詞を修飾できないので、『性格』を修飾する文では使えない。"}, {"text": "活発だ", "is_correct": false, "explanation": "終止形は名詞に直接続かないので、『性格』とはつながらない。"}, {"text": "活発で", "is_correct": false, "explanation": "中止形は名詞に続けられないので、『性格なので』では形が合わない。"}], "correct_form": "活発な", "base_form": "活発", "form_label": "連体形", "sentence_index": 7, "explanations": {"活発な": "連体形で、後ろの『性格』を修飾するので、文に合う。", "活発に": "連用形は名詞を修飾できないので、『性格』を修飾する文では使えない。", "活発だ": "終止形は名詞に直接続かないので、『性格』とはつながらない。", "活発で": "中止形は名詞に続けられないので、『性格なので』では形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不活発", "is_correct": true, "explanation": "〈動きや活動が少ない〉の意味で、「よく動き回る」の対義語として辞書に並ぶ。"}, {"text": "慎重", "is_correct": false, "explanation": "〈注意深いこと〉の意味で、活動の多少を表す対義語ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "〈厳しく守るさま〉の意味で、この文の対義語には当たらない。"}, {"text": "冷静", "is_correct": false, "explanation": "〈感情に流されない〉の意味で、動きの盛んさと対になる語ではない。"}], "correct_answer": "不活発", "explanations": {"不活発": "〈動きや活動が少ない〉の意味で、「よく動き回る」の対義語として辞書に並ぶ。", "慎重": "〈注意深いこと〉の意味で、活動の多少を表す対義語ではない。", "厳格": "〈厳しく守るさま〉の意味で、この文の対義語には当たらない。", "冷静": "〈感情に流されない〉の意味で、動きの盛んさと対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不活発", "is_correct": true, "explanation": "〈動きや活動が少ない〉の意味で、「商店街が活発になる」の対義語として辞書に並ぶ。"}, {"text": "地味", "is_correct": false, "explanation": "〈目立たないさま〉の意味で、活動の多少を表す対義語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "〈恐れず思い切るさま〉の意味で、この文の対義語には当たらない。"}, {"text": "堅実", "is_correct": false, "explanation": "〈着実で確かなさま〉の意味で、活動の盛んさとは対にならない。"}], "correct_answer": "不活発", "explanations": {"不活発": "〈動きや活動が少ない〉の意味で、「商店街が活発になる」の対義語として辞書に並ぶ。", "地味": "〈目立たないさま〉の意味で、活動の多少を表す対義語ではない。", "大胆": "〈恐れず思い切るさま〉の意味で、この文の対義語には当たらない。", "堅実": "〈着実で確かなさま〉の意味で、活動の盛んさとは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "活発：元気で、よく動いたり、活動したりする様子。", "primary_collocate": null, "pronunciation": "かっぱつ", "ipa": "kappatsɯ", "syllable_count": 4, "sentences": [{"text": "彼女は活発な性格で、新しい人ともすぐに仲よくなる。", "target_word": "活発", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は活発[かっぱつ]な性格[せいかく]で、新[あたら]しい人[ひと]ともすぐに仲[なか]よくなる。", "sentence_source": "generated"}, {"text": "このクラブは活発に活動していて、毎週イベントがある。", "target_word": "活発", "complexity_tier": "T3", "furigana": "このクラブは活発[かっぱつ]に活動[かつどう]していて、毎週[まいしゅう]イベントがある。", "sentence_source": "generated"}, {"text": "会議では、活発な意見交換が行われた。", "target_word": "活発", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、活発[かっぱつ]な意見[いけん]交換[こうかん]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "祖父は八十歳だが、今でも活発に動き回っている。", "target_word": "活発", "complexity_tier": "T3", "furigana": "祖父[そふ]は八十歳[はちじゅっさい]だが、今[いま]でも活発[かっぱつ]に動[うご]き回[まわ]っている。", "sentence_source": "generated"}, {"text": "梅雨の時期は前線が活発になり、大雨が降りやすい。", "target_word": "活発", "complexity_tier": "T3", "furigana": "梅雨[つゆ]の時期[じき]は前線[ぜんせん]が活発[かっぱつ]になり、大雨[おおあめ]が降[ふ]りやすい。", "sentence_source": "generated"}, {"text": "火山が活発になり、注意が呼びかけられている。", "target_word": "活発", "complexity_tier": "T3", "furigana": "火山[かざん]が活発[かっぱつ]になり、注意[ちゅうい]が呼[よ]びかけられている。", "sentence_source": "generated"}, {"text": "市場では、今日も活発な取引が続いている。", "target_word": "活発", "complexity_tier": "T3", "furigana": "市場[いちば]では、今日[きょう]も活発[かっぱつ]な取引[とりひき]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "彼は活発すぎて、授業中もじっとしていられない。", "target_word": "活発", "complexity_tier": "T3", "furigana": "彼[かれ]は活発[かっぱつ]すぎて、授業中[じゅぎょうちゅう]もじっとしていられない。", "sentence_source": "generated"}, {"text": "活発な子どもは、食事の量も多い。", "target_word": "活発", "complexity_tier": "T3", "furigana": "活発[かっぱつ]な子[こ]どもは、食事[しょくじ]の量[りょう]も多[おお]い。", "sentence_source": "generated"}, {"text": "商店街が活発になって、町に人が戻ってきた。", "target_word": "活発", "complexity_tier": "T3", "furigana": "商店街[しょうてんがい]が活発[かっぱつ]になって、町[まち]に人[ひと]が戻[もど]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活発", "label": "語幹"}, {"form": "活発な", "label": "連体形"}, {"form": "活発に", "label": "連用形"}, {"form": "活発だ", "label": "終止形"}, {"form": "活発で", "label": "中止形"}], "register": "中立（常体）", "sense_fingerprint": "元気で、人や物事の動きや活動がさかんなようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活発", "is_correct": true, "explanation": "「活発な性格」で、動きや行動が盛んで元気な人柄を表す。文に合う。"}, {"text": "豪華", "is_correct": false, "explanation": "〈ぜいたくで華やかな〉の意味。人の性格には使わないので合わない。"}, {"text": "不便", "is_correct": false, "explanation": "〈便利でない〉の意味。性格を表す語としては成り立たない。"}, {"text": "順調", "is_correct": false, "explanation": "〈物事がはかどる〉の意味。人の気質を言うには使えない。"}], "explanations": {"活発": "「活発な性格」で、動きや行動が盛んで元気な人柄を表す。文に合う。", "豪華": "〈ぜいたくで華やかな〉の意味。人の性格には使わないので合わない。", "不便": "〈便利でない〉の意味。性格を表す語としては成り立たない。", "順調": "〈物事がはかどる〉の意味。人の気質を言うには使えない。"}, "sentence_index": 0, "correct_answer": "活発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは味が活発で、後味まで深く残る。", "explanation": "ここは〈味が濃い〉の意味。活発は動きや活動が盛んなことで、味の濃さには使わない。"}, {"text": "この橋は基礎が活発で、大きな地震でも崩れない。", "explanation": "ここは〈しっかりして安定している〉の意味。活発は動きの盛んさを表し、構造の強さには使えない。"}, {"text": "この薬は効き目が活発で、飲むとすぐ眠くなる。", "explanation": "ここは〈強く効く〉の意味。活発は活動が盛んな様子で、効き目の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活発", "is_correct": true, "explanation": "「活発な取引」で、市場の動きがさかんな様子を表す。文に合う。"}, {"text": "健気", "is_correct": false, "explanation": "〈けなげでいじらしい〉の意味で、取引の様子には合わない。"}, {"text": "純朴", "is_correct": false, "explanation": "〈飾り気がなく素直〉の意味で、取引には使えない。"}, {"text": "陽気", "is_correct": false, "explanation": "〈明るく楽しい〉の意味で、取引の勢いを表すことはできない。"}], "explanations": {"活発": "「活発な取引」で、市場の動きがさかんな様子を表す。文に合う。", "健気": "〈けなげでいじらしい〉の意味で、取引の様子には合わない。", "純朴": "〈飾り気がなく素直〉の意味で、取引には使えない。", "陽気": "〈明るく楽しい〉の意味で、取引の勢いを表すことはできない。"}, "sentence_index": 6, "correct_answer": "活発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池の水は活発で、底まで透き通って見える。", "explanation": "ここは〈澄んでいる〉の意味。活発は動きや活動の盛んさを表すので、水の透明さには使わない。"}, {"text": "この商品は在庫が活発で、すぐに売り切れた。", "explanation": "ここは〈売れ行きがよい〉の意味。活発は在庫の多さには使わず、売れ行きには好調を使う。"}, {"text": "彼女は寝たきりの祖母のそばで、活発に静かに見守っていた。", "explanation": "ここは〈そっと見守る〉の意味。活発は動きが盛んなことで、静かな見守りとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "観客が活発の応援をして、試合が盛り上がった。", "corrected_sentence": "観客が活発な応援をして、試合が盛り上がった。", "error_description": "連体形「活発な」が正しい。形状詞「活発」は名詞を修飾するとき「な」が必要で、「の」は形が合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "活発に", "is_correct": true, "explanation": "連用形で、動詞「活動していて」を修飾する。文に合う。"}, {"text": "活発な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。ここは動詞句「活動していて」に続くので、連用形が必要。"}, {"text": "活発だ", "is_correct": false, "explanation": "終止形で、「活動していて」とつながらない。"}, {"text": "活発", "is_correct": false, "explanation": "語幹だけでは「活動していて」を修飾できず、文が成り立たない。"}], "correct_form": "活発に", "base_form": "活発", "form_label": "連用形", "sentence_index": 1, "explanations": {"活発に": "連用形で、動詞「活動していて」を修飾する。文に合う。", "活発な": "連体形で名詞を修飾する形。ここは動詞句「活動していて」に続くので、連用形が必要。", "活発だ": "終止形で、「活動していて」とつながらない。", "活発": "語幹だけでは「活動していて」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39617, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は休日になると活発を外へ出かけて、友達と遊ぶ。", "corrected_sentence": "弟は休日になると活発に外へ出かけて、友達と遊ぶ。", "error_description": "副詞的な「活発に」が正しい。「活発を」は助詞「を」が誤りで、活発は形状詞なので目的語にできない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活発", "is_correct": true, "explanation": "語幹で、「すぎ」を付けて「活発すぎて」となる。文に合う。"}, {"text": "活発に", "is_correct": false, "explanation": "連用形は「すぎ」を直接つけられず、「活発にすぎて」は成り立たない。"}, {"text": "活発で", "is_correct": false, "explanation": "中止形は「すぎ」に続かず、「活発ですぎて」は不自然。"}, {"text": "活発だった", "is_correct": false, "explanation": "過去形は「すぎ」に続かず、文の形が崩れる。"}], "correct_form": "活発", "base_form": "活発", "form_label": "語幹", "sentence_index": 7, "explanations": {"活発": "語幹で、「すぎ」を付けて「活発すぎて」となる。文に合う。", "活発に": "連用形は「すぎ」を直接つけられず、「活発にすぎて」は成り立たない。", "活発で": "中止形は「すぎ」に続かず、「活発ですぎて」は不自然。", "活発だった": "過去形は「すぎ」に続かず、文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「まく」の対象を示す助詞で、「農薬をまいています」と続いて文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「まく」の対象は目的語になるので「を」が必要。「が」は主語を示し、ここでは文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すもので、「まく」の対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「まく」の対象を表すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「まく」の対象を示す助詞で、「農薬をまいています」と続いて文に合う。", "が": "「まく」の対象は目的語になるので「を」が必要。「が」は主語を示し、ここでは文が成り立たない。", "と": "「と」は並列や相手を示すもので、「まく」の対象を表せない。", "へ": "方向を示す助詞で、「まく」の対象を表すことはできない。"}, "error_tags": {"が": "「まく」の対象は目的語になるので「を」が必要。「が」は主語を示し、ここでは文が成り立たない。", "と": "「と」は並列や相手を示すもので、「まく」の対象を表せない。", "へ": "方向を示す助詞で、「まく」の対象を表すことはできない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
