INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "農薬は、虫や病気から作物を守るための薬です。", "primary_collocate": null, "pronunciation": "のうやく", "ipa": "noɯjakɯ", "syllable_count": 4, "sentences": [{"text": "農薬は、虫から野菜を守るための薬です。", "target_word": "農薬", "complexity_tier": "T2", "furigana": "農薬[のうやく]は、虫[むし]から野菜[やさい]を守[まも]るための薬[くすり]です。", "sentence_source": "generated"}, {"text": "おじいさんは畑に農薬をまいています。", "target_word": "農薬", "complexity_tier": "T2", "furigana": "おじいさんは畑[はたけ]に農薬[のうやく]をまいています。", "sentence_source": "generated"}, {"text": "この店の果物は、農薬が少ないと書いてあります。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "この店[みせ]の果物[くだもの]は、農薬[のうやく]が少[すく]ないと書[か]いてあります。", "sentence_source": "generated"}, {"text": "農薬がついているかもしれないので、野菜はよく洗います。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]がついているかもしれないので、野菜[やさい]はよく洗[あら]います。", "sentence_source": "generated"}, {"text": "虫が増えたので、農家の人が農薬を買いに行きました。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "虫[むし]が増[ふ]えたので、農家[のうか]の人[ひと]が農薬[のうやく]を買[か]いに行[い]きました。", "sentence_source": "generated"}, {"text": "農薬を使わない米は、少し値段が高いです。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]を使[つか]わない米[こめ]は、少[すこ]し値段[ねだん]が高[たか]いです。", "sentence_source": "generated"}, {"text": "農薬のにおいが強くて、窓を閉めました。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]のにおいが強[つよ]くて、窓[まど]を閉[し]めました。", "sentence_source": "generated"}, {"text": "雨が降ると、農薬が川に流れてしまうことがあります。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、農薬[のうやく]が川[かわ]に流[なが]れてしまうことがあります。", "sentence_source": "generated"}, {"text": "農薬が体に悪い心配があるので、有機野菜を選びます。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]が体[からだ]に悪[わる]い心配[しんぱい]があるので、有機野菜[ゆうきやさい]を選[えら]びます。", "sentence_source": "generated"}, {"text": "農薬の袋には、使い方が細かく書かれています。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]の袋[ふくろ]には、使[つか]い方[かた]が細[こま]かく書[か]かれています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農薬", "label": "基本形"}], "register": "中立", "sense_fingerprint": "虫や病気から作物を守るためにまく薬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農薬", "is_correct": true, "explanation": "虫や病気から作物を守る薬を表し、「〜は、虫から野菜を守るための薬です」の空欄に入る語。"}, {"text": "肥料", "is_correct": false, "explanation": "作物を育てる栄養のことで、虫から守る薬ではないため「薬です」と合わない。"}, {"text": "種", "is_correct": false, "explanation": "作物のもとになる物で、虫から野菜を守る薬ではないため文が成り立たない。"}, {"text": "機械", "is_correct": false, "explanation": "農作業に使う道具で、薬ではないため「〜は薬です」に当てはまらない。"}], "explanations": {"農薬": "虫や病気から作物を守る薬を表し、「〜は、虫から野菜を守るための薬です」の空欄に入る語。", "肥料": "作物を育てる栄養のことで、虫から守る薬ではないため「薬です」と合わない。", "種": "作物のもとになる物で、虫から野菜を守る薬ではないため文が成り立たない。", "機械": "農作業に使う道具で、薬ではないため「〜は薬です」に当てはまらない。"}, "sentence_index": 0, "correct_answer": "農薬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいたので、農薬を飲んで寝ました。", "explanation": "ここは人の病気を治す〈薬〉の意味。農薬は虫や病気から作物を守る薬で、人が飲むものではないので合わない。"}, {"text": "キャンプ場で農薬を塗ったので、蚊に刺されませんでした。", "explanation": "ここは〈虫除けスプレー〉の意味。農薬は畑で作物を守るためにまくもので、人の肌に塗るものではないので合わない。"}, {"text": "父は農薬を仕事にしていて、毎朝早く畑に出ます。", "explanation": "ここは〈農業〉の意味。農薬は作物を守る薬のことで、仕事や職業を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農薬", "is_correct": true, "explanation": "においの元として文に自然に続く、この語の正しい用法。"}, {"text": "電卓", "is_correct": false, "explanation": "においの元として成り立たず、窓を閉める文脈に合わない。"}, {"text": "支柱", "is_correct": false, "explanation": "植物を支える棒で、においが強い物として文の流れに合わない。"}, {"text": "杭", "is_correct": false, "explanation": "土に打ち込む棒で、強いにおいで窓を閉めるという内容に合わない。"}], "explanations": {"農薬": "においの元として文に自然に続く、この語の正しい用法。", "電卓": "においの元として成り立たず、窓を閉める文脈に合わない。", "支柱": "植物を支える棒で、においが強い物として文の流れに合わない。", "杭": "土に打ち込む棒で、強いにおいで窓を閉めるという内容に合わない。"}, "sentence_index": 6, "correct_answer": "農薬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外から帰ったら、手を農薬で消毒しました。", "explanation": "ここは〈消毒液〉の意味。農薬は畑の虫や病気から作物を守るためのもので、手の消毒には使わないので合わない。"}, {"text": "朝早く収穫した農薬を、市場に出荷しました。", "explanation": "ここは〈農作物〉の意味。農薬は作物を守る薬で、収穫して売るものではないので合わない。"}, {"text": "食器を農薬で洗って、ぴかぴかにしました。", "explanation": "ここは〈洗剤〉の意味。農薬は作物を守るためのもので、食器を洗う用途には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑の虫を減らすため、農薬が使いました。", "corrected_sentence": "畑の虫を減らすため、農薬を使いました。", "error_description": "「使う」の対象を示す助詞は「を」。「が」が誤りで、正しくは「農薬を使いました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39618, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農家は虫を防ぐため、農薬を育てています。", "corrected_sentence": "農家は虫を防ぐため、農薬を使っています。", "error_description": "「育てる」は作物に使う動詞で、農薬には「使う」を用いる。「育てています」が誤りで、正しくは「使っています」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
