INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「農薬が残っていない」の〈が〉。残る対象を主語として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すが、「残る」は目的語をとらないため「農薬を残っていない」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を表すため、「農薬で残っていない」は残存の主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すため、「農薬から残っていない」は主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「農薬が残っていない」の〈が〉。残る対象を主語として示す正しい助詞。", "を": "〈を〉は目的語を示すが、「残る」は目的語をとらないため「農薬を残っていない」は成り立たない。", "で": "〈で〉は手段や場所を表すため、「農薬で残っていない」は残存の主語を示せない。", "から": "〈から〉は起点を表すため、「農薬から残っていない」は主語を示せない。"}, "error_tags": {"を": "対象", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "農作物の病害虫や雑草を防除するために使用される化学物質や生物由来の薬剤。", "primary_collocate": null, "pronunciation": "のうやく", "ipa": "noɯjakɯ", "syllable_count": 4, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "農薬", "complexity_tier": "T4", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "農家は、害虫から作物を守るために農薬をまきます。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農家[のうか]は、害虫[がいちゅう]から作物[さくもつ]を守[まも]るために農薬[のうやく]をまきます。", "sentence_source": "generated"}, {"text": "この野菜は農薬の量が少ないので、子どもにも安心です。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "この野菜[やさい]は農薬[のうやく]の量[りょう]が少[すく]ないので、子[こ]どもにも安心[あんしん]です。", "sentence_source": "generated"}, {"text": "農薬を使いすぎると、土や川の水がよごれてしまいます。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]を使[つか]いすぎると、土[つち]や川[かわ]の水[みず]がよごれてしまいます。", "sentence_source": "generated"}, {"text": "今年は雑草が多かったため、農薬の散布を二度行った。", "target_word": "農薬", "complexity_tier": "T4", "furigana": "今年[ことし]は雑草[ざっそう]が多[おお]かったため、農薬[のうやく]の散布[さんぷ]を二度[にど]行[おこな]った。", "sentence_source": "generated"}, {"text": "有機栽培では、化学的に作られた農薬は原則として使えません。", "target_word": "農薬", "complexity_tier": "T4", "furigana": "有機栽培[ゆうきさいばい]では、化学的[かがくてき]に作[つく]られた農薬[のうやく]は原則[げんそく]として使[つか]えません。", "sentence_source": "generated"}, {"text": "畑に農薬をまいた日は、近くで遊ばないよう、注意書きが張り出されました。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "畑[はたけ]に農薬[のうやく]をまいた日[ひ]は、近[ちか]くで遊[あそ]ばないよう、注意書[ちゅういが]きが張[は]り出[だ]されました。", "sentence_source": "generated"}, {"text": "消費者の間では、農薬が残っていない食品を求める声が強まっている。", "target_word": "農薬", "complexity_tier": "T4", "furigana": "消費者[しょうひしゃ]の間[あいだ]では、農薬[のうやく]が残[のこ]っていない食品[しょくひん]を求[もと]める声[こえ]が強[つよ]まっている。", "sentence_source": "generated"}, {"text": "農薬を使わない代わりに、手で虫を一匹ずつ取る農家もいます。", "target_word": "農薬", "complexity_tier": "T3", "furigana": "農薬[のうやく]を使[つか]わない代[か]わりに、手[て]で虫[むし]を一匹[いっぴき]ずつ取[と]る農家[のうか]もいます。", "sentence_source": "generated"}, {"text": "収穫前の一定期間は、農薬をまくことが法律で禁止されている。", "target_word": "農薬", "complexity_tier": "T4", "furigana": "収穫前[しゅうかくまえ]の一定期間[いっていきかん]は、農薬[のうやく]をまくことが法律[ほうりつ]で禁止[きんし]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農薬", "label": "基本形"}], "register": "中立", "sense_fingerprint": "病害虫や雑草を防ぐために作物にまく薬剤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農薬", "is_correct": true, "explanation": "「農薬を使わずに野菜を育てる」の目的語。作物の病害虫を防ぐ薬剤を指す正しい語。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草を使わずに野菜を育てる」は意味が通らず、文脈に合わない。"}, {"text": "害虫", "is_correct": false, "explanation": "「害虫を使わずに野菜を育てる」は道具として成り立たず、文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書を使わずに野菜を育てる」は農業の文脈に合わず、意味が成り立たない。"}], "explanations": {"農薬": "「農薬を使わずに野菜を育てる」の目的語。作物の病害虫を防ぐ薬剤を指す正しい語。", "雑草": "「雑草を使わずに野菜を育てる」は意味が通らず、文脈に合わない。", "害虫": "「害虫を使わずに野菜を育てる」は道具として成り立たず、文脈に合わない。", "教科書": "「教科書を使わずに野菜を育てる」は農業の文脈に合わず、意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "農薬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑の土が弱ってきたので、農薬を足して、土を元気にする。", "explanation": "ここは〈肥料〉の意味。農薬は害虫や雑草を防ぐもので、土を元気にする働きはない。"}, {"text": "風邪のときは農薬を飲んで、ゆっくり休む。", "explanation": "ここは〈薬〉の意味。農薬は人が飲むものではなく、作物に使う薬剤なので合わない。"}, {"text": "油汚れの食器は、農薬で洗うとよく落ちる。", "explanation": "ここは〈洗剤〉の意味。農薬は食器を洗う物ではなく、作物に使う薬剤なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農薬", "is_correct": true, "explanation": "「畑に農薬をまいた日」の目的語。畑にまく薬剤を指す正しい語。"}, {"text": "花火", "is_correct": false, "explanation": "「畑に花火をまいた日」は意味が成り立たず、文脈に合わない。"}, {"text": "札束", "is_correct": false, "explanation": "「畑に札束をまいた日」は意味が通らず、畑の文脈にも合わない。"}, {"text": "空気", "is_correct": false, "explanation": "「畑に空気をまいた日」は意味が成り立たず、農作業の文脈に合わない。"}], "explanations": {"農薬": "「畑に農薬をまいた日」の目的語。畑にまく薬剤を指す正しい語。", "花火": "「畑に花火をまいた日」は意味が成り立たず、文脈に合わない。", "札束": "「畑に札束をまいた日」は意味が通らず、畑の文脈にも合わない。", "空気": "「畑に空気をまいた日」は意味が成り立たず、農作業の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "農薬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農薬は朝早くから畑に出て、作物の世話をする。", "explanation": "元は〈農家〉。農薬は人ではないので、朝に畑へ出て作業する主語にはならない。"}, {"text": "夕方、農薬を終えた父が、縁側で汗を拭いている。", "explanation": "元は〈農作業〉。農薬は薬剤なので、作業を終えるという言い方には合わない。"}, {"text": "祖父は長年、農薬を営んで家族を支えてきた。", "explanation": "元は〈農業〉。農薬は薬剤で、生業として営む対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑に農薬にまいたあと、雨が降りました。", "corrected_sentence": "畑に農薬をまいたあと、雨が降りました。", "error_description": "「まく」は対象を〈を〉で示す。〈に〉は誤り。正しくは「農薬をまいた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39619, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農薬をまける時期を、農家と相談しました。", "corrected_sentence": "農薬をまく時期を、農家と相談しました。", "error_description": "「まく」を「まける」と誤っている。「まける」は負ける・値引くの意で、薬剤を撒く動作には合わない。正しくは「まく」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「断片」が「見つかった」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「見つかる」は目的語を取らない動詞なので、「を」は不可。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、見つかったという出来事には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、ここでは文の意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「断片」が「見つかった」の主語になる。", "を": "「見つかる」は目的語を取らない動詞なので、「を」は不可。", "へ": "「へ」は移動の方向を示すので、見つかったという出来事には合わない。", "と": "「と」は並列や相手を示すので、ここでは文の意味が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「断片」が「並べて展示してある」の主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、骨の断片が展示された状態を表す文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、断片の出どころを表す読みになり、展示の文とは合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、この文の意味には入らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「断片」が「並べて展示してある」の主語になる。", "へ": "「へ」は方向を示すので、骨の断片が展示された状態を表す文には合わない。", "から": "「から」は起点を示すので、断片の出どころを表す読みになり、展示の文とは合わない。", "より": "「より」は比較を示すので、この文の意味には入らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かの一部が小さく切れて、ばらばらになったもの。", "primary_collocate": null, "pronunciation": "だんぺん", "ipa": "dampeɴ", "syllable_count": 4, "sentences": [{"text": "割れたコップの断片が床に散らばっている。", "target_word": "断片", "complexity_tier": "T3", "furigana": "割[わ]れたコップの断片[だんぺん]が床[ゆか]に散[ち]らばっている。", "sentence_source": "generated"}, {"text": "発掘現場で、古い壺の断片が見つかった。", "target_word": "断片", "complexity_tier": "T3", "furigana": "発掘[はっくつ]現場[げんば]で、古[ふる]い壺[つぼ]の断片[だんぺん]が見[み]つかった。", "sentence_source": "generated"}, {"text": "ガラスの断片で指を切らないように、そっと拾った。", "target_word": "断片", "complexity_tier": "T3", "furigana": "ガラスの断片[だんぺん]で指[ゆび]を切[き]らないように、そっと拾[ひろ]った。", "sentence_source": "generated"}, {"text": "事故のあと、道路に車の断片が落ちていた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、道路[どうろ]に車[くるま]の断片[だんぺん]が落[お]ちていた。", "sentence_source": "generated"}, {"text": "紙を細かく破って、断片をごみ箱に捨てた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "紙[かみ]を細[こま]かく破[やぶ]って、断片[だんぺん]をごみ箱[ばこ]に捨[す]てた。", "sentence_source": "generated"}, {"text": "隕石の断片が、庭から見つかった。", "target_word": "断片", "complexity_tier": "T3", "furigana": "隕石[いんせき]の断片[だんぺん]が、庭[にわ]から見[み]つかった。", "sentence_source": "generated"}, {"text": "割れた皿の断片をつなぎ合わせて、元の形に戻した。", "target_word": "断片", "complexity_tier": "T3", "furigana": "割[わ]れた皿[さら]の断片[だんぺん]をつなぎ合[あ]わせて、元[もと]の形[かたち]に戻[もど]した。", "sentence_source": "generated"}, {"text": "博物館には、動物の骨の断片が並べて展示してある。", "target_word": "断片", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、動物[どうぶつ]の骨[ほね]の断片[だんぺん]が並[なら]べて展示[てんじ]してある。", "sentence_source": "generated"}, {"text": "爆発のあと、壁の断片が遠くまで飛んでいた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "爆発[ばくはつ]のあと、壁[かべ]の断片[だんぺん]が遠[とお]くまで飛[と]んでいた。", "sentence_source": "generated"}, {"text": "木の箱が壊れて、板の断片が畑に落ちていた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "木[き]の箱[はこ]が壊[こわ]れて、板[いた]の断片[だんぺん]が畑[はたけ]に落[お]ちていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断片", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "割れたり切れたりして散らばった物のかけら(ガラス・皿・骨など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断片", "is_correct": true, "explanation": "正解。割れて床に散らばったコップの小さなかけらを指すので、ここに入る。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は刃物で、割れたコップの一部ではないので「割れたコップの〜」に続かない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は床に敷く布で、コップの破片を表さないので文が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は割れたコップの一部として成立せず、床に散らばるものとして意味が通らない。"}], "explanations": {"断片": "正解。割れて床に散らばったコップの小さなかけらを指すので、ここに入る。", "包丁": "包丁は刃物で、割れたコップの一部ではないので「割れたコップの〜」に続かない。", "座布団": "座布団は床に敷く布で、コップの破片を表さないので文が成り立たない。", "財布": "財布は割れたコップの一部として成立せず、床に散らばるものとして意味が通らない。"}, "sentence_index": 0, "correct_answer": "断片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい自転車の断片を取り付けた。", "explanation": "断片に〈部品〉の意味はない。断片は割れたり切れたりして散らばったかけらで、組み立てて取り付ける部品は指さないので合わない。"}, {"text": "花瓶の表面に、大きな断片を塗った。", "explanation": "断片に〈上塗り〉の意味はない。断片は割れてできたかけらで、塗って表面を覆うものは指さないので合わない。"}, {"text": "木を縦に切ると、その断片を電話でつないだ。", "explanation": "断片に〈通話〉の意味はない。断片は切れたかけらで、電話をつないで話す相手にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断片", "is_correct": true, "explanation": "正解。割れた皿の小さなかけらを指し、つなぎ合わせる対象になる。"}, {"text": "切符", "is_correct": false, "explanation": "切符は紙の乗車券で、割れた皿の一部として入らないので文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、皿の一部ではないのでつなぎ合わせる対象にならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、割れた皿の部分として文が意味をなさない。"}], "explanations": {"断片": "正解。割れた皿の小さなかけらを指し、つなぎ合わせる対象になる。", "切符": "切符は紙の乗車券で、割れた皿の一部として入らないので文が成り立たない。", "鉛筆": "鉛筆は筆記具で、皿の一部ではないのでつなぎ合わせる対象にならない。", "冷蔵庫": "冷蔵庫は家電で、割れた皿の部分として文が意味をなさない。"}, "sentence_index": 6, "correct_answer": "断片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場で作った木の箱の断片を出荷した。", "explanation": "断片に〈完成品〉の意味はない。断片は割れたり切れたりして散らばったかけらで、仕上げて出荷する完成品は指さないので合わない。"}, {"text": "木の箱には、きれいな断片がほどこしてある。", "explanation": "断片に〈装飾〉の意味はない。断片は割れや切れ目でできたかけらで、表面を飾るものとしては合わない。"}, {"text": "この木の箱は断片がよく、中の氷が溶けにくい。", "explanation": "断片に〈断熱〉の意味はない。断片は割れた欠片で、熱の伝わりにくさを表す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラス工房の床に、色つきの断片を散らばっていた。", "corrected_sentence": "ガラス工房の床に、色つきの断片が散らばっていた。", "error_description": "「散らばる」は主語を取る自動詞なので、正しくは「断片が」。誤って「断片を」になっている（断片に直接つく助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39620, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床に落ちた皿の断片が、慎重にほうきで集めた。", "corrected_sentence": "床に落ちた皿の断片を、慎重にほうきで集めた。", "error_description": "「集める」は目的語を取る他動詞なので、正しくは「断片を」。誤って「断片が」になっている（断片に直接つく助詞の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "synonym", "options": [{"text": "かけら", "is_correct": true, "explanation": "正解。断片と同じく、全体から切り離された小さな部分を指す。"}, {"text": "全体", "is_correct": false, "explanation": "全体は断片と反対に、まとまった全部を指すので類義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、切り離された部分の意味はない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は台所の刃物で、部分や破片の意味は持たない。"}], "correct_answer": "かけら", "explanations": {"かけら": "正解。断片と同じく、全体から切り離された小さな部分を指す。", "全体": "全体は断片と反対に、まとまった全部を指すので類義語ではない。", "天気": "天気は空模様を指し、切り離された部分の意味はない。", "包丁": "包丁は台所の刃物で、部分や破片の意味は持たない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「断片」が「読み解いた」の目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、読み解く対象を表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、読み解くという行為には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示すので、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「断片」が「読み解いた」の目的語になる。", "に": "「に」は位置や相手を示すので、読み解く対象を表せず不自然。", "へ": "「へ」は方向を示すので、読み解くという行為には合わない。", "と": "「と」は共同や引用を示すので、ここでは文が成り立たない。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "synonym", "options": [{"text": "かけら", "is_correct": true, "explanation": "正解。断片は、より大きな全体から離れた一部分という意味で、かけらと同じ関係にある。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、全体の一部という意味では使われない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、部分を表す語ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、切り離された部分の意味とは無関係。"}], "correct_answer": "かけら", "explanations": {"かけら": "正解。断片は、より大きな全体から離れた一部分という意味で、かけらと同じ関係にある。", "座布団": "座布団は敷物で、全体の一部という意味では使われない。", "鉛筆": "鉛筆は筆記具で、部分を表す語ではない。", "冷蔵庫": "冷蔵庫は家電で、切り離された部分の意味とは無関係。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体の一部が切り離されて、小さくなったかけらや部分。", "primary_collocate": null, "pronunciation": "だんぺん", "ipa": "dampeɴ", "syllable_count": 4, "sentences": [{"text": "昔の記憶の断片が、夢の中によみがえった。", "target_word": "断片", "complexity_tier": "T3", "furigana": "昔[むかし]の記憶[きおく]の断片[だんぺん]が、夢[ゆめ]の中[なか]によみがえった。", "sentence_source": "generated"}, {"text": "古い手紙の断片だけが残っていて、全文は読めない。", "target_word": "断片", "complexity_tier": "T3", "furigana": "古[ふる]い手紙[てがみ]の断片[だんぺん]だけが残[のこ]っていて、全文[ぜんぶん]は読[よ]めない。", "sentence_source": "generated"}, {"text": "会話の断片を聞いただけでは、話の内容は分からない。", "target_word": "断片", "complexity_tier": "T3", "furigana": "会話[かいわ]の断片[だんぺん]を聞[き]いただけでは、話[はなし]の内容[ないよう]は分[わ]からない。", "sentence_source": "generated"}, {"text": "彼の話から、事件の断片が少しずつ見えてきた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]から、事件[じけん]の断片[だんぺん]が少[すこ]しずつ見[み]えてきた。", "sentence_source": "generated"}, {"text": "証言の断片を集めて、順番に並べた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "証言[しょうげん]の断片[だんぺん]を集[あつ]めて、順番[じゅんばん]に並[なら]べた。", "sentence_source": "generated"}, {"text": "映画の断片しか覚えていないので、題名が思い出せない。", "target_word": "断片", "complexity_tier": "T3", "furigana": "映画[えいが]の断片[だんぺん]しか覚[おぼ]えていないので、題名[だいめい]が思[おも]い出[だ]せない。", "sentence_source": "generated"}, {"text": "ニュースの断片をつなぐと、全体の流れが分かる。", "target_word": "断片", "complexity_tier": "T3", "furigana": "ニュースの断片[だんぺん]をつなぐと、全体[ぜんたい]の流[なが]れが分[わ]かる。", "sentence_source": "generated"}, {"text": "遺跡から出た文字の断片を、学者が読み解いた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "遺跡[いせき]から出[で]た文字[もじ]の断片[だんぺん]を、学者[がくしゃ]が読[よ]み解[と]いた。", "sentence_source": "generated"}, {"text": "歌詞の断片を覚えているだけで、曲名は分からない。", "target_word": "断片", "complexity_tier": "T3", "furigana": "歌詞[かし]の断片[だんぺん]を覚[おぼ]えているだけで、曲名[きょくめい]は分[わ]からない。", "sentence_source": "generated"}, {"text": "彼女の言葉の断片から、悩んでいると感じた。", "target_word": "断片", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の言葉[ことば]の断片[だんぺん]から、悩[なや]んでいると感[かん]じた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "断片", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "全体から切り離された一部分(記憶・手紙・話などの残りの部分)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断片", "is_correct": true, "explanation": "正解。記憶の一部がかけらのように切り離されて残ったものを指し、夢によみがえる対象になる。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は台所の刃物で、記憶の一部として文が成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、記憶のかけらとしては意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、夢によみがえる記憶の一部にはならない。"}], "explanations": {"断片": "正解。記憶の一部がかけらのように切り離されて残ったものを指し、夢によみがえる対象になる。", "包丁": "包丁は台所の刃物で、記憶の一部として文が成り立たない。", "座布団": "座布団は敷物で、記憶のかけらとしては意味が通らない。", "天気": "天気は空模様で、夢によみがえる記憶の一部にはならない。"}, "sentence_index": 0, "correct_answer": "断片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼に会った断片を、来年まで延期した。", "explanation": "断片に〈予定〉の意味はない。断片は切り離された一部のかけらで、延期できる予定は指さないので合わない。"}, {"text": "親子の間に、長い断片が生まれた。", "explanation": "断片に〈断絶〉の意味はない。断片は切り離された一部のかけらで、関係が途切れた状態は指さないので合わない。"}, {"text": "彼女の断片を、冷蔵庫で冷やした。", "explanation": "断片に〈食材〉の意味はない。断片は切り離された一部のかけらで、冷やして保存する食材の意味には合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断片", "is_correct": true, "explanation": "正解。ニュースの一部が切り離されたものを指し、つなぐことで全体の流れが分かる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、ニュースの内容としてつなぐ対象にならない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、ニュースの一部として文が成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、ニュースをつないで流れを知る文には合わない。"}], "explanations": {"断片": "正解。ニュースの一部が切り離されたものを指し、つなぐことで全体の流れが分かる。", "鉛筆": "鉛筆は筆記具で、ニュースの内容としてつなぐ対象にならない。", "切符": "切符は乗車券で、ニュースの一部として文が成り立たない。", "冷蔵庫": "冷蔵庫は家電で、ニュースをつないで流れを知る文には合わない。"}, "sentence_index": 6, "correct_answer": "断片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の断片が、ようやく決まった。", "explanation": "断片に〈日程〉の意味はない。断片は切り離された一部のかけらで、いつ行うかの予定は指さないので合わない。"}, {"text": "彼は断片を避けて、答えをあいまいにした。", "explanation": "断片に〈断言〉の意味はない。断片は切り離された一部で、言い切る行為は指さないので合わない。"}, {"text": "彼は断片を決めて、家を出た。", "explanation": "断片に〈覚悟〉の意味はない。覚悟を決めるのは心であり、断片は心を決める対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの頃の思い出の断片を、ふとよみがえってきた。", "corrected_sentence": "子どもの頃の思い出の断片が、ふとよみがえってきた。", "error_description": "「よみがえる」は主語を取る自動詞なので、正しくは「断片が」。誤って「断片を」になっている（断片に直接つく助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39621, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い日記の断片が、丁寧に読み返した。", "corrected_sentence": "古い日記の断片を、丁寧に読み返した。", "error_description": "「読み返す」は目的語を取る他動詞なので、正しくは「断片を」。誤って「断片が」になっている（断片に直接つく助詞の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インフルエンザが蔓延し」の主語を示し、文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "蔓延は目的語を取らないので、「インフルエンザを蔓延し」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「インフルエンザの蔓延し」では文が続かない。「の」は名詞の後に付く。"}, {"text": "へ", "is_correct": false, "explanation": "「インフルエンザへ蔓延し」は方向の意味になり、文の内容に合わない。"}], "correct_answer": "が", "explanations": {"が": "「インフルエンザが蔓延し」の主語を示し、文が自然に続く。", "を": "蔓延は目的語を取らないので、「インフルエンザを蔓延し」は誤り。", "の": "「インフルエンザの蔓延し」では文が続かない。「の」は名詞の後に付く。", "へ": "「インフルエンザへ蔓延し」は方向の意味になり、文の内容に合わない。"}, "error_tags": {"を": "目的語の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終息", "is_correct": true, "explanation": "蔓延の対義語。病気などの広がりが収まり終わることを表す。"}, {"text": "放置", "is_correct": false, "explanation": "そのまま放っておくこと。広がりの反対を表す語ではない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べること。広がりとは対にならない。"}, {"text": "増築", "is_correct": false, "explanation": "建物を増やして大きくすること。広がりの対義語ではない。"}], "correct_answer": "終息", "explanations": {"終息": "蔓延の対義語。病気などの広がりが収まり終わることを表す。", "放置": "そのまま放っておくこと。広がりの反対を表す語ではない。", "点検": "状態を調べること。広がりとは対にならない。", "増築": "建物を増やして大きくすること。広がりの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一気に蔓延する」の副詞的な「に」で、文の流れに合う。"}, {"text": "と", "is_correct": false, "explanation": "「病気と一気に」では並列にならず、文が不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「一気より蔓延する」は比較の意味にならず、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「一気で蔓延する」は不自然。副詞の「一気に」の形が必要。"}], "correct_answer": "に", "explanations": {"に": "「一気に蔓延する」の副詞的な「に」で、文の流れに合う。", "と": "「病気と一気に」では並列にならず、文が不自然になる。", "より": "「一気より蔓延する」は比較の意味にならず、文が通らない。", "で": "「一気で蔓延する」は不自然。副詞の「一気に」の形が必要。"}, "error_tags": {"と": "並列の誤り", "より": "比較の誤り", "で": "副詞形の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終息", "is_correct": true, "explanation": "蔓延の対義語。ウイルスなどの広がりが収まり終わることを表す。"}, {"text": "製造", "is_correct": false, "explanation": "物を作り出すこと。広がりの反対を表す語ではない。"}, {"text": "翻訳", "is_correct": false, "explanation": "ある言語の文章を別の言語に置き換えること。広がりとは対にならない。"}, {"text": "抽選", "is_correct": false, "explanation": "くじで当たりを決めること。広がりの対義語ではない。"}], "correct_answer": "終息", "explanations": {"終息": "蔓延の対義語。ウイルスなどの広がりが収まり終わることを表す。", "製造": "物を作り出すこと。広がりの反対を表す語ではない。", "翻訳": "ある言語の文章を別の言語に置き換えること。広がりとは対にならない。", "抽選": "くじで当たりを決めること。広がりの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気や悪いことが、どんどん広がること。", "primary_collocate": null, "pronunciation": "まんえん", "ipa": "maɴeɴ", "syllable_count": 4, "sentences": [{"text": "冬は風邪が蔓延しやすいので、手洗いが大切だ。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "冬[ふゆ]は風邪[かぜ]が蔓延[まんえん]しやすいので、手洗[てあら]いが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "学校でインフルエンザが蔓延し、いくつかのクラスが休みになった。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "学校[がっこう]でインフルエンザが蔓延[まんえん]し、いくつかのクラスが休[やす]みになった。", "sentence_source": "generated"}, {"text": "早く対策をしないと、病気の蔓延は止められない。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "早[はや]く対策[たいさく]をしないと、病気[びょうき]の蔓延[まんえん]は止[と]められない。", "sentence_source": "generated"}, {"text": "手洗いの習慣が、ウイルスの蔓延を防いでいる。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "手洗[てあら]いの習慣[しゅうかん]が、ウイルスの蔓延[まんえん]を防[ふせ]いでいる。", "sentence_source": "generated"}, {"text": "田んぼに害虫が蔓延して、今年の米は少なくなった。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "田[た]んぼに害虫[がいちゅう]が蔓延[まんえん]して、今年[ことし]の米[こめ]は少[すく]なくなった。", "sentence_source": "generated"}, {"text": "村で病気が蔓延したため、道が閉じられた。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "村[むら]で病気[びょうき]が蔓延[まんえん]したため、道[みち]が閉[と]じられた。", "sentence_source": "generated"}, {"text": "医者は、感染症の蔓延を心配している。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、感染症[かんせんしょう]の蔓延[まんえん]を心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "水が汚れていると、病気が一気に蔓延する。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "水[みず]が汚[よご]れていると、病気[びょうき]が一気[いっき]に蔓延[まんえん]する。", "sentence_source": "generated"}, {"text": "ワクチンのおかげで、この病気の蔓延はおさまった。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "ワクチンのおかげで、この病気[びょうき]の蔓延[まんえん]はおさまった。", "sentence_source": "generated"}, {"text": "人が集まる場所では、ウイルスが蔓延しやすい。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "人[ひと]が集[あつ]まる場所[ばしょ]では、ウイルスが蔓延[まんえん]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蔓延", "label": "基本形"}, {"form": "蔓延する", "label": "する動詞 終止形"}, {"form": "蔓延した", "label": "過去形"}, {"form": "蔓延して", "label": "て形"}, {"form": "蔓延しやすい", "label": "やすい形"}], "register": "formal", "sense_fingerprint": "病気や害虫など望ましくないものが、勢いよく広がっていくこと。する動詞としても使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蔓延", "is_correct": true, "explanation": "「風邪が蔓延しやすい」は病気が広がりやすいという意味になり、文に合う。"}, {"text": "収穫", "is_correct": false, "explanation": "「風邪が収穫しやすい」は成り立たない。収穫は作物を取り入れることで、病気には使わない。"}, {"text": "解散", "is_correct": false, "explanation": "「風邪が解散しやすい」は意味が通らない。解散は集まりを終えることを指す。"}, {"text": "開設", "is_correct": false, "explanation": "「風邪が開設しやすい」は不自然。開設は施設などを新しく設けることで、病気の広がりには使わない。"}], "explanations": {"蔓延": "「風邪が蔓延しやすい」は病気が広がりやすいという意味になり、文に合う。", "収穫": "「風邪が収穫しやすい」は成り立たない。収穫は作物を取り入れることで、病気には使わない。", "解散": "「風邪が解散しやすい」は意味が通らない。解散は集まりを終えることを指す。", "開設": "「風邪が開設しやすい」は不自然。開設は施設などを新しく設けることで、病気の広がりには使わない。"}, "sentence_index": 0, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この服は去年から蔓延している。", "explanation": "ここは〈流行〉の意味。蔓延は病気や悪いことが広がる時に使い、服の人気には使わない。"}, {"text": "この新しい掃除機は、もう家庭に蔓延した。", "explanation": "ここは〈普及〉の意味。蔓延は望ましくないものが広がる時に使い、良い製品が行き渡る時には使わない。"}, {"text": "この店の名前は町中に蔓延している。", "explanation": "ここは〈広まる〉の意味。蔓延は悪いことにだけ使い、店の名前が知られていく時には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔓延", "is_correct": true, "explanation": "「感染症の蔓延を心配している」で、感染症が広がることへの心配として自然。"}, {"text": "配達", "is_correct": false, "explanation": "「感染症の配達を心配」は意味が通らない。配達は物を届けること。"}, {"text": "解体", "is_correct": false, "explanation": "「感染症の解体を心配」は不自然。解体は建物などをこわすこと。"}, {"text": "採掘", "is_correct": false, "explanation": "「感染症の採掘を心配」は成り立たない。採掘は地下の資源を掘り出すこと。"}], "explanations": {"蔓延": "「感染症の蔓延を心配している」で、感染症が広がることへの心配として自然。", "配達": "「感染症の配達を心配」は意味が通らない。配達は物を届けること。", "解体": "「感染症の解体を心配」は不自然。解体は建物などをこわすこと。", "採掘": "「感染症の採掘を心配」は成り立たない。採掘は地下の資源を掘り出すこと。"}, "sentence_index": 6, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "そのレストランは、いつも客で蔓延している。", "explanation": "ここは〈満員〉の意味。蔓延は望ましくないものが広がる時に使い、客が多く集まる様子には使わない。"}, {"text": "この歌は子どもの間で蔓延して、だれもが口ずさむ。", "explanation": "ここは〈大ヒット〉の意味。蔓延は悪いことが広がる時に使い、歌が人気を集める時には使わない。"}, {"text": "町の人口が蔓延して、学校が足りなくなった。", "explanation": "ここは〈増加〉の意味。蔓延は望ましくないものが広がる時に使い、人口が増える時には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ワクチンは感染症の蔓延に防ぐ。", "corrected_sentence": "ワクチンは感染症の蔓延を防ぐ。", "error_description": "「防ぐ」は目的語に「を」を取る。「蔓延に」は助詞の誤りで、正しくは「蔓延を防ぐ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この病気は冬に蔓延しやすくい。", "corrected_sentence": "この病気は冬に蔓延しやすい。", "error_description": "「しやすい」はい形容詞なので語末は「い」。「しやすくい」は語形の誤りで、正しくは「蔓延しやすい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「うその情報が蔓延して」の主語を示し、文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "蔓延は目的語を取らないので、「情報を蔓延して」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「情報の蔓延して」では文が続かない。「の」は名詞の後に付く。"}, {"text": "へ", "is_correct": false, "explanation": "「情報へ蔓延して」は方向の意味になり、文の内容に合わない。"}], "correct_answer": "が", "explanations": {"が": "「うその情報が蔓延して」の主語を示し、文が自然に続く。", "を": "蔓延は目的語を取らないので、「情報を蔓延して」は誤り。", "の": "「情報の蔓延して」では文が続かない。「の」は名詞の後に付く。", "へ": "「情報へ蔓延して」は方向の意味になり、文の内容に合わない。"}, "error_tags": {"を": "目的語の誤り", "の": "連体修飾の誤り", "へ": "方向の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終息", "is_correct": true, "explanation": "蔓延の対義語。悪い習慣や問題の広がりが収まり終わることを表す。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。広がりの反対を表す語ではない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べること。広がりとは対にならない。"}, {"text": "開設", "is_correct": false, "explanation": "施設などを新しく設けること。広がりの対義語ではない。"}], "correct_answer": "終息", "explanations": {"終息": "蔓延の対義語。悪い習慣や問題の広がりが収まり終わることを表す。", "解散": "集まりを解くこと。広がりの反対を表す語ではない。", "点検": "状態を調べること。広がりとは対にならない。", "開設": "施設などを新しく設けること。広がりの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スマホ依存が蔓延し」の主語を示し、文が自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "「スマホ依存と蔓延し」は並列の意味になり、文が不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「依存より蔓延し」では文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "蔓延は目的語を取らないので、「依存を蔓延し」は誤り。"}], "correct_answer": "が", "explanations": {"が": "「スマホ依存が蔓延し」の主語を示し、文が自然に続く。", "と": "「スマホ依存と蔓延し」は並列の意味になり、文が不自然になる。", "より": "比較を示すが、「依存より蔓延し」では文が通らない。", "を": "蔓延は目的語を取らないので、「依存を蔓延し」は誤り。"}, "error_tags": {"と": "並列の誤り", "より": "比較の誤り", "を": "目的語の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終息", "is_correct": true, "explanation": "蔓延の対義語。望ましくない空気や問題の広がりが収まることを表す。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すこと。広がりの反対を表す語ではない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作り出すこと。広がりとは対にならない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けること。広がりの対義語ではない。"}], "correct_answer": "終息", "explanations": {"終息": "蔓延の対義語。望ましくない空気や問題の広がりが収まることを表す。", "採掘": "地下の資源を掘り出すこと。広がりの反対を表す語ではない。", "製造": "物を作り出すこと。広がりとは対にならない。", "配達": "物を届けること。広がりの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気や悪い出来事、考えなどが、広く行き渡ること。広がること。", "primary_collocate": null, "pronunciation": "まんえん", "ipa": "maɴeɴ", "syllable_count": 4, "sentences": [{"text": "会社に不正が蔓延し、社員の信頼がなくなった。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "会社[かいしゃ]に不正[ふせい]が蔓延[まんえん]し、社員[しゃいん]の信頼[しんらい]がなくなった。", "sentence_source": "generated"}, {"text": "ネットにうその情報が蔓延して、多くの人が混乱した。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "ネットにうその情報[じょうほう]が蔓延[まんえん]して、多[おお]くの人[ひと]が混乱[こんらん]した。", "sentence_source": "generated"}, {"text": "町に不安が蔓延していたが、市長の言葉で少し落ち着いた。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "町[まち]に不安[ふあん]が蔓延[まんえん]していたが、市長[しちょう]の言葉[ことば]で少[すこ]し落[お]ち着[つ]いた。", "sentence_source": "generated"}, {"text": "悪い習慣が蔓延する前に、学校で教えるべきだ。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "悪[わる]い習慣[しゅうかん]が蔓延[まんえん]する前[まえ]に、学校[がっこう]で教[おし]えるべきだ。", "sentence_source": "generated"}, {"text": "「どうせ無理だ」という考えの蔓延が、若者の力を奪っている。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "「どうせ無理[むり]だ」という考[かんが]えの蔓延[まんえん]が、若者[わかもの]の力[ちから]を奪[うば]っている。", "sentence_source": "generated"}, {"text": "昔は、国中に貧困が蔓延していた。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "昔[むかし]は、国中[くにじゅう]に貧困[ひんこん]が蔓延[まんえん]していた。", "sentence_source": "generated"}, {"text": "汚職の蔓延は、国の力を弱める。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "汚職[おしょく]の蔓延[まんえん]は、国[くに]の力[ちから]を弱[よわ]める。", "sentence_source": "generated"}, {"text": "スマホ依存が蔓延し、会話の時間が減った家庭が多い。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "スマホ依存[いぞん]が蔓延[まんえん]し、会話[かいわ]の時間[じかん]が減[へ]った家庭[かてい]が多[おお]い。", "sentence_source": "generated"}, {"text": "暴力が蔓延する社会では、人は安心して暮らせない。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "暴力[ぼうりょく]が蔓延[まんえん]する社会[しゃかい]では、人[ひと]は安心[あんしん]して暮[く]らせない。", "sentence_source": "generated"}, {"text": "あきらめの空気が職場に蔓延している。", "target_word": "蔓延", "complexity_tier": "T3", "furigana": "あきらめの空気[くうき]が職場[しょくば]に蔓延[まんえん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蔓延", "label": "基本形"}, {"form": "蔓延する", "label": "する動詞 終止形"}, {"form": "蔓延した", "label": "過去形"}, {"form": "蔓延して", "label": "て形"}, {"form": "蔓延している", "label": "ている形"}], "register": "formal", "sense_fingerprint": "不正・不安・悪い考えなど望ましくないものが、社会や組織の中に広く行き渡ること。する動詞としても使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蔓延", "is_correct": true, "explanation": "「会社に不正が蔓延し」で、不正が組織に広く行き渡るという意味に合う。"}, {"text": "増築", "is_correct": false, "explanation": "「不正が増築し」は成り立たない。増築は建物を増やすこと。"}, {"text": "寄付", "is_correct": false, "explanation": "「不正が寄付し」は意味が通らない。寄付は金品を差し出すこと。"}, {"text": "清掃", "is_correct": false, "explanation": "「不正が清掃し」は不自然。清掃は場所をきれいにすること。"}], "explanations": {"蔓延": "「会社に不正が蔓延し」で、不正が組織に広く行き渡るという意味に合う。", "増築": "「不正が増築し」は成り立たない。増築は建物を増やすこと。", "寄付": "「不正が寄付し」は意味が通らない。寄付は金品を差し出すこと。", "清掃": "「不正が清掃し」は不自然。清掃は場所をきれいにすること。"}, "sentence_index": 0, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "思いやりが社会に蔓延した。", "explanation": "ここは〈浸透〉の意味。蔓延は望ましくないものが広がる時に使い、思いやりのような良い考えには使わない。"}, {"text": "その感動が会場中に蔓延した。", "explanation": "ここは〈伝わる〉の意味。蔓延は悪いことが広がる時に使い、感動が伝わる時には使わない。"}, {"text": "会場は熱気で蔓延していた。", "explanation": "ここは〈満ちる〉の意味。蔓延は望ましくないものが広がる時に使い、熱気があふれる様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔓延", "is_correct": true, "explanation": "「汚職の蔓延は、国の力を弱める」で、汚職が社会に広がることを表し自然。"}, {"text": "翻訳", "is_correct": false, "explanation": "「汚職の翻訳は」は成り立たない。翻訳は言語を置き換えること。"}, {"text": "抽選", "is_correct": false, "explanation": "「汚職の抽選は」は意味が通らない。抽選はくじで決めること。"}, {"text": "製図", "is_correct": false, "explanation": "「汚職の製図は」は不自然。製図は図面を描くこと。"}], "explanations": {"蔓延": "「汚職の蔓延は、国の力を弱める」で、汚職が社会に広がることを表し自然。", "翻訳": "「汚職の翻訳は」は成り立たない。翻訳は言語を置き換えること。", "抽選": "「汚職の抽選は」は意味が通らない。抽選はくじで決めること。", "製図": "「汚職の製図は」は不自然。製図は図面を描くこと。"}, "sentence_index": 6, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの歌手の人気が国中に蔓延している。", "explanation": "ここは〈知名度が上がる〉の意味。蔓延は望ましくないものが広がる時に使い、人が広く知られるようになる様子には使わない。"}, {"text": "会社の利益が蔓延した。", "explanation": "ここは〈増加〉の意味。蔓延は悪いことが広がる時に使い、利益が増える時には使わない。"}, {"text": "そのお店の親切さが、人から人へと蔓延していった。", "explanation": "ここは〈広まる〉の意味。蔓延は病気や悪いことが広がる時に使い、よい行いが人づてに広がる時には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不安が社会を蔓延している。", "corrected_sentence": "不安が社会に蔓延している。", "error_description": "「蔓延」は場所を「に」で示す。「社会を蔓延」の「を」は誤りで、正しくは「社会に蔓延している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39623, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汚職が社会に蔓延ていた。", "corrected_sentence": "汚職が社会に蔓延していた。", "error_description": "「蔓延」はする動詞の名詞なので、て形は「蔓延して」。「し」が抜けた「蔓延ていた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「落ち葉が重なって」の主語を示し、文が自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "重なるは目的語を取らないので、「落ち葉を重なって」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「落ち葉の重なって」では文が続かない。「の」は名詞の後に付く。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「落ち葉より重なって」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「落ち葉が重なって」の主語を示し、文が自然に続く。", "を": "重なるは目的語を取らないので、「落ち葉を重なって」は誤り。", "の": "「落ち葉の重なって」では文が続かない。「の」は名詞の後に付く。", "より": "比較を示すが、「落ち葉より重なって」では意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
