INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかのものが、同じところにのること。", "primary_collocate": null, "pronunciation": "かさなる", "ipa": "kasanaɾɯ", "syllable_count": 4, "sentences": [{"text": "机の上に本が重なっている。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に本[ほん]が重[かさ]なっている。", "sentence_source": "generated"}, {"text": "落ち葉が重なって、道がやわらかくなった。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]が重[かさ]なって、道[みち]がやわらかくなった。", "sentence_source": "generated"}, {"text": "皿が重なると、下の皿を取り出しにくい。", "target_word": "重なる", "complexity_tier": "T3", "furigana": "皿[さら]が重[かさ]なると、下[した]の皿[さら]を取[と]り出[だ]しにくい。", "sentence_source": "generated"}, {"text": "木の枝が重なって、日の光が地面まで届かない。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]が重[かさ]なって、日[ひ]の光[ひかり]が地面[じめん]まで届[とど]かない。", "sentence_source": "generated"}, {"text": "二つの円が重なる部分を、青くぬった。", "target_word": "重なる", "complexity_tier": "T3", "furigana": "二[ふた]つの円[えん]が重[かさ]なる部分[ぶぶん]を、青[あお]くぬった。", "sentence_source": "generated"}, {"text": "洗った皿が重なっているので、乾きにくい。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "洗[あら]った皿[さら]が重[かさ]なっているので、乾[かわ]きにくい。", "sentence_source": "generated"}, {"text": "二枚の紙が重なると、字が透けて読みにくい。", "target_word": "重なる", "complexity_tier": "T3", "furigana": "二枚[にまい]の紙[かみ]が重[かさ]なると、字[じ]が透[す]けて読[よ]みにくい。", "sentence_source": "generated"}, {"text": "箱が何段も重なっていて、いちばん下が見えない。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "箱[はこ]が何段[なんだん]も重[かさ]なっていて、いちばん下[した]が見[み]えない。", "sentence_source": "generated"}, {"text": "山が重なって見えて、遠くの景色はぼんやりしている。", "target_word": "重なって", "complexity_tier": "T3", "furigana": "山[やま]が重[かさ]なって見[み]えて、遠[とお]くの景色[けしき]はぼんやりしている。", "sentence_source": "generated"}, {"text": "洗濯物が重なったまま、乾いていなかった。", "target_word": "重なった", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]が重[かさ]なったまま、乾[かわ]いていなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重なる", "label": "終止形"}, {"form": "重なり", "label": "連用形"}, {"form": "重なって", "label": "て形"}, {"form": "重なった", "label": "過去形"}, {"form": "重ならない", "label": "否定形"}, {"form": "重なれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "複数の物が上や同じ位置にのって、重なった状態になること。自動詞（五段）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e98ef48-57f9-48e9-8d82-e4547e310132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重なって", "is_correct": true, "explanation": "「本が重なっている」の「重なって」で、本が上にのっている様子に合う。"}, {"text": "重なり", "is_correct": false, "explanation": "「重なりいる」の形は成り立たない。連用形は「いる」に直接続かない。"}, {"text": "重なった", "is_correct": false, "explanation": "「重なったいる」は誤り。過去形は「いる」の前に続けられない。"}, {"text": "重ならない", "is_correct": false, "explanation": "「重ならないいる」は文法的に成り立たず、重なっていない意味にもならない。"}], "explanations": {"重なって": "「本が重なっている」の「重なって」で、本が上にのっている様子に合う。", "重なり": "「重なりいる」の形は成り立たない。連用形は「いる」に直接続かない。", "重なった": "「重なったいる」は誤り。過去形は「いる」の前に続けられない。", "重ならない": "「重ならないいる」は文法的に成り立たず、重なっていない意味にもならない。"}, "sentence_index": 0, "correct_answer": "重なって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "東京と大阪は重なっている。", "explanation": "ここは〈近い〉の意味。重なるは物が上や同じ場所にのる時に使い、離れた都市には使わない。"}, {"text": "道の両側に店が重なっている。", "explanation": "ここは〈並ぶ〉の意味。横に並んでいる店には、上にのる意味の重なるは使わない。"}, {"text": "お客さんは、レジの前に一列に重なって待っている。", "explanation": "ここは〈行列する〉の意味。重なるは物が上にのる時に使い、人が前後に一列で待つ様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重なる", "is_correct": true, "explanation": "「二枚の紙が重なると、字が透けて読みにくい」の条件を示す終止形で、文に合う。"}, {"text": "重ねる", "is_correct": false, "explanation": "重ねるは他動詞で、「紙が重ねると」は主語と合わず不自然。"}, {"text": "重なりたい", "is_correct": false, "explanation": "「重なりたいと」は文が成り立たない。願望の形は条件の「と」に続かない。"}, {"text": "重なりました", "is_correct": false, "explanation": "丁寧な過去形で、条件の「と」にはつながらない。"}], "explanations": {"重なる": "「二枚の紙が重なると、字が透けて読みにくい」の条件を示す終止形で、文に合う。", "重ねる": "重ねるは他動詞で、「紙が重ねると」は主語と合わず不自然。", "重なりたい": "「重なりたいと」は文が成り立たない。願望の形は条件の「と」に続かない。", "重なりました": "丁寧な過去形で、条件の「と」にはつながらない。"}, "sentence_index": 6, "correct_answer": "重なる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕日が重なって、空が暗くなった。", "explanation": "ここは〈沈む〉の意味。重なるは物が上にのる時に使い、太陽が地平線の向こうに隠れる様子には使わない。"}, {"text": "島々が海に重なっている。", "explanation": "ここは〈点在する〉の意味。島が散らばる様子は、上にのる意味の重なるでは表せない。"}, {"text": "二人の誕生日は重なっている。", "explanation": "ここは〈同じ日になる〉の意味。日付が同時になる意味で、物が上にのる意味の重なるとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根の瓦が重なりている。", "corrected_sentence": "屋根の瓦が重なっている。", "error_description": "「重なっている」は「重なって＋いる」の形。「重なりている」は連用形に「ている」を続けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重なって", "is_correct": true, "explanation": "「落ち葉が重なって、道がやわらかくなった」の原因を示す「て形」で正しい。"}, {"text": "重なる", "is_correct": false, "explanation": "終止形のままでは「、」で続く原因の文として成り立たない。"}, {"text": "重なれ", "is_correct": false, "explanation": "命令形は文の途中に置けず、文が続かない。"}, {"text": "重なろう", "is_correct": false, "explanation": "意向形は文の途中に置けず、文が続かない。"}], "correct_form": "重なって", "base_form": "重なる", "form_label": "て形", "sentence_index": 1, "explanations": {"重なって": "「落ち葉が重なって、道がやわらかくなった」の原因を示す「て形」で正しい。", "重なる": "終止形のままでは「、」で続く原因の文として成り立たない。", "重なれ": "命令形は文の途中に置けず、文が続かない。", "重なろう": "意向形は文の途中に置けず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39624, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪が屋根の上を重なっている。", "corrected_sentence": "雪が屋根の上に重なっている。", "error_description": "重なるは「〜に重なる」の形で場所を「に」で示す。「上を重なって」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重なって", "is_correct": true, "explanation": "「箱が何段も重なっていて、いちばん下が見えない」の「て形」で正しい。"}, {"text": "重なるな", "is_correct": false, "explanation": "禁止形で、「何段も重なるな」は文が続かず、文の意味に合わない。"}, {"text": "重なれる", "is_correct": false, "explanation": "可能形の「重なれる」は、箱の状態を述べる文の形と合わない。"}, {"text": "重ならず", "is_correct": false, "explanation": "否定の連用形で、「何段も重ならず」は下が見えない状態の説明と矛盾する。"}], "correct_form": "重なって", "base_form": "重なる", "form_label": "て形", "sentence_index": 7, "explanations": {"重なって": "「箱が何段も重なっていて、いちばん下が見えない」の「て形」で正しい。", "重なるな": "禁止形で、「何段も重なるな」は文が続かず、文の意味に合わない。", "重なれる": "可能形の「重なれる」は、箱の状態を述べる文の形と合わない。", "重ならず": "否定の連用形で、「何段も重ならず」は下が見えない状態の説明と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '954601f7-fb85-4b3b-bbef-964d55d261b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『蜂群が』は、空を黒く染める動作の主語を示す。主語には『が』を付ける。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や対象を示すため、染める動作の主語にはならない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、『空を』と重なるため『蜂群を空を』は非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『蜂群が』は、空を黒く染める動作の主語を示す。主語には『が』を付ける。", "に": "『に』は相手や対象を示すため、染める動作の主語にはならない。", "を": "『を』は目的語を示すが、『空を』と重なるため『蜂群を空を』は非文になる。", "へ": "『へ』は方向を示すため、主語にはならない。"}, "error_tags": {"に": "相手・対象", "を": "目的語の重複", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『蜂群は』は、夕方になると巣へ戻る話題の主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "『戻る』は自動詞なので『を』は目的語を取れず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すため、戻る主体の役割は果たせない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すため、戻る主体にはならない。"}], "correct_answer": "は", "explanations": {"は": "『蜂群は』は、夕方になると巣へ戻る話題の主題を示す。", "を": "『戻る』は自動詞なので『を』は目的語を取れず、不自然。", "より": "『より』は比較の基準を示すため、戻る主体の役割は果たせない。", "から": "『から』は起点を示すため、戻る主体にはならない。"}, "error_tags": {"を": "目的語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みつばちのむれのことです。たくさんのみつばちが一しょにとんでいるすがたをいいます。", "primary_collocate": null, "pronunciation": "ほうぐん", "ipa": "hoːɡɯɴ", "syllable_count": 4, "sentences": [{"text": "巣箱から蜂群が一斉に飛び立った。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "巣箱[すばこ]から蜂群[ほうぐん]が一斉[いっせい]に飛[と]び立[た]った。", "sentence_source": "generated"}, {"text": "蜂群が空を黒く染めていた。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "蜂群[ほうぐん]が空[そら]を黒[くろ]く染[そ]めていた。", "sentence_source": "generated"}, {"text": "蜂群が近づいてきたので、私たちは静かに離れた。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "蜂群[ほうぐん]が近[ちか]づいてきたので、私[わたし]たちは静[しず]かに離[はな]れた。", "sentence_source": "generated"}, {"text": "春になると、蜂群が花畑へ向かう。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "春[はる]になると、蜂群[ほうぐん]が花畑[はなばたけ]へ向[む]かう。", "sentence_source": "generated"}, {"text": "養蜂家は蜂群の動きをじっと見守った。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "養蜂家[ようほうか]は蜂群[ほうぐん]の動[うご]きをじっと見守[みまも]った。", "sentence_source": "generated"}, {"text": "大きな蜂群が木の枝に集まっている。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "大[おお]きな蜂群[ほうぐん]が木[き]の枝[えだ]に集[あつ]まっている。", "sentence_source": "generated"}, {"text": "蜂群の羽音が遠くから聞こえた。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "蜂群[ほうぐん]の羽音[はおと]が遠[とお]くから聞[き]こえた。", "sentence_source": "generated"}, {"text": "蜂群は夕方になると巣へ戻る。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "蜂群[ほうぐん]は夕方[ゆうがた]になると巣[す]へ戻[もど]る。", "sentence_source": "generated"}, {"text": "煙を使うと、蜂群は落ち着く。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "煙[けむり]を使[つか]うと、蜂群[ほうぐん]は落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "蜂群に出会ったら、走らずにゆっくり下がろう。", "target_word": "蜂群", "complexity_tier": "T3", "furigana": "蜂群[ほうぐん]に出会[であ]ったら、走[はし]らずにゆっくり下[さ]がろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜂群", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "みつばちのむれ、とんでいるすがた", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 下がろ (Zipf 1.83)']::text[], '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜂群", "is_correct": true, "explanation": "巣箱から一斉に飛び立つのは、ミツバチの集団である蜂群。文の主語として自然につながる。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "蜂蜜は液体の食品で、飛び立つことはない。"}, {"text": "巣房", "is_correct": false, "explanation": "巣房は巣の中の六角形の部屋で、飛ぶものではない。"}, {"text": "養蜂家", "is_correct": false, "explanation": "養蜂家は人なので、巣箱から一斉に飛び立つ主語にはならない。"}], "explanations": {"蜂群": "巣箱から一斉に飛び立つのは、ミツバチの集団である蜂群。文の主語として自然につながる。", "蜂蜜": "蜂蜜は液体の食品で、飛び立つことはない。", "巣房": "巣房は巣の中の六角形の部屋で、飛ぶものではない。", "養蜂家": "養蜂家は人なので、巣箱から一斉に飛び立つ主語にはならない。"}, "sentence_index": 0, "correct_answer": "蜂群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渡り鳥の蜂群が、秋の空を南へ渡っていった。", "explanation": "ここは〈群れ〉の意味。蜂群はミツバチの集まりに限るので、渡り鳥の群れには使わない。"}, {"text": "瓶に詰めた蜂群を、朝のパンにたっぷり塗った。", "explanation": "ここは〈蜂蜜〉の意味。瓶に詰めてパンに塗るのは蜂蜜で、蜂群は蜜ではなくミツバチの集まりを指すので合わない。"}, {"text": "この蜂群は木製で、箱の四隅がしっかり組まれている。", "explanation": "ここは〈巣箱〉の意味。木で組み立てた箱を指すのは巣箱で、蜂群は箱ではなくミツバチの集まりなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜂群", "is_correct": true, "explanation": "羽音を立てるのは、ミツバチの集まりである蜂群。『の羽音』と直接つながる。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は粉で、羽音を立てることはない。"}, {"text": "巣板", "is_correct": false, "explanation": "巣板は蜜蝋でできた板で、音は出さない。"}, {"text": "蜜源", "is_correct": false, "explanation": "蜜源は蜜のとれる花や場所を指すので、羽音を立てる主体ではない。"}], "explanations": {"蜂群": "羽音を立てるのは、ミツバチの集まりである蜂群。『の羽音』と直接つながる。", "花粉": "花粉は粉で、羽音を立てることはない。", "巣板": "巣板は蜜蝋でできた板で、音は出さない。", "蜜源": "蜜源は蜜のとれる花や場所を指すので、羽音を立てる主体ではない。"}, "sentence_index": 6, "correct_answer": "蜂群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "散歩中、足元を一匹の蜂群がふらふら飛んでいた。", "explanation": "ここは〈働き蜂〉の意味。一匹で飛ぶ個体は働き蜂で、蜂群は集団を指すので『一匹の』とは合わない。"}, {"text": "巣の奥では、蜂群が毎日千個の卵を産んでいる。", "explanation": "ここは〈女王蜂〉の意味。卵を産むのは一匹の女王で、群れ全体である蜂群は産卵の主体にならない。"}, {"text": "花から蜂群を集めて、巣へ運ぶ。", "explanation": "ここは〈蜜〉の意味。花から集めて巣へ運ぶのは蜜で、蜂群は蜜ではなくミツバチの集まりを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜂群に夕暮れの空を黒く染めながら、川の向こうへ飛んでいった。", "corrected_sentence": "蜂群が夕暮れの空を黒く染めながら、川の向こうへ飛んでいった。", "error_description": "主語は『が』で示す。『蜂群に』の『に』では蜂群が染める動作の主体にならず、文として不自然。正しくは『蜂群が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜂群が朝の光を浴びて、いっせいに羽ばたきた。", "corrected_sentence": "蜂群が朝の光を浴びて、いっせいに羽ばたいた。", "error_description": "『羽ばたく』の過去形は『羽ばたいた』。『羽ばたきた』は活用を誤った形で、正しくは『羽ばたいた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
