INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「症候」が「書かれていた」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「書かれる」は目的語を取らない受身の形なので、「を」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、症候が主語になる文の意味が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、症候の出どころを表す読みになり、この文とは合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「症候」が「書かれていた」の主語になる。", "を": "「書かれる」は目的語を取らない受身の形なので、「を」は不自然。", "で": "「で」は手段や場所を示すので、症候が主語になる文の意味が成り立たない。", "から": "「から」は起点を示すので、症候の出どころを表す読みになり、この文とは合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "びょうきのしるし。", "primary_collocate": null, "pronunciation": "しょうこう", "ipa": "ɕoːkoː", "syllable_count": 4, "sentences": [{"text": "医者は患者の症候を丁寧に調べて、病気の種類を考えた。", "target_word": "症候", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の症候[しょうこう]を丁寧[ていねい]に調[しら]べて、病気[びょうき]の種類[しゅるい]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "初期の症候は軽いので、気づかないまま過ごす人も多い。", "target_word": "症候", "complexity_tier": "T3", "furigana": "初期[しょき]の症候[しょうこう]は軽[かる]いので、気[き]づかないまま過[す]ごす人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "この病気には、はっきりした症候がほとんど現れない。", "target_word": "症候", "complexity_tier": "T3", "furigana": "この病気[びょうき]には、はっきりした症候[しょうこう]がほとんど現[あらわ]れない。", "sentence_source": "generated"}, {"text": "熱やせきなどの症候が出たら、早めに病院へ行くべきだ。", "target_word": "症候", "complexity_tier": "T3", "furigana": "熱[ねつ]やせきなどの症候[しょうこう]が出[で]たら、早[はや]めに病院[びょういん]へ行[い]くべきだ。", "sentence_source": "generated"}, {"text": "祖母の症候を見逃したせいで、治療が遅れてしまった。", "target_word": "症候", "complexity_tier": "T3", "furigana": "祖母[そぼ]の症候[しょうこう]を見逃[みのが]したせいで、治療[ちりょう]が遅[おく]れてしまった。", "sentence_source": "generated"}, {"text": "医学生は、病気ごとの症候を覚えなければならない。", "target_word": "症候", "complexity_tier": "T3", "furigana": "医学生[いがくせい]は、病気[びょうき]ごとの症候[しょうこう]を覚[おぼ]えなければならない。", "sentence_source": "generated"}, {"text": "症候が消えても、薬は最後まで飲み続ける必要がある。", "target_word": "症候", "complexity_tier": "T3", "furigana": "症候[しょうこう]が消[き]えても、薬[くすり]は最後[さいご]まで飲[の]み続[つづ]ける必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "本には、その病気に特有の症候が詳しく書かれていた。", "target_word": "症候", "complexity_tier": "T3", "furigana": "本[ほん]には、その病気[びょうき]に特有[とくゆう]の症候[しょうこう]が詳[くわ]しく書[か]かれていた。", "sentence_source": "generated"}, {"text": "症候が似ているので、二つの病気を区別するのは難しい。", "target_word": "症候", "complexity_tier": "T3", "furigana": "症候[しょうこう]が似[に]ているので、二[ふた]つの病気[びょうき]を区別[くべつ]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "目が黄色くなるのは、肝臓の病気を示す症候の一つだ。", "target_word": "症候", "complexity_tier": "T3", "furigana": "目[め]が黄色[きいろ]くなるのは、肝臓[かんぞう]の病気[びょうき]を示[しめ]す症候[しょうこう]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "症候", "label": "基本形"}], "register": "文章語・医学（常体）", "sense_fingerprint": "病気の存在を示すしるし。診断の手がかりになる症状・兆し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "症候", "is_correct": true, "explanation": "正解。病気のしるしを指し、医者が患者について丁寧に調べる対象になる。"}, {"text": "財布", "is_correct": false, "explanation": "財布は持ち物で、患者の病気のしるしとして調べる対象にならない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様で、患者の状態を調べて病気の種類を考える対象にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、患者の状態を調べる対象にならないので文が成り立たない。"}], "explanations": {"症候": "正解。病気のしるしを指し、医者が患者について丁寧に調べる対象になる。", "財布": "財布は持ち物で、患者の病気のしるしとして調べる対象にならない。", "天候": "天候は空模様で、患者の状態を調べて病気の種類を考える対象にはならない。", "座布団": "座布団は敷物で、患者の状態を調べる対象にならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "症候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病気には、新しい症候が開発された。", "explanation": "症候に〈治療〉の意味はない。症候は病気のしるしで、病気を治す方法や薬は指さないので合わない。"}, {"text": "医学会で、この病気の症候を三件報告した。", "explanation": "症候に〈症例〉の意味はない。症候は体に現れるしるしで、事例として件数を数える語ではないので合わない。"}, {"text": "予防接種で、症候をつけた。", "explanation": "症候に〈免疫〉の意味はない。症候は病気のときに現れるしるしで、抵抗力を指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "症候", "is_correct": true, "explanation": "正解。病気のしるしを指し、消えるとその後の薬の服用を続ける理由になる。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、消えても薬を飲み続ける話とつながらない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は刃物で、体の状態として消える対象にならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、消えることと薬の服用の文脈がつながらない。"}], "explanations": {"症候": "正解。病気のしるしを指し、消えるとその後の薬の服用を続ける理由になる。", "切符": "切符は乗車券で、消えても薬を飲み続ける話とつながらない。", "包丁": "包丁は刃物で、体の状態として消える対象にならない。", "鉛筆": "鉛筆は文房具で、消えることと薬の服用の文脈がつながらない。"}, "sentence_index": 6, "correct_answer": "症候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は症候で静かに眠っていた。", "explanation": "症候に〈病床〉の意味はない。症候は病気のしるしで、寝る場所を表さないので合わない。"}, {"text": "薬の症候は三年だと書いてある。", "explanation": "症候に〈寿命〉の意味はない。症候は病気のしるしで、使える期間は表さないので合わない。"}, {"text": "病気の症候には、手洗いがいちばん大切だ。", "explanation": "症候に〈予防〉の意味はない。症候は病気が起きたあとに現れるしるしで、病気を防ぐ手段は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "めまいの症候を続くときは、無理をせず休むべきだ。", "corrected_sentence": "めまいの症候が続くときは、無理をせず休むべきだ。", "error_description": "「続く」は主語を取る自動詞なので、正しくは「症候が」。誤って「症候を」になっている（症候に直接つく助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "頭痛の症候が感じたら、早めに休むべきだ。", "corrected_sentence": "頭痛の症候を感じたら、早めに休むべきだ。", "error_description": "「感じる」は目的語を取る他動詞なので、正しくは「症候を」。誤って「症候が」になっている（症候に直接つく助詞の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
