INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39630, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんのものが集まったまとまり。", "primary_collocate": null, "pronunciation": "ぐん", "ipa": "ɡɯɴ", "syllable_count": 2, "sentences": [{"text": "ピアノの発表会では、年齢の近い子どもが一つの群にまとめられた。", "target_word": "群", "complexity_tier": "T3", "furigana": "ピアノの発表会[はっぴょうかい]では、年齢[ねんれい]の近[ちか]い子[こ]どもが一[ひと]つの群[ぐん]にまとめられた。", "sentence_source": "generated"}, {"text": "この店では、料理を味の系統ごとに三つの群に分けてメニューに載せている。", "target_word": "群", "complexity_tier": "T3", "furigana": "この店[みせ]では、料理[りょうり]を味[あじ]の系統[けいとう]ごとに三[みっ]つの群[ぐん]に分[わ]けてメニューに載[の]せている。", "sentence_source": "generated"}, {"text": "調査では、参加者を二つの群に分けて結果を比べた。", "target_word": "群", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、参加者[さんかしゃ]を二[ふた]つの群[ぐん]に分[わ]けて結果[けっか]を比[くら]べた。", "sentence_source": "generated"}, {"text": "薬を飲んだ群は、飲まなかった群より早く熱が下がった。", "target_word": "群", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだ群[ぐん]は、飲[の]まなかった群[ぐん]より早[はや]く熱[ねつ]が下[さ]がった。", "sentence_source": "generated"}, {"text": "似た性質の数字を一つの群にまとめると、全体が見やすくなる。", "target_word": "群", "complexity_tier": "T3", "furigana": "似[に]た性質[せいしつ]の数字[すうじ]を一[ひと]つの群[ぐん]にまとめると、全体[ぜんたい]が見[み]やすくなる。", "sentence_source": "generated"}, {"text": "大会の出場者は、タイムによって三つの群に分けられた。", "target_word": "群", "complexity_tier": "T3", "furigana": "大会[たいかい]の出場者[しゅつじょうしゃ]は、タイムによって三[みっ]つの群[ぐん]に分[わ]けられた。", "sentence_source": "generated"}, {"text": "若い患者の群では、副作用はほとんど見られなかった。", "target_word": "群", "complexity_tier": "T3", "furigana": "若[わか]い患者[かんじゃ]の群[ぐん]では、副作用[ふくさよう]はほとんど見[み]られなかった。", "sentence_source": "generated"}, {"text": "年齢が高い群ほど、運動の時間が短いという結果が出た。", "target_word": "群", "complexity_tier": "T3", "furigana": "年齢[ねんれい]が高[たか]い群[ぐん]ほど、運動[うんどう]の時間[じかん]が短[みじか]いという結果[けっか]が出[で]た。", "sentence_source": "generated"}, {"text": "英語の授業で、彼女は成績の良い群に入れられた。", "target_word": "群", "complexity_tier": "T3", "furigana": "英語[えいご]の授業[じゅぎょう]で、彼女[かのじょ]は成績[せいせき]の良[よ]い群[ぐん]に入[い]れられた。", "sentence_source": "generated"}, {"text": "同じ食事をした群の中で、体重が増えた人は少なかった。", "target_word": "群", "complexity_tier": "T3", "furigana": "同[おな]じ食事[しょくじ]をした群[ぐん]の中[なか]で、体重[たいじゅう]が増[ふ]えた人[ひと]は少[すく]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "群", "label": "基本形"}], "register": "文章語（常体）", "sense_fingerprint": "多くのものが集まってできた一まとまり。比較や分類の単位としても使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群", "is_correct": true, "explanation": "同じ年ごろの子どもがまとまった集団を指すので、『一つの群にまとめられた』に合う。"}, {"text": "波", "is_correct": false, "explanation": "水面の動きを表す語で、子どもをまとめる意味では使えないので合わない。"}, {"text": "靴", "is_correct": false, "explanation": "履くものを指す語で、人の集まりを表さないので合わない。"}, {"text": "灯", "is_correct": false, "explanation": "光や明かりの意味で、人をまとめる文脈には入らないので合わない。"}], "explanations": {"群": "同じ年ごろの子どもがまとまった集団を指すので、『一つの群にまとめられた』に合う。", "波": "水面の動きを表す語で、子どもをまとめる意味では使えないので合わない。", "靴": "履くものを指す語で、人の集まりを表さないので合わない。", "灯": "光や明かりの意味で、人をまとめる文脈には入らないので合わない。"}, "sentence_index": 0, "correct_answer": "群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その二人は、一つの群で協力して発表した。", "explanation": "ここは〈組〉（二人一組）の意味で取り違えている。群は同じ種類のものが集まった一まとまりを指し、少人数の組には使わないので合わない。"}, {"text": "祖父の形見の群は、古い時計だ。", "explanation": "ここは〈品〉（一つの品物）の意味で取り違えている。群は同じ種類のものが集まった一まとまりで、一点の品物は指さないので合わない。"}, {"text": "この町は、県の中で人口が三番目に多い群だ。", "explanation": "ここは〈郡〉（行政区画）の意味。群は集まりを表す語で、地域の区分には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群", "is_correct": true, "explanation": "若い患者がまとまった集団を指し、『患者の群では』の文脈に合う。"}, {"text": "鉢", "is_correct": false, "explanation": "植木や料理を入れる器を指すので、患者の集団には使えないので合わない。"}, {"text": "帯", "is_correct": false, "explanation": "布や腰に巻くものの意味で、人の集まりの文脈には入らないので合わない。"}, {"text": "札", "is_correct": false, "explanation": "紙の札（ふだ）の意味で、患者を区分する集団の語にはならないので合わない。"}], "explanations": {"群": "若い患者がまとまった集団を指し、『患者の群では』の文脈に合う。", "鉢": "植木や料理を入れる器を指すので、患者の集団には使えないので合わない。", "帯": "布や腰に巻くものの意味で、人の集まりの文脈には入らないので合わない。", "札": "紙の札（ふだ）の意味で、患者を区分する集団の語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このジュースは砂糖の群が多すぎて、飲みにくい。", "explanation": "ここは〈量〉の意味で取り違えている。群は同じ種類のものが集まったまとまりで、分量を表す語ではないので合わない。"}, {"text": "父は群の県庁で働いている。", "explanation": "ここは地名〈群馬県〉の一部。群だけでは地名にならず、集まりの意味でも合わないので誤り。"}, {"text": "社会の群では、ルールを守る人が多い。", "explanation": "ここは〈集団〉の意味で取り違えている。群は同じ性質のものの集まりを表す分類の単位で、人々の社会的な集まりには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場では、部品を形ごとに二つの群を分けて保管した。", "corrected_sentence": "工場では、部品を形ごとに二つの群に分けて保管した。", "error_description": "『分ける』は『〜に分ける』と結果の区分を『に』で表す。『群を分ける』は誤りで、正しくは『群に分ける』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医師は、症状の軽い患者を一つの群をまとめて治療した。", "corrected_sentence": "医師は、症状の軽い患者を一つの群にまとめて治療した。", "error_description": "『を』が二つ重なる誤り。『まとめる』の結果は『に』で表すので、『一つの群を』ではなく『一つの群に』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
