INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39632, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みつばちがたくさんいなくなる病気のことです。", "primary_collocate": null, "pronunciation": "しーしーでぃー", "ipa": "ɕiːɕiːdiː", "syllable_count": 6, "sentences": [{"text": "CCD が起きると、巣から働きバチが急にいなくなる。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] が起[お]きると、巣[す]から働[はたら]きバチが急[きゅう]にいなくなる。", "sentence_source": "generated"}, {"text": "養蜂家は、CCD で巣箱のミツバチが減ったと話した。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "養蜂家[ようほうか]は、CCD[しーしーでぃー] で巣箱[すばこ]のミツバチが減[へ]ったと話[はな]した。", "sentence_source": "generated"}, {"text": "CCD の原因は、農薬やダニなど、いろいろな説がある。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] の原因[げんいん]は、農薬[のうやく]やダニなど、いろいろな説[せつ]がある。", "sentence_source": "generated"}, {"text": "ミツバチが消える CCD は、農作物の受粉にも影響する。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "ミツバチが消[き]える CCD[しーしーでぃー] は、農作物[のうさくぶつ]の受粉[じゅふん]にも影響[えいきょう]する。", "sentence_source": "generated"}, {"text": "巣箱が空っぽになっているのを見て、養蜂家は CCD を疑った。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "巣箱[すばこ]が空[から]っぽになっているのを見[み]て、養蜂家[ようほうか]は CCD[しーしーでぃー] を疑[うたが]った。", "sentence_source": "generated"}, {"text": "CCD のせいで、果物の実がなりにくくなった畑もある。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] のせいで、果物[くだもの]の実[み]がなりにくくなった畑[はたけ]もある。", "sentence_source": "generated"}, {"text": "アメリカでは、CCD によってたくさんの巣が全滅した。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "アメリカでは、CCD[しーしーでぃー] によってたくさんの巣[す]が全滅[ぜんめつ]した。", "sentence_source": "generated"}, {"text": "CCD の調査のために、研究者が養蜂場を訪れた。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] の調査[ちょうさ]のために、研究者[けんきゅうしゃ]が養蜂場[ようほうじょう]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "CCD はミツバチの病気だが、人にはうつらない。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] はミツバチの病気[びょうき]だが、人[ひと]にはうつらない。", "sentence_source": "generated"}, {"text": "CCD が広がると、はちみつの値段も上がるかもしれない。", "target_word": "CCD", "complexity_tier": "T3", "furigana": "CCD[しーしーでぃー] が広[ひろ]がると、はちみつの値段[ねだん]も上[あ]がるかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CCD", "label": "基本形"}], "register": "略称・やや専門的（常体）", "sense_fingerprint": "ミツバチが巣から大量にいなくなる病気。アルファベットの略称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6b92975-9430-4ee0-8102-1db91d53642d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CCD", "is_correct": true, "explanation": "ミツバチの病気の名前なので、『CCD が起きると』の主語に合う。"}, {"text": "虹", "is_correct": false, "explanation": "空に現れる光の現象で、巣からハチがいなくなる病気の主語にはならないので合わない。"}, {"text": "霧", "is_correct": false, "explanation": "空気中の水滴を指し、ハチの病気を表さないので合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色を指し、病気の意味にはならないので合わない。"}], "explanations": {"CCD": "ミツバチの病気の名前なので、『CCD が起きると』の主語に合う。", "虹": "空に現れる光の現象で、巣からハチがいなくなる病気の主語にはならないので合わない。", "霧": "空気中の水滴を指し、ハチの病気を表さないので合わない。", "夕焼け": "夕方の空の色を指し、病気の意味にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "CCD"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "養蜂家は、毎朝の CCD で巣箱を掃除した。", "explanation": "ここは〈作業〉の意味で取り違えている。CCD は病気の名前で、掃除などの作業を指す語ではないので合わない。"}, {"text": "養蜂家は、CCD をかごに入れて市場へ運んだ。", "explanation": "ここは〈ミツバチ〉（生き物）の意味で取り違えている。CCD は病名で、かごに入れて運ぶ生き物ではないので合わない。"}, {"text": "農家は、畑に CCD を撒いて害虫を退治した。", "explanation": "ここは〈農薬〉の意味で取り違えている。CCD は病名で、畑に撒いて害虫を退治する薬剤ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CCD", "is_correct": true, "explanation": "病気の名として『CCD によってたくさんの巣が全滅した』に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章の意味で、巣を全滅させる原因にはならないので合わない。"}, {"text": "太鼓", "is_correct": false, "explanation": "打ち鳴らす楽器で、巣の全滅との結びつきがなく合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を収める家具で、原因として文が成り立たないので合わない。"}], "explanations": {"CCD": "病気の名として『CCD によってたくさんの巣が全滅した』に合う。", "手紙": "書いた文章の意味で、巣を全滅させる原因にはならないので合わない。", "太鼓": "打ち鳴らす楽器で、巣の全滅との結びつきがなく合わない。", "本棚": "本を収める家具で、原因として文が成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "CCD"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は CCD を職業にしている。", "explanation": "ここは〈養蜂〉（ミツバチを飼うこと）の意味で取り違えている。CCD は病気の名で、仕事や活動の意味では使わないので合わない。"}, {"text": "この事故の CCD は、機械の故障だった。", "explanation": "ここは〈原因〉の意味で取り違えている。CCD は病気の名前なので、機械の故障そのものを指す語ではないので合わない。"}, {"text": "CCD は、花の蜜を集める生き物だ。", "explanation": "ここは〈ミツバチ〉（生き物）の意味で取り違えている。CCD は病気の名前で、蜜を集める生き物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "養蜂場では、CCD を広がって、ミツバチの数が減った。", "corrected_sentence": "養蜂場では、CCD が広がって、ミツバチの数が減った。", "error_description": "『広がる』は主語に『が』を取る自動詞。『CCD を広がる』は誤りで、正しくは『CCD が広がる』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、CCD を感染した巣を調べた。", "corrected_sentence": "研究者は、CCD に感染した巣を調べた。", "error_description": "『感染する』は『に』で感染源を表す。『CCD を感染した』は誤りで、正しくは『CCD に感染した』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04bba9e7-f57d-41bb-b75c-bc9cdf22fd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
