INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何か悪いことが起こるかもしれないと、気をつけること。", "primary_collocate": null, "pronunciation": "けいかい", "ipa": "keːkai", "syllable_count": 4, "sentences": [{"text": "台風が近づいているので、川の水位を警戒している。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているので、川[かわ]の水位[すいい]を警戒[けいかい]している。", "sentence_source": "generated"}, {"text": "犬は知らない人を警戒して、ほえた。", "target_word": "警戒", "complexity_tier": "T2", "furigana": "犬[いぬ]は知[し]らない人[ひと]を警戒[けいかい]して、ほえた。", "sentence_source": "generated"}, {"text": "夜道では、周りを警戒したほうがいい。", "target_word": "警戒", "complexity_tier": "T2", "furigana": "夜道[よみち]では、周[まわ]りを警戒[けいかい]したほうがいい。", "sentence_source": "generated"}, {"text": "警察は、事件のあとも町を警戒し続けている。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、事件[じけん]のあとも町[まち]を警戒[けいかい]し続[つづ]けている。", "sentence_source": "generated"}, {"text": "先生は、大雨に警戒するようにと呼びかけた。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "先生[せんせい]は、大雨[おおあめ]に警戒[けいかい]するようにと呼[よ]びかけた。", "sentence_source": "generated"}, {"text": "ねこは新しい家で、警戒しながら歩いた。", "target_word": "警戒", "complexity_tier": "T2", "furigana": "ねこは新[あたら]しい家[いえ]で、警戒[けいかい]しながら歩[ある]いた。", "sentence_source": "generated"}, {"text": "森でクマが出たので、警戒が必要だ。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "森[もり]でクマが出[で]たので、警戒[けいかい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は人を信じやすいので、もう少し警戒するべきだ。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]を信[しん]じやすいので、もう少[すこ]し警戒[けいかい]するべきだ。", "sentence_source": "generated"}, {"text": "選手たちは、相手の速い攻撃を警戒していた。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、相手[あいて]の速[はや]い攻撃[こうげき]を警戒[けいかい]していた。", "sentence_source": "generated"}, {"text": "雪の多い日は、屋根からの落雪に警戒する必要がある。", "target_word": "警戒", "complexity_tier": "T4", "furigana": "雪[ゆき]の多[おお]い日[ひ]は、屋根[やね]からの落雪[らくせつ]に警戒[けいかい]する必要[ひつよう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "警戒", "label": "基本形"}, {"form": "警戒する", "label": "辞書形(する動詞)"}, {"form": "警戒した", "label": "過去形"}, {"form": "警戒して", "label": "て形"}, {"form": "警戒している", "label": "進行・状態"}], "register": "neutral", "sense_fingerprint": "悪いことが起こらないよう、前もって用心して気をつける行為(警戒する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 落雪 (Zipf 1.61)']::text[], '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "「水位を警戒している」は、台風の接近に備えて見守る意味になり、文脈に合う。"}, {"text": "無視", "is_correct": false, "explanation": "「無視している」は見ないふりをすることで、水位を見張っている文脈と逆になる。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄」は手放して捨てることで、水位を対象にすると意味が成り立たない。"}, {"text": "解消", "is_correct": false, "explanation": "「解消」は問題をなくすことで、水位を見ている状況には合わない。"}], "explanations": {"警戒": "「水位を警戒している」は、台風の接近に備えて見守る意味になり、文脈に合う。", "無視": "「無視している」は見ないふりをすることで、水位を見張っている文脈と逆になる。", "放棄": "「放棄」は手放して捨てることで、水位を対象にすると意味が成り立たない。", "解消": "「解消」は問題をなくすことで、水位を見ている状況には合わない。"}, "sentence_index": 0, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "観客は、選手たちに大きな警戒を送った。", "explanation": "ここは〈声援〉の意味。警戒は危険への用心で、相手を励ますために送る気持ちとは違う。"}, {"text": "先生は、新入生に警戒の招待状を出した。", "explanation": "ここは〈招待〉の意味。警戒は危険への用心で、招待状に書く誘いの内容とは合わない。"}, {"text": "会場の人々が、選手の入場に警戒の拍手を送った。", "explanation": "ここは〈拍手〉の意味。警戒は危険への用心で、ほめたたえる拍手の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "「警戒が必要だ」は、クマへの危険に備えて用心する意味になり、文脈に合う。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝が必要だ」は、危険な場面で礼を述べる必要があるという話になり、クマが出た状況と合わない。"}, {"text": "歓迎", "is_correct": false, "explanation": "「歓迎が必要だ」は、危険なクマを迎え入れる意味になり、文脈に合わない。"}, {"text": "拍手", "is_correct": false, "explanation": "「拍手が必要だ」は、危険を前にして喝采を送る意味になり、文脈に合わない。"}], "explanations": {"警戒": "「警戒が必要だ」は、クマへの危険に備えて用心する意味になり、文脈に合う。", "感謝": "「感謝が必要だ」は、危険な場面で礼を述べる必要があるという話になり、クマが出た状況と合わない。", "歓迎": "「歓迎が必要だ」は、危険なクマを迎え入れる意味になり、文脈に合わない。", "拍手": "「拍手が必要だ」は、危険を前にして喝采を送る意味になり、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父の誕生日に、警戒の花束を贈った。", "explanation": "ここは〈祝福〉の意味。警戒は危険への用心なので、祝いの気持ちを表す花束とは合わない。"}, {"text": "空港で、彼は留学する友人に警戒の別れを告げた。", "explanation": "ここは〈別れ〉の意味。警戒は危険に備えて気をつけることで、別れの挨拶には使わない。"}, {"text": "新入社員のために、警戒の歓迎会を開いた。", "explanation": "ここは〈歓迎〉の意味。警戒は危険への用心で、新入社員を迎える会には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあとも、町に警戒を続いている。", "corrected_sentence": "大雨のあとも、町に警戒が続いている。", "error_description": "「続く」は主語に「が」を取るので、「警戒を」は誤り。正しくは「警戒が続いている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の予報が出たので、川の増水の警戒する必要がある。", "corrected_sentence": "雨の予報が出たので、川の増水を警戒する必要がある。", "error_description": "「警戒する」は対象を「を」で示す。「の」は誤りで、正しくは「増水を警戒する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「警戒が強まる」の主語を示す。警戒が主語になる文なので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「強まる」は目的語を取らない自動詞なので、「警戒を」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「警戒に強まる」は、強まる動きの主語を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「警戒の強まり、」は名詞句で止まり、文の述語が続かず成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「警戒が強まる」の主語を示す。警戒が主語になる文なので正しい。", "を": "「強まる」は目的語を取らない自動詞なので、「警戒を」は文が成り立たない。", "に": "「警戒に強まる」は、強まる動きの主語を示せず不自然。", "の": "「警戒の強まり、」は名詞句で止まり、文の述語が続かず成り立たない。"}, "error_tags": {"が": "主語", "を": "対象", "に": "位置", "の": "名詞化"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
