INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "危険や問題が起こる前に、注意を促すための合図や気持ち。", "primary_collocate": null, "pronunciation": "けいかい", "ipa": "keːkai", "syllable_count": 4, "sentences": [{"text": "気象庁は、大雨への警戒を呼びかけた。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "気象庁[きしょうちょう]は、大雨[おおあめ]への警戒[けいかい]を呼[よ]びかけた。", "sentence_source": "generated"}, {"text": "津波への警戒が強まり、海岸の人たちは高い場所へ逃げた。", "target_word": "警戒", "complexity_tier": "T4", "furigana": "津波[つなみ]への警戒[けいかい]が強[つよ]まり、海岸[かいがん]の人[ひと]たちは高[たか]い場所[ばしょ]へ逃[に]げた。", "sentence_source": "generated"}, {"text": "町に警戒が広がり、夜に出歩く人は少なくなった。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "町[まち]に警戒[けいかい]が広[ひろ]がり、夜[よる]に出歩[であ]く人[ひと]は少[すく]なくなった。", "sentence_source": "generated"}, {"text": "新しいウイルスの発生で、世界中に警戒が高まっている。", "target_word": "警戒", "complexity_tier": "T4", "furigana": "新[あたら]しいウイルスの発生[はっせい]で、世界中[せかいじゅう]に警戒[けいかい]が高[たか]まっている。", "sentence_source": "generated"}, {"text": "大雨の予報が出て、市は警戒を強めるよう職員に伝えた。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の予報[よほう]が出[で]て、市[し]は警戒[けいかい]を強[つよ]めるよう職員[しょくいん]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "先生の「気をつけて」という一言が、生徒たちの警戒を促した。", "target_word": "警戒", "complexity_tier": "T4", "furigana": "先生[せんせい]の「気[き]をつけて」という一言[ひとこと]が、生徒[せいと]たちの警戒[けいかい]を促[うなが]した。", "sentence_source": "generated"}, {"text": "事件のあとも警戒は続き、学校の前に警察が立っている。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "事件[じけん]のあとも警戒[けいかい]は続[つづ]き、学校[がっこう]の前[まえ]に警察[けいさつ]が立[た]っている。", "sentence_source": "generated"}, {"text": "山の天気は変わりやすいと、警戒の声が上がった。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "山[やま]の天気[てんき]は変[か]わりやすいと、警戒[けいかい]の声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "強い地震の直後は、余震への警戒を解いてはいけない。", "target_word": "警戒", "complexity_tier": "T4", "furigana": "強[つよ]い地震[じしん]の直後[ちょくご]は、余震[よしん]への警戒[けいかい]を解[と]いてはいけない。", "sentence_source": "generated"}, {"text": "赤いランプは、機械の異常を知らせる警戒の合図だ。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "赤[あか]いランプは、機械[きかい]の異常[いじょう]を知[し]らせる警戒[けいかい]の合図[あいず]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "警戒", "label": "基本形"}, {"form": "警戒の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "危険の前に注意を促す合図、または人々や心に生じる用心の気持ち(警戒が高まる・解ける)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "「大雨への警戒を呼びかけた」は、危険への注意を促す意味で文に合う。"}, {"text": "無視", "is_correct": false, "explanation": "「無視を呼びかけた」は注意を促す文脈と逆になり、意味が通らない。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄を呼びかけた」は、大雨への対応として意味が成り立たない。"}, {"text": "解消", "is_correct": false, "explanation": "「解消を呼びかけた」は、大雨という危険を前にした呼びかけとして不自然。"}], "explanations": {"警戒": "「大雨への警戒を呼びかけた」は、危険への注意を促す意味で文に合う。", "無視": "「無視を呼びかけた」は注意を促す文脈と逆になり、意味が通らない。", "放棄": "「放棄を呼びかけた」は、大雨への対応として意味が成り立たない。", "解消": "「解消を呼びかけた」は、大雨という危険を前にした呼びかけとして不自然。"}, "sentence_index": 0, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "応援団は、警戒のリズムで手拍子を打った。", "explanation": "ここは〈リズム〉の意味。警戒は注意を促す合図や気持ちで、手拍子の調子を表す言葉ではない。"}, {"text": "合格の知らせに、町じゅうに警戒の花が咲いた。", "explanation": "ここは〈喜び〉の意味。警戒は危険への注意で、うれしさが広がる場面では使わない。"}, {"text": "お祭りの前日、町じゅうが警戒の衣装を縫った。", "explanation": "ここは〈衣装〉の意味。警戒は注意の合図や気持ちで、祭りの衣装を指すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "「警戒は続き」は事件の後も用心が続く意味になり、警察が立つ文脈に合う。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝は続き」は礼の気持ちが続く意味になり、警察が立つ文脈と合わない。"}, {"text": "祝杯", "is_correct": false, "explanation": "「祝杯は続き」は祝いの杯が続く意味になり、事件後の状況とは噛み合わない。"}, {"text": "歓迎", "is_correct": false, "explanation": "「歓迎は続き」は客を迎える気持ちが続く意味になり、警察が立つ状況に合わない。"}], "explanations": {"警戒": "「警戒は続き」は事件の後も用心が続く意味になり、警察が立つ文脈に合う。", "感謝": "「感謝は続き」は礼の気持ちが続く意味になり、警察が立つ文脈と合わない。", "祝杯": "「祝杯は続き」は祝いの杯が続く意味になり、事件後の状況とは噛み合わない。", "歓迎": "「歓迎は続き」は客を迎える気持ちが続く意味になり、警察が立つ状況に合わない。"}, "sentence_index": 6, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祭りの会場で、警戒に当たる人が増えた。", "explanation": "ここは〈警備〉の意味。警戒に当たるのは見張る仕事で、注意を促す合図や気持ちとは違う。"}, {"text": "祭りの夜、町の人たちは警戒の踊りを披露した。", "explanation": "ここは〈踊り〉の意味。警戒は注意を促す合図や気持ちで、披露する踊りの名前ではない。"}, {"text": "チームは決勝で、警戒の勝利を収めた。", "explanation": "ここは〈勝利〉の意味。警戒は注意の気持ちや合図で、試合の勝ち負けには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨の予報が出て、町に警戒を高まっている。", "corrected_sentence": "大雨の予報が出て、町に警戒が高まっている。", "error_description": "「高まる」は主語に「が」を取るので、「警戒を」は誤り。正しくは「警戒が高まっている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町に警戒を広がっている。", "corrected_sentence": "町に警戒が広がっている。", "error_description": "「広がる」は主語に「が」を取るので、「警戒を」は誤り。正しくは「警戒が広がっている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
