INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39636, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「信号を決めて」で、決める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「信号が決めて」では信号が主語になり、決める主体として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「信号の決めて」は所有・修飾の「の」で、動詞の文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「信号より」は比較を示し、決める対象を示す文の形に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「信号を決めて」で、決める対象を示す。", "が": "「信号が決めて」では信号が主語になり、決める主体として成り立たない。", "の": "「信号の決めて」は所有・修飾の「の」で、動詞の文として成り立たない。", "より": "「信号より」は比較を示し、決める対象を示す文の形に合わない。"}, "error_tags": {"が": "主語", "の": "所有・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こることを知らせる合図。", "primary_collocate": null, "pronunciation": "しんごう", "ipa": "ɕiŋɡoː", "syllable_count": 4, "sentences": [{"text": "山の上から煙で信号を送ると、下の村の人たちがすぐに集まった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)から煙(けむり)で信号(しんごう)を送(おく)ると、下(した)の村(むら)の人(ひと)たちがすぐに集(あつ)まった。", "sentence_source": "generated"}, {"text": "船は旗を振って、近くの船に信号を送った。", "target_word": "信号", "complexity_tier": "T3", "furigana": "船(ふね)は旗(はた)を振(ふ)って、近(ちか)くの船(ふね)に信号(しんごう)を送(おく)った。", "sentence_source": "generated"}, {"text": "遭難した人は、鏡で光を反射させて助けを呼ぶ信号を出した。", "target_word": "信号", "complexity_tier": "T3", "furigana": "遭難(そうなん)した人(ひと)は、鏡(かがみ)で光(ひかり)を反射(はんしゃ)させて助(たす)けを呼(よ)ぶ信号(しんごう)を出(だ)した。", "sentence_source": "generated"}, {"text": "彼は目で「もう帰ろう」という信号を送ってきた。", "target_word": "信号", "complexity_tier": "T3", "furigana": "彼(かれ)は目(め)で「もう帰(かえ)ろう」という信号(しんごう)を送(おく)ってきた。", "sentence_source": "generated"}, {"text": "空に上がった花火が、祭りの始まりの信号だった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "空(そら)に上(あ)がった花火(はなび)が、祭(まつ)りの始(はじ)まりの信号(しんごう)だった。", "sentence_source": "generated"}, {"text": "ベルが鳴ったら試合開始の信号だと、選手全員が理解していた。", "target_word": "信号", "complexity_tier": "T3", "furigana": "ベルが鳴(な)ったら試合開始(しあいかいし)の信号(しんごう)だと、選手全員(せんしゅぜんいん)が理解(りかい)していた。", "sentence_source": "generated"}, {"text": "無線で短い信号が届いたので、救助隊はすぐに出発した。", "target_word": "信号", "complexity_tier": "T3", "furigana": "無線(むせん)で短(みじか)い信号(しんごう)が届(とど)いたので、救助隊(きゅうじょたい)はすぐに出発(しゅっぱつ)した。", "sentence_source": "generated"}, {"text": "二人は暗号の信号を決めて、離れた場所でも連絡を取り合った。", "target_word": "信号", "complexity_tier": "T3", "furigana": "二人(ふたり)は暗号(あんごう)の信号(しんごう)を決(き)めて、離(はな)れた場所(ばしょ)でも連絡(れんらく)を取(と)り合(あ)った。", "sentence_source": "generated"}, {"text": "灯台の光は、暗い海を進む船に港の近さを伝える信号になっている。", "target_word": "信号", "complexity_tier": "T3", "furigana": "灯台(とうだい)の光(ひかり)は、暗(くら)い海(うみ)を進(すす)む船(ふね)に港(みなと)の近(ちか)さを伝(つた)える信号(しんごう)になっている。", "sentence_source": "generated"}, {"text": "先生が手を上げて信号を出すと、生徒たちは静かになった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "先生(せんせい)が手(て)を上(あ)げて信号(しんごう)を出(だ)すと、生徒(せいと)たちは静(しず)かになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "信号", "label": "基本形"}], "register": "plain", "sense_fingerprint": "何かが起こる・始まることを光・煙・音・動作などで相手に知らせる合図", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布団", "is_correct": false, "explanation": "煙で布団を送っても合図にならず、「信号を送る」の文脈に合わない。"}, {"text": "花", "is_correct": false, "explanation": "「花を送る」は合図の意味にならず、村の人が集まる文脈と合わない。"}, {"text": "水", "is_correct": false, "explanation": "「水を送る」は合図にならず、煙で知らせる文脈と合わない。"}, {"text": "信号", "is_correct": true, "explanation": "正解。煙で合図を送って村の人が集まった、という文脈に合う。"}], "explanations": {"布団": "煙で布団を送っても合図にならず、「信号を送る」の文脈に合わない。", "花": "「花を送る」は合図の意味にならず、村の人が集まる文脈と合わない。", "水": "「水を送る」は合図にならず、煙で知らせる文脈と合わない。", "信号": "正解。煙で合図を送って村の人が集まった、という文脈に合う。"}, "sentence_index": 0, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学では、数の式を信号で表す。", "explanation": "ここは〈記号〉の意味。式を表すのは記号で、信号は合図を指すので合わない。"}, {"text": "交差点の信号が赤だったので、車は止まった。", "explanation": "ここは〈交通信号機〉の意味。車を止める装置で、合図を送る意味とは違う。"}, {"text": "プラスの信号をつけて、数の正負を示す。", "explanation": "ここは〈符号〉の意味。正負を示すのは符号で、信号は合図なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小麦粉", "is_correct": false, "explanation": "「無線で短い小麦粉が届いた」は成り立たず、救助の文脈に合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画は無線で届く短いものではなく、救助隊が出発する文脈に合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸が無線で届くことはなく、救助隊の出発につながらない。"}, {"text": "信号", "is_correct": true, "explanation": "正解。無線で届いた短い信号を受けて救助隊が出発した、という文脈に合う。"}], "explanations": {"小麦粉": "「無線で短い小麦粉が届いた」は成り立たず、救助の文脈に合わない。", "絵画": "絵画は無線で届く短いものではなく、救助隊が出発する文脈に合わない。", "石鹸": "石鹸が無線で届くことはなく、救助隊の出発につながらない。", "信号": "正解。無線で届いた短い信号を受けて救助隊が出発した、という文脈に合う。"}, "sentence_index": 6, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "わからない単語は、信号で意味を調べた。", "explanation": "ここは〈辞書〉の意味。意味を調べる資料は辞書で、信号は合図なので合わない。"}, {"text": "次の電車の時刻を、信号で確かめた。", "explanation": "ここは〈時刻表〉の意味。時刻を確かめる資料は時刻表で、信号は合わない。"}, {"text": "その信号で、きれいな曲を演奏した。", "explanation": "ここは〈楽器〉の意味。演奏に使うのは楽器で、信号は合図なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
