INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠くの島から、煙の信号が届きした。", "corrected_sentence": "遠くの島から、煙の信号が届いた。", "error_description": "「届いた」の活用が誤っている。「届く」の過去形は「届いた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
