INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39637, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄を知らせたり、注意を促したりするためのサイン。", "primary_collocate": null, "pronunciation": "しんごう", "ipa": "ɕiŋɡoː", "syllable_count": 4, "sentences": [{"text": "頭痛は体が休みたいという信号かもしれない。", "target_word": "信号", "complexity_tier": "T3", "furigana": "頭痛(ずつう)は体(からだ)が休(やす)みたいという信号(しんごう)かもしれない。", "sentence_source": "generated"}, {"text": "空が急に暗くなったのは、嵐が近づいている信号だった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "空(そら)が急(きゅう)に暗(くら)くなったのは、嵐(あらし)が近(ちか)づいている信号(しんごう)だった。", "sentence_source": "generated"}, {"text": "子どもが急に泣き出したのは、眠いという信号だった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "子(こ)どもが急(きゅう)に泣(な)き出(だ)したのは、眠(ねむ)いという信号(しんごう)だった。", "sentence_source": "generated"}, {"text": "彼の小さなため息は、疲れているという信号だと思う。", "target_word": "信号", "complexity_tier": "T3", "furigana": "彼(かれ)の小(ちい)さなため息(いき)は、疲(つか)れているという信号(しんごう)だと思(おも)う。", "sentence_source": "generated"}, {"text": "機械から変な音がするのは、故障が近いという信号だ。", "target_word": "信号", "complexity_tier": "T3", "furigana": "機械(きかい)から変(へん)な音(おと)がするのは、故障(こしょう)が近(ちか)いという信号(しんごう)だ。", "sentence_source": "generated"}, {"text": "ランプの赤い光は、注意しろという信号だ。", "target_word": "信号", "complexity_tier": "T3", "furigana": "ランプの赤(あか)い光(ひかり)は、注意(ちゅうい)しろという信号(しんごう)だ。", "sentence_source": "generated"}, {"text": "友だちが目をそらしたのは、話したくないという信号だった。", "target_word": "信号", "complexity_tier": "T3", "furigana": "友(とも)だちが目(め)をそらしたのは、話(はな)したくないという信号(しんごう)だった。", "sentence_source": "generated"}, {"text": "犬がしっぽを振るのは、うれしいという信号だ。", "target_word": "信号", "complexity_tier": "T3", "furigana": "犬(いぬ)がしっぽを振(ふ)るのは、うれしいという信号(しんごう)だ。", "sentence_source": "generated"}, {"text": "胃が痛むのは、食べすぎに注意しろという体からの信号だ。", "target_word": "信号", "complexity_tier": "T3", "furigana": "胃(い)が痛(いた)むのは、食(た)べすぎに注意(ちゅうい)しろという体(からだ)からの信号(しんごう)だ。", "sentence_source": "generated"}, {"text": "犬が低くうなるのは、近づくなという信号だ。", "target_word": "信号", "complexity_tier": "T3", "furigana": "犬(いぬ)が低(ひく)くうなるのは、近(ちか)づくなという信号(しんごう)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "信号", "label": "基本形"}], "register": "plain", "sense_fingerprint": "体・動物・機械などが示す、状態を知らせたり注意を促したりするサイン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: うなる (Zipf 2.41)']::text[], '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39637, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌", "is_correct": false, "explanation": "「体が休みたいという歌かもしれない」は意味が通らず、体の信号の文脈に合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は体の状態を知らせないので、「休みたいという雲」は成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は体の状態を知らせる物ではなく、頭痛の文脈に合わない。"}, {"text": "信号", "is_correct": true, "explanation": "正解。頭痛が体の休息を知らせるサインだ、という文脈に合う。"}], "explanations": {"歌": "「体が休みたいという歌かもしれない」は意味が通らず、体の信号の文脈に合わない。", "雲": "雲は体の状態を知らせないので、「休みたいという雲」は成り立たない。", "鍵": "鍵は体の状態を知らせる物ではなく、頭痛の文脈に合わない。", "信号": "正解。頭痛が体の休息を知らせるサインだ、という文脈に合う。"}, "sentence_index": 0, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の気温は、信号で確かめればいい。", "explanation": "ここは〈温度計〉の意味。気温を測るのは温度計で、信号では確かめられない。"}, {"text": "わからない漢字は、信号で調べればいい。", "explanation": "ここは〈辞書〉の意味。調べる道具は辞書で、信号は使えないので合わない。"}, {"text": "信号が青に変わるまで、横断歩道の前で待った。", "explanation": "ここは〈交通信号機〉の意味。横断歩道の前で待つための装置で、サインや注意の意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39637, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旗", "is_correct": false, "explanation": "「話したくないという旗だった」は意味が通らず、目をそらす合図の文脈に合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は話したくない気持ちを示す物ではなく、文が成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "石は気持ちを示すサインにならず、「話したくないという石」は不自然。"}, {"text": "信号", "is_correct": true, "explanation": "正解。目をそらしたのは話したくないという合図だった、という文脈に合う。"}], "explanations": {"旗": "「話したくないという旗だった」は意味が通らず、目をそらす合図の文脈に合わない。", "皿": "皿は話したくない気持ちを示す物ではなく、文が成り立たない。", "石": "石は気持ちを示すサインにならず、「話したくないという石」は不自然。", "信号": "正解。目をそらしたのは話したくないという合図だった、という文脈に合う。"}, "sentence_index": 6, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱があるかどうか、信号で測った。", "explanation": "ここは〈体温計〉の意味。熱を測る道具は体温計で、信号では測れないので合わない。"}, {"text": "明日の天気を、信号で確かめた。", "explanation": "ここは〈天気予報〉の意味。天気を知るのは天気予報で、信号では確かめられない。"}, {"text": "体重を、信号で量った。", "explanation": "ここは〈体重計〉の意味。体重を量るのは体重計で、信号は合わないので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39637, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアが勝手に開くのは、故障の信号を出ているからだ。", "corrected_sentence": "ドアが勝手に開くのは、故障の信号が出ているからだ。", "error_description": "「信号」に続く助詞が「を」になっている。「出る」は自動詞なので、主語は「が」で示すのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39637, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ランプが赤く点滅するのは、電池切れの信号した。", "corrected_sentence": "ランプが赤く点滅するのは、電池切れの信号だ。", "error_description": "「信号だ」の「だ」が「した」になっている。名詞文の「だ」で言い切るのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "獲得", "is_correct": true, "explanation": "喪失の対義語。失うことの反対で、得ることを指す。"}, {"text": "成長", "is_correct": false, "explanation": "心身や能力が育つこと。失うことの反対語ではない。"}, {"text": "挑戦", "is_correct": false, "explanation": "困難なことに取り組むこと。喪失との対義関係はない。"}, {"text": "解決", "is_correct": false, "explanation": "問題を片づけること。喪失とは対義関係にない。"}], "correct_answer": "獲得", "explanations": {"獲得": "喪失の対義語。失うことの反対で、得ることを指す。", "成長": "心身や能力が育つこと。失うことの反対語ではない。", "挑戦": "困難なことに取り組むこと。喪失との対義関係はない。", "解決": "問題を片づけること。喪失とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "喪失は「語る」の対象（目的語）なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。語るのは老人で、喪失が語るわけではない。"}, {"text": "に", "is_correct": false, "explanation": "帰着や対象を示す。「喪失に語る」とは言わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「喪失で語る」は不自然。"}], "correct_answer": "を", "explanations": {"を": "喪失は「語る」の対象（目的語）なので「を」。", "が": "主語を示す。語るのは老人で、喪失が語るわけではない。", "に": "帰着や対象を示す。「喪失に語る」とは言わない。", "で": "手段や場所を示す。「喪失で語る」は不自然。"}, "error_tags": {"が": "主語", "に": "帰着・目的地", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "獲得", "is_correct": true, "explanation": "喪失の対義語。失うことの反対で、得ることを指す。"}, {"text": "出発", "is_correct": false, "explanation": "その場所を離れて出ること。喪失の対義語ではない。"}, {"text": "帰宅", "is_correct": false, "explanation": "家に帰ること。喪失とは対義関係にない。"}, {"text": "入学", "is_correct": false, "explanation": "学校に入ること。喪失とは対義関係にない。"}], "correct_answer": "獲得", "explanations": {"獲得": "喪失の対義語。失うことの反対で、得ることを指す。", "出発": "その場所を離れて出ること。喪失の対義語ではない。", "帰宅": "家に帰ること。喪失とは対義関係にない。", "入学": "学校に入ること。喪失とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "大切なものをなくしてしまうこと。", "primary_collocate": null, "pronunciation": "そうしつ", "ipa": "soːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "大切な人との別れによる喪失は、時間をかけて癒えていく。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "大切[たいせつ]な人[ひと]との別[わか]れによる喪失[そうしつ]は、時間[じかん]をかけて癒[い]えていく。", "sentence_source": "generated"}, {"text": "火事で家を失い、彼は思い出の品の喪失を深く悲しんだ。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "火事[かじ]で家[いえ]を失[うしな]い、彼[かれ]は思[おも]い出[で]の品[しな]の喪失[そうしつ]を深[ふか]く悲[かな]しんだ。", "sentence_source": "generated"}, {"text": "祖母が残した手紙の喪失は、家族みんなにとって大きな痛手だった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "祖母[そぼ]が残[のこ]した手紙[てがみ]の喪失[そうしつ]は、家族[かぞく]みんなにとって大[おお]きな痛手[いたで]だった。", "sentence_source": "generated"}, {"text": "母の死という喪失を乗り越えて、彼女は教師になった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "母[はは]の死[し]という喪失[そうしつ]を乗[の]り越[こ]えて、彼女[かのじょ]は教師[きょうし]になった。", "sentence_source": "generated"}, {"text": "戦争は、人々から家と家族の両方を奪い、深い喪失を残した。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "戦争[せんそう]は、人々[ひとびと]から家[いえ]と家族[かぞく]の両方[りょうほう]を奪[うば]い、深[ふか]い喪失[そうしつ]を残[のこ]した。", "sentence_source": "generated"}, {"text": "親友の喪失を、彼はなかなか受け入れられなかった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "親友[しんゆう]の喪失[そうしつ]を、彼[かれ]はなかなか受[う]け入[い]れられなかった。", "sentence_source": "generated"}, {"text": "長年の夢を断たれた喪失は、お金では埋められない。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "長年[ながねん]の夢[ゆめ]を断[た]たれた喪失[そうしつ]は、お金[かね]では埋[う]められない。", "sentence_source": "generated"}, {"text": "故郷の喪失を語る老人の声は、静かで悲しそうだった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "故郷[こきょう]の喪失[そうしつ]を語[かた]る老人[ろうじん]の声[こえ]は、静[しず]かで悲[かな]しそうだった。", "sentence_source": "generated"}, {"text": "大切な指輪の喪失に気づいた彼女は、青ざめて店中を探した。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "大切[たいせつ]な指輪[ゆびわ]の喪失[そうしつ]に気[き]づいた彼女[かのじょ]は、青[あお]ざめて店中[みせじゅう]を探[さが]した。", "sentence_source": "generated"}, {"text": "ペットとの別れがもたらす喪失の痛みは、そう簡単には消えない。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "ペットとの別れがもたらす喪失[そうしつ]の痛みは、そう簡単には消えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喪失する", "label": "辞書形"}, {"form": "喪失した", "label": "過去形"}, {"form": "喪失して", "label": "て形"}, {"form": "喪失しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "家族・故郷・思い出の品など、かけがえのない大切なものを失うこと。悲しみや痛手を伴う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喪失", "is_correct": true, "explanation": "大切な人を失うことを指す。別れによって失った悲しみが癒えていく文に入る。"}, {"text": "再会", "is_correct": false, "explanation": "別れの後にまた会うこと。「別れによる再会」では癒えていく痛みの原因にならない。"}, {"text": "出会い", "is_correct": false, "explanation": "新しく知り合うこと。別れによる痛みの原因とは合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "別れによって生じる結婚という関係は文として成り立たない。"}], "explanations": {"喪失": "大切な人を失うことを指す。別れによって失った悲しみが癒えていく文に入る。", "再会": "別れの後にまた会うこと。「別れによる再会」では癒えていく痛みの原因にならない。", "出会い": "新しく知り合うこと。別れによる痛みの原因とは合わない。", "結婚": "別れによって生じる結婚という関係は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "喪失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父の死から三年、彼女は新しい家の喪失を祝った。", "explanation": "ここは〈獲得〉の意味。喪失は失うことなので、得たものを祝う文では意味が逆になる。"}, {"text": "会社は新事業で大きな喪失を出し、来期の計画を見直した。", "explanation": "ここは〈損失〉の意味。金銭的な損には「損失」を使い、「喪失を出す」とは言わない。"}, {"text": "彼は夢の喪失を追い求めて、毎日努力を続けている。", "explanation": "ここは〈目標（得たいもの）〉の意味。喪失は失うことなので、目指して手に入れるものにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喪失", "is_correct": true, "explanation": "夢を断たれて失った大切なものを指す。お金では埋められないという文に入る。"}, {"text": "会話", "is_correct": false, "explanation": "言葉を交わすこと。「断たれた会話」は文の意味が合わない。"}, {"text": "食事", "is_correct": false, "explanation": "食べること。夢を断たれた結果とは結びつかない。"}, {"text": "挨拶", "is_correct": false, "explanation": "人に言葉や礼を交わすこと。夢を断たれたものとしては文が成り立たない。"}], "explanations": {"喪失": "夢を断たれて失った大切なものを指す。お金では埋められないという文に入る。", "会話": "言葉を交わすこと。「断たれた会話」は文の意味が合わない。", "食事": "食べること。夢を断たれた結果とは結びつかない。", "挨拶": "人に言葉や礼を交わすこと。夢を断たれたものとしては文が成り立たない。"}, "sentence_index": 6, "correct_answer": "喪失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に突然、街の灯りが喪失した。", "explanation": "ここは〈消失〉の意味。喪失は持っていたものを手放すことで、突然消えた灯りには使わない。"}, {"text": "チームは最終戦で大事な試合を喪失し、優勝を逃した。", "explanation": "ここは〈敗北〉の意味。試合に負けることは「敗北」や「負ける」で言い、「試合を喪失する」とは言わない。"}, {"text": "長年の夢を喪失して、彼はついに夢を実現した。", "explanation": "ここは〈達成〉の意味。長年の夢を叶えることは喪失とは逆の出来事で、「喪失」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の死がもたらす喪失に悲しみは、ゆっくりと薄れていく。", "corrected_sentence": "祖父の死がもたらす喪失の悲しみは、ゆっくりと薄れていく。", "error_description": "「喪失の悲しみ」の「の」は、喪失の内容を悲しみに結びつける正しい助詞。「に」にすると、文の意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は大切な写真の喪失を受け取れず、何度も泣いた。", "corrected_sentence": "彼女は大切な写真の喪失を受け入れられず、何度も泣いた。", "error_description": "「喪失を受け入れる」が正しい連語。「受け取る」は物を受け取る意味で、喪失と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "獲得", "is_correct": true, "explanation": "喪失の対義語。失うことの反対で、得ることを指す。"}, {"text": "交流", "is_correct": false, "explanation": "人と人が行き来して関わること。失うことの反対語ではない。"}, {"text": "練習", "is_correct": false, "explanation": "技術を繰り返し身につけること。喪失との対義関係はない。"}, {"text": "誤解", "is_correct": false, "explanation": "物事を正しく理解しないこと。喪失とは対義関係にない。"}], "correct_answer": "獲得", "explanations": {"獲得": "喪失の対義語。失うことの反対で、得ることを指す。", "交流": "人と人が行き来して関わること。失うことの反対語ではない。", "練習": "技術を繰り返し身につけること。喪失との対義関係はない。", "誤解": "物事を正しく理解しないこと。喪失とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「喪失が進む」の形で、喪失が主語になることを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「喪失を進む」とは言わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着を示す。「喪失に進む」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「喪失で進む」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「喪失が進む」の形で、喪失が主語になることを示す。", "を": "目的語を示す。「喪失を進む」とは言わない。", "に": "帰着を示す。「喪失に進む」は不自然。", "で": "手段や場所を示す。「喪失で進む」は不自然。"}, "error_tags": {"を": "目的語", "に": "帰着・目的地", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "獲得", "is_correct": true, "explanation": "喪失の対義語。失うことの反対で、得ることを指す。"}, {"text": "出発", "is_correct": false, "explanation": "その場所を離れて出ること。喪失の対義語ではない。"}, {"text": "入学", "is_correct": false, "explanation": "学校に入ること。喪失とは対義関係にない。"}, {"text": "食事", "is_correct": false, "explanation": "食べること。喪失とは対義関係にない。"}], "correct_answer": "獲得", "explanations": {"獲得": "喪失の対義語。失うことの反対で、得ることを指す。", "出発": "その場所を離れて出ること。喪失の対義語ではない。", "入学": "学校に入ること。喪失とは対義関係にない。", "食事": "食べること。喪失とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "それまで持っていたものや状態を、失うこと。なくすこと。", "primary_collocate": null, "pronunciation": "そうしつ", "ipa": "soːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "事故で視力を喪失した彼は、点字を学び始めた。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "事故[じこ]で視力[しりょく]を喪失[そうしつ]した彼[かれ]は、点字[てんじ]を学[まな]び始[はじ]めた。", "sentence_source": "generated"}, {"text": "試合に大敗して、選手たちは戦う意欲を喪失した。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "試合[しあい]に大敗[たいはい]して、選手[せんしゅ]たちは戦[たたか]う意欲[いよく]を喪失[そうしつ]した。", "sentence_source": "generated"}, {"text": "有罪判決を受けると、議員は資格を喪失する。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "有罪判決[ゆうざいはんけつ]を受[う]けると、議員[ぎいん]は資格[しかく]を喪失[そうしつ]する。", "sentence_source": "generated"}, {"text": "契約を破ると、その権利を喪失することになる。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "契約[けいやく]を破[やぶ]ると、その権利[けんり]を喪失[そうしつ]することになる。", "sentence_source": "generated"}, {"text": "長い入院生活で、彼は体力を喪失してしまった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "長[なが]い入院生活[にゅういんせいかつ]で、彼[かれ]は体力[たいりょく]を喪失[そうしつ]してしまった。", "sentence_source": "generated"}, {"text": "国籍の喪失は、手続きを経て初めて認められる。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "国籍[こくせき]の喪失[そうしつ]は、手続[てつづ]きを経[へ]て初[はじ]めて認[みと]められる。", "sentence_source": "generated"}, {"text": "大事な試験に落ちて、彼は一時的に自信を喪失した。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "大事[だいじ]な試験[しけん]に落[お]ちて、彼[かれ]は一時的[いちじてき]に自信[じしん]を喪失[そうしつ]した。", "sentence_source": "generated"}, {"text": "森林の喪失が進むと、多くの動物が住む場所を失う。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "森林[しんりん]の喪失[そうしつ]が進[すす]むと、多[おお]くの動物[どうぶつ]が住[す]む場所[ばしょ]を失[うしな]う。", "sentence_source": "generated"}, {"text": "病気が原因で、味覚を喪失する人もいる。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "病気[びょうき]が原因[げんいん]で、味覚[みかく]を喪失[そうしつ]する人[ひと]もいる。", "sentence_source": "generated"}, {"text": "信頼を喪失した会社は、客を取り戻すのに何年もかかった。", "target_word": "喪失", "complexity_tier": "T3", "furigana": "信頼[しんらい]を喪失[そうしつ]した会社[かいしゃ]は、客[きゃく]を取[と]り戻[もど]すのに何年[なんねん]もかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喪失する", "label": "辞書形"}, {"form": "喪失した", "label": "過去形"}, {"form": "喪失して", "label": "て形"}, {"form": "喪失しない", "label": "否定形"}, {"form": "喪失される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "視力・資格・意欲・自信など、それまで持っていた能力・権利・状態がなくなること。「〜を喪失する」の形で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喪失", "is_correct": true, "explanation": "能力や状態を失うこと。視力を失った文に入る。"}, {"text": "寄付", "is_correct": false, "explanation": "お金や物を人に与えること。視力には使えない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かけること。視力を失うとは言わない。"}, {"text": "接種", "is_correct": false, "explanation": "ワクチンなどを体に入れること。視力には使えない。"}], "explanations": {"喪失": "能力や状態を失うこと。視力を失った文に入る。", "寄付": "お金や物を人に与えること。視力には使えない。", "散歩": "歩いて出かけること。視力を失うとは言わない。", "接種": "ワクチンなどを体に入れること。視力には使えない。"}, "sentence_index": 0, "correct_answer": "喪失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資格試験に合格して、彼は新しい権利を喪失した。", "explanation": "ここは〈獲得〉の意味。合格して得たものを喪失と言うのは逆で、文が矛盾する。"}, {"text": "祖父から受け継いだ土地を、彼は今も喪失して大切にしている。", "explanation": "ここは〈所有〉の意味。今も持っているものには喪失は使えず、文が矛盾する。"}, {"text": "友人との約束を喪失して、彼は信頼を守った。", "explanation": "ここは〈破る〉の意味。約束は破るもので、喪失とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喪失", "is_correct": true, "explanation": "自信を失ったという意味で、文の流れに合う。"}, {"text": "観察", "is_correct": false, "explanation": "よく見て調べること。自信には使えない。"}, {"text": "謝罪", "is_correct": false, "explanation": "わびること。自信とは合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終えること。自信には使えない。"}], "explanations": {"喪失": "自信を失ったという意味で、文の流れに合う。", "観察": "よく見て調べること。自信には使えない。", "謝罪": "わびること。自信とは合わない。", "解散": "集まりを終えること。自信には使えない。"}, "sentence_index": 6, "correct_answer": "喪失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リハビリを続けて、彼はついに視力を喪失した。", "explanation": "ここは〈回復〉の意味。回復の努力の結果を喪失と言うのは逆で、文が矛盾する。"}, {"text": "念願の上場を喪失して、社長は株主に感謝を伝えた。", "explanation": "ここは〈達成〉の意味。念願を果たしたことを喪失とは言わず、文が矛盾する。"}, {"text": "長い交渉の末、会社はついに新しい取引先を喪失した。", "explanation": "ここは〈勝ち取る〉の意味。苦労の末に得た成果を喪失と言うのは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は長年の努力で得た権利に喪失した。", "corrected_sentence": "彼は長年の努力で得た権利を喪失した。", "error_description": "「喪失する」は目的語に「を」をとる。「権利に」の「に」は誤りで、正しくは「権利を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39639, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人の信頼を喪失しられた彼は、もう一度築き直す決意をした。", "corrected_sentence": "友人の信頼を喪失した彼は、もう一度築き直す決意をした。", "error_description": "「喪失する」の活用は「喪失した」。「喪失しられた」は存在しない形で、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食糧を分けて食べた」で、分けて食べる対象を示すので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「食糧に大切に分けて食べた」では場所や相手になり、分ける対象が示せない。"}, {"text": "と", "is_correct": false, "explanation": "「食糧と大切に分けて食べた」では並列になり、分ける対象の文として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「食糧へ大切に分けて食べた」では方向を示してしまい、分ける動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「食糧を分けて食べた」で、分けて食べる対象を示すので「を」が入る。", "に": "「食糧に大切に分けて食べた」では場所や相手になり、分ける対象が示せない。", "と": "「食糧と大切に分けて食べた」では並列になり、分ける対象の文として合わない。", "へ": "「食糧へ大切に分けて食べた」では方向を示してしまい、分ける動作の対象にならない。"}, "error_tags": {"に": "対象・相手の格", "と": "並列・共同の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「食糧が足りなくて」で、足りなくなった食糧が主語になる。「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「食糧を足りなくて」では目的語になり、足りないという状態を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「食糧で足りなくて」では手段や材料の意味になり、不足の文として合わない。"}, {"text": "から", "is_correct": false, "explanation": "「食糧から足りなくて」では起点を示すが、不足の主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "「食糧が足りなくて」で、足りなくなった食糧が主語になる。「が」が入る。", "を": "「食糧を足りなくて」では目的語になり、足りないという状態を表せない。", "で": "「食糧で足りなくて」では手段や材料の意味になり、不足の文として合わない。", "から": "「食糧から足りなくて」では起点を示すが、不足の主語を表せない。"}, "error_tags": {"を": "目的語の格", "で": "手段・場所の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物のことです。人が生きていくために必要なものです。", "primary_collocate": null, "pronunciation": "しょくりょう", "ipa": "ɕokɯɾʲoː", "syllable_count": 4, "sentences": [{"text": "災害に備えて、家に三日分の食糧を用意している。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "災害(さいがい)に備(そな)えて、家(いえ)に三日分(みっかぶん)の食糧(しょくりょう)を用意(ようい)している。", "sentence_source": "generated"}, {"text": "山で道に迷ったので、少ない食糧を大切に分けて食べた。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "山(やま)で道(みち)に迷(まよ)ったので、少(すく)ない食糧(しょくりょう)を大切(たいせつ)に分(わ)けて食(た)べた。", "sentence_source": "generated"}, {"text": "国は外国から食糧を輸入して、足りない分を補っている。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "国(くに)は外国(がいこく)から食糧(しょくりょう)を輸入(ゆにゅう)して、足(た)りない分(ぶん)を補(おぎな)っている。", "sentence_source": "generated"}, {"text": "冬の間、村の人たちは蓄えた食糧で生活した。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "冬(ふゆ)の間(あいだ)、村(むら)の人(ひと)たちは蓄(たくわ)えた食糧(しょくりょう)で生活(せいかつ)した。", "sentence_source": "generated"}, {"text": "船には長い旅のための食糧が積まれていた。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "船(ふね)には長(なが)い旅(たび)のための食糧(しょくりょう)が積(つ)まれていた。", "sentence_source": "generated"}, {"text": "地震のあと、ボランティアが避難所に食糧を届けた。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "地震(じしん)のあと、ボランティアが避難所(ひなんじょ)に食糧(しょくりょう)を届(とど)けた。", "sentence_source": "generated"}, {"text": "雨が少なかった年は、畑の作物が育たず食糧が足りなくなった。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "雨(あめ)が少(すく)なかった年(とし)は、畑(はたけ)の作物(さくもつ)が育(そだ)たず食糧(しょくりょう)が足(た)りなくなった。", "sentence_source": "generated"}, {"text": "戦争中は食糧が足りなくて、みんな苦しい生活をしていた。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "戦争中(せんそうちゅう)は食糧(しょくりょう)が足(た)りなくて、みんな苦(くる)しい生活(せいかつ)をしていた。", "sentence_source": "generated"}, {"text": "登山隊は一週間分の食糧をリュックに入れて出発した。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "登山隊(とざんたい)は一週間分(いっしゅうかんぶん)の食糧(しょくりょう)をリュックに入(い)れて出発(しゅっぱつ)した。", "sentence_source": "generated"}, {"text": "倉庫の食糧は、湿気が入らないように箱に入れてある。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "倉庫(そうこ)の食糧(しょくりょう)は、湿気(しっけ)が入(はい)らないように箱(はこ)に入(い)れてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食糧", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人が生きるために必要な食べ物。備蓄・輸入・不足などの文脈で使う主食的な食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食糧", "is_correct": true, "explanation": "災害に備えて家に三日分ためておく食べ物として、「食糧」が自然に入る。"}, {"text": "花火", "is_correct": false, "explanation": "娯楽用の火薬製品で、災害用に三日分用意する物ではない。"}, {"text": "絵本", "is_correct": false, "explanation": "読み物なので、災害に備えて三日分用意する物として不自然。"}, {"text": "卒業証書", "is_correct": false, "explanation": "学校の修了を証明する書類で、災害に備えて用意する物ではない。"}], "explanations": {"食糧": "災害に備えて家に三日分ためておく食べ物として、「食糧」が自然に入る。", "花火": "娯楽用の火薬製品で、災害用に三日分用意する物ではない。", "絵本": "読み物なので、災害に備えて三日分用意する物として不自然。", "卒業証書": "学校の修了を証明する書類で、災害に備えて用意する物ではない。"}, "sentence_index": 0, "correct_answer": "食糧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家族みんなで食糧を飲み交わして、楽しく話した。", "explanation": "ここは〈酒〉の意味。酒を酌み交わすとは言うが、食糧は飲み交わすものではないので合わない。"}, {"text": "家族が食糧を囲んで、夕食の話をした。", "explanation": "ここは〈食卓〉の意味。食卓を囲むとは言うが、食糧を囲むとは言わない。"}, {"text": "母は食後に食糧のボタンを留めて、戸棚にしまった。", "explanation": "ここは〈ボタン〉の意味。服のボタンを留めるとは言うが、食糧にはボタンがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食糧", "is_correct": true, "explanation": "作物が育たず足りなくなった対象として、生きるための食べ物の「食糧」が自然に入る。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記具で、作物の不作によって足りなくなる物ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "体の状態を表す語で、不作の文脈で足りなくなるものではない。"}, {"text": "絵の具", "is_correct": false, "explanation": "絵を描く道具で、作物が育たない文脈とは関係がない。"}], "explanations": {"食糧": "作物が育たず足りなくなった対象として、生きるための食べ物の「食糧」が自然に入る。", "鉛筆": "筆記具で、作物の不作によって足りなくなる物ではない。", "眠気": "体の状態を表す語で、不作の文脈で足りなくなるものではない。", "絵の具": "絵を描く道具で、作物が育たない文脈とは関係がない。"}, "sentence_index": 6, "correct_answer": "食糧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は来週の食糧を立てて、買い物に出かけた。", "explanation": "ここは〈献立〉の意味。献立は立てるが、食糧を立てるとは言わない。"}, {"text": "母は、食糧を着て出かけた。", "explanation": "ここは〈服〉の意味。服を着るとは言うが、食糧は身につけるものではないので合わない。"}, {"text": "寝る前に、母は食糧を敷いてくれた。", "explanation": "ここは〈寝具〉の意味。布団を敷くとは言うが、食糧を敷く使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "避難所では、食糧を一人に一日分ずつ配られた。", "corrected_sentence": "避難所では、食糧が一人に一日分ずつ配られた。", "error_description": "誤りは「食糧を」。配られる物の主語は「が」で示すので、正しくは「食糧が」。「を」では受身の文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39640, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "船には食糧を三か月分積まれていた。", "corrected_sentence": "船には食糧が三か月分積まれていた。", "error_description": "誤りは「食糧を」。積まれる物の主語は「が」で示すので、正しくは「食糧が」。「を」では受身の文として不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食糧を手に入れられない」で、手に入れる対象を示すので「を」が入る。"}, {"text": "と", "is_correct": false, "explanation": "「食糧と手に入れられない」では並列になり、手に入れる対象が示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「食糧へ手に入れられない」では方向を示してしまい、対象として合わない。"}, {"text": "で", "is_correct": false, "explanation": "「食糧で十分に手に入れられない」では手段の意味になり、対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「食糧を手に入れられない」で、手に入れる対象を示すので「を」が入る。", "と": "「食糧と手に入れられない」では並列になり、手に入れる対象が示せない。", "へ": "「食糧へ手に入れられない」では方向を示してしまい、対象として合わない。", "で": "「食糧で十分に手に入れられない」では手段の意味になり、対象を表せない。"}, "error_tags": {"と": "並列・共同の格", "へ": "方向の格", "で": "手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「食糧にしていた」で、魚や木の実を食糧として用いる変化の先を示すので「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「食糧をしていた」では目的語になり、変化の先が示せない。"}, {"text": "が", "is_correct": false, "explanation": "「食糧がしていた」では主語になってしまい、魚や木の実を食糧にする文として合わない。"}, {"text": "から", "is_correct": false, "explanation": "「食糧からしていた」では起点を示してしまい、用途の変化を表せない。"}], "correct_answer": "に", "explanations": {"に": "「食糧にしていた」で、魚や木の実を食糧として用いる変化の先を示すので「に」が入る。", "を": "「食糧をしていた」では目的語になり、変化の先が示せない。", "が": "「食糧がしていた」では主語になってしまい、魚や木の実を食糧にする文として合わない。", "から": "「食糧からしていた」では起点を示してしまい、用途の変化を表せない。"}, "error_tags": {"を": "目的語の格", "が": "主語の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間が生命を維持するために必要とする食物。", "primary_collocate": null, "pronunciation": "しょくりょう", "ipa": "ɕokɯɾʲoː", "syllable_count": 4, "sentences": [{"text": "人間は水と食糧がなければ、長く生きられない。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "人間(にんげん)は水(みず)と食糧(しょくりょう)がなければ、長(なが)く生(い)きられない。", "sentence_source": "generated"}, {"text": "世界には、毎日の食糧を十分に手に入れられない人々がいる。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "世界(せかい)には、毎日(まいにち)の食糧(しょくりょう)を十分(じゅうぶん)に手(て)に入(い)れられない人々(ひとびと)がいる。", "sentence_source": "generated"}, {"text": "洪水で道が壊れて、町に食糧が届かなくなった。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "洪水(こうずい)で道(みち)が壊(こわ)れて、町(まち)に食糧(しょくりょう)が届(とど)かなくなった。", "sentence_source": "generated"}, {"text": "人口が増えると、必要な食糧の量も増える。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "人口(じんこう)が増(ふ)えると、必要(ひつよう)な食糧(しょくりょう)の量(りょう)も増(ふ)える。", "sentence_source": "generated"}, {"text": "宇宙飛行士は、軽くて長持ちする食糧を宇宙に持っていく。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "宇宙飛行士(うちゅうひこうし)は、軽(かる)くて長持(ながも)ちする食糧(しょくりょう)を宇宙(うちゅう)に持(も)っていく。", "sentence_source": "generated"}, {"text": "冬の山は食べ物が少なく、人々は保存しておいた食糧で春を待った。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "冬(ふゆ)の山(やま)は食べ物(たべもの)が少(すく)なく、人々(ひとびと)は保存(ほぞん)しておいた食糧(しょくりょう)で春(はる)を待(ま)った。", "sentence_source": "generated"}, {"text": "政府は米の備蓄を増やして、食糧の不足に備えている。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "政府(せいふ)は米(こめ)の備蓄(びちく)を増(ふ)やして、食糧(しょくりょう)の不足(ふそく)に備(そな)えている。", "sentence_source": "generated"}, {"text": "無人島で暮らす男は、魚や木の実を食糧にしていた。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "無人島(むじんとう)で暮(く)らす男(おとこ)は、魚(さかな)や木(き)の実(み)を食糧(しょくりょう)にしていた。", "sentence_source": "generated"}, {"text": "町の人々は、足りない食糧を少しずつ分け合った。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "町(まち)の人々(ひとびと)は、足(た)りない食糧(しょくりょう)を少(すこ)しずつ分(わ)け合(あ)った。", "sentence_source": "generated"}, {"text": "軍隊は遠い土地に行くとき、食糧も一緒に運ぶ。", "target_word": "食糧", "complexity_tier": "T3", "furigana": "軍隊(ぐんたい)は遠(とお)い土地(とち)に行(い)くとき、食糧(しょくりょう)も一緒(いっしょ)に運(はこ)ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食糧", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人間が命を保つために必要とする食物。社会・国・集団の生存にかかわる食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食糧", "is_correct": true, "explanation": "人間が生きるために必要な物として、水と並べて入る語は「食糧」。"}, {"text": "座布団", "is_correct": false, "explanation": "座る時に使う布製品で、生きるために欠かせない物として水と並ばない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記具で、水と並べて生命を維持する物として語られることはない。"}, {"text": "花火", "is_correct": false, "explanation": "娯楽用の火薬製品で、生命維持に必要な物ではない。"}], "explanations": {"食糧": "人間が生きるために必要な物として、水と並べて入る語は「食糧」。", "座布団": "座る時に使う布製品で、生きるために欠かせない物として水と並ばない。", "鉛筆": "筆記具で、水と並べて生命を維持する物として語られることはない。", "花火": "娯楽用の火薬製品で、生命維持に必要な物ではない。"}, "sentence_index": 0, "correct_answer": "食糧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人口が増えると、家族全員で食糧を結う時間も増える。", "explanation": "ここは〈髪〉の意味。髪を結うとは言うが、食糧は結うものではないので合わない。"}, {"text": "人口が増えると、必要な食糧を立てる回数も増える。", "explanation": "ここは〈献立〉の意味。献立を立てるとは言うが、食糧を立てるとは言わない。"}, {"text": "人口が増えると、家族が食糧を囲む機会も増える。", "explanation": "ここは〈食卓〉の意味。食卓を囲むとは言うが、食糧を囲むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食糧", "is_correct": true, "explanation": "政府が備蓄で備える対象として、生きるための食べ物の「食糧」が入る。"}, {"text": "色彩", "is_correct": false, "explanation": "物の色合いを表す語で、米の備蓄によって備える対象にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "体の状態を表す語で、備蓄で備える対象ではない。"}, {"text": "漢字", "is_correct": false, "explanation": "文字の一種で、米の備蓄と結びつく文脈にはない。"}], "explanations": {"食糧": "政府が備蓄で備える対象として、生きるための食べ物の「食糧」が入る。", "色彩": "物の色合いを表す語で、米の備蓄によって備える対象にはならない。", "眠気": "体の状態を表す語で、備蓄で備える対象ではない。", "漢字": "文字の一種で、米の備蓄と結びつく文脈にはない。"}, "sentence_index": 6, "correct_answer": "食糧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は、古い食糧を縫って、雑巾を作った。", "explanation": "ここは〈布〉の意味。布を縫うとは言うが、食糧は縫うものではないので合わない。"}, {"text": "寝る前に、母は食糧を敷いてくれた。", "explanation": "ここは〈寝具〉の意味。布団を敷くとは言うが、食糧を敷く使い方はしない。"}, {"text": "母は夜に食糧を紡いで、毛糸を作った。", "explanation": "ここは〈糸〉の意味。糸を紡ぐとは言うが、食糧は紡ぐものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町では、食糧を足りなくなって配給が始まった。", "corrected_sentence": "町では、食糧が足りなくなって配給が始まった。", "error_description": "誤りは「食糧を」。「足りない」の主語は「が」で示すので、正しくは「食糧が」。「を」では文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39641, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "無人島では、魚や木の実を食糧を変えて暮らした。", "corrected_sentence": "無人島では、魚や木の実を食糧に変えて暮らした。", "error_description": "誤りは「食糧を」。何かに変わる先は「に」で示すので、正しくは「食糧に」。「を」では変化の先が示せず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
