INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある人がいないこと。", "primary_collocate": null, "pronunciation": "ふざい", "ipa": "ɸɯzai", "syllable_count": 3, "sentences": [{"text": "部長の不在のあいだは、私が電話を受けることになっている。", "target_word": "不在", "complexity_tier": "T3", "furigana": "部長[ぶちょう]の不在[ふざい]のあいだは、私[わたし]が電話[でんわ]を受[う]けることになっている。", "sentence_source": "generated"}, {"text": "社長が不在だったので、用件は秘書に伝えた。", "target_word": "不在", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が不在[ふざい]だったので、用件[ようけん]は秘書[ひしょ]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "母は今日、買い物に出かけていて不在だ。", "target_word": "不在", "complexity_tier": "T3", "furigana": "母[はは]は今日[きょう]、買[か]い物[もの]に出[で]かけていて不在[ふざい]だ。", "sentence_source": "generated"}, {"text": "担任の先生の不在を知った生徒たちは、教室で大騒ぎした。", "target_word": "不在", "complexity_tier": "T3", "furigana": "担任[たんにん]の先生[せんせい]の不在[ふざい]を知[し]った生徒[せいと]たちは、教室[きょうしつ]で大騒[おおさわ]ぎした。", "sentence_source": "generated"}, {"text": "家に行ったが不在で、荷物を渡せなかった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "家[いえ]に行[い]ったが不在[ふざい]で、荷物[にもつ]を渡[わた]せなかった。", "sentence_source": "generated"}, {"text": "彼の不在がこんなに寂しいとは思わなかった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "彼[かれ]の不在[ふざい]がこんなに寂[さび]しいとは思[おも]わなかった。", "sentence_source": "generated"}, {"text": "不在の間に、お客様から何度も連絡があった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "不在[ふざい]の間[あいだ]に、お客様[きゃくさま]から何度[なんど]も連絡[れんらく]があった。", "sentence_source": "generated"}, {"text": "父が長く不在だったため、子どもたちは母と暮らしていた。", "target_word": "不在", "complexity_tier": "T3", "furigana": "父[ちち]が長[なが]く不在[ふざい]だったため、子[こ]どもたちは母[はは]と暮[く]らしていた。", "sentence_source": "generated"}, {"text": "インターホンを押しても返事がなく、住人は不在のようだった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "インターホンを押[お]しても返事[へんじ]がなく、住人[じゅうにん]は不在[ふざい]のようだった。", "sentence_source": "generated"}, {"text": "店長の不在を知らずに来た客は、がっかりして帰っていった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "店長[てんちょう]の不在[ふざい]を知[し]らずに来[き]た客[きゃく]は、がっかりして帰[かえ]っていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不在", "label": "基本形"}, {"form": "不在だ", "label": "断定形"}, {"form": "不在の", "label": "連体形(の)"}, {"form": "不在で", "label": "連用形(で)"}, {"form": "不在だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "訪問先や家・職場などで、会いたい人が今そこにいないこと。留守・外出中の意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不在", "is_correct": true, "explanation": "「部長の不在のあいだ」は、部長がいない時間を表す。電話を受ける文脈に合う。"}, {"text": "信頼", "is_correct": false, "explanation": "「信頼」は信じて頼ること。「部長の信頼のあいだ」は時間を表さず、意味が通らない。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝」はありがたく思う気持ち。「部長の感謝のあいだ」は時間の表現として成立しない。"}, {"text": "所有", "is_correct": false, "explanation": "「所有」は持っていること。「部長の所有のあいだ」は不自然で、期間を表せない。"}], "explanations": {"不在": "「部長の不在のあいだ」は、部長がいない時間を表す。電話を受ける文脈に合う。", "信頼": "「信頼」は信じて頼ること。「部長の信頼のあいだ」は時間を表さず、意味が通らない。", "感謝": "「感謝」はありがたく思う気持ち。「部長の感謝のあいだ」は時間の表現として成立しない。", "所有": "「所有」は持っていること。「部長の所有のあいだ」は不自然で、期間を表せない。"}, "sentence_index": 0, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町には、江戸時代の古い寺が今も不在だ。", "explanation": "ここは〈存在〉の意味。寺が今もあることは「存在する」と言う。不在は本来いるべき人がいないことに使うので、建物には合わない。"}, {"text": "事故のあと、彼の行方は今も不在だ。", "explanation": "ここは〈不明〉の意味。行方がわからないことは「行方不明」「不明」と言う。不在は人が本来いる場所にいない状態を指すので合わない。"}, {"text": "満員の電車で、一つだけ不在の席があった。", "explanation": "ここは〈空席〉の意味。座れる席が空いている状態は「空席」と言う。不在は人について使うので、席には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不在", "is_correct": true, "explanation": "「不在の間」は、本来いるはずの人がいない期間を表す。お客様から連絡があった時間帯に合う。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解の間」は期間を表せず、文の意味が通らない。"}, {"text": "熱意", "is_correct": false, "explanation": "「熱意の間」は時間を表す言い方にならず、連絡の文脈とも合わない。"}, {"text": "悲鳴", "is_correct": false, "explanation": "「悲鳴の間」は期間の表現にならず、不自然で意味が通らない。"}], "explanations": {"不在": "「不在の間」は、本来いるはずの人がいない期間を表す。お客様から連絡があった時間帯に合う。", "誤解": "「誤解の間」は期間を表せず、文の意味が通らない。", "熱意": "「熱意の間」は時間を表す言い方にならず、連絡の文脈とも合わない。", "悲鳴": "「悲鳴の間」は期間の表現にならず、不自然で意味が通らない。"}, "sentence_index": 6, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ベルを鳴らしたが、中から返事が不在だった。", "explanation": "ここは〈応答がないこと〉の意味。応答がないことは「無言」「無反応」と言う。不在は人が本来いる場所にいないことを表すので、返事には使わない。"}, {"text": "計算には小さな不在が出た。", "explanation": "ここは〈誤差〉の意味。計算結果のずれは「誤差」と言う。不在は人がいないことを表すので、数値のずれには使わない。"}, {"text": "このデータには一部不在がある。", "explanation": "ここは〈欠落〉の意味。データの抜けは「欠落」と言う。不在は人が本来いる場所にいないことを表すので、データには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長が不在したので、会議は延期になった。", "corrected_sentence": "社長が不在だったので、会議は延期になった。", "error_description": "正しくは「不在だった」。「不在する」という動詞は一般的に使わないので、「不在した」は誤り。名詞の不在には「だった」を付けて述語にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生が不在を間に、生徒は自習をした。", "corrected_sentence": "先生が不在の間に、生徒は自習をした。", "error_description": "正しくは「不在の間」（「の」）。「不在を」は目的語の「を」なので、「間」につながらず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「責任者の不在が」は、不在を主語にして「混乱を大きくした」原因を述べる。文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「不在を」は目的語になるが、「大きくした」の目的語は「混乱」なので、目的語が二つ並んで不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「不在へ」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「不在の、」は連体修飾の形で文が切れてしまい、文法的につながらない。"}], "correct_answer": "が", "explanations": {"が": "「責任者の不在が」は、不在を主語にして「混乱を大きくした」原因を述べる。文に合う。", "を": "「不在を」は目的語になるが、「大きくした」の目的語は「混乱」なので、目的語が二つ並んで不自然。", "へ": "「へ」は方向を表すので、「不在へ」は意味が通らない。", "の": "「不在の、」は連体修飾の形で文が切れてしまい、文法的につながらない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「親の不在が」は、不在を主語にして「長引くと」の主語を示す。文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「長引く」は「〜が長引く」の形で主語を取るため、「不在に長引く」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "「長引く」は自動詞なので目的語「を」を取れず、「不在を長引く」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「不在へ長引く」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「親の不在が」は、不在を主語にして「長引くと」の主語を示す。文に合う。", "に": "「長引く」は「〜が長引く」の形で主語を取るため、「不在に長引く」は不自然。", "を": "「長引く」は自動詞なので目的語「を」を取れず、「不在を長引く」は成り立たない。", "へ": "「へ」は方向を表すため、「不在へ長引く」は意味が通らない。"}, "error_tags": {"に": "位置・時点", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や場面に、本来いるべき人がいないこと。また、そのような状態。", "primary_collocate": null, "pronunciation": "ふざい", "ipa": "ɸɯzai", "syllable_count": 3, "sentences": [{"text": "会議にリーダーが不在のまま、話し合いが始まった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "会議[かいぎ]にリーダーが不在[ふざい]のまま、話[はな]し合[あ]いが始[はじ]まった。", "sentence_source": "generated"}, {"text": "責任者の不在が、現場の混乱を大きくした。", "target_word": "不在", "complexity_tier": "T3", "furigana": "責任者[せきにんしゃ]の不在[ふざい]が、現場[げんば]の混乱[こんらん]を大[おお]きくした。", "sentence_source": "generated"}, {"text": "父親の不在という状況で育った彼は、早く自立した。", "target_word": "不在", "complexity_tier": "T3", "furigana": "父親[ちちおや]の不在[ふざい]という状況[じょうきょう]で育[そだ]った彼[かれ]は、早[はや]く自立[じりつ]した。", "sentence_source": "generated"}, {"text": "担当医が不在の病棟では、看護師が対応に追われた。", "target_word": "不在", "complexity_tier": "T3", "furigana": "担当医[たんとうい]が不在[ふざい]の病棟[びょうとう]では、看護師[かんごし]が対応[たいおう]に追[お]われた。", "sentence_source": "generated"}, {"text": "王の不在が続くと、国の政治は不安定になる。", "target_word": "不在", "complexity_tier": "T3", "furigana": "王[おう]の不在[ふざい]が続[つづ]くと、国[くに]の政治[せいじ]は不安定[ふあんてい]になる。", "sentence_source": "generated"}, {"text": "教師が不在の教室では、自習の時間になった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "教師[きょうし]が不在[ふざい]の教室[きょうしつ]では、自習[じしゅう]の時間[じかん]になった。", "sentence_source": "generated"}, {"text": "決定権を持つ人の不在で、会議は何も決まらなかった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "決定権[けっていけん]を持[も]つ人[ひと]の不在[ふざい]で、会議[かいぎ]は何[なに]も決[き]まらなかった。", "sentence_source": "generated"}, {"text": "親の不在が長引くと、子どもは寂しい思いをする。", "target_word": "不在", "complexity_tier": "T3", "furigana": "親[おや]の不在[ふざい]が長引[ながび]くと、子[こ]どもは寂[さび]しい思[おも]いをする。", "sentence_source": "generated"}, {"text": "主役の不在を、舞台の上の誰も埋められなかった。", "target_word": "不在", "complexity_tier": "T3", "furigana": "主役[しゅやく]の不在[ふざい]を、舞台[ぶたい]の上[うえ]の誰[だれ]も埋[う]められなかった。", "sentence_source": "generated"}, {"text": "監督が不在でも、選手たちは落ち着いて試合に臨んだ。", "target_word": "不在", "complexity_tier": "T3", "furigana": "監督[かんとく]が不在[ふざい]でも、選手[せんしゅ]たちは落[お]ち着[つ]いて試合[しあい]に臨[のぞ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不在", "label": "基本形"}, {"form": "不在の", "label": "連体形(の)"}, {"form": "不在で", "label": "連用形(で)"}, {"form": "不在のまま", "label": "状態(のまま)"}], "register": "formal", "sense_fingerprint": "会議・職場・家庭などで、責任者や中心人物などいるべき人がいない状態。その影響や問題を述べる場面で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不在", "is_correct": true, "explanation": "「リーダーが不在のまま」は、リーダーがいない状態が続いたままという意味。会議が始まった文脈に合う。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝」は気持ちを表す語。「リーダーが感謝のまま」は状態として意味が通らない。"}, {"text": "所有", "is_correct": false, "explanation": "「所有のまま」ではリーダーの状態を表せず、不自然になる。"}, {"text": "悲鳴", "is_correct": false, "explanation": "「悲鳴のまま」は状態を表す語として成立せず、会議の文脈に合わない。"}], "explanations": {"不在": "「リーダーが不在のまま」は、リーダーがいない状態が続いたままという意味。会議が始まった文脈に合う。", "感謝": "「感謝」は気持ちを表す語。「リーダーが感謝のまま」は状態として意味が通らない。", "所有": "「所有のまま」ではリーダーの状態を表せず、不自然になる。", "悲鳴": "「悲鳴のまま」は状態を表す語として成立せず、会議の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白紙のページに、一行だけ不在が残っていた。", "explanation": "ここは〈空白〉の意味。紙に何も書かれていない部分は「空白」と言う。不在は本来いるべき人がいない状態に使うので、紙の余白には合わない。"}, {"text": "事務所の金庫から、現金が不在だった。", "explanation": "ここは〈消失〉の意味。なくなった物は「消失」「紛失」と言う。不在は人がいるべき場所にいないことに使うので、お金には合わない。"}, {"text": "この壁には、火事の不在が残っている。", "explanation": "ここは〈痕跡〉の意味。火事のあとに残った跡は「痕跡」と言う。不在は人がいないことを表すので、焼け跡には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不在", "is_correct": true, "explanation": "「決定権を持つ人の不在で」は、その人がいないことが原因で会議が決まらなかったという意味。文に合う。"}, {"text": "熱湯", "is_correct": false, "explanation": "「熱湯で」は手段や材料を表し、ここでは原因として意味が通らない。"}, {"text": "落書き", "is_correct": false, "explanation": "「落書きで」は会議が何も決まらなかった原因として不自然で、文脈に合わない。"}, {"text": "花束", "is_correct": false, "explanation": "「花束で」は、会議が何も決まらなかった理由として成り立たない。"}], "explanations": {"不在": "「決定権を持つ人の不在で」は、その人がいないことが原因で会議が決まらなかったという意味。文に合う。", "熱湯": "「熱湯で」は手段や材料を表し、ここでは原因として意味が通らない。", "落書き": "「落書きで」は会議が何も決まらなかった原因として不自然で、文脈に合わない。", "花束": "「花束で」は、会議が何も決まらなかった理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この製品には大きな不在がある。", "explanation": "ここは〈欠陥〉の意味。製品の不良点は「欠陥」と言う。不在は人が本来いるべき場所にいないことを表すので、製品には合わない。"}, {"text": "壁と床のあいだに、わずかな不在があった。", "explanation": "ここは〈隙間〉の意味。物と物のあいだのすき間は「隙間」と言う。不在は人がいないことに使うので、壁と床のあいだには合わない。"}, {"text": "この店には、まだ試着室が不在だ。", "explanation": "ここは〈存在〉の意味。設備がないことは「存在しない」と言う。不在は本来いるべき人がいないことに使うので、設備には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "リーダーの不在をため、チームは判断を先送りにした。", "corrected_sentence": "リーダーの不在のため、チームは判断を先送りにした。", "error_description": "正しくは「不在のため」（「の」）。「不在を」は目的語の「を」で、原因を表す「ため」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39643, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コーチが不在でまま、練習は始まった。", "corrected_sentence": "コーチが不在のまま、練習は始まった。", "error_description": "正しくは「不在のまま」（「の」）。「不在で」は断定の「で」で、「まま」の前には「の」が必要。「不在でまま」は文法的に続かず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「繁殖を助ける」の目的語を表す。「助ける」は対象を「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「繁殖に助ける」とは言えず、「助ける」の対象には「を」が要る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「助ける」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞につくもので、動詞「助ける」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「繁殖を助ける」の目的語を表す。「助ける」は対象を「を」で示す。", "に": "「繁殖に助ける」とは言えず、「助ける」の対象には「を」が要る。", "へ": "方向を表す「へ」は「助ける」の目的語にならない。", "の": "連体修飾の「の」は名詞につくもので、動詞「助ける」の目的語にはならない。"}, "error_tags": {"に": "位置・相手の格", "へ": "方向の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「人の手で」と、手段・方法を表す。人の手によって繁殖させる、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「手を繁殖させる」とは言えず、文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「手に」は場所を表すが、「手に繁殖させている」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「手の繁殖させている」は文の構造が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「人の手で」と、手段・方法を表す。人の手によって繁殖させる、という意味になる。", "を": "「手を繁殖させる」とは言えず、文の意味が通らない。", "に": "「手に」は場所を表すが、「手に繁殖させている」は意味が通らない。", "の": "「手の繁殖させている」は文の構造が成り立たない。"}, "error_tags": {"を": "目的語の格", "に": "位置の格", "の": "連体修飾の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物が子どもをふやして、数をふやすこと。", "primary_collocate": null, "pronunciation": "はんしょく", "ipa": "haɲɕokɯ", "syllable_count": 4, "sentences": [{"text": "ウサギは繁殖が早いので、すぐに数が増える。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "ウサギは繁殖[はんしょく]が早[はや]いので、すぐに数[かず]が増[ふ]える。", "sentence_source": "generated"}, {"text": "池の魚の繁殖を助けるため、水草を植えた。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "池[いけ]の魚[さかな]の繁殖[はんしょく]を助[たす]けるため、水草[みずくさ]を植[う]えた。", "sentence_source": "generated"}, {"text": "春になると、鳥の繁殖の季節が始まります。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "春[はる]になると、鳥[とり]の繁殖[はんしょく]の季節[きせつ]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "この動物は、冬の間は繁殖しません。", "target_word": "繁殖しません", "complexity_tier": "T3", "furigana": "この動物[どうぶつ]は、冬[ふゆ]の間[あいだ]は繁殖[はんしょく]しません。", "sentence_source": "generated"}, {"text": "動物園では、パンダの繁殖に力を入れている。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、パンダの繁殖[はんしょく]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "ネズミが繁殖して、倉庫の食べ物が減ってしまった。", "target_word": "繁殖して", "complexity_tier": "T3", "furigana": "ネズミが繁殖[はんしょく]して、倉庫[そうこ]の食[た]べ物[もの]が減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "カエルは水の中で繁殖します。", "target_word": "繁殖します", "complexity_tier": "T3", "furigana": "カエルは水[みず]の中[なか]で繁殖[はんしょく]します。", "sentence_source": "generated"}, {"text": "絶滅しそうな鳥を守るため、人の手で繁殖させている。", "target_word": "繁殖させている", "complexity_tier": "T3", "furigana": "絶滅[ぜつめつ]しそうな鳥[とり]を守[まも]るため、人[ひと]の手[て]で繁殖[はんしょく]させている。", "sentence_source": "generated"}, {"text": "暖かい場所では、虫の繁殖が盛んになる。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "暖[あたた]かい場所[ばしょ]では、虫[むし]の繁殖[はんしょく]が盛[さか]んになる。", "sentence_source": "generated"}, {"text": "牧場では、馬の繁殖を専門にしている人が働いている。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "牧場[ぼくじょう]では、馬[うま]の繁殖[はんしょく]を専門[せんもん]にしている人[ひと]が働[はたら]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁殖する", "label": "辞書形"}, {"form": "繁殖します", "label": "丁寧形"}, {"form": "繁殖して", "label": "て形"}, {"form": "繁殖した", "label": "た形"}, {"form": "繁殖しない", "label": "ない形"}, {"form": "繁殖させる", "label": "使役形"}], "register": "中立（丁寧体と普通体）", "sense_fingerprint": "動物が子を産み育てて数が増えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "「子をふやして数が増える」意味。ウサギの増える速さを表すのに合う。"}, {"text": "購入", "is_correct": false, "explanation": "「買い入れること」。「ウサギは購入が早い」は意味をなさず、増える速さを表せない。"}, {"text": "清掃", "is_correct": false, "explanation": "「掃除すること」。ウサギの増え方とは結びつかない。"}, {"text": "散歩", "is_correct": false, "explanation": "「ぶらぶら歩くこと」。増える速さの話には合わない。"}], "explanations": {"繁殖": "「子をふやして数が増える」意味。ウサギの増える速さを表すのに合う。", "購入": "「買い入れること」。「ウサギは購入が早い」は意味をなさず、増える速さを表せない。", "清掃": "「掃除すること」。ウサギの増え方とは結びつかない。", "散歩": "「ぶらぶら歩くこと」。増える速さの話には合わない。"}, "sentence_index": 0, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は毎週末、客が列を作るほど繁殖している。", "explanation": "ここは〈繁盛〉の意味。店の人気や客の多さには繁盛を使う。繁殖は動物が子をふやすことなので、店には合わない。"}, {"text": "うわさが繁殖して、町中に広がった。", "explanation": "ここは〈広まる〉の意味。うわさが広がることには広まるを使う。繁殖は生き物が子をふやすことに使うので、うわさには合わない。"}, {"text": "借金が繁殖して、家計が苦しくなった。", "explanation": "ここは〈膨らむ〉の意味。金額が増えることには膨らむを使う。繁殖は生き物について言うので、借金には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁殖します", "is_correct": true, "explanation": "「子をふやして数が増える」意味。カエルの増え方を言うのに合う。"}, {"text": "出荷します", "is_correct": false, "explanation": "「商品を送り出すこと」。カエルが水の中で行うこととは結びつかない。"}, {"text": "演奏します", "is_correct": false, "explanation": "「楽器などで音楽を奏でること」。カエルの生活の話には合わない。"}, {"text": "販売します", "is_correct": false, "explanation": "「商品を売ること」。カエルが水の中で行うことにはならない。"}], "explanations": {"繁殖します": "「子をふやして数が増える」意味。カエルの増え方を言うのに合う。", "出荷します": "「商品を送り出すこと」。カエルが水の中で行うこととは結びつかない。", "演奏します": "「楽器などで音楽を奏でること」。カエルの生活の話には合わない。", "販売します": "「商品を売ること」。カエルが水の中で行うことにはならない。"}, "sentence_index": 6, "correct_answer": "繁殖します"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "江戸は商業都市として大きく繁殖した。", "explanation": "ここは〈繁栄〉の意味。都市や国が栄えることには繁栄を使う。繁殖は動植物が子をふやすことなので、都市には合わない。"}, {"text": "その噂は一晩で町中に繁殖した。", "explanation": "ここは〈広まる〉の意味。噂や話題が広がることには広まるを使う。繁殖は生き物が子をふやすことなので、噂には合わない。"}, {"text": "会社の売上が毎月繁殖している。", "explanation": "ここは〈伸びる〉の意味。売上が増えることには伸びるを使う。繁殖は生き物について言うので、売上には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ネズミの繁殖に防ぐため、ごみを捨てた。", "corrected_sentence": "ネズミの繁殖を防ぐため、ごみを捨てた。", "error_description": "助詞の誤り。「防ぐ」の目的語は「繁殖を」。「繁殖に」は誤りで、正しくは「繁殖を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネズミは暗い倉庫でよく繁殖ます。", "corrected_sentence": "ネズミは暗い倉庫でよく繁殖します。", "error_description": "活用の誤り。丁寧形は「繁殖します」。「繁殖ます」は「し」が抜けていて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「カビの繁殖に向いた」の「に」。「向く」は相手を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「繁殖を向いた」は成り立たず、「向く」には「を」を取れない。"}, {"text": "で", "is_correct": false, "explanation": "「繁殖で向いた」は手段を表すが、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「繁殖の向いた季節」は文の構造が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「カビの繁殖に向いた」の「に」。「向く」は相手を「に」で示す。", "を": "「繁殖を向いた」は成り立たず、「向く」には「を」を取れない。", "で": "「繁殖で向いた」は手段を表すが、意味が通らない。", "の": "「繁殖の向いた季節」は文の構造が成り立たない。"}, "error_tags": {"を": "目的語の格", "で": "場所・手段の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「シカが」の「が」。「シカ」が「繁殖しすぎて」の主語であることを示す。"}, {"text": "に", "is_correct": false, "explanation": "「シカに繁殖しすぎて」は文が成り立たず、主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「シカで繁殖しすぎて」は手段や場所を表すが、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「シカと繁殖しすぎて」は並列になり、後ろの「森の草が食べられた」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「シカが」の「が」。「シカ」が「繁殖しすぎて」の主語であることを示す。", "に": "「シカに繁殖しすぎて」は文が成り立たず、主語を示せない。", "で": "「シカで繁殖しすぎて」は手段や場所を表すが、意味が通らない。", "と": "「シカと繁殖しすぎて」は並列になり、後ろの「森の草が食べられた」と結びつかない。"}, "error_tags": {"に": "位置・相手の格", "で": "場所・手段の格", "と": "並列・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生物が子孫を残して個体数を増やすこと。", "primary_collocate": null, "pronunciation": "はんしょく", "ipa": "haɲɕokɯ", "syllable_count": 4, "sentences": [{"text": "外来の魚が繁殖して、昔からいた魚が減った。", "target_word": "繁殖して", "complexity_tier": "T3", "furigana": "外来[がいらい]の魚[さかな]が繁殖[はんしょく]して、昔[むかし]からいた魚[さかな]が減[へ]った。", "sentence_source": "generated"}, {"text": "梅雨は湿気が多く、カビの繁殖に向いた季節です。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "梅雨[つゆ]は湿気[しっけ]が多[おお]く、カビの繁殖[はんしょく]に向[む]いた季節[きせつ]です。", "sentence_source": "generated"}, {"text": "食べ物を冷蔵庫に入れるのは、細菌の繁殖を防ぐためだ。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]を冷蔵庫[れいぞうこ]に入[い]れるのは、細菌[さいきん]の繁殖[はんしょく]を防[ふせ]ぐためだ。", "sentence_source": "generated"}, {"text": "このサボテンは、種でも株分けでも繁殖できる。", "target_word": "繁殖できる", "complexity_tier": "T3", "furigana": "このサボテンは、種[たね]でも株分[かぶわ]けでも繁殖[はんしょく]できる。", "sentence_source": "generated"}, {"text": "湖で藻が大量に繁殖し、水が緑色になった。", "target_word": "繁殖し", "complexity_tier": "T3", "furigana": "湖[みずうみ]で藻[も]が大量[たいりょう]に繁殖[はんしょく]し、水[みず]が緑色[みどりいろ]になった。", "sentence_source": "generated"}, {"text": "暑いと菌の繁殖が速くなるから、お弁当は早めに食べましょう。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "暑[あつ]いと菌[きん]の繁殖[はんしょく]が速[はや]くなるから、お弁当[べんとう]は早[はや]めに食[た]べましょう。", "sentence_source": "generated"}, {"text": "研究者は、ハチの繁殖の仕組みを調べている。", "target_word": "繁殖", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、ハチの繁殖[はんしょく]の仕組[しく]みを調[しら]べている。", "sentence_source": "generated"}, {"text": "シカが繁殖しすぎて、森の草が食べられてしまった。", "target_word": "繁殖しすぎて", "complexity_tier": "T3", "furigana": "シカが繁殖[はんしょく]しすぎて、森[もり]の草[くさ]が食[た]べられてしまった。", "sentence_source": "generated"}, {"text": "この島では、ウミガメが毎年繁殖している。", "target_word": "繁殖している", "complexity_tier": "T3", "furigana": "この島[しま]では、ウミガメが毎年[まいとし]繁殖[はんしょく]している。", "sentence_source": "generated"}, {"text": "水槽の中で、小さな貝が繁殖して増えていた。", "target_word": "繁殖して", "complexity_tier": "T3", "furigana": "水槽[すいそう]の中[なか]で、小[ちい]さな貝[かい]が繁殖[はんしょく]して増[ふ]えていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁殖する", "label": "辞書形"}, {"form": "繁殖します", "label": "丁寧形"}, {"form": "繁殖して", "label": "て形"}, {"form": "繁殖した", "label": "た形"}, {"form": "繁殖しない", "label": "ない形"}, {"form": "繁殖させる", "label": "使役形"}], "register": "中立（丁寧体と普通体）", "sense_fingerprint": "細菌・植物・外来種などの生物が子孫を残して個体数が増えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁殖して", "is_correct": true, "explanation": "「子孫を残して個体数を増やす」意味。外来の魚が増えて在来の魚が減る話に合う。"}, {"text": "演奏して", "is_correct": false, "explanation": "「楽器などで音楽を奏でる」。魚の数が増えることとは結びつかない。"}, {"text": "販売して", "is_correct": false, "explanation": "「商品を売る」。魚が増えて減る話には合わない。"}, {"text": "撮影して", "is_correct": false, "explanation": "「写真や映像を撮る」。魚の数の変化とは結びつかない。"}], "explanations": {"繁殖して": "「子孫を残して個体数を増やす」意味。外来の魚が増えて在来の魚が減る話に合う。", "演奏して": "「楽器などで音楽を奏でる」。魚の数が増えることとは結びつかない。", "販売して": "「商品を売る」。魚が増えて減る話には合わない。", "撮影して": "「写真や映像を撮る」。魚の数の変化とは結びつかない。"}, "sentence_index": 0, "correct_answer": "繁殖して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "戦後、この国は貿易で大きく繁殖した。", "explanation": "ここは〈繁栄〉の意味。国や町が栄えることには繁栄を使う。繁殖は生物が子孫を残して数をふやすことなので、国には合わない。"}, {"text": "倉庫の在庫が繁殖して、棚に入りきらなくなった。", "explanation": "ここは〈増える〉の意味。在庫の数が増えることには増えるを使う。繁殖は生物について言うので、在庫には合わない。"}, {"text": "台風が繁殖して、沿岸の被害が広がった。", "explanation": "ここは〈発生〉の意味。台風が生まれて現れることには発生を使う。台風は生物ではないので、繁殖は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "「子孫を残して個体数を増やす」意味。ハチの繁殖の仕組みという研究対象に合う。"}, {"text": "清掃", "is_correct": false, "explanation": "「掃除すること」。ハチの仕組みを調べる話とは結びつかない。"}, {"text": "出荷", "is_correct": false, "explanation": "「商品を送り出すこと」。ハチの仕組みの研究には合わない。"}, {"text": "購入", "is_correct": false, "explanation": "「買い入れること」。ハチの仕組みの研究とは結びつかない。"}], "explanations": {"繁殖": "「子孫を残して個体数を増やす」意味。ハチの繁殖の仕組みという研究対象に合う。", "清掃": "「掃除すること」。ハチの仕組みを調べる話とは結びつかない。", "出荷": "「商品を送り出すこと」。ハチの仕組みの研究には合わない。", "購入": "「買い入れること」。ハチの仕組みの研究とは結びつかない。"}, "sentence_index": 6, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この夏、流行の服が繁殖して、街中の人が着ている。", "explanation": "ここは〈はやる〉の意味。服が広く人気になることには、はやるを使う。繁殖は生物について使うので、服には合わない。"}, {"text": "その話題は一晩で国中に繁殖した。", "explanation": "ここは〈広まる〉の意味。話題や情報が広がることには広まるを使う。繁殖は生物が数をふやすことなので、話題には合わない。"}, {"text": "ネット通販の利用者が年々繁殖している。", "explanation": "ここは〈伸びる〉の意味。利用者や売上が増えることには伸びるを使う。繁殖は生物について使うので、人数には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雑菌の繁殖が防ぐため、台所を毎日拭く。", "corrected_sentence": "雑菌の繁殖を防ぐため、台所を毎日拭く。", "error_description": "助詞の誤り。「防ぐ」の目的語は「繁殖を」。「繁殖が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い池では、ボウフラは繁殖ない。", "corrected_sentence": "寒い池では、ボウフラは繁殖しない。", "error_description": "否定形の誤り。正しくは「繁殖しない」。「繁殖ない」は「し」が抜けていて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "阻害する対象「成長」を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「成長に阻害する」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「成長で阻害する」は対象を表せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「成長と阻害する」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "阻害する対象「成長」を示す「を」。", "に": "「成長に阻害する」は文法的に成り立たない。", "で": "「成長で阻害する」は対象を表せず不自然。", "と": "「成長と阻害する」は成り立たない。"}, "error_tags": {"に": "target_marker", "で": "means", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促進", "is_correct": true, "explanation": "物事の進行を進める意味で、「阻害」の反対。"}, {"text": "妨害", "is_correct": false, "explanation": "妨げる意味で、類義語であり反対語ではない。"}, {"text": "抑制", "is_correct": false, "explanation": "抑える意味で、反対語ではない。"}, {"text": "遅延", "is_correct": false, "explanation": "遅れることで、反対語ではない。"}], "correct_answer": "促進", "explanations": {"促進": "物事の進行を進める意味で、「阻害」の反対。", "妨害": "妨げる意味で、類義語であり反対語ではない。", "抑制": "抑える意味で、反対語ではない。", "遅延": "遅れることで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "阻害する対象「進行」を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「進行に阻害する」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「進行で阻害する」は対象を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「進行から阻害する」は不自然で成り立たない。"}], "correct_answer": "を", "explanations": {"を": "阻害する対象「進行」を示す「を」。", "に": "「進行に阻害する」は成り立たない。", "で": "「進行で阻害する」は対象を表せない。", "から": "「進行から阻害する」は不自然で成り立たない。"}, "error_tags": {"に": "target_marker", "で": "means", "から": "source"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推進", "is_correct": true, "explanation": "物事を前に進める意味で、「阻害」の反対。"}, {"text": "阻止", "is_correct": false, "explanation": "止める意味で、類義語。"}, {"text": "制限", "is_correct": false, "explanation": "限る意味で、反対語ではない。"}, {"text": "停滞", "is_correct": false, "explanation": "進まない状態で、反対語ではない。"}], "correct_answer": "推進", "explanations": {"推進": "物事を前に進める意味で、「阻害」の反対。", "阻止": "止める意味で、類義語。", "制限": "限る意味で、反対語ではない。", "停滞": "進まない状態で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の進行や機能を妨げること。", "primary_collocate": null, "pronunciation": "そがい", "ipa": "soɡai", "syllable_count": 3, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "阻害", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールの下[もと]では、市場[しじょう]メカニズムを通[つう]じた適正[てきせい]なリスクプレミアムの形成[けいせい]が阻害[そがい]され、結果[けっか]として財政[ざいせい]の持続[じぞく]可能性[かのうせい]を担保[たんぽ]するべき債務[さいむ]の価格的[かかくてき]シグナルが鈍磨[どんま]する懸念[けねん]が拭[ぬぐ]えない。", "sentence_source": "mined"}, {"text": "雑草が成長を阻害する。", "target_word": "阻害", "complexity_tier": "T2", "furigana": "雑草[ざっそう]が成長[せいちょう]を阻害[そがい]する。", "sentence_source": "generated"}, {"text": "騒音は睡眠を阻害します。", "target_word": "阻害", "complexity_tier": "T2", "furigana": "騒音[そうおん]は睡眠[すいみん]を阻害[そがい]します。", "sentence_source": "generated"}, {"text": "古い制度が改革の阻害になっている。", "target_word": "阻害", "complexity_tier": "T3", "furigana": "古[ふる]い制度[せいど]が改革[かいかく]の阻害[そがい]になっている。", "sentence_source": "generated"}, {"text": "血流が阻害されると、細胞は働けなくなる。", "target_word": "阻害", "complexity_tier": "T4", "furigana": "血流[けつりゅう]が阻害[そがい]されると、細胞[さいぼう]は働[はたら]けなくなる。", "sentence_source": "generated"}, {"text": "この薬は酵素の働きを阻害する。", "target_word": "阻害", "complexity_tier": "T3", "furigana": "この薬[くすり]は酵素[こうそ]の働[はたら]きを阻害[そがい]する。", "sentence_source": "generated"}, {"text": "過度な規制は、新しい企業の成長の阻害となる。", "target_word": "阻害", "complexity_tier": "T4", "furigana": "過度[かど]な規制[きせい]は、新[あたら]しい企業[きぎょう]の成長[せいちょう]の阻害[そがい]となる。", "sentence_source": "generated"}, {"text": "連絡不足は、仕事の進行を阻害する。", "target_word": "阻害", "complexity_tier": "T3", "furigana": "連絡[れんらく]不足[ぶそく]は、仕事[しごと]の進行[しんこう]を阻害[そがい]する。", "sentence_source": "generated"}, {"text": "問題が解決しない限り、計画は阻害され続ける。", "target_word": "阻害", "complexity_tier": "T4", "furigana": "問題[もんだい]が解決[かいけつ]しない限[かぎ]り、計画[けいかく]は阻害[そがい]され続[つづ]ける。", "sentence_source": "generated"}, {"text": "排水が阻害されたため、道路が冠水した。", "target_word": "阻害", "complexity_tier": "T4", "furigana": "排水[はいすい]が阻害[そがい]されたため、道路[どうろ]が冠水[かんすい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻害する", "label": "活用"}, {"form": "阻害された", "label": "活用"}, {"form": "阻害要因", "label": "派生"}, {"form": "阻害剤", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の進行や機能を妨げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阻害", "is_correct": true, "explanation": "見出し語「そがい」そのもの。"}, {"text": "疎開", "is_correct": false, "explanation": "「そかい」で、「が」が「か」に変わる一音違いの別語。"}, {"text": "素材", "is_correct": false, "explanation": "「そざい」で、「が」が「ざ」に変わる一音違いの別語。"}, {"text": "粗大", "is_correct": false, "explanation": "「そだい」で、「が」が「だ」に変わる一音違いの別語。"}, {"text": "市外", "is_correct": false, "explanation": "「しがい」で、「そ」が「し」に変わる一音違いの別語。"}], "explanations": {"阻害": "見出し語「そがい」そのもの。", "疎開": "「そかい」で、「が」が「か」に変わる一音違いの別語。", "素材": "「そざい」で、「が」が「ざ」に変わる一音違いの別語。", "粗大": "「そだい」で、「が」が「だ」に変わる一音違いの別語。", "市外": "「しがい」で、「そ」が「し」に変わる一音違いの別語。"}, "sentence_index": null, "correct_answer": "阻害"}, "level_3": {"options": [{"text": "阻害", "is_correct": true, "explanation": "「形成が阻害され」で、適正な価格形成が妨げられる意味に合う。"}, {"text": "実施", "is_correct": false, "explanation": "形は合うが、「形成が実施される」では意味が合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "形は合うが、「形成が撤回される」では意味が合わない。"}, {"text": "公表", "is_correct": false, "explanation": "形は合うが、「形成が公表される」では意味が合わない。"}], "explanations": {"阻害": "「形成が阻害され」で、適正な価格形成が妨げられる意味に合う。", "実施": "形は合うが、「形成が実施される」では意味が合わない。", "撤回": "形は合うが、「形成が撤回される」では意味が合わない。", "公表": "形は合うが、「形成が公表される」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "阻害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日ジョギングをして健康を阻害している。", "explanation": "ジョギングは健康を妨げるものではなく、「阻害」の使い方が文脈に合わない。"}, {"text": "友人の阻害を受けて、新しい仕事を始めることができた。", "explanation": "「阻害」は妨げることなので、助けを受ける意味では使えない。"}, {"text": "この薬は体の回復を阻害して、病気を早く治す。", "explanation": "回復を妨げるのに早く治るという矛盾があり、「阻害」の意味と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "阻害", "is_correct": true, "explanation": "見出し語「そがい」そのもの。"}, {"text": "戸外", "is_correct": false, "explanation": "「こがい」で、「そ」が「こ」に変わる一音違いの別語。"}, {"text": "相違", "is_correct": false, "explanation": "「そうい」で、「が」が「う」に変わる一音違いの別語。"}, {"text": "うがい", "is_correct": false, "explanation": "「うがい」で、「そ」が「う」に変わる一音違いの別語。"}], "explanations": {"阻害": "見出し語「そがい」そのもの。", "戸外": "「こがい」で、「そ」が「こ」に変わる一音違いの別語。", "相違": "「そうい」で、「が」が「う」に変わる一音違いの別語。", "うがい": "「うがい」で、「そ」が「う」に変わる一音違いの別語。"}, "sentence_index": null, "correct_answer": "阻害"}, "level_3": {"options": [{"text": "阻害", "is_correct": true, "explanation": "過度な規制が成長を妨げるという意味に合う。"}, {"text": "発表", "is_correct": false, "explanation": "形は合うが、「成長の発表となる」では意味が合わない。"}, {"text": "参加", "is_correct": false, "explanation": "形は合うが、「成長の参加となる」では意味が合わない。"}, {"text": "計算", "is_correct": false, "explanation": "形は合うが、「成長の計算となる」では意味が合わない。"}], "explanations": {"阻害": "過度な規制が成長を妨げるという意味に合う。", "発表": "形は合うが、「成長の発表となる」では意味が合わない。", "参加": "形は合うが、「成長の参加となる」では意味が合わない。", "計算": "形は合うが、「成長の計算となる」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "阻害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "広い道路の整備が交通の阻害となり、渋滞が解消した。", "explanation": "「阻害」なら渋滞が悪化するはずで、解消という結果と矛盾する。"}, {"text": "彼女は努力して、試験の合格を阻害した。", "explanation": "努力の結果は「達成」であり、「阻害」では意味が合わない。"}, {"text": "私は毎朝コーヒーを阻害して目を覚ます。", "explanation": "「阻害」は飲む意味ではなく、コーヒーと結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい法律が経済の発展に阻害した。", "corrected_sentence": "新しい法律が経済の発展を阻害した。", "error_description": "「阻害する」は対象を「を」で取る他動詞的表現で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39647, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "情報の不足が決定を阻害にする。", "corrected_sentence": "情報の不足が決定を阻害する。", "error_description": "「阻害」はサ変名詞で「阻害する」と言い、「阻害にする」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「提言」は「聞く」の対象なので、直後に「を」を付ける。「提言を聞いて」となる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「提言が聞いて」では提言が聞く側の主語にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「聞く」の相手を示す。提言は相手ではないので「提言に聞いて」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「提言へ聞いて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「提言」は「聞く」の対象なので、直後に「を」を付ける。「提言を聞いて」となる。", "が": "「が」は主語を示す。「提言が聞いて」では提言が聞く側の主語にならないので合わない。", "に": "「に」は「聞く」の相手を示す。提言は相手ではないので「提言に聞いて」は合わない。", "へ": "「へ」は方向を示す。「提言へ聞いて」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「提言として」の「と」。提言を「意見を出す立場」として示すので、直後に「して」が続く。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「提言の」の後に「して出せば」が続くと文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「提言より」では比べる対象が成り立たず、「して出せば」に続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「〜からして」は「〜すら」の意で、ここでは意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「提言として」の「と」。提言を「意見を出す立場」として示すので、直後に「して」が続く。", "の": "「の」は名詞をつなぐ。「提言の」の後に「して出せば」が続くと文が成り立たない。", "より": "「より」は比較を示す。「提言より」では比べる対象が成り立たず、「して出せば」に続かない。", "から": "「から」は起点を示す。「〜からして」は「〜すら」の意で、ここでは意味が通らない。"}, "error_tags": {"の": "修飾", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の考えや意見を、みんなに伝えるために出すこと。", "primary_collocate": null, "pronunciation": "ていげん", "ipa": "teːɡeɴ", "syllable_count": 4, "sentences": [{"text": "会議で、新入社員が自分の考えを提言した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、新入社員[しんにゅうしゃいん]が自分[じぶん]の考[かんが]えを提言[ていげん]した。", "sentence_source": "generated"}, {"text": "彼の提言を聞いて、みんなが静かになった。", "target_word": "提言", "complexity_tier": "T3", "furigana": "彼[かれ]の提言[ていげん]を聞[き]いて、みんなが静[しず]かになった。", "sentence_source": "generated"}, {"text": "生徒会は、学校を楽しくするための提言を出した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "生徒会[せいとかい]は、学校[がっこう]を楽[たの]しくするための提言[ていげん]を出[だ]した。", "sentence_source": "generated"}, {"text": "町の人たちに向けて、彼は短い提言を発表した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちに向[む]けて、彼[かれ]は短[みじか]い提言[ていげん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "提言は、わかりやすい言葉で伝えることが大切だ。", "target_word": "提言", "complexity_tier": "T3", "furigana": "提言[ていげん]は、わかりやすい言葉[ことば]で伝[つた]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "先輩の提言のおかげで、話し合いが前に進んだ。", "target_word": "提言", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の提言[ていげん]のおかげで、話[はな]し合[あ]いが前[まえ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "彼女は勇気を出して、クラスの前で提言した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は勇気[ゆうき]を出[だ]して、クラスの前[まえ]で提言[ていげん]した。", "sentence_source": "generated"}, {"text": "小さな意見でも、提言として出せば、みんなが考えてくれる。", "target_word": "提言", "complexity_tier": "T3", "furigana": "小[ちい]さな意見[いけん]でも、提言[ていげん]として出[だ]せば、みんなが考[かんが]えてくれる。", "sentence_source": "generated"}, {"text": "住民の提言を集めた冊子が、図書館に置かれている。", "target_word": "提言", "complexity_tier": "T3", "furigana": "住民[じゅうみん]の提言[ていげん]を集[あつ]めた冊子[さっし]が、図書館[としょかん]に置[お]かれている。", "sentence_source": "generated"}, {"text": "彼は会議でいつも具体的な提言をするので、みんなに頼りにされている。", "target_word": "提言", "complexity_tier": "T3", "furigana": "彼[かれ]は会議[かいぎ]でいつも具体的[ぐたいてき]な提言[ていげん]をするので、みんなに頼[たよ]りにされている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提言する", "label": "辞書形"}, {"form": "提言した", "label": "過去形"}, {"form": "提言して", "label": "て形"}, {"form": "提言される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "会議や集まりで、自分の考えや意見をみんなに向けて出すこと、またその意見", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提言", "is_correct": true, "explanation": "「考えを提言する」は会議などで意見を出す意味で、文の「自分の考えを〜した」に合う。"}, {"text": "計算", "is_correct": false, "explanation": "「計算」は数を求めることなので、「考えを計算した」は意味が通らない。"}, {"text": "乗車", "is_correct": false, "explanation": "「乗車」は乗り物に乗ることなので、「考えを乗車した」は文脈に合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることなので、「考えを点火した」は意味が通らない。"}], "explanations": {"提言": "「考えを提言する」は会議などで意見を出す意味で、文の「自分の考えを〜した」に合う。", "計算": "「計算」は数を求めることなので、「考えを計算した」は意味が通らない。", "乗車": "「乗車」は乗り物に乗ることなので、「考えを乗車した」は文脈に合わない。", "点火": "「点火」は火をつけることなので、「考えを点火した」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "提言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい機械を入れて、工場の騒音を大きく提言できた。", "explanation": "ここは〈低減〉（数や量を減らす）の意味。提言は意見を出すことなので、騒音を減らす文には合わない。"}, {"text": "彼は、ずっと言えなかった気持ちを、放課後に彼女へ提言した。", "explanation": "ここは〈告白〉（秘めた気持ちを相手に打ち明ける）の意味。提言は意見を出して相手に勧めることなので、個人の気持ちを打ち明ける文には合わない。"}, {"text": "店員に、彼はコーヒーを二つ提言した。", "explanation": "ここは〈注文〉（品物を頼む）の意味。提言は意見を出すことなので、飲み物を頼む文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提言", "is_correct": true, "explanation": "「提言する」の形で、クラスで意見を出す行為を表す。文脈に合う。"}, {"text": "注射", "is_correct": false, "explanation": "「注射」は薬を体に入れることなので、「クラスの前で注射した」は意味が通らない。"}, {"text": "離婚", "is_correct": false, "explanation": "「離婚」は夫婦関係を解消することなので、クラスの前で行う文脈には合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「解雇」は雇用を終わらせることなので、「クラスの前で解雇した」は勇気を出す文脈に合わない。"}], "explanations": {"提言": "「提言する」の形で、クラスで意見を出す行為を表す。文脈に合う。", "注射": "「注射」は薬を体に入れることなので、「クラスの前で注射した」は意味が通らない。", "離婚": "「離婚」は夫婦関係を解消することなので、クラスの前で行う文脈には合わない。", "解雇": "「解雇」は雇用を終わらせることなので、「クラスの前で解雇した」は勇気を出す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "提言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は答案を、赤ペンで提言した。", "explanation": "ここは〈採点〉（答えを判定して点をつける）の意味。提言は意見を出すことなので、答案を判定する文には合わない。"}, {"text": "朝、先生に、彼は『おはよう』と提言した。", "explanation": "ここは〈挨拶〉（会ったときに声をかける）の意味。提言は意見を出すことなので、あいさつの文には合わない。"}, {"text": "彼は毎週、庭の木を提言した。", "explanation": "ここは〈剪定〉（枝を切って形を整える）の意味。提言は意見を出すことなので、木の手入れをする文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学生たちは、市役所に提言に出した。", "corrected_sentence": "大学生たちは、市役所に提言を出した。", "error_description": "助詞の誤り。「提言」は「出す」の目的語なので「を」が正しい。「提言に出した」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民団体は、市長に提言すって、計画を見直した。", "corrected_sentence": "市民団体は、市長に提言して、計画を見直した。", "error_description": "活用の誤り。「提言する」のて形は「提言して」。「提言すって」は「する」の活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「受けて」の対象を示す。「委員会の提言を受けて」となる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「提言が受けて」では提言が受ける主体にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や対象を示す。「提言に受けて」は「〜を受ける」の形にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「提言で受けて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「受けて」の対象を示す。「委員会の提言を受けて」となる。", "が": "「が」は主語を示す。「提言が受けて」では提言が受ける主体にならないので合わない。", "に": "「に」は相手や対象を示す。「提言に受けて」は「〜を受ける」の形にならず不自然。", "で": "「で」は手段を示す。「提言で受けて」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「発表する」の対象を示す。「提言を発表した」となる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「提言の発表した」は動詞に続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「提言へ発表した」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「提言より発表した」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「発表する」の対象を示す。「提言を発表した」となる。", "の": "「の」は名詞をつなぐ。「提言の発表した」は動詞に続かず不自然。", "へ": "「へ」は方向を示す。「提言へ発表した」は意味が通らない。", "より": "「より」は比較を示す。「提言より発表した」は文が成り立たない。"}, "error_tags": {"の": "修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある問題について、こうしたほうがいいという考えを、はっきりと意見として出すこと。", "primary_collocate": null, "pronunciation": "ていげん", "ipa": "teːɡeɴ", "syllable_count": 4, "sentences": [{"text": "専門家の委員会が、ごみ問題についての提言をまとめた。", "target_word": "提言", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の委員会[いいんかい]が、ごみ問題[もんだい]についての提言[ていげん]をまとめた。", "sentence_source": "generated"}, {"text": "市長は、委員会の提言を受けて、新しい計画を作った。", "target_word": "提言", "complexity_tier": "T3", "furigana": "市長[しちょう]は、委員会[いいんかい]の提言[ていげん]を受[う]けて、新[あたら]しい計画[けいかく]を作[つく]った。", "sentence_source": "generated"}, {"text": "報告書には、水不足を減らすための提言が三つ書かれている。", "target_word": "提言", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]には、水不足[みずぶそく]を減[へ]らすための提言[ていげん]が三[みっ]つ書[か]かれている。", "sentence_source": "generated"}, {"text": "学者たちは、政府に対して、教育制度を見直すよう提言した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "学者[がくしゃ]たちは、政府[せいふ]に対[たい]して、教育制度[きょういくせいど]を見直[みなお]すよう提言[ていげん]した。", "sentence_source": "generated"}, {"text": "彼は、渋滞を減らすために、バスを増やすべきだと提言した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "彼[かれ]は、渋滞[じゅうたい]を減[へ]らすために、バスを増[ふ]やすべきだと提言[ていげん]した。", "sentence_source": "generated"}, {"text": "その提言は具体的で、すぐに実行できる内容だった。", "target_word": "提言", "complexity_tier": "T3", "furigana": "その提言[ていげん]は具体的[ぐたいてき]で、すぐに実行[じっこう]できる内容[ないよう]だった。", "sentence_source": "generated"}, {"text": "環境団体は、森を守るための提言を国に出した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "環境団体[かんきょうだんたい]は、森[もり]を守[まも]るための提言[ていげん]を国[くに]に出[だ]した。", "sentence_source": "generated"}, {"text": "事故のあと、調査チームは安全対策の提言を発表した。", "target_word": "提言", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、調査[ちょうさ]チームは安全対策[あんぜんたいさく]の提言[ていげん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "提言が出されたが、費用の問題でまだ実行されていない。", "target_word": "提言", "complexity_tier": "T3", "furigana": "提言[ていげん]が出[だ]されたが、費用[ひよう]の問題[もんだい]でまだ実行[じっこう]されていない。", "sentence_source": "generated"}, {"text": "医者の会は、働き方を変えるべきだという強い提言を行った。", "target_word": "提言", "complexity_tier": "T3", "furigana": "医者[いしゃ]の会[かい]は、働[はたら]き方[かた]を変[か]えるべきだという強[つよ]い提言[ていげん]を行[おこな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提言する", "label": "辞書形"}, {"form": "提言した", "label": "過去形"}, {"form": "提言して", "label": "て形"}, {"form": "提言される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "ある問題の解決のために、こうすべきだという具体的な考えを、委員会や専門家などが意見として出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提言", "is_correct": true, "explanation": "「提言をまとめる」で、問題の解決策をまとめる意味。文脈に合う。"}, {"text": "運転", "is_correct": false, "explanation": "「運転」は車などを操ること。「ごみ問題についての運転」は意味が通らない。"}, {"text": "感染", "is_correct": false, "explanation": "「感染」は病気がうつること。ごみ問題の報告をまとめる文脈には合わない。"}, {"text": "注射", "is_correct": false, "explanation": "「注射」は薬を体に入れること。ごみ問題の文書をまとめる文には合わない。"}], "explanations": {"提言": "「提言をまとめる」で、問題の解決策をまとめる意味。文脈に合う。", "運転": "「運転」は車などを操ること。「ごみ問題についての運転」は意味が通らない。", "感染": "「感染」は病気がうつること。ごみ問題の報告をまとめる文脈には合わない。", "注射": "「注射」は薬を体に入れること。ごみ問題の文書をまとめる文には合わない。"}, "sentence_index": 0, "correct_answer": "提言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、彼は友人を映画に提言した。", "explanation": "ここは〈誘う〉（相手に一緒に行こうと声をかける）の意味。提言は意見を出すことなので、誘う文には合わない。"}, {"text": "彼は、ずっと隠していた好意を、夕方に彼女へ提言した。", "explanation": "ここは〈告白〉（好意を相手に打ち明ける）の意味。提言は意見を出して勧めることなので、好意を伝える文には合わない。"}, {"text": "店員に、彼はサンドイッチを三つ提言した。", "explanation": "ここは〈注文〉（品物を頼む）の意味。提言は意見を出すことなので、食べ物を頼む文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提言", "is_correct": true, "explanation": "「提言を出す」で、森を守る意見を国に示す意味。文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は歩くことなので、「森を守るための散歩を国に出した」は成り立たない。"}, {"text": "出血", "is_correct": false, "explanation": "「出血」は血が出ることなので、国に出すものではない。"}, {"text": "乗車", "is_correct": false, "explanation": "「乗車」は乗り物に乗ることなので、国に出すものではない。"}], "explanations": {"提言": "「提言を出す」で、森を守る意見を国に示す意味。文脈に合う。", "散歩": "「散歩」は歩くことなので、「森を守るための散歩を国に出した」は成り立たない。", "出血": "「出血」は血が出ることなので、国に出すものではない。", "乗車": "「乗車」は乗り物に乗ることなので、国に出すものではない。"}, "sentence_index": 6, "correct_answer": "提言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新商品の性能を、雑誌で大きく提言した。", "explanation": "ここは〈宣伝〉（商品をよく知らせる）の意味。提言は意見を出すことなので、商品を売り込む文には合わない。"}, {"text": "工場長は、機械を一台ずつ提言した。", "explanation": "ここは〈点検〉（機械の状態を一つずつ調べる）の意味。提言は意見を出すことなので、機械を調べる文には合わない。"}, {"text": "社長は、部下を海外へ提言した。", "explanation": "ここは〈派遣〉（人を仕事で他の場所へ送る）の意味。提言は意見を出すことなので、人を送る文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、計画の提言が専門家に求めた。", "corrected_sentence": "市は、計画の提言を専門家に求めた。", "error_description": "助詞の誤り。「求める」の対象を示す「を」が正しい。「提言が」は主語の形で、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "環境団体は、国に新しい対策を提言するした。", "corrected_sentence": "環境団体は、国に新しい対策を提言した。", "error_description": "動詞の重複。「提言する」に過去の「した」を重ねた誤り。過去形は「提言した」だけで足りる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「養蜂では」で、養蜂という話題の場面を示す。「では」の「で」として正しい。"}, {"text": "も", "is_correct": false, "explanation": "「養蜂も」は係助詞で、「は」と重ねると文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「養蜂が」は主語の印で、「は」と続けると不自然。"}, {"text": "の", "is_correct": false, "explanation": "「養蜂の」は名詞を修飾する「の」で、「は」と続けると文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「養蜂では」で、養蜂という話題の場面を示す。「では」の「で」として正しい。", "も": "「養蜂も」は係助詞で、「は」と重ねると文が成り立たない。", "が": "「養蜂が」は主語の印で、「は」と続けると不自然。", "の": "「養蜂の」は名詞を修飾する「の」で、「は」と続けると文が成り立たない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "も": "係助詞（は と重複）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
