INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "はちを育てて、はちみつをとることです。", "primary_collocate": null, "pronunciation": "ようほう", "ipa": "joːhoː", "syllable_count": 4, "sentences": [{"text": "祖父は山の近くで養蜂をしている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "祖父[そふ]は山[やま]の近[ちか]くで養蜂[ようほう]をしている。", "sentence_source": "generated"}, {"text": "養蜂では、はちを守るための箱を使う。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]では、はちを守[まも]るための箱[はこ]を使[つか]う。", "sentence_source": "generated"}, {"text": "養蜂を始めてから、花の季節が待ち遠しくなった。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]を始[はじ]めてから、花[はな]の季節[きせつ]が待[ま]ち遠[どお]しくなった。", "sentence_source": "generated"}, {"text": "この村は養蜂がさかんで、おいしいはちみつが有名だ。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "この村[むら]は養蜂[ようほう]がさかんで、おいしいはちみつが有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "養蜂には、はちにさされない服が必要だ。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]には、はちにさされない服[ふく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "夏は暑いので、養蜂の仕事は大変だ。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、養蜂[ようほう]の仕事[しごと]は大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "養蜂で作ったはちみつを、市場で売った。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]で作[つく]ったはちみつを、市場[いちば]で売[う]った。", "sentence_source": "generated"}, {"text": "私は将来、養蜂を仕事にしたいと思っている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "私[わたし]は将来[しょうらい]、養蜂[ようほう]を仕事[しごと]にしたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "養蜂の体験教室で、はちみつのとり方を学んだ。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]の体験[たいけん]教室[きょうしつ]で、はちみつのとり方[かた]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "花が少ない年は、養蜂がうまくいかない。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "花[はな]が少[すく]ない年[とし]は、養蜂[ようほう]がうまくいかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養蜂", "label": "基本形"}, {"form": "養蜂する", "label": "サ変動詞形"}], "register": "標準", "sense_fingerprint": "はちを育ててはちみつをとること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "養蜂", "is_correct": true, "explanation": "「養蜂をしている」は、はちを育ててはちみつをとる仕事をしている、という意味で文脈に合う。"}, {"text": "窓", "is_correct": false, "explanation": "「窓をしている」とは言わない。窓は建物の開口部を表す名詞。"}, {"text": "牛乳", "is_correct": false, "explanation": "「牛乳をしている」は意味が通らない。牛乳は飲み物。"}, {"text": "果樹", "is_correct": false, "explanation": "「果樹をしている」は不自然で、果樹は植物の総称なので動作の目的語にならない。"}], "explanations": {"養蜂": "「養蜂をしている」は、はちを育ててはちみつをとる仕事をしている、という意味で文脈に合う。", "窓": "「窓をしている」とは言わない。窓は建物の開口部を表す名詞。", "牛乳": "「牛乳をしている」は意味が通らない。牛乳は飲み物。", "果樹": "「果樹をしている」は不自然で、果樹は植物の総称なので動作の目的語にならない。"}, "sentence_index": 0, "correct_answer": "養蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この村では蚕を養蜂して、絹の織物を作っている。", "explanation": "ここは〈養蚕〉の意味。養蜂は蜂を育ててはちみつをとることで、蚕を育てて絹をとる文脈には使えない。"}, {"text": "夫婦は子どもの養蜂に力を入れた。", "explanation": "ここは〈養育〉の意味。養蜂は蜂を育ててはちみつをとることで、子どもには使わない。"}, {"text": "土に養蜂を与えると、野菜がよく育つ。", "explanation": "ここは〈養分〉の意味。養蜂は蜂を育てることで、土に与える栄養を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "養蜂", "is_correct": true, "explanation": "「養蜂で作ったはちみつ」は、養蜂によって得たはちみつ、という意味で文脈に合う。"}, {"text": "養殖", "is_correct": false, "explanation": "「養殖で作ったはちみつ」は意味が通らない。養殖は魚などを育てて出荷すること。"}, {"text": "搾乳", "is_correct": false, "explanation": "「搾乳」は乳をしぼることで、「搾乳で作ったはちみつ」は成り立たない。"}, {"text": "栽培", "is_correct": false, "explanation": "「栽培」は植物を育てることで、はちみつの製造の説明には合わない。"}], "explanations": {"養蜂": "「養蜂で作ったはちみつ」は、養蜂によって得たはちみつ、という意味で文脈に合う。", "養殖": "「養殖で作ったはちみつ」は意味が通らない。養殖は魚などを育てて出荷すること。", "搾乳": "「搾乳」は乳をしぼることで、「搾乳で作ったはちみつ」は成り立たない。", "栽培": "「栽培」は植物を育てることで、はちみつの製造の説明には合わない。"}, "sentence_index": 6, "correct_answer": "養蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池では魚を養蜂して、刺身を出している。", "explanation": "ここは〈養殖〉の意味。養蜂は蜂を育てることで、魚を育てて出荷する文脈には使えない。"}, {"text": "この畑では花を養蜂して、きれいな花束を作っている。", "explanation": "ここは〈栽培〉の意味。養蜂は蜂を育てることで、花を育てる栽培の文脈には使えない。"}, {"text": "動物園では、ペンギンを養蜂している。", "explanation": "ここは〈飼育〉の意味。養蜂ははちを育てることに限られ、動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は去年、山の近くで養蜂が始めた。", "corrected_sentence": "祖父は去年、山の近くで養蜂を始めた。", "error_description": "「始める」は目的語に「を」を取るので、「養蜂が」は誤り。正しくは「養蜂を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39650, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は引退後、養蜂が趣味にしたいと考えている。", "corrected_sentence": "父は引退後、養蜂を趣味にしたいと考えている。", "error_description": "「趣味にする」の目的語は「を」で示す。「養蜂が」は誤り。正しくは「養蜂を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「養蜂の技術」の「の」で、養蜂を技術の前に置いて修飾している。"}, {"text": "が", "is_correct": false, "explanation": "「養蜂が技術を学ぶ」となり、養蜂が学ぶ主体になって意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「養蜂を技術を学ぶ」と目的語が二つ重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は学ぶ相手を表せず、不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「養蜂の技術」の「の」で、養蜂を技術の前に置いて修飾している。", "が": "「養蜂が技術を学ぶ」となり、養蜂が学ぶ主体になって意味が通らない。", "を": "「養蜂を技術を学ぶ」と目的語が二つ重なり、文として成り立たない。", "へ": "方向を示す「へ」は学ぶ相手を表せず、不自然になる。"}, "error_tags": {"が": "主語（学ぶ主体）", "を": "目的語の重複", "へ": "方向（帰着点）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「春から秋にかけて、養蜂は」の「は」で、文の主題を示す係助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「養蜂へ最も忙しい時期を迎える」となり、方向を示すが意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「養蜂より最も忙しい時期を迎える」となり、比較の意味で文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「養蜂から最も忙しい時期を迎える」となり、起点の意味が文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「春から秋にかけて、養蜂は」の「は」で、文の主題を示す係助詞。", "へ": "「養蜂へ最も忙しい時期を迎える」となり、方向を示すが意味が通らない。", "より": "「養蜂より最も忙しい時期を迎える」となり、比較の意味で文脈に合わない。", "から": "「養蜂から最も忙しい時期を迎える」となり、起点の意味が文に合わない。"}, "error_tags": {"へ": "方向（帰着点）", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ミツバチを飼育して、蜂蜜や蜜ろうなどを生産すること。また、そのための技術や産業。", "primary_collocate": null, "pronunciation": "ようほう", "ipa": "joːhoː", "syllable_count": 4, "sentences": [{"text": "この地域では、養蜂が重要な産業の一つになっている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、養蜂[ようほう]が重要[じゅうよう]な産業[さんぎょう]の一[ひと]つになっている。", "sentence_source": "generated"}, {"text": "最新の養蜂の技術を学ぶため、農家が研修に参加した。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "最新[さいしん]の養蜂[ようほう]の技術[ぎじゅつ]を学[まな]ぶため、農家[のうか]が研修[けんしゅう]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "養蜂により、蜂蜜と蜜ろうが生産される。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]により、蜂蜜[はちみつ]と蜜[みつ]ろうが生産[せいさん]される。", "sentence_source": "generated"}, {"text": "都市部でも屋上で養蜂を行う例が増えている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "都市部[としぶ]でも屋上[おくじょう]で養蜂[ようほう]を行[おこな]う例[れい]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "農薬の影響で、養蜂への被害が心配されている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "農薬[のうやく]の影響[えいきょう]で、養蜂[ようほう]への被害[ひがい]が心配[しんぱい]されている。", "sentence_source": "generated"}, {"text": "養蜂は、果物の受粉を助ける役割も果たしている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]は、果物[くだもの]の受粉[じゅふん]を助[たす]ける役割[やくわり]も果[は]たしている。", "sentence_source": "generated"}, {"text": "彼は大学で養蜂を専攻している。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で養蜂[ようほう]を専攻[せんこう]している。", "sentence_source": "generated"}, {"text": "春から秋にかけて、養蜂は最も忙しい時期を迎える。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "春[はる]から秋[あき]にかけて、養蜂[ようほう]は最[もっと]も忙[いそが]しい時期[じき]を迎[むか]える。", "sentence_source": "generated"}, {"text": "国内の養蜂は、後継者不足という課題を抱えている。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "国内[こくない]の養蜂[ようほう]は、後継者[こうけいしゃ]不足[ぶそく]という課題[かだい]を抱[かか]えている。", "sentence_source": "generated"}, {"text": "養蜂の歴史は古く、古代から人は蜂蜜を採ってきた。", "target_word": "養蜂", "complexity_tier": "T3", "furigana": "養蜂[ようほう]の歴史[れきし]は古[ふる]く、古代[こだい]から人[ひと]は蜂蜜[はちみつ]を採[と]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養蜂", "label": "基本形"}, {"form": "養蜂する", "label": "サ変動詞形"}], "register": "やや硬い", "sense_fingerprint": "ミツバチを飼い蜂蜜などを生産する技術・産業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "地震は自然災害で、産業の一つにはならないため「重要な産業の一つ」に合わない。"}, {"text": "養蜂", "is_correct": true, "explanation": "養蜂は蜂蜜などを生産する産業なので、「この地域で重要な産業の一つ」として自然に入る。"}, {"text": "遠足", "is_correct": false, "explanation": "遠足は学校の行事で、地域の産業とは言えないので文が成り立たない。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は人のふるまいで、地域の産業として扱うことはできないので文意が合わない。"}], "explanations": {"地震": "地震は自然災害で、産業の一つにはならないため「重要な産業の一つ」に合わない。", "養蜂": "養蜂は蜂蜜などを生産する産業なので、「この地域で重要な産業の一つ」として自然に入る。", "遠足": "遠足は学校の行事で、地域の産業とは言えないので文が成り立たない。", "挨拶": "挨拶は人のふるまいで、地域の産業として扱うことはできないので文意が合わない。"}, "sentence_index": 0, "correct_answer": "養蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農家では去年から養蜂を始めて、毎朝たくさんの卵を出荷している。", "explanation": "ここは〈養鶏〉の意味。養蜂はミツバチを飼って蜂蜜などを得る営みで、卵は得られないので合わない。"}, {"text": "山あいの村では養蜂が盛んで、繭を町に運んでいた。", "explanation": "ここは〈養蚕〉の意味。繭は蚕から取れるもので、養蜂からは生まれないので合わない。"}, {"text": "この牧場では養蜂をしていて、毎朝牛乳を出荷している。", "explanation": "ここは〈酪農〉の意味。乳牛から牛乳を得る仕事で、養蜂の対象はミツバチなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寝坊", "is_correct": false, "explanation": "寝坊は生活上の失敗で、大学で専攻する分野としては文が成り立たない。"}, {"text": "養蜂", "is_correct": true, "explanation": "養蜂は大学で専攻できる分野なので、「大学で養蜂を専攻している」として自然に入る。"}, {"text": "昼寝", "is_correct": false, "explanation": "昼寝は休息の行為で、大学の専攻としては文意が合わない。"}, {"text": "運動会", "is_correct": false, "explanation": "運動会は学校行事で、専攻の対象として「を専攻」と続けると不自然になる。"}], "explanations": {"寝坊": "寝坊は生活上の失敗で、大学で専攻する分野としては文が成り立たない。", "養蜂": "養蜂は大学で専攻できる分野なので、「大学で養蜂を専攻している」として自然に入る。", "昼寝": "昼寝は休息の行為で、大学の専攻としては文意が合わない。", "運動会": "運動会は学校行事で、専攻の対象として「を専攻」と続けると不自然になる。"}, "sentence_index": 6, "correct_answer": "養蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この湾では養蜂が盛んで、漁師が毎朝、網で魚を獲っている。", "explanation": "ここは〈漁業〉の意味。養蜂はミツバチを飼う営みで、網で魚を獲る漁業の話には合わないので誤り。"}, {"text": "この家では養蜂を始めて、毎朝、犬を散歩に連れていく。", "explanation": "ここは〈飼育〉の意味。養蜂はミツバチを対象にする営みで、犬の散歩とは結びつかないので合わない。"}, {"text": "この農家は養蜂を続けて、豚肉を町の店に卸している。", "explanation": "ここは〈養豚〉の意味。養蜂ではハチを飼うので、豚肉は生産されず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町では、養蜂が始める人が増えている。", "corrected_sentence": "この町では、養蜂を始める人が増えている。", "error_description": "「始める」は他動詞なので目的語を「を」で示す。「養蜂が」は誤りで、正しくは「養蜂を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "養蜂に生計を立てる人が増えている。", "corrected_sentence": "養蜂で生計を立てる人が増えている。", "error_description": "「生計を立てる」は手段を「で」で示す。「養蜂に」は誤りで、正しくは「養蜂で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
