INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "病気や悪いことから自分を守る力のこと。", "primary_collocate": null, "pronunciation": "たいせい", "ipa": "taiseː", "syllable_count": 4, "sentences": [{"text": "寒い地方で育った彼は、寒さへの耐性が強い。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]で育[そだ]った彼[かれ]は、寒[さむ]さへの耐性[たいせい]が強[つよ]い。", "sentence_source": "generated"}, {"text": "新人のころに厳しく鍛えられたので、批判への耐性がついた。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "新人[しんじん]のころに厳[きび]しく鍛[きた]えられたので、批判[ひはん]への耐性[たいせい]がついた。", "sentence_source": "generated"}, {"text": "毎朝冷たい水を浴びて、風邪に対する耐性を高めている。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]冷[つめ]たい水[みず]を浴[あ]びて、風邪[かぜ]に対[たい]する耐性[たいせい]を高[たか]めている。", "sentence_source": "generated"}, {"text": "辛い食べ物への耐性は、人によってかなり差がある。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "辛[から]い食[た]べ物[もの]への耐性[たいせい]は、人[ひと]によってかなり差[さ]がある。", "sentence_source": "generated"}, {"text": "長時間の満員電車にも耐性ができて、今はあまり疲れない。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]の満員電車[まんいんでんしゃ]にも耐性[たいせい]ができて、今[いま]はあまり疲[つか]れない。", "sentence_source": "generated"}, {"text": "幼いころに外で遊ぶと、病気への耐性がつくと言われる。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "幼[おさな]いころに外[そと]で遊[あそ]ぶと、病気[びょうき]への耐性[たいせい]がつくと言[い]われる。", "sentence_source": "generated"}, {"text": "彼は失敗への耐性が低く、一度の失敗で自信をなくしてしまう。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]への耐性[たいせい]が低[ひく]く、一度[いちど]の失敗[しっぱい]で自信[じしん]をなくしてしまう。", "sentence_source": "generated"}, {"text": "騒音の多い町で暮らすうちに、音への耐性が自然に身についた。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "騒音[そうおん]の多[おお]い町[まち]で暮[く]らすうちに、音[おと]への耐性[たいせい]が自然[しぜん]に身[み]についた。", "sentence_source": "generated"}, {"text": "暑さへの耐性がない私は、真夏の外出を避けている。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "暑[あつ]さへの耐性[たいせい]がない私[わたし]は、真夏[まなつ]の外出[がいしゅつ]を避[さ]けている。", "sentence_source": "generated"}, {"text": "山で鍛えた兄は、疲れへの耐性が高く、最後まで歩き通した。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "山[やま]で鍛[きた]えた兄[あに]は、疲[つか]れへの耐性[たいせい]が高[たか]く、最後[さいご]まで歩[ある]き通[とお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐性", "label": "基本形"}], "register": "plain", "sense_fingerprint": "寒さ・病気・批判などに負けずに耐える、人の体や心の力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐性", "is_correct": true, "explanation": "「寒さへの耐性」は寒さに負けない力を表し、空所にそのまま入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱の高さのことで、「寒さへの体温が強い」は意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の湿り気のことで、寒さに対する強さを表せない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさのことで、寒さとは結びつかない。"}], "explanations": {"耐性": "「寒さへの耐性」は寒さに負けない力を表し、空所にそのまま入る。", "体温": "体温は体の熱の高さのことで、「寒さへの体温が強い」は意味が通らない。", "湿度": "湿度は空気の湿り気のことで、寒さに対する強さを表せない。", "音量": "音量は音の大きさのことで、寒さとは結びつかない。"}, "sentence_index": 0, "correct_answer": "耐性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "回路の耐性を測ってから、電流を流した。", "explanation": "ここは〈抵抗〉（電気の流れにくさ）の意味。耐性は外からの刺激に影響されにくい性質で、電気回路の値には使わない。"}, {"text": "この靴は耐性が高く、何年も履ける。", "explanation": "ここは〈耐久性〉（長く使える丈夫さ）の意味。耐性は病気や刺激への強さを指し、物の丈夫さには使わない。"}, {"text": "彼はピアノの耐性が高く、難しい曲も弾きこなす。", "explanation": "ここは〈技能〉（身につけた腕前）の意味。耐性は影響を受けにくさを表すので、演奏の腕前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐性", "is_correct": true, "explanation": "「失敗への耐性が低く」は失敗に負けない力の弱さを表し、空所にそのまま入る。"}, {"text": "資金", "is_correct": false, "explanation": "資金はお金のことで、「失敗への資金が低く」は意味をなさない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の暖かさのことで、失敗とは結びつかない。"}, {"text": "学費", "is_correct": false, "explanation": "学費は学校に払うお金のことで、失敗への強さの意味にならない。"}], "explanations": {"耐性": "「失敗への耐性が低く」は失敗に負けない力の弱さを表し、空所にそのまま入る。", "資金": "資金はお金のことで、「失敗への資金が低く」は意味をなさない。", "気温": "気温は空気の暖かさのことで、失敗とは結びつかない。", "学費": "学費は学校に払うお金のことで、失敗への強さの意味にならない。"}, "sentence_index": 6, "correct_answer": "耐性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは耐性が深く、香りが長く残る。", "explanation": "ここは〈風味〉（味や香りの豊かさ）の意味。耐性は耐える力で、味の豊かさは表せない。"}, {"text": "このジャケットは耐性が高く、雨の日も濡れない。", "explanation": "ここは〈防水性〉（水を通しにくい性質）の意味。耐性は病気や刺激への強さで、水を通さない性質には使わない。"}, {"text": "この機械は耐性が高く、小さな音も拾う。", "explanation": "ここは〈感度〉（わずかな刺激への反応の鋭さ）の意味。耐性は影響を受けにくさなので、小さな音を拾う鋭さとは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は若いころから寒い地方で働いてきたので、寒さへの耐性を強い。", "corrected_sentence": "祖母は若いころから寒い地方で働いてきたので、寒さへの耐性が強い。", "error_description": "形容詞「強い」の主語になる「耐性」には「が」を付けるべきところ、「を」を付けている。「を」は他動詞の目的語を示すので、「強い」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長年の厳しい練習で、彼女は暑さへの耐性が軽い。", "corrected_sentence": "長年の厳しい練習で、彼女は暑さへの耐性が高い。", "error_description": "耐性の程度は「高い」「低い」で表すので、「軽い」は誤り。「軽い」は重さを表す形容詞で、耐性とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
