INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39653, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "外部からの刺激や病原体などに対して、影響を受けにくい性質。", "primary_collocate": null, "pronunciation": "たいせい", "ipa": "taiseː", "syllable_count": 4, "sentences": [{"text": "抗生物質を使いすぎると、薬に耐性を持つ菌が増える。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "抗生物質[こうせいぶっしつ]を使[つか]いすぎると、薬[くすり]に耐性[たいせい]を持[も]つ菌[きん]が増[ふ]える。", "sentence_source": "generated"}, {"text": "この雑草は除草剤への耐性があり、薬をまいても枯れない。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "この雑草[ざっそう]は除草剤[じょそうざい]への耐性[たいせい]があり、薬[くすり]をまいても枯[か]れない。", "sentence_source": "generated"}, {"text": "細菌が薬剤に対する耐性を獲得し、治療が難しくなった。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "細菌[さいきん]が薬剤[やくざい]に対[たい]する耐性[たいせい]を獲得[かくとく]し、治療[ちりょう]が難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "新しい稲は、病気や寒さへの耐性を高めるために開発された。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "新[あたら]しい稲[いね]は、病気[びょうき]や寒[さむ]さへの耐性[たいせい]を高[たか]めるために開発[かいはつ]された。", "sentence_source": "generated"}, {"text": "同じ殺虫剤を使い続けたため、害虫に耐性ができてしまった。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "同[おな]じ殺虫剤[さっちゅうざい]を使[つか]い続[つづ]けたため、害虫[がいちゅう]に耐性[たいせい]ができてしまった。", "sentence_source": "generated"}, {"text": "この金属は熱への耐性が高く、エンジン部品に使われる。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "この金属[きんぞく]は熱[ねつ]への耐性[たいせい]が高[たか]く、エンジン部品[ぶひん]に使[つか]われる。", "sentence_source": "generated"}, {"text": "ウイルスが薬への耐性を持つかどうか、研究者が調べている。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "ウイルスが薬[くすり]への耐性[たいせい]を持[も]つかどうか、研究者[けんきゅうしゃ]が調[しら]べている。", "sentence_source": "generated"}, {"text": "植物ごとに乾燥への耐性は違い、サボテンは特に高い。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]ごとに乾燥[かんそう]への耐性[たいせい]は違[ちが]い、サボテンは特[とく]に高[たか]い。", "sentence_source": "generated"}, {"text": "耐性のある菌には、普通の薬はほとんど効かない。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "耐性[たいせい]のある菌[きん]には、普通[ふつう]の薬[くすり]はほとんど効[き]かない。", "sentence_source": "generated"}, {"text": "医師は耐性ができないよう、薬を決められた通りに飲むよう勧めた。", "target_word": "耐性", "complexity_tier": "T3", "furigana": "医師[いし]は耐性[たいせい]ができないよう、薬[くすり]を決[き]められた通[とお]りに飲[の]むよう勧[すす]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耐性", "label": "基本形"}], "register": "plain", "sense_fingerprint": "薬・熱・乾燥などの刺激に対して、菌や植物や物質が影響を受けにくい性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39653, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐性", "is_correct": true, "explanation": "「薬に耐性を持つ」は薬が効きにくくなる性質を表し、空所にそのまま入る。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、「薬に体重を持つ菌」は意味をなさない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は感じたことを言葉にしたもので、菌の性質には結びつかない。"}, {"text": "温度", "is_correct": false, "explanation": "温度は熱の度合いのことで、「薬に温度を持つ」は薬と菌の関係として成り立たない。"}], "explanations": {"耐性": "「薬に耐性を持つ」は薬が効きにくくなる性質を表し、空所にそのまま入る。", "体重": "体重は体の重さのことで、「薬に体重を持つ菌」は意味をなさない。", "感想": "感想は感じたことを言葉にしたもので、菌の性質には結びつかない。", "温度": "温度は熱の度合いのことで、「薬に温度を持つ」は薬と菌の関係として成り立たない。"}, "sentence_index": 0, "correct_answer": "耐性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この接着剤は耐性が強く、どんな素材にもくっつく。", "explanation": "ここは〈接着力〉（物をくっつける力）の意味。耐性は影響を受けにくさを表すので、くっつく力とは別のもの。"}, {"text": "この電池は耐性が大きく、電流がほとんど流れない。", "explanation": "ここは〈抵抗〉（電気の流れにくさ）の意味。耐性は刺激に影響されにくい性質で、電気の流れにくさには使わない。"}, {"text": "この土は耐性が高く、雨水をすぐ通す。", "explanation": "ここは〈透水性〉（水を通す性質）の意味。耐性は影響を受けにくさで、水を通すことを表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39653, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐性", "is_correct": true, "explanation": "「薬への耐性を持つかどうか」は薬に影響されにくい性質を表し、空所にそのまま入る。"}, {"text": "人数", "is_correct": false, "explanation": "人数は人の数のことで、「薬への人数を持つ」は意味をなさない。"}, {"text": "価格", "is_correct": false, "explanation": "価格は値段のことで、薬への性質を表せない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色の取り合わせのことで、薬との関係として成り立たない。"}], "explanations": {"耐性": "「薬への耐性を持つかどうか」は薬に影響されにくい性質を表し、空所にそのまま入る。", "人数": "人数は人の数のことで、「薬への人数を持つ」は意味をなさない。", "価格": "価格は値段のことで、薬への性質を表せない。", "色彩": "色彩は色の取り合わせのことで、薬との関係として成り立たない。"}, "sentence_index": 6, "correct_answer": "耐性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアプリは耐性が高く、起動がとても速い。", "explanation": "ここは〈処理速度〉の意味。耐性は影響を受けにくさで、速さは表せない。"}, {"text": "マラソンの後半で耐性が尽きて、歩くしかなかった。", "explanation": "ここは〈体力〉（動き続ける力）の意味。耐性は刺激への強さで、体力のように尽きて減るものではない。"}, {"text": "このタオルは耐性が高く、すぐ水を吸う。", "explanation": "ここは〈吸収力〉（水を吸い込む力）の意味。耐性は影響を受けにくさで、水を吸い込む性質とは別のもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39653, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の畑で育つこの植物は、乾燥への耐性を強く、水をあまり必要としない。", "corrected_sentence": "夏の畑で育つこの植物は、乾燥への耐性が強く、水をあまり必要としない。", "error_description": "「強い」の主語になる「耐性」には「が」を付けるべきところ、「を」を付けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39653, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この菌は薬への耐性が濃く、ほとんどの抗生物質が効かない。", "corrected_sentence": "この菌は薬への耐性が強く、ほとんどの抗生物質が効かない。", "error_description": "耐性の程度は「強い」「高い」で表すので、「濃い」は誤り。「濃い」は色や液体の濃さに使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
