INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39654, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "function", "definition": "〜に かかわる こと。", "primary_collocate": null, "pronunciation": "かんする", "ipa": "kaɴsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この図書館には環境問題に関する本がたくさんある。", "target_word": "関する", "complexity_tier": "T3", "furigana": "この図書館[としょかん]には環境問題[かんきょうもんだい]に関[かん]する本[ほん]がたくさんある。", "sentence_source": "generated"}, {"text": "事故に関する情報が少ないので、まだ原因は分からない。", "target_word": "関する", "complexity_tier": "T3", "furigana": "事故[じこ]に関[かん]する情報[じょうほう]が少[すく]ないので、まだ原因[げんいん]は分[わ]からない。", "sentence_source": "generated"}, {"text": "旅行に関する質問は、受付で聞いてください。", "target_word": "関する", "complexity_tier": "T3", "furigana": "旅行[りょこう]に関[かん]する質問[しつもん]は、受付[うけつけ]で聞[き]いてください。", "sentence_source": "generated"}, {"text": "お金に関する話は、家族でもしにくいことがある。", "target_word": "関する", "complexity_tier": "T3", "furigana": "お金[かね]に関[かん]する話[はなし]は、家族[かぞく]でもしにくいことがある。", "sentence_source": "generated"}, {"text": "彼は歴史に関する知識が豊富で、何を聞いても答えてくれる。", "target_word": "関する", "complexity_tier": "T3", "furigana": "彼[かれ]は歴史[れきし]に関[かん]する知識[ちしき]が豊富[ほうふ]で、何[なに]を聞[き]いても答[こた]えてくれる。", "sentence_source": "generated"}, {"text": "健康に関する記事を読んで、毎朝歩くことにした。", "target_word": "関する", "complexity_tier": "T3", "furigana": "健康[けんこう]に関[かん]する記事[きじ]を読[よ]んで、毎朝[まいあさ]歩[ある]くことにした。", "sentence_source": "generated"}, {"text": "契約に関する書類を、明日までに出してください。", "target_word": "関する", "complexity_tier": "T3", "furigana": "契約[けいやく]に関[かん]する書類[しょるい]を、明日[あした]までに出[だ]してください。", "sentence_source": "generated"}, {"text": "この会社は安全に関する規則が厳しい。", "target_word": "関する", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は安全[あんぜん]に関[かん]する規則[きそく]が厳[きび]しい。", "sentence_source": "generated"}, {"text": "先生は進路に関する相談に、いつも親切に答えてくれる。", "target_word": "関する", "complexity_tier": "T3", "furigana": "先生[せんせい]は進路[しんろ]に関[かん]する相談[そうだん]に、いつも親切[しんせつ]に答[こた]えてくれる。", "sentence_source": "generated"}, {"text": "料理に関する番組が好きで、毎週見ている。", "target_word": "関する", "complexity_tier": "T3", "furigana": "料理[りょうり]に関[かん]する番組[ばんぐみ]が好[す]きで、毎週[まいしゅう]見[み]ている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関する", "label": "終止形"}, {"form": "関して", "label": "て形"}, {"form": "関した", "label": "過去形"}, {"form": "関しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "「〜に関する＋名詞」の形で、話題・対象を示す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関する", "is_correct": true, "explanation": "「〜に関する本」で話題の範囲を示す連体形。文脈に合う。"}, {"text": "驚く", "is_correct": false, "explanation": "「環境問題に驚く本」は、驚かせる本という意味にも、話題を示す文にもならない。"}, {"text": "通う", "is_correct": false, "explanation": "「通う」は行き来することなので、「環境問題に通う本」は意味が通らない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は寝ることなので、「環境問題に眠る本」は意味が通らない。"}], "explanations": {"関する": "「〜に関する本」で話題の範囲を示す連体形。文脈に合う。", "驚く": "「環境問題に驚く本」は、驚かせる本という意味にも、話題を示す文にもならない。", "通う": "「通う」は行き来することなので、「環境問題に通う本」は意味が通らない。", "眠る": "「眠る」は寝ることなので、「環境問題に眠る本」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "関する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は先生に関して、窓を閉めた。", "explanation": "ここは〈閉める〉（開いているものを塞ぐ）の意味。関してはある話題を示す語なので、窓を閉める動作には使えない。"}, {"text": "この工事は、完成まで三年関する。", "explanation": "ここは〈かかる〉（時間を要する）の意味。関するは話題を示すので、期間を表す文には使えない。"}, {"text": "彼は窓に関して、牛乳を買った。", "explanation": "ここは〈購入〉（代金を払って手に入れる）の意味。関してはある話題を示す語なので、物を買う動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関する", "is_correct": true, "explanation": "「〜に関する書類」で話題を示す連体形。文脈に合う。"}, {"text": "飽きる", "is_correct": false, "explanation": "「飽きる」は嫌になることなので、「契約に飽きる書類」は意味が通らない。"}, {"text": "慣れる", "is_correct": false, "explanation": "「慣れる」は習熟することなので、「契約に慣れる書類」は成り立たない。"}, {"text": "泣く", "is_correct": false, "explanation": "「泣く」は涙を流すことなので、「契約に泣く書類」は意味が通らない。"}], "explanations": {"関する": "「〜に関する書類」で話題を示す連体形。文脈に合う。", "飽きる": "「飽きる」は嫌になることなので、「契約に飽きる書類」は意味が通らない。", "慣れる": "「慣れる」は習熟することなので、「契約に慣れる書類」は成り立たない。", "泣く": "「泣く」は涙を流すことなので、「契約に泣く書類」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "関する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は夜十時に関して、すぐに寝た。", "explanation": "ここは〈就寝〉（ねむりにつく）の意味。関してはある話題を示す語なので、寝る動作には使えない。"}, {"text": "私と彼は、昔から関するので、今も話をする。", "explanation": "ここは〈関係〉（つながりがある）の意味。関するは話題を示す語なので、人どうしのつながりは表せない。"}, {"text": "彼は毎朝七時の電車に関した。", "explanation": "ここは〈乗る〉（乗り物に入る）の意味。関するは話題を示す語なので、電車に乗る動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39654, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このホテルは、客の安全を関する規則を毎年見直している。", "corrected_sentence": "このホテルは、客の安全に関する規則を毎年見直している。", "error_description": "助詞の誤り。「〜に関する」の形を取るので、「安全」に続く助詞は「に」が正しい。「を」では話題を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39654, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市役所は、住民の健康に関すした相談を毎週受けている。", "corrected_sentence": "市役所は、住民の健康に関する相談を毎週受けている。", "error_description": "活用の誤り。「関する」に過去の「した」を重ねた誤り。名詞「相談」を修飾する形は「関する」で正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
