INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39655, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "function", "definition": "かかわりをもつ。関係する。多く「〜に関する」の形で使う。", "primary_collocate": null, "pronunciation": "かんする", "ipa": "kaɴsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この問題に関して、私は何も知らない。", "target_word": "関して", "complexity_tier": "T3", "furigana": "この問題[もんだい]に関[かん]して、私[わたし]は何[なに]も知[し]らない。", "sentence_source": "generated"}, {"text": "試験の日程に関して、まだ連絡が来ていない。", "target_word": "関して", "complexity_tier": "T3", "furigana": "試験[しけん]の日程[にってい]に関[かん]して、まだ連絡[れんらく]が来[き]ていない。", "sentence_source": "generated"}, {"text": "事件に関して、警察は詳しい説明をしなかった。", "target_word": "関して", "complexity_tier": "T3", "furigana": "事件[じけん]に関[かん]して、警察[けいさつ]は詳[くわ]しい説明[せつめい]をしなかった。", "sentence_source": "generated"}, {"text": "私に関することなら、気にせず何でも聞いてほしい。", "target_word": "関する", "complexity_tier": "T3", "furigana": "私[わたし]に関[かん]することなら、気[き]にせず何[なん]でも聞[き]いてほしい。", "sentence_source": "generated"}, {"text": "環境に関して、各国の考え方は大きく違う。", "target_word": "関して", "complexity_tier": "T3", "furigana": "環境[かんきょう]に関[かん]して、各国[かっこく]の考[かんが]え方[かた]は大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "彼は仕事に関する悩みを、友人に打ち明けた。", "target_word": "関する", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]に関[かん]する悩[なや]みを、友人[ゆうじん]に打[う]ち明[あ]けた。", "sentence_source": "generated"}, {"text": "検査の結果は、命に関することではなかったので、安心した。", "target_word": "関する", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]は、命[いのち]に関[かん]することではなかったので、安心[あんしん]した。", "sentence_source": "generated"}, {"text": "料金に関して、不明な点があれば窓口で尋ねてほしい。", "target_word": "関して", "complexity_tier": "T3", "furigana": "料金[りょうきん]に関[かん]して、不明[ふめい]な点[てん]があれば窓口[まどぐち]で尋[たず]ねてほしい。", "sentence_source": "generated"}, {"text": "税金に関する法律が変わるため、会社は準備を始めた。", "target_word": "関する", "complexity_tier": "T3", "furigana": "税金[ぜいきん]に関[かん]する法律[ほうりつ]が変[か]わるため、会社[かいしゃ]は準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "その件に関して、社長はまだ意見を述べていない。", "target_word": "関して", "complexity_tier": "T3", "furigana": "その件[けん]に関[かん]して、社長[しゃちょう]はまだ意見[いけん]を述[の]べていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関する", "label": "終止形"}, {"form": "関して", "label": "て形"}, {"form": "関した", "label": "過去形"}, {"form": "関しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "「〜に関して」「〜に関する」で、ある事柄と関係を持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関して", "is_correct": true, "explanation": "「〜に関して」で、話題の範囲を示す。文脈に合う。"}, {"text": "眠って", "is_correct": false, "explanation": "「眠って」は寝ることなので、「この問題に眠って」は意味が通らない。"}, {"text": "飛んで", "is_correct": false, "explanation": "「飛んで」は空中を移動することなので、「この問題に飛んで」は成り立たない。"}, {"text": "乾いて", "is_correct": false, "explanation": "「乾いて」は水分がなくなることなので、「この問題に乾いて」は意味が通らない。"}], "explanations": {"関して": "「〜に関して」で、話題の範囲を示す。文脈に合う。", "眠って": "「眠って」は寝ることなので、「この問題に眠って」は意味が通らない。", "飛んで": "「飛んで」は空中を移動することなので、「この問題に飛んで」は成り立たない。", "乾いて": "「乾いて」は水分がなくなることなので、「この問題に乾いて」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "関して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は友達に関して、一緒に食事をした。", "explanation": "ここは〈同行〉（相手と一緒に行動する）の意味。関してはある話題を示す語なので、人と行動をともにする文には合わない。"}, {"text": "彼は毎朝、公園に関して一周した。", "explanation": "ここは〈巡る〉（場所をぐるりと回る）の意味。関してはある話題を示す語なので、場所を回る動作には使えない。"}, {"text": "彼は部屋に関して入った。", "explanation": "ここは〈入室〉（部屋の中へ移る）の意味。関してはある話題を示す語なので、場所へ移動する文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関する", "is_correct": true, "explanation": "「〜に関すること」で話題の範囲を示す。文脈に合う。"}, {"text": "驚く", "is_correct": false, "explanation": "「命に驚くこと」は意味が通らず、「ではなかった」ともつながらない。"}, {"text": "通う", "is_correct": false, "explanation": "「通う」は行き来することなので、「命に通うこと」は成り立たない。"}, {"text": "泣く", "is_correct": false, "explanation": "「泣く」は涙を流すことなので、「命に泣くこと」は文脈に合わない。"}], "explanations": {"関する": "「〜に関すること」で話題の範囲を示す。文脈に合う。", "驚く": "「命に驚くこと」は意味が通らず、「ではなかった」ともつながらない。", "通う": "「通う」は行き来することなので、「命に通うこと」は成り立たない。", "泣く": "「泣く」は涙を流すことなので、「命に泣くこと」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "関する"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、そのバスに関して乗った。", "explanation": "ここは〈乗車〉（乗り物に入る）の意味。関してはある話題を示す語なので、乗り物に入る動作には使えない。"}, {"text": "彼女は、そのりんごに関して食べた。", "explanation": "ここは〈食べる〉（食物を口に入れて飲み込む）の意味。関してはある話題を示す語なので、食べる動作には使えない。"}, {"text": "家族は、そのホテルに関して泊まった。", "explanation": "ここは〈宿泊〉（宿に滞在する）の意味。関してはある話題を示す語なので、宿に滞在する文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、この計画を関して、説明会を開いた。", "corrected_sentence": "市は、この計画に関して、説明会を開いた。", "error_description": "助詞の誤り。「〜に関して」の形で話題を示すので、「計画」には「に」を付ける。「を」では成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は、新しい規則に関するて、説明会を開いた。", "corrected_sentence": "会社は、新しい規則に関して、説明会を開いた。", "error_description": "活用の誤り。「関して」のて形は「関し」に「て」を付けたもの。「関するて」は「する」に「て」を付けた誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
