INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「共存を大切にする」で、共存が大切にされる対象になるので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「大切にしてきた」の主語は「村」なので、「共存が」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示す。「大切にする」の対象には使わないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、動詞「大切にしてきた」の目的語にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「共存を大切にする」で、共存が大切にされる対象になるので「を」が正しい。", "が": "「が」は主語を示す。「大切にしてきた」の主語は「村」なので、「共存が」では文が成り立たない。", "に": "「に」は相手や方向を示す。「大切にする」の対象には使わないので合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、動詞「大切にしてきた」の目的語にはならないので合わない。"}, "error_tags": {"が": "主語を示す助詞", "に": "相手・方向の助詞", "の": "名詞をつなぐ助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いろいろなものがいっしょに生きていくこと。", "primary_collocate": null, "pronunciation": "きょうぞん", "ipa": "kʲoːzoɴ", "syllable_count": 4, "sentences": [{"text": "この島では、人間と野生の動物が共存している。", "target_word": "共存", "complexity_tier": "T3", "furigana": "この島[しま]では、人間[にんげん]と野生[やせい]の動物[どうぶつ]が共存[きょうぞん]している。", "sentence_source": "generated"}, {"text": "森には多くの植物が共存しているため、虫も鳥も多い。", "target_word": "共存", "complexity_tier": "T3", "furigana": "森[もり]には多[おお]くの植物[しょくぶつ]が共存[きょうぞん]しているため、虫[むし]も鳥[とり]も多[おお]い。", "sentence_source": "generated"}, {"text": "都会でも、自然との共存を考える人が増えている。", "target_word": "共存", "complexity_tier": "T3", "furigana": "都会[とかい]でも、自然[しぜん]との共存[きょうぞん]を考[かんが]える人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "池では魚とカメが共存していて、毎日にぎやかだ。", "target_word": "共存", "complexity_tier": "T3", "furigana": "池[いけ]では魚[さかな]とカメが共存[きょうぞん]していて、毎日[まいにち]にぎやかだ。", "sentence_source": "generated"}, {"text": "犬と猫の共存は難しいと思っていたが、わが家では仲良く暮らしている。", "target_word": "共存", "complexity_tier": "T3", "furigana": "犬[いぬ]と猫[ねこ]の共存[きょうぞん]は難[むずか]しいと思[おも]っていたが、わが家[や]では仲良[なかよ]く暮[く]らしている。", "sentence_source": "generated"}, {"text": "サンゴ礁では、さまざまな生き物の共存する姿が見られる。", "target_word": "共存", "complexity_tier": "T3", "furigana": "サンゴ礁[しょう]では、さまざまな生[い]き物[もの]の共存[きょうぞん]する姿[すがた]が見[み]られる。", "sentence_source": "generated"}, {"text": "農家は野生の動物との共存を考えて、畑のまわりに木を植えた。", "target_word": "共存", "complexity_tier": "T3", "furigana": "農家[のうか]は野生[やせい]の動物[どうぶつ]との共存[きょうぞん]を考[かんが]えて、畑[はたけ]のまわりに木[き]を植[う]えた。", "sentence_source": "generated"}, {"text": "この村では、昔からクマとの共存を大切にしてきた。", "target_word": "共存", "complexity_tier": "T3", "furigana": "この村[むら]では、昔[むかし]からクマとの共存[きょうぞん]を大切[たいせつ]にしてきた。", "sentence_source": "generated"}, {"text": "この池では、魚と水草が共存できるように、水の量を調整している。", "target_word": "共存", "complexity_tier": "T3", "furigana": "この池[いけ]では、魚[さかな]と水草[みずくさ]が共存[きょうぞん]できるように、水[みず]の量[りょう]を調整[ちょうせい]している。", "sentence_source": "generated"}, {"text": "違う種類の鳥が共存する湖で、写真を撮った。", "target_word": "共存", "complexity_tier": "T3", "furigana": "違[ちが]う種類[しゅるい]の鳥[とり]が共存[きょうぞん]する湖[みずうみ]で、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共存する", "label": "終止形"}, {"form": "共存し", "label": "連用形"}, {"form": "共存して", "label": "て形"}, {"form": "共存した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "人と自然・動植物など、いろいろな生き物が同じ場所で共に生きる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "「人間と野生の動物が〜している」で、いっしょに生きている状態を表すので文脈に合う。"}, {"text": "延期", "is_correct": false, "explanation": "「延期」は予定を後ろにずらす意味で、人と動物の関係を述べる文には入らない。"}, {"text": "解体", "is_correct": false, "explanation": "「解体」は組み立てたものをばらす意味で、生き物どうしの状態には使えない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は設備などを取り除く意味で、人と動物が「している」状態を表す文には合わない。"}], "explanations": {"共存": "「人間と野生の動物が〜している」で、いっしょに生きている状態を表すので文脈に合う。", "延期": "「延期」は予定を後ろにずらす意味で、人と動物の関係を述べる文には入らない。", "解体": "「解体」は組み立てたものをばらす意味で、生き物どうしの状態には使えない。", "撤去": "「撤去」は設備などを取り除く意味で、人と動物が「している」状態を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパソコンは三人で共存している。", "explanation": "ここは〈共有〉の意味。共存は互いが共に生きることで、一つの物を分け合う場面では使わない。"}, {"text": "人間と野生の動物は、土地をめぐって共存している。", "explanation": "ここは〈対立〉の意味。土地を争う状況を表すのは対立で、共存は共に生きる状態を指すので合わない。"}, {"text": "二つのチームは、優勝を目指して共存している。", "explanation": "ここは〈競争〉の意味。優勝を争う場面は競争で、共存は共に生きることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "「野生の動物との〜を考えて」で、共に生きる在り方を指すので文脈に合う。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解」は思い違いの意味で、「誤解を考えて木を植えた」とは文が成り立たない。"}, {"text": "祝福", "is_correct": false, "explanation": "「祝福」はめでたいことを喜ぶ意味で、動物との関係を考える文には合わない。"}, {"text": "延長", "is_correct": false, "explanation": "「延長」は期間や長さを伸ばす意味で、「動物との延長を考えて」は不自然で合わない。"}], "explanations": {"共存": "「野生の動物との〜を考えて」で、共に生きる在り方を指すので文脈に合う。", "誤解": "「誤解」は思い違いの意味で、「誤解を考えて木を植えた」とは文が成り立たない。", "祝福": "「祝福」はめでたいことを喜ぶ意味で、動物との関係を考える文には合わない。", "延長": "「延長」は期間や長さを伸ばす意味で、「動物との延長を考えて」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "資料と雑誌が部屋に共存していて、探し物が見つからない。", "explanation": "ここは〈混在〉の意味。違うものが入り混じって乱れた状態は混在で、共存の穏やかに共にある意味とは合わない。"}, {"text": "この池は一種類の魚が共存している。", "explanation": "ここは〈独占〉の意味。一つのものだけが占める状態は独占で、複数のものが共に生きる共存とは合わない。"}, {"text": "二人の俳優が舞台で共存して、観客を沸かせた。", "explanation": "ここは〈共演〉の意味。同じ舞台に立つことは共演で、共存は共に生き続ける状態を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川の上流では、人とサケが共存で暮らしている。", "corrected_sentence": "川の上流では、人とサケが共存して暮らしている。", "error_description": "「共存」の直後に「で」が付いているのが誤り。動詞「共存する」のて形「共存して」にして「暮らしている」とつなぐのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39656, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この林では、タヌキとキツネが共存せ暮らしている。", "corrected_sentence": "この林では、タヌキとキツネが共存して暮らしている。", "error_description": "「共存せ」は未然形の「せ」で、そのままでは続かない。動詞「共存する」のて形「共存して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
