INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39657, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "異なるものが互いに認め合い、ともに存在し続けること。", "primary_collocate": null, "pronunciation": "きょうぞん", "ipa": "kʲoːzoɴ", "syllable_count": 4, "sentences": [{"text": "多くの国の人が働く職場では、文化の共存が大切だ。", "target_word": "共存", "complexity_tier": "T3", "furigana": "多[おお]くの国[くに]の人[ひと]が働[はたら]く職場[しょくば]では、文化[ぶんか]の共存[きょうぞん]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "宗教の違う人々が共存する町で、私は育った。", "target_word": "共存", "complexity_tier": "T3", "furigana": "宗教[しゅうきょう]の違[ちが]う人々[ひとびと]が共存[きょうぞん]する町[まち]で、私[わたし]は育[そだ]った。", "sentence_source": "generated"}, {"text": "互いの考えを認め合えば、意見の違う人とも共存できる。", "target_word": "共存", "complexity_tier": "T3", "furigana": "互[たが]いの考[かんが]えを認[みと]め合[あ]えば、意見[いけん]の違[ちが]う人[ひと]とも共存[きょうぞん]できる。", "sentence_source": "generated"}, {"text": "二つの言語が共存する国では、学校でも両方を学ぶ。", "target_word": "共存", "complexity_tier": "T3", "furigana": "二[ふた]つの言語[げんご]が共存[きょうぞん]する国[くに]では、学校[がっこう]でも両方[りょうほう]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "新しい住民と古い住民の共存を目指して、祭りを開いた。", "target_word": "共存", "complexity_tier": "T3", "furigana": "新[あたら]しい住民[じゅうみん]と古[ふる]い住民[じゅうみん]の共存[きょうぞん]を目指[めざ]して、祭[まつ]りを開[ひら]いた。", "sentence_source": "generated"}, {"text": "違いを認めない社会では、共存は難しい。", "target_word": "共存", "complexity_tier": "T3", "furigana": "違[ちが]いを認[みと]めない社会[しゃかい]では、共存[きょうぞん]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "外国人との共存について、市民が話し合う会が開かれた。", "target_word": "共存", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]との共存[きょうぞん]について、市民[しみん]が話[はなし]し合[あ]う会[かい]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "伝統と新しい技術が共存する街並みが、観光客に人気だ。", "target_word": "共存", "complexity_tier": "T3", "furigana": "伝統[でんとう]と新[あたら]しい技術[ぎじゅつ]が共存[きょうぞん]する街並[まちな]みが、観光客[かんこうきゃく]に人気[にんき]だ。", "sentence_source": "generated"}, {"text": "彼女は異なる文化の共存を、自分の研究テーマに選んだ。", "target_word": "共存", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は異[こと]なる文化[ぶんか]の共存[きょうぞん]を、自分[じぶん]の研究[けんきゅう]テーマに選[えら]んだ。", "sentence_source": "generated"}, {"text": "相手を尊重しなければ、本当の共存とは言えない。", "target_word": "共存", "complexity_tier": "T3", "furigana": "相手[あいて]を尊重[そんちょう]しなければ、本当[ほんとう]の共存[きょうぞん]とは言[い]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共存する", "label": "終止形"}, {"form": "共存し", "label": "連用形"}, {"form": "共存して", "label": "て形"}, {"form": "共存した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "違う文化・考え・立場が互いを認め合ってともにあり続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39657, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "「文化の共存が大切だ」で、異なる文化が互いを認めて共にある意味になり文脈に合う。"}, {"text": "誤訳", "is_correct": false, "explanation": "「誤訳」は訳し間違いの意味で、文化の大切さを述べる文には合わない。"}, {"text": "発注", "is_correct": false, "explanation": "「発注」は商品などを注文する意味で、「文化の発注が大切だ」は成り立たない。"}, {"text": "完走", "is_correct": false, "explanation": "「完走」は競走などを最後まで走り切る意味で、文化を対象にした文には合わない。"}], "explanations": {"共存": "「文化の共存が大切だ」で、異なる文化が互いを認めて共にある意味になり文脈に合う。", "誤訳": "「誤訳」は訳し間違いの意味で、文化の大切さを述べる文には合わない。", "発注": "「発注」は商品などを注文する意味で、「文化の発注が大切だ」は成り立たない。", "完走": "「完走」は競走などを最後まで走り切る意味で、文化を対象にした文には合わない。"}, "sentence_index": 0, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの政党は、税金をめぐって共存している。", "explanation": "ここは〈対立〉の意味。税金をめぐって争う状況は対立で、共存は互いを認め合って共にあり続けることなので合わない。"}, {"text": "多くの人が主人公の気持ちと共存した。", "explanation": "ここは〈共感〉の意味。他人の気持ちに心を寄せるのは共感で、共存は人や考えが共にあり続けることを指すので合わない。"}, {"text": "会議は長引いたが、ついに共存に達した。", "explanation": "ここは〈合意〉の意味。意見が一致して決まることは合意で、「共存に達した」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39657, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "「外国人との〜について話し合う」で、互いに認め合って共にある在り方を指すので文脈に合う。"}, {"text": "祝辞", "is_correct": false, "explanation": "「祝辞」はお祝いの言葉の意味で、「外国人との祝辞について話し合う」とは言わない。"}, {"text": "消毒", "is_correct": false, "explanation": "「消毒」は菌を殺す意味で、外国人との関係を話し合う文には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は点数をつける意味で、「外国人との採点について」は文が成り立たない。"}], "explanations": {"共存": "「外国人との〜について話し合う」で、互いに認め合って共にある在り方を指すので文脈に合う。", "祝辞": "「祝辞」はお祝いの言葉の意味で、「外国人との祝辞について話し合う」とは言わない。", "消毒": "「消毒」は菌を殺す意味で、外国人との関係を話し合う文には合わない。", "採点": "「採点」は点数をつける意味で、「外国人との採点について」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の俳優が映画で共存して、主役を演じた。", "explanation": "ここは〈共演〉の意味。同じ作品に出演することは共演で、共存は互いを認め合って共にあり続けることを指すので合わない。"}, {"text": "グループは意見の違いで共存を解消した。", "explanation": "ここは〈分裂〉の意味。組織が割れて別々になることは分裂で、共存は割れずに共にあり続ける状態を指すので合わない。"}, {"text": "全員が彼女の提案と共存した。", "explanation": "ここは〈同意〉の意味。提案に賛成することは同意で、提案と共存するという言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39657, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "違う文化を持つ人々の共存を、地域の大切な課題だ。", "corrected_sentence": "違う文化を持つ人々の共存が、地域の大切な課題だ。", "error_description": "主語になる「共存」に「を」が付いているのが誤り。主語を示す「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39657, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "互いを認め合う、共存な関係を築きたい。", "corrected_sentence": "互いを認め合う、共存の関係を築きたい。", "error_description": "「共存」は名詞なので、後ろの名詞につなぐには「の」を使う。「な」は誤りで、「共存の関係」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「求める」は対象を「を」で示すので、「再考」の直前に「を」を置く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、求められる対象である「再考」には付かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すので、直接の対象「再考」には付かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、求める対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「求める」は対象を「を」で示すので、「再考」の直前に「を」を置く。", "が": "「が」は主語を示すので、求められる対象である「再考」には付かない。", "に": "「に」は相手や方向を示すので、直接の対象「再考」には付かない。", "で": "「で」は手段や場所を示すので、求める対象を表せない。"}, "error_tags": {"が": "主格", "に": "相手の格", "で": "手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「やり方を再考した」の「を」は、考え直す対象の「やり方」を示すので正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、対象を示す「やり方」の後には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、ここでは文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、考え直す対象の後には置けない。"}], "correct_answer": "を", "explanations": {"を": "「やり方を再考した」の「を」は、考え直す対象の「やり方」を示すので正しい。", "へ": "「へ」は方向を示すので、対象を示す「やり方」の後には合わない。", "と": "「と」は相手や並列を示すので、ここでは文が成り立たない。", "より": "「より」は比較を示すので、考え直す対象の後には置けない。"}, "error_tags": {"へ": "方向の格", "と": "相手の格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もう一度、よく考えること。", "primary_collocate": null, "pronunciation": "さいこう", "ipa": "saikoː", "syllable_count": 4, "sentences": [{"text": "計画に問題があるので、再考が必要です。", "target_word": "再考", "complexity_tier": "T3", "furigana": "計画[けいかく]に問題[もんだい]があるので、再考[さいこう]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "部長は私たちに再考を求めました。", "target_word": "再考", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は私[わたし]たちに再考[さいこう]を求[もと]めました。", "sentence_source": "generated"}, {"text": "この案はまだ再考の余地があります。", "target_word": "再考", "complexity_tier": "T3", "furigana": "この案[あん]はまだ再考[さいこう]の余地[よち]があります。", "sentence_source": "generated"}, {"text": "急いで決めずに、再考してください。", "target_word": "再考", "complexity_tier": "T3", "furigana": "急[いそ]いで決[き]めずに、再考[さいこう]してください。", "sentence_source": "generated"}, {"text": "店長の提案を聞いて、予定を再考することにした。", "target_word": "再考", "complexity_tier": "T3", "furigana": "店長[てんちょう]の提案[ていあん]を聞[き]いて、予定[よてい]を再考[さいこう]することにした。", "sentence_source": "generated"}, {"text": "引っ越しを再考したほうがいいと友人に言われた。", "target_word": "再考", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しを再考[さいこう]したほうがいいと友人[ゆうじん]に言[い]われた。", "sentence_source": "generated"}, {"text": "会議では、価格の再考が話し合われた。", "target_word": "再考", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、価格[かかく]の再考[さいこう]が話[はな]し合[あ]われた。", "sentence_source": "generated"}, {"text": "結果が悪かったので、やり方を再考した。", "target_word": "再考", "complexity_tier": "T3", "furigana": "結果[けっか]が悪[わる]かったので、やり方[かた]を再考[さいこう]した。", "sentence_source": "generated"}, {"text": "再考の結果、旅行は来月に延ばしました。", "target_word": "再考", "complexity_tier": "T3", "furigana": "再考[さいこう]の結果[けっか]、旅行[りょこう]は来月[らいげつ]に延[の]ばしました。", "sentence_source": "generated"}, {"text": "大事なことなので、再考を重ねてから返事をします。", "target_word": "再考", "complexity_tier": "T3", "furigana": "大事[だいじ]なことなので、再考[さいこう]を重[かさ]ねてから返事[へんじ]をします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "再考する", "label": "辞書形"}, {"form": "再考した", "label": "過去形"}, {"form": "再考しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "もう一度よく考えること。『再考の余地』『再考を求める』など決定前の見直し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再考", "is_correct": true, "explanation": "「計画に問題があるので、〜が必要です」には、決定前にもう一度考え直す意味の「再考」が入る。"}, {"text": "再会", "is_correct": false, "explanation": "人と会う意味になり、計画の見直しという文脈に合わない。"}, {"text": "再生", "is_correct": false, "explanation": "動かし直す、または録音を流す意味で、考え直す文脈には入らない。"}, {"text": "再開", "is_correct": false, "explanation": "中断していた物事を始め直す意味で、問題を見直す文脈には当たらない。"}], "explanations": {"再考": "「計画に問題があるので、〜が必要です」には、決定前にもう一度考え直す意味の「再考」が入る。", "再会": "人と会う意味になり、計画の見直しという文脈に合わない。", "再生": "動かし直す、または録音を流す意味で、考え直す文脈には入らない。", "再開": "中断していた物事を始め直す意味で、問題を見直す文脈には当たらない。"}, "sentence_index": 0, "correct_answer": "再考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "迷子の犬を再考して、家まで連れて帰った。", "explanation": "ここは〈探し出す〉の意味。再考は考え直すことで、犬を探して連れ戻す意味では使わない。"}, {"text": "壊れたケーキを再考して、もう一度作った。", "explanation": "ここは〈作り直す〉の意味。再考は頭の中で考え直すことで、物を作り直す場面には使わない。"}, {"text": "十年ぶりに友人と再考した。", "explanation": "ここは〈再会〉の意味。再考は考えを改めることで、人と会う意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再考", "is_correct": true, "explanation": "「価格の再考が話し合われた」には、決めた価格を考え直す意味の「再考」が入る。"}, {"text": "再訪", "is_correct": false, "explanation": "同じ場所を訪ねる意味で、価格の話し合いには合わない。"}, {"text": "再録", "is_correct": false, "explanation": "書物などに記録し直す意味で、価格の話し合いには合わない。"}, {"text": "再来", "is_correct": false, "explanation": "もう一度来る意味で、価格の議論の文脈には入らない。"}], "explanations": {"再考": "「価格の再考が話し合われた」には、決めた価格を考え直す意味の「再考」が入る。", "再訪": "同じ場所を訪ねる意味で、価格の話し合いには合わない。", "再録": "書物などに記録し直す意味で、価格の話し合いには合わない。", "再来": "もう一度来る意味で、価格の議論の文脈には入らない。"}, "sentence_index": 6, "correct_answer": "再考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "なくした物を再考したら、かばんの中から見つかった。", "explanation": "ここは〈探す〉の意味。再考は考えを改めることで、物を探す動作には使わない。"}, {"text": "昔の友人の名前を再考した。", "explanation": "ここは〈思い出す〉の意味。再考は一度出した考えを改めることで、記憶をたどる場面には合わない。"}, {"text": "壊れたパソコンを再考して、直した。", "explanation": "ここは〈修理〉の意味。再考は考えを改めることで、機械を直す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部長は社員に計画の再考に求めた。", "corrected_sentence": "部長は社員に計画の再考を求めた。", "error_description": "「求める」は対象に「を」を取るので、「再考に」は誤り。正しくは「再考を求めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その提案を再考しで、答えを変えた。", "corrected_sentence": "その提案を再考して、答えを変えた。", "error_description": "「再考して」の「して」を「しで」と濁らせた誤り。正しくは「再考して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
